arquivos.codigo:
"""A busca por perfil. Só roda com os filtros mínimos preenchidos ou "tanto faz"
(a máquina garante; na locação a mobília é um deles). Até `max_no_bairro` no bairro e `max_ao_redor` nos bairros
aqui perto (config/filtros.yaml); 1 resultado, e do bairro pedido, vira card; 0
vira lista_vazia. Nunca oferece outro tipo nem outra finalidade no lugar.

Devolve DADOS: quem escreve a lista é o template `lista.md`."""
from __future__ import annotations

import re

from nay.acoes.enviar_imovel import card, valor_texto, valores
from nay.cerebro.catalogo import Filtros, preco, tipos_pedidos
from nay.cerebro.cerebro import Cerebro
from nay.cerebro.ficha import nao_aceita_financiamento
from nay.config import cfg
from nay.estado import prazos
from nay.estado.filtros import finalidade_pelo_valor
from nay.nos import no
from nay.texto import normal, reais
from nay.tipos import Conversa, Imovel, ResultadoFerramenta

ROTULO = {"apartamento": "apartamento", "casa": "casa", "casa_condominio": "casa em condomínio", "flat": "flat",
          "cobertura": "cobertura", "sala": "sala", "loja": "loja", "terreno": "terreno", "predio": "prédio",
          "galpao": "galpão", "comercial": "imóvel comercial"}


def filtros_da_conversa(c: Conversa) -> Filtros:
    # "alugar ou comprar" / "tanto faz" com valor: o valor diz o negócio (regra do Tel: até 30 mil é aluguel, de
    # 100 mil para cima é venda). Sem isso a busca comparava o teto só com o aluguel e a venda nunca aparecia.
    valor = c.filtro_teto or c.filtro_piso
    fin = c.filtro_finalidade if c.filtro_finalidade in ("locacao", "venda") else finalidade_pelo_valor(valor)
    tipo = c.filtro_tipo           # "tanto_faz" segue: para o catálogo é casa ou apartamento, nunca sala ou loja
    mob = c.filtro_mobilia if c.filtro_mobilia in ("mobiliado", "semi") else None
    return Filtros(finalidade=fin, tipo=tipo, teto=c.filtro_teto, bairros=tuple(c.filtro_regiao or ()),
                   quartos=c.filtro_quartos, mobilia=mob, piso=c.filtro_piso)


def quartos_texto(i: Imovel) -> str | None:
    if not i.quartos:
        return None
    return f"{i.quartos} quarto{'s' if i.quartos > 1 else ''}"


def linha(i: Imovel, finalidade: str | None) -> dict:
    """Um imóvel numa linha de lista (lista.md, qual_deles.md, confirmar_imovel.md)."""
    return {"codigo": i.codigo, "condominio": i.condominio_nome or ROTULO.get(i.tipo, "Imóvel").capitalize(),
            "bairro": i.bairro or "Manaus", "quartos": quartos_texto(i), "valor": valor_texto(i, finalidade)}


def artigo(nome: str) -> str:
    """'No Aleixo', 'Na Ponta Negra', 'Na Cidade Nova', 'No bairro Da Paz'."""
    primeira = nome.split()[0].lower() if nome.strip() else ""
    if primeira in ("da", "do", "de", "das", "dos"):
        return f"No bairro {nome}"
    return f"{'Na' if primeira.endswith('a') or primeira == 'cidade' else 'No'} {nome}"


def onde(cer: Cerebro, bairros: tuple[str, ...]) -> str:
    """'No Aleixo' / 'Na Ponta Negra' / 'Na região que você pediu' / 'Em Manaus'."""
    if len(bairros) == 1:
        return artigo(cer.nome_do_bairro(bairros[0]))
    return "Na região que você pediu" if bairros else "Em Manaus"


def _tem_ar(cer: Cerebro, i: Imovel) -> bool:
    fi = cer.ficha(i.codigo) or {}
    return any(re.search(r"climatiz|ar.?condicionado", normal(str(x)))
               for x in (fi.get("car_imovel") or []) + (fi.get("car_condominio") or []))


def _achar(cer: Cerebro, f: Filtros, fora: set[int], so_climatizado: bool) -> list[Imovel]:
    """Os imóveis do filtro. `so_climatizado`: sem mobília no cadastro, mas com ar (o "só climatizado" do Tel)."""
    if not so_climatizado:
        return [i for i in cer.catalogo.buscar(f) if i.codigo not in fora]
    # "pelo menos ar" (Alteração 2, D): o semimobiliado tem o ar, e o sem móveis serve se tiver
    sem_mobilia = Filtros(**{**f.__dict__, "mobilia": None})
    return [i for i in cer.catalogo.buscar(sem_mobilia)
            if i.codigo not in fora and (i.mobilia == "semi" or (i.mobilia != "mobiliado" and _tem_ar(cer, i)))]


# PILARES (Pedro, 19/10/2026: "elevador quero que seja um dos pilares principais"): extra que, pedido, NÃO cai. O
# imóvel vertical sem elevador fica de fora mesmo que não sobre nada (a piscina continua "havendo, só eles; não
# havendo, todos e a lista avisa"). Casa não tem elevador para faltar: o pilar só vale para o que tem andar.
PILARES = frozenset({"elevador"})
VERTICAL = re.compile(r"^(apartamento|flat|cobertura|kitnet|studio|sala)")
# PRIORIDADES (Pedro, 20/10/2026: "esse imóvel teria prioridade ao ser enviado para um cliente que já pediu imóveis de
# fino acabamento"): extra que NÃO filtra nem avisa que falta; só põe primeiro os que o cadastro marca (Sim no Checklist
# rápido / Editar imóvel, core_imovel_busca.fino_acabamento). Os outros continuam na lista, depois deles.
# 20/10: "condominio novo" também (os recentes da planilha primeiro, cerebro/proximos.py).
PRIORIDADES = frozenset({"fino acabamento", "condominio novo"})


def filtrantes(extras: tuple[str, ...]) -> tuple[str, ...]:
    """Os que as CARACTERÍSTICAS precisam ter; fino acabamento só ordena e financiamento é campo do cadastro."""
    return tuple(e for e in extras if e not in PRIORIDADES and e != "financiavel")


def _so_financiaveis(cer: Cerebro, lado: list[Imovel]) -> list[Imovel]:
    # 21/10: quem disse "financiável" não recebe imóvel cujo cadastro diz que não aceita financiamento
    return [i for i in lado if not nao_aceita_financiamento(cer.ficha(i.codigo) or {})]


def _fino_primeiro(lado: list[Imovel]) -> list[Imovel]:
    """Os de fino acabamento na frente, sem mudar a ordem (o preço) dentro de cada grupo."""
    return sorted(lado, key=lambda i: not i.fino_acabamento)


def tem_extras(cer: Cerebro, i: Imovel, extras: tuple[str, ...]) -> bool:
    """O imóvel (ou o condomínio dele) tem o que ele pediu a mais? Lido das características do anúncio."""
    fi = cer.ficha(i.codigo) or {}
    ditas = " ".join(normal(str(x)) for x in (fi.get("car_imovel") or []) + (fi.get("car_condominio") or []))
    return all(e in ditas for e in extras)


def _passa_nos_pilares(cer: Cerebro, i: Imovel, extras: tuple[str, ...]) -> bool:
    """Os extras que são pilar: o vertical precisa ter; a casa passa (não se cobra elevador de casa)."""
    pilares = tuple(e for e in extras if e in PILARES)
    if not pilares or not VERTICAL.match(normal(i.tipo or "")):
        return True
    return tem_extras(cer, i, pilares)


def _dos_proximos(cer: Cerebro, f: Filtros, fora: set[int], so_climatizado: bool, ref: str | None,
                  ja: list[Imovel]) -> list[Imovel]:
    """Os imóveis dos condomínios próximos (planilha) que ficam fora dos bairros procurados, com os mesmos filtros."""
    if not ref or not cer.proximos:
        return []
    tem = {i.codigo for i in ja}
    em_toda_parte = Filtros(**{**f.__dict__, "bairros": ()})
    return [i for i in _achar(cer, em_toda_parte, fora, so_climatizado)
            if i.codigo not in tem and cer.proximos.perto_de(ref, i)]


def _aqui_e_perto(cer: Cerebro, f: Filtros, fora: set[int], so_climatizado: bool,
                  extras: tuple[str, ...] = (), varios: bool = False,
                  ref: str | None = None) -> tuple[list[Imovel], list[Imovel]]:
    """(no bairro pedido, nos bairros aqui perto), cada um até a cota de config/filtros.yaml. Os vizinhos são
    procurados com os MESMOS filtros (finalidade, tipo, faixa de valor, quartos, mobília): só o bairro muda.
    `extras` ("piscina", 13868): havendo imóvel com o que ele pediu a mais, só eles; não havendo, todos (e a
    lista avisa)."""
    cotas = cfg("filtros")
    aqui = _achar(cer, f, fora, so_climatizado)
    perto: list[Imovel] = []
    if f.bairros:
        vizinhos = tuple(dict.fromkeys(v for b in f.bairros for v in cer.bairros.perto(b) if v not in f.bairros))
        if vizinhos:
            ao_redor = Filtros(**{**f.__dict__, "bairros": vizinhos})
            perto = _achar(cer, ao_redor, fora, so_climatizado)
    perto += _dos_proximos(cer, f, fora, so_climatizado, ref, aqui + perto) if f.bairros else []
    exigidos = filtrantes(extras)
    if exigidos:
        # 19/10: primeiro os pilares (elevador): quem não tem sai, mesmo que não sobre nada
        aqui, perto = ([i for i in lado if _passa_nos_pilares(cer, i, exigidos)] for lado in (aqui, perto))
        com = [[i for i in lado if tem_extras(cer, i, exigidos)] for lado in (aqui, perto)]
        aqui, perto = com if any(com) else (aqui, perto)
    if "financiavel" in extras:            # exigência que NÃO cai: sem financiamento o imóvel não serve a ele
        aqui, perto = _so_financiaveis(cer, aqui), _so_financiaveis(cer, perto)
    if PRIORIDADES & set(extras):          # 20/10: alto padrão pedido, os de fino acabamento vêm antes da cota
        aqui, perto = _fino_primeiro(aqui), _fino_primeiro(perto)
    # 20/10 (a planilha dos condomínios próximos): os do condomínio pedido e os próximos da mesma classe na frente
    novo = "condominio novo" in extras
    aqui, perto = cer.proximos.ordenar(aqui, ref, novo), cer.proximos.ordenar(perto, ref, novo)
    mais = int(cotas.get("max_varios_clientes", 0)) if varios else 0      # vários clientes: mais opções (12/10)
    return aqui[:max(cotas["max_no_bairro"], mais)], perto[:max(cotas["max_ao_redor"], mais)]


def _escondidos(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> dict:
    """O que cabe no pedido (no lugar ou perto) e ficou de fora só porque ele já recebeu hoje ou recusou. É com
    isso que ela decide perguntar "Está perguntando para outro cliente, certo?" (acoes/preparo.py)."""
    if not fora:
        return {}
    aqui, perto = _aqui_e_perto(cer, f, set(), c.filtro_mobilia == "climatizado", c.filtro_extras)
    fora_daqui = [i for i in aqui + perto if i.codigo in fora]
    if not fora_daqui:
        return {}
    nomes = ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})" for i in fora_daqui[:3])
    return {"escondidos": [i.codigo for i in fora_daqui], "escondidos_texto": nomes}


def _mais_longe(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> list[Imovel]:
    """Nem no lugar pedido nem nos vizinhos há nada NA FAIXA. Antes de negar, os bairros um pouco mais longe (até
    `raio_medio_km` dos pedidos), com os MESMOS filtros e a MESMA faixa de valor, do mais perto para o mais longe.
    Tel, 06/10, rodada 8: "é melhor priorizar faixa de preço mesmo em bairros mais longe, porém não muito, uma
    média só; um cliente de 6 mil não quer apartamento de 2 mil"."""
    if not f.bairros:
        return []
    vistos = set(f.bairros) | {v for b in f.bairros for v in cer.bairros.perto(b)}
    medios = cer.bairros.um_pouco_mais_longe(f.bairros, float(cfg("filtros").get("raio_medio_km", 10)), vistos)
    if not medios:
        return []
    la = _achar(cer, Filtros(**{**f.__dict__, "bairros": tuple(medios)}), fora, c.filtro_mobilia == "climatizado")
    la = _so_financiaveis(cer, la) if "financiavel" in c.filtro_extras else la
    ordem = {b: n for n, b in enumerate(medios)}
    return sorted(la, key=lambda i: ordem.get(i.bairro_norm, len(ordem)))[:cfg("filtros")["max_ao_redor"]]


def _abaixo_da_faixa(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> dict:
    """A faixa do valor não achou NADA, nem nos vizinhos: existe coisa mais barata com os outros filtros? Ela NÃO
    lista por conta própria (Tel, 06/10, rodada 5: "ela mandou um monte de apartamento barato, a pessoa não quer
    isso"): diz que nessa faixa não tem, a partir de quanto tem, e pergunta se ele quer ver. Devolve o que o
    template precisa, ou {} se não há nada abaixo (ou não se sabe se é aluguel ou compra)."""
    if not f.teto or f.finalidade not in ("locacao", "venda"):
        return {}
    sem_piso = Filtros(**{**f.__dict__, "sem_piso": True})
    aqui, perto = _aqui_e_perto(cer, sem_piso, fora, c.filtro_mobilia == "climatizado", c.filtro_extras)
    if not (aqui or perto):
        return {}
    mais_barato = min(aqui + perto, key=lambda i: preco(i, sem_piso) or 0)
    return {"nada": False, "tem_abaixo": True, "a_partir": reais(preco(mais_barato, sem_piso)),
            "valores_do_mais_barato": valores(mais_barato)}


def _vazia_ou_de_antes(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int], base: dict) -> dict:
    """Nada novo na faixa. Se nesse perfil só existe o que ele já tem, ela diz isso, em vez de "não tenho"."""
    if not ja:
        return base
    lados = _aqui_e_perto(cer, f, set(c.rejeitados), c.filtro_mobilia == "climatizado")
    tinha = [i for lado in lados for i in lado]
    if not tinha:
        return base
    nomes = ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})" for i in tinha[:3])
    return {**base, "nada": False, "so_enviados": True, "enviados_texto": nomes}


def _ja_no_lugar(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int]) -> str:
    """O que cabe no pedido NO LUGAR PEDIDO mas ele já recebeu (Hilário, 06/10, rodada 7: pediu Parque 10 e ouviu
    "não tenho imóvel nesse perfil"; os dois que cabiam já tinham ido para ele). Ela diz quais são, em vez de negar."""
    if not ja:
        return ""
    aqui, _ = _aqui_e_perto(cer, f, set(c.rejeitados), c.filtro_mobilia == "climatizado", c.filtro_extras)
    return ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})"
                     for i in aqui if i.codigo in ja)


def _sem_tipo(f: Filtros, todos: list[Imovel], pedidos: tuple[str, ...]) -> str | None:
    """Ele pediu casa E apartamento (vários clientes) e de um dos tipos não há nada: a lista diz isso, em vez de
    sair só com o outro tipo como se fosse a resposta (Pedro, 13/10: quem pediu casa não recebe apartamento calado)."""
    if f.tipo != "tanto_faz" or len(pedidos) < 2:
        return None
    tem = {"casa" if i.tipo == "casa_condominio" else i.tipo for i in todos}
    return " nem ".join(ROTULO.get(t, t) for t in pedidos if t not in tem) or None


@no("acoes.buscar")
def buscar(cer: Cerebro, c: Conversa, sem_piso: bool = False, agora=None, varios: bool = False,
           tipos: tuple[str, ...] = ()) -> ResultadoFerramenta:
    """`sem_piso`: ele ACEITOU ver o que há abaixo da faixa do valor; a lista sai sem o limite de baixo.
    `agora`: o instante do turno; o que ele "já recebeu" é só o que saiu antes dele. `tipos`: os que ele pediu."""
    f, cotas = filtros_da_conversa(c), cfg("filtros")
    f = Filtros(**{**f.__dict__, "sem_piso": sem_piso or f.sem_piso, "tipos": tipos_pedidos(f, tipos)})
    # o que ele já recebeu não é proposto de novo (Pedro, 05/10: "os próximos filtros não podem conter imóveis
    # já enviados"); o que recusou, também não. Desde 10/10 isso vale para O PEDIDO DE HOJE: o que saiu em outro
    # dia, ou para outro cliente, volta a aparecer (estado/prazos.py, `conta_desde`).
    ja = cer.enviados(c.chave, agora, prazos.conta_desde(c, agora))
    fora = set(c.rejeitados) | ja
    aqui, perto = _aqui_e_perto(cer, f, fora, c.filtro_mobilia == "climatizado", c.filtro_extras, varios,
                                c.filtro_condominio)
    base_escondidos = _escondidos(cer, c, f, fora)
    longe = [] if (aqui or perto) else _mais_longe(cer, c, f, fora)
    perto = perto or longe          # sai na segunda mensagem da lista, com outra abertura (`mais_longe`)
    todos = aqui + perto
    local = onde(cer, f.bairros)
    base = {"Onde": local, "onde": local[0].lower() + local[1:], "tipo_texto": ROTULO.get(f.tipo or "", "imóvel"),
            "nada": True, "so_enviados": False, **base_escondidos}
    if not todos:
        return _nada(cer, c, f, ja, fora, base)
    # ele pediu piscina e nenhum do perfil tem: a lista sai com o aviso, em vez de "não tenho"
    exigidos = filtrantes(c.filtro_extras)     # o fino acabamento nunca vira "com fino acabamento eu não tenho"
    falta_extra = bool(exigidos) and not tem_extras(cer, todos[0], exigidos)
    sem_extra = " e ".join(exigidos) if falta_extra else None
    if len(todos) == 1 and aqui and cotas.get("um_resultado_vira_card") and not sem_extra:
        r = card(cer, todos[0].codigo, f.finalidade)     # de outro bairro não vira card: vai a lista com o aviso
        return ResultadoFerramenta("buscar", r.texto_pronto, r.codigos, valores=r.valores, bairros=r.bairros,
                                   dados={"um_so": todos[0].codigo, **base_escondidos})
    ja_aqui = "" if aqui else _ja_no_lugar(cer, c, f, ja)
    dados = {**base, "sem_extra": sem_extra, "qtd_texto": f"{len(aqui)} opç{'ão' if len(aqui) == 1 else 'ões'}",
             "tem_no_bairro": bool(aqui), "so_ao_redor": not aqui and not ja_aqui and not longe,
             "ja_no_bairro": ja_aqui or None, "tem_ao_redor": bool(perto), "mais_longe": bool(longe),
             "nem_perto": bool(longe) and not ja_aqui, "sem_tipo": _sem_tipo(f, todos, tipos),
             "de_perto": bool(perto) and not longe,
             "no_bairro": [linha(i, f.finalidade) for i in aqui], "ao_redor": [linha(i, f.finalidade) for i in perto]}
    return ResultadoFerramenta("buscar", "", frozenset(i.codigo for i in todos),
                               valores=frozenset().union(*(valores(i) for i in todos)),
                               bairros=frozenset(i.bairro_norm for i in todos), dados=dados)


def _nada(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int], fora: set[int], base: dict) -> ResultadoFerramenta:
    """A busca não achou nada novo. Na ordem: só existe o que ele já tem; quer semimobiliado e há "só climatizado"
    (pergunta se interessa: Tel, 02/10, uma vez); há coisa abaixo da faixa do valor (pergunta se ele quer ver);
    ou não há nada mesmo ("Quer tentar outro bairro ou outro valor?")."""
    base = _vazia_ou_de_antes(cer, c, f, ja, base)
    if c.filtro_mobilia == "semi" and c.ultima_acao != "pergunta_so_climatizado":
        if any(_aqui_e_perto(cer, f, fora, True)):
            return ResultadoFerramenta("buscar", "", dados={**base, "so_climatizado": True})
    # Tel, 06/10, rodada 8: fora da faixa ela NÃO oferece ("se não tiver, só avisar que não tem, sem problema").
    # A oferta do que há abaixo só volta se `oferecer_abaixo_da_faixa` for ligado em config/filtros.yaml.
    oferece = cfg("filtros").get("oferecer_abaixo_da_faixa", False) and base["nada"] and not f.sem_piso
    abaixo = _abaixo_da_faixa(cer, c, f, fora) if oferece else {}
    return ResultadoFerramenta("buscar", "", valores=abaixo.pop("valores_do_mais_barato", frozenset()),
                               dados={**base, **abaixo, "vazio": True})

"""Enviar imóvel é determinístico: portão, card, fotos. Zero modelo.

O card é o MESMO dos grupos quando a ficha do anúncio tem (imovel_ficha.card,
com o preço conferido); senão, o template `card.md` com os dados do cadastro.
Imóvel de parceiro nunca tem card. Fora do mercado vira `indisponivel.md`, com
os disponíveis do mesmo condomínio (regra do Tel de 28/09). As fotos são só do
imóvel do turno e só as que existem: sem foto não existe frase sobre foto."""
from __future__ import annotations

import re

from nay.acoes.card_perguntas import andar_no_card, incluso_no_card
from nay.cerebro.cerebro import Cerebro
from nay.cerebro.ficha import _campo
from nay.compositor.compor import compor
from nay.config import cfg
from nay.nos import no
from nay.texto import normal, reais
from nay.tipos import Imovel, ResultadoFerramenta

# os 4 níveis (nayia 344, 11/10): "com modulados e ar" é o antigo semimobiliado; "nao" = só climatizado
MOBILIA = {"semi": "Com modulados e ar", "mobiliado": "Mobiliado", "nao": "Só climatizado", "nada": "Sem mobília"}
TIPO = {"apartamento": "Apartamento", "casa": "Casa", "casa_condominio": "Casa em condomínio", "flat": "Flat",
        "cobertura": "Cobertura", "sala": "Sala", "loja": "Loja", "terreno": "Terreno"}


def finalidade_de(i: Imovel, pedida: str | None = None) -> str | None:
    """A finalidade em que o imóvel é mostrado: a da conversa, se ele serve a ela; senão a dele."""
    if pedida == "venda" and i.de_venda:
        return "venda"
    if pedida == "locacao" and i.de_locacao:
        return "locacao"
    return "locacao" if i.de_locacao else "venda" if i.de_venda else None


def valor_texto(i: Imovel, pedida: str | None = None) -> str:
    fin = finalidade_de(i, pedida)
    v = i.valor_venda if fin == "venda" else i.valor_aluguel
    if not v:
        return "valor sob consulta"
    return reais(v) + ("/mês" if fin == "locacao" else "")


def valores(i: Imovel) -> frozenset[int]:
    return frozenset(int(v) for v in (i.valor_aluguel, i.valor_venda, i.taxa_condominio) if v)


def _plural(n: int | None, um: str, varios: str) -> str | None:
    return f"{n} {um if n == 1 else varios}" if n else None


def taxa_inclusa_no_aluguel(fi: dict | None) -> bool:
    """O cadastro diz que a taxa de condomínio já está no aluguel (campo "incluso no aluguel")."""
    return "condom" in normal(_campo(fi or {}, "incluso no aluguel") or "")


def card_do_cadastro(i: Imovel, pedida: str | None = None, fi: dict | None = None) -> str:
    """`fi`: a ficha do cadastro, para saber se a taxa de condomínio já está no aluguel.

    20/10/2026: o card SOMAVA "+ condomínio" sempre que havia taxa cadastrada, sem olhar o campo "incluso
    no aluguel". O 3841 (Mont Clair) tem taxa de R$ 1.000 e "incluso no aluguel: Taxa de Condomínio", e o
    card saiu "R$ 3.700/mês + condomínio R$ 1.000" para dois corretores (...8609 09h11 e ...1484 07h16):
    eles leem R$ 4.700 e repassam isso ao cliente. São 259 imóveis de locação nessa situação."""
    fin = finalidade_de(i, pedida)
    inclusa = fin == "locacao" and taxa_inclusa_no_aluguel(fi)
    return compor("card", {
        "tipo": i.tipo_original or TIPO.get(i.tipo, "Imóvel"),
        "finalidade_texto": "para venda" if fin == "venda" else "para locação",
        "condominio": i.condominio_nome, "bairro": i.bairro or "Manaus",
        "quartos": _plural(i.quartos, "quarto", "quartos"), "suites": _plural(i.suites, "suíte", "suítes"),
        "vagas": _plural(i.vagas, "vaga", "vagas"), "area": int(i.area_util) if i.area_util else None,
        "valor": valor_texto(i, pedida), "taxa_inclusa": inclusa,
        "taxa": None if inclusa else (reais(i.taxa_condominio) if i.taxa_condominio else None),
        "mobilia": MOBILIA.get(i.mobilia or ""), "andar": andar_no_card(i, fi),
        "incluso": incluso_no_card(fi, sem_condominio=inclusa) if fin == "locacao" else None,
        "observacao": observacao_curta(i), "codigo": i.codigo})


def observacao_curta(i: Imovel) -> str | None:
    """A observação do cadastro numa linha só, até 300 caracteres (Pedro, 11/10: "vai o card com essas informações
    e o texto da observação junto")."""
    o = re.sub(r"\s*\n+\s*", " / ", (i.observacao or "").strip())
    return (o[:297].rstrip() + "…") if len(o) > 300 else (o or None)


def _antes_do_valor(card: str, novas: list[str]) -> str:
    """Bullets novos no card do anúncio, antes das linhas de valor (ou do código)."""
    if not novas:
        return card
    linhas = card.splitlines()
    onde = next((k for k, ln in enumerate(linhas) if SECAO_DE_VALOR.match(ln) or ln.lower().startswith("código:")),
                len(linhas))
    return "\n".join(linhas[:onde] + [f"• {x}" for x in novas] + linhas[onde:])


def com_observacao(card: str, i: Imovel) -> str:
    """O card do anúncio (imovel_ficha.card) não tem a observação: entra como bullet antes das linhas de valor."""
    o = observacao_curta(i)
    return card if not o or o.lower() in card.lower() else _antes_do_valor(card, [o])


def com_perguntas(card: str, i: Imovel, fi: dict | None, pedida: str | None) -> str:
    """O card do anúncio com o andar (ou a escada) e o que o aluguel inclui (acoes/card_perguntas.py), quando ele
    ainda não diz."""
    baixo = card.lower()
    andar = None if re.search(r"\bandar\b|lances? de escada|t[ée]rreo", baixo) else andar_no_card(i, fi)
    incluso = (incluso_no_card(fi) if finalidade_de(i, pedida) == "locacao" and "inclus" not in baixo else None)
    return _antes_do_valor(card, [x for x in (andar, incluso and f"Incluso no aluguel: {incluso}") if x])


def _card_da_ficha(i: Imovel, ficha: dict | None) -> str | None:
    card = (ficha or {}).get("card")
    if not card or f"Código: {i.codigo}" not in card:
        return None
    preco = i.valor_aluguel if i.de_locacao else i.valor_venda
    return card if preco and reais(preco) in card else None


SECAO_DE_VALOR = re.compile(r"^\s*(venda|loca[cç][aã]o|aluguel)\s*:", re.I)


def so_da_finalidade(card: str, i: Imovel, pedida: str | None) -> str:
    """O card do imóvel que serve à locação E à venda, para quem pediu uma das duas (Tel, 06/10, rodada 5, turno
    13879: pedido de LOCAÇÃO recebeu "Venda: R$ 350.000 • não aceita financiamento"). Sai a linha do outro valor
    com os itens dela (financiamento, permuta); sem finalidade conhecida, ficam os dois."""
    if pedida not in ("locacao", "venda") or not (i.de_locacao and i.de_venda):
        return card
    linhas, fora = [], False
    for linha in card.splitlines():
        secao = SECAO_DE_VALOR.match(linha)
        if secao:
            fora = secao.group(1).lower().startswith("venda") == (pedida == "locacao")
        elif not linha.lstrip().startswith("•"):
            fora = False                 # "Código: ...": a seção do valor acabou
        if not fora and not (pedida == "locacao" and "financiamento" in linha.lower()):
            linhas.append(linha)
    return "\n".join(linhas)


@no("acoes.card")
def card(cer: Cerebro, codigo: int, pedida: str | None = None) -> ResultadoFerramenta:
    i = cer.catalogo.get(codigo)
    if i is None:
        return ResultadoFerramenta("card", "", dados={"recusa": "nao_existe"})
    if i.e_parceiro:
        return ResultadoFerramenta("card", "", dados={"recusa": "parceiro"})
    if not i.no_mercado:
        return fora_do_mercado(cer, i)
    fi = cer.ficha(codigo)
    da_ficha = _card_da_ficha(i, fi)
    texto = (com_perguntas(com_observacao(so_da_finalidade(da_ficha, i, pedida), i), i, fi, pedida) if da_ficha
             else card_do_cadastro(i, pedida, fi))
    return ResultadoFerramenta("card", texto, frozenset({codigo}), valores=valores(i),
                               bairros=frozenset({i.bairro_norm}), dados={"qtd_fotos": i.qtd_fotos})


# O "condomínio" que é só o nome do TIPO (75 imóveis no cadastro: "Casa", "Loja/Ponto", "Condomínio não
# identificado"). Não é um lugar: duas casas com "Casa" no campo não têm nada a ver uma com a outra.
NOME_QUE_NAO_E_CONDOMINIO = frozenset(normal(
    "casa casas apartamento apartamentos sobrado kitnet flat cobertura loja ponto sala salas andar terreno lote "
    "galpao deposito predio comercial imovel condominio residencial nao identificado de em via publica").split())


def e_condominio(nome_norm: str | None) -> bool:
    """O nome diz QUAL condomínio é? ("casa" e "condominio nao identificado" não dizem.)"""
    return bool(set((nome_norm or "").split()) - NOME_QUE_NAO_E_CONDOMINIO)


def fora_do_mercado(cer: Cerebro, i: Imovel) -> ResultadoFerramenta:
    """O imóvel saiu: diz que saiu e, se houver, mostra os disponíveis do MESMO condomínio e do MESMO negócio.

    03/10: perguntada do 5736 (casa de rua alugada, com "Casa" no campo do condomínio), ela respondeu "No
    mesmo condomínio eu tenho" e listou cinco casas À VENDA de outros bairros. Nome de tipo não é condomínio, e
    quem procurava aluguel não quer casa de R$ 900 mil.
    """
    outros = [o for o in cer.catalogo.ofertaveis()
              if e_condominio(i.condominio_norm) and o.condominio_norm == i.condominio_norm and o.codigo != i.codigo
              and ((i.de_locacao and o.de_locacao) or (i.de_venda and o.de_venda)
                   or not (i.de_locacao or i.de_venda))][:5]
    linhas = [{"codigo": o.codigo, "condominio": o.condominio_nome or TIPO.get(o.tipo, "Imóvel"),
               "bairro": o.bairro or "Manaus", "valor": valor_texto(o)} for o in outros]
    texto = compor("indisponivel", {"codigo": i.codigo, "outros": linhas, "tem_outros": bool(linhas),
                                    "sem_outros": not linhas})
    return ResultadoFerramenta("card", texto, frozenset({i.codigo} | {o.codigo for o in outros}),
                               valores=frozenset().union(*(valores(o) for o in outros)) if outros else frozenset(),
                               dados={"fora_do_mercado": True, "ofereceu_parecido": not linhas})


@no("acoes.fotos")
def fotos(cer: Cerebro, codigo: int) -> ResultadoFerramenta:
    i = cer.catalogo.get(codigo)
    if i is None or i.e_parceiro or not i.no_mercado:
        return ResultadoFerramenta("fotos", "", dados={"recusa": "fora do mercado ou parceiro"})
    urls = cer.fotos(codigo)
    limite = int(cfg("limites").get("max_fotos_por_envio") or 0)
    if limite:
        urls = urls[:limite]
    return ResultadoFerramenta("fotos", "", frozenset({codigo}), fotos=tuple((codigo, u) for u in urls),
                               dados={"qtd": len(urls)})

"""Executar a ação decidida pela máquina: chamar o que ela precisa (busca, card,
fotos, ficha, dúvida), montar as peças pelos templates e validar.

Nenhuma ação chama modelo, menos a pergunta que a ficha não responde sozinha
(acoes/duvida.py). Vetou, não troca o texto por outro: a resposta de modelo cai e o
corretor recebe o template fixo (a dúvida vira pendência; o resto escala)."""
from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from zoneinfo import ZoneInfo

from nay.acoes import duvida, grupo, ja_enviei, portao, preparo, varios
from nay.acoes.buscar import buscar, linha
from nay.acoes.enviar_imovel import card, fotos, valores
from nay.acoes.responder_ficha import responder_ficha
from nay.cerebro.cerebro import Cerebro
from nay.compositor.compor import compor, existe
from nay.config import cfg
from nay.contexto.resolver_imovel import pediu_status
from nay.estado import maquina, memoria, multiplos
from nay.estado.acao import Acao, Evento
from nay.nos import no
from nay.texto import cumprimentou, primeiro_nome
from nay.tipos import Conversa, Peca, ResultadoFerramenta
from nay.trace.trace import Trace
from nay.validador.validar import Permitido, Veredito, saneado, validar

MANAUS = ZoneInfo("America/Manaus")
FINALIDADE = {"locacao": "locação", "venda": "venda"}
MIDIA = {"imagem": "imagem(ns)", "documento": "documento(s)", "video": "vídeo(s)"}
# As frases fixas do Tel que usam, no sentido certo, uma palavra que o validador barra: "parceria", e o "eu te
# aviso por aqui" de quem anotou a visita (não é promessa de resposta: é o fecho da visita marcada).
ISENTOS = {"parceria": frozenset({"parceria_nunca"}), "pode_anunciar": frozenset({"parceria_nunca"}),
           "visita_anotada": frozenset({"promessa_ou_sem_resposta"})}


@dataclass(frozen=True)
class Base:
    """O que todo template pode usar, igual para o turno inteiro."""
    nome: str | None
    telefone: str
    agora: datetime
    texto_dele: str
    conversa: Conversa
    primeira_do_dia: bool = False

    def ctx(self, **mais) -> dict:
        return {"nome": primeiro_nome(self.nome) or "", "telefone": self.telefone, "agora": self.agora,
                "primeira_do_dia": self.primeira_do_dia, "horas": cfg("limites")["escalacao_expira_h"], **mais}


def _qual(cer: Cerebro, candidatos: tuple[int, ...], finalidade: str | None) -> ResultadoFerramenta:
    ims = [i for c in candidatos if (i := cer.catalogo.get(c)) and i.no_mercado and not i.e_parceiro][:5]
    return ResultadoFerramenta("qual", "", frozenset(i.codigo for i in ims),
                               valores=frozenset().union(*(valores(i) for i in ims)) if ims else frozenset(),
                               dados={"candidatos": [linha(i, finalidade) for i in ims]})


@no("acoes.ferramentas")
def ferramentas(cer: Cerebro, conv: Conversa, ev: Evento, a: Acao, tr: Trace,
                modelos=None, juiz=None) -> tuple[Conversa, Acao, dict]:
    """Chama o que a ação precisa. Pode trocar a ação quando o resultado pede (busca com
    1 resultado vira apresentar; imóvel sem prova de pedido vira "É este?"; imóvel já mandado
    vira aviso; dúvida sem resposta vira pendência)."""
    res: dict[str, ResultadoFerramenta] = {}
    conv, a = preparo.antes_de_tudo(cer, conv, ev, a, res)
    if a.tipo == "buscar":
        with tr.medir("acoes", "buscar", conv) as e:
            res["buscar"] = e.saida = buscar(cer, conv, bool(a.dados.get("sem_piso")), ev.agora,
                                             *memoria.para_a_busca(ev.ja_dito, ev.texto))
        conv, a = preparo.depois_da_busca(cer, conv, ev, a, res["buscar"])
    if a.tipo == "template" and a.template == "qual_da_lista" and "codigos" in a.dados:
        conv, a = preparo.mesma_lista(cer, conv, ev)               # "manda esse aí" depois da lista: qual deles?
    # já saiu para essa pessoa: "já te enviei, tem interesse?" (vem antes do portão: do imóvel que ele já tem, a
    # pergunta certa é essa, e o sim dele vale como a prova do pedido)
    a = ja_enviei.aplicar(cer, conv, a, res, ev.agora, ev.texto)
    conv, a = portao.aplicar(cer, conv, ev, a, tr, juiz)    # é o imóvel que ele pediu? senão, "É este imóvel?"
    if a.tipo == "apresentar":
        with tr.medir("acoes", "card", a.codigo) as e:
            res["card"] = e.saida = card(cer, a.codigo, conv.filtro_finalidade)
        if res["card"].dados.get("recusa"):
            conv, a = maquina.escalar(conv, ev, f"imóvel {a.codigo}: {res['card'].dados['recusa']}")
    if a.tipo in ("apresentar", "fotos") and (a.com_fotos or a.tipo == "fotos"):
        _fotos(cer, a, res, tr)
    multiplos.ferramenta(cer, conv, a, res, tr)       # o imóvel que vai na frente do pedido novo (12/10)
    if a.tipo == "responder_varios":        # "os dois são mobiliados né": a ficha de cada um, ou "qual deles?"
        conv, a = varios.responder(cer, conv, a, res)
    if a.tipo == "perguntar_qual":
        res["qual"] = _qual(cer, a.candidatos, conv.filtro_finalidade)
    if a.tipo == "responder_ficha":
        conv, a = duvida.ficha_ou_duvida(cer, conv, ev, a, res, tr, modelos)
    if a.tipo == "apresentar_varios":
        conv, a = varios.preparar(cer, conv, ev, a, res, tr)
    return conv, a, res


def permitido(cer: Cerebro, conv: Conversa, ev: Evento, a: Acao, res: dict) -> Permitido:
    rs = list(res.values())
    dele = set(ev.contexto.literais) | set(ev.contexto.candidatos) | set(ev.condominio_codigos) | (
        {ev.contexto.codigo} if ev.contexto.origem in ("citacao", "literal", "card", "lista") else set())
    return Permitido(
        codigos=frozenset().union(*(r.codigos for r in rs)) if rs else frozenset(),
        valores=frozenset().union(*(r.valores for r in rs)) if rs else frozenset(),
        fotos=frozenset(u for r in rs for _, u in r.fotos), codigos_dele=frozenset(c for c in dele if c),
        finalidade=conv.filtro_finalidade, acao=a.tipo, catalogo=cer.catalogo)


# ------------------------------------------------------------------ as peças
def _txt(nome: str, b: Base, codigo: int | None = None, **mais) -> Peca:
    return Peca("texto", texto=compor(nome, b.ctx(**{"codigo": codigo, **mais})), codigo=codigo, motivo=nome)


def _tel(nome: str, b: Base, **mais) -> Peca:
    return Peca("texto", texto=compor(nome, b.ctx(**mais)), motivo="aviso_tel", papel_destino="tel")


def _de_novo(a: Acao, b: Base) -> list[Peca]:
    """O aviso de quem recebe de novo o que já tinha recebido (ele confirmou ou pediu de novo)."""
    d = a.dados.get("de_novo")
    return [_txt("mandando_de_novo", b, **d)] if d else []


def _fotos_e_fecho(a: Acao, res: dict, b: Base, avisa: bool = True) -> list[Peca]:
    r = res.get("fotos")
    # a pergunta que veio junto com o pedido das fotos: respondida DEPOIS das fotos, para não dividir as imagens
    resposta = _resposta(res, a) if a.pergunta else []
    if not r or not r.fotos:
        return [_txt("sem_fotos", b)] + resposta
    fecho = "depois_das_fotos" if a.sugerir_visita else "depois_das_fotos_sem_visita"
    if a.sugerir_visita and a.dados.get("fecho"):
        # o código digitado e o card colado fecham com "Tem alguma dúvida ou quer agendar uma visita?" (Tel, 07/10).
        # A frase oferece a visita, então segue a regra de 1 sugestão por dia: da segunda vez, só "Aqui as fotos".
        fecho = a.dados["fecho"]
    imagens = [Peca("imagem", imagem_url=u, codigo=c, motivo="foto") for c, u in r.fotos]
    return (_de_novo(a, b) if avisa else []) + imagens + [_txt(fecho, b, codigo=a.codigo)] + resposta


def _apresentar(a: Acao, res: dict, b: Base) -> list[Peca]:
    r = res.get("card")
    fora = bool(r and r.dados.get("fora_do_mercado"))
    itens: list[Peca] = []
    if fora:
        return [Peca("texto", texto=r.texto_pronto, codigo=a.codigo, motivo="indisponivel")]
    if a.dados.get("oferece_visita"):       # "tenho um cliente interessado nesse": as informações e a visita (13913)
        ficha = [Peca("texto", texto=r.texto_pronto, codigo=a.codigo, motivo="card")] if a.com_card and r else []
        return ficha + [_txt("quer_agendar_visita", b, codigo=a.codigo)]
    if a.com_status or not (a.com_card or a.com_fotos):      # só perguntou, ou colou o card sem pedir: a situação
        so = not (a.com_card or a.com_fotos)                # "[diz que sim]" (Tel, 02/10) e oferece o resto
        nome = "status_so" if so else "status_disponivel"
        if so and cumprimentou(b.texto_dele):              # cumprimentou: cumprimenta de volta (só "Bom dia" em
            nome = "status_so_cumprimento" if pediu_status(b.texto_dele) else "status_so_marcou"   # cima do card)
        itens.append(_txt(nome, b, codigo=a.codigo))
    itens += _de_novo(a, b)
    if a.com_card and r and r.texto_pronto:
        itens.append(Peca("texto", texto=r.texto_pronto, codigo=a.codigo, motivo="card"))
    if a.com_fotos:
        itens += _fotos_e_fecho(a, res, b, avisa=False)
    return itens


def _filtro(a: Acao, b: Base) -> list[Peca]:
    nome, fin = f"pergunta_{a.filtro}", b.conversa.filtro_finalidade
    if a.filtro == "regiao" and b.conversa.veio_do_grupo and fin in FINALIDADE:
        nome = "pergunta_regiao_veio_do_grupo"
    # A mesma pergunta pela segunda vez seguida (ele respondeu outra coisa) não sai igual (Tel, 06/10, rodada 5,
    # conversa 13918: "Até que valor o seu cliente quer?" três vezes): "Entendo! Só para continuarmos nossa busca
    # aqui no sistema, até qual valor seu cliente quer?". `b.conversa` ainda tem a última pergunta DE ANTES.
    # Da terceira vez em diante a frase ALTERNA entre as duas reformulações (rodada 7: a terceira saía igual à
    # segunda): nunca duas mensagens iguais seguidas.
    antes = b.conversa
    repete = antes.ultima_pergunta == a.filtro and antes.ultima_acao in (f"pergunta_{a.filtro}", "repetiu_pergunta")
    variantes = [n for n in (f"pergunta_{a.filtro}_de_novo", f"pergunta_{a.filtro}_de_novo_2") if existe(n)]
    if repete and variantes:
        nome = variantes[(max(antes.pergunta_vezes, 1) - 1) % len(variantes)]   # 0 = conversa de antes da 024
    return [_txt(nome, b, finalidade_texto=FINALIDADE.get(fin or "", ""))]


def _escalar(a: Acao, b: Base) -> list[Peca]:
    if a.template == "recebi_midia":
        aviso = _tel("aviso_tel_midia", b, codigo=b.conversa.foco_codigo, texto=b.texto_dele[:200] or None, **a.dados)
    elif a.dados.get("aviso"):
        aviso = _tel(a.dados["aviso"], b, codigo=a.codigo or b.conversa.foco_codigo, texto=b.texto_dele[:200],
                     **{k: v for k, v in a.dados.items() if k != "aviso"})
    else:
        aviso = _tel("aviso_tel_duvida", b, codigo=a.codigo or b.conversa.foco_codigo or "?",
                     pergunta=(a.pergunta or b.texto_dele)[:200])
    return [_txt(a.template or "escalado", b), aviso, *grupo.aviso(a, b)]   # 24/10: e ao grupo da equipe


def _fotos(cer: Cerebro, a: Acao, res: dict, tr: Trace) -> None:
    with tr.medir("acoes", "fotos", a.codigo) as e:
        res["fotos"] = e.saida = fotos(cer, a.codigo)
    if a.tipo == "fotos" and a.pergunta:        # "qual andar? manda as fotos": a ficha responde junto (12/10)
        with tr.medir("acoes", "responder_ficha", a.codigo) as e:
            res["responder_ficha"] = e.saida = responder_ficha(cer, a.codigo, a.pergunta)


def _resposta(res: dict, a: Acao) -> list[Peca]:
    if res.get("duvida"):
        return [Peca("texto", texto=res["duvida"].texto_pronto, codigo=a.codigo, motivo="resposta_duvida_luna")]
    r = res.get("responder_ficha")
    if not r or not r.texto_pronto:
        return []
    return [Peca("texto", texto=r.texto_pronto, codigo=a.codigo, motivo="resposta_ficha")]


def _da_visita(a: Acao, b: Base) -> list[Peca]:
    """A pergunta do dia e da hora, a confirmação dos dados ou o "anotei" (com o aviso ao Tel)."""
    itens = [_txt(a.template or "visita_entregue", b, codigo=a.codigo, **a.dados)]
    if a.template == "visita_anotada":
        # O que vem depois do "sim" (proprietário, Rayssa, a etapa Visitas do CRM e a Nay calada) é do sistema
        # velho: no modo real o worker chama a ponte (saida/visita_velha.py, migração 302 do nayia) e este aviso
        # sai da caixa, porque o velho manda o dele. Em sombra e no treino fica só este aviso.
        itens.append(_tel("aviso_tel_visita_confirmada", b, codigo=a.codigo, **a.dados))
    return itens


@no("composicao.pecas")
def pecas(a: Acao, res: dict[str, ResultadoFerramenta], b: Base) -> list[Peca]:
    """Da ação e do que ela buscou, as mensagens na ordem em que saem."""
    aviso = res.get("aviso")
    antes = [Peca("texto", texto=aviso.texto_pronto, motivo="condominio_sem_oferta")] if aviso else []
    return antes + multiplos.pecas(a, res) + _pecas(a, res, b)


def _pecas(a: Acao, res: dict[str, ResultadoFerramenta], b: Base) -> list[Peca]:      # noqa: C901
    t = a.tipo
    if t == "fora_da_lista":
        return [_tel("aviso_tel_fora_da_lista", b, texto=b.texto_dele[:200])] if a.dados.get("perguntou") else []
    if t == "template":
        dados = {**a.dados, **({"opcoes": " ou ".join(a.dados["candidatos"])} if "candidatos" in a.dados else {})}
        return [_txt(a.template, b, codigo=dados.pop("codigo", a.codigo), **dados)]
    if t == "perguntar_filtro":
        return _filtro(a, b)
    if t == "buscar":
        d = res["buscar"].dados
        # o pedido mudou e o que cabe ele já tem de hoje: "Está perguntando para outro cliente, certo?" (10/10)
        outro = [_txt("outro_cliente", b)] if a.dados.get("pergunta_outro_cliente") else []
        if d.get("vazio"):
            return [_txt("so_o_de_hoje", b, **d)] + outro if outro else [_txt("lista_vazia", b, **d)]
        # os bairros ao redor vão em mensagem separada (Pedro, 02/10); a pergunta fecha a última
        ao_redor = [_txt("lista_ao_redor", b, **d)] if d.get("tem_ao_redor") else []
        return [_txt("lista", b, **d, fecha=not ao_redor)] + ao_redor + outro
    if t == "apresentar":
        return _apresentar(a, res, b)
    if t == "apresentar_varios":
        itens = varios.pecas(a, res)
        if a.dados.get("opcoes"):           # um dos nomes serve a dois da lista: os certos, e "qual deles?" do resto
            return itens + [_txt("qual_da_lista", b, opcoes=a.dados["opcoes"])]
        if a.dados.get("da_busca"):         # a busca achou 2 ou 3: os cards completos no lugar da lista (12/10)
            abre = _txt("achei_poucos", b, qtd_texto=a.dados.get("qtd_texto"), onde=a.dados.get("onde"))
            return [abre] + itens + [_txt("depois_dos_cards", b)]
        if a.dados.get("so_cards"):         # mais de 2 de uma vez: só os cards, e as fotos quando ele pedir
            return itens + [_txt("depois_dos_cards", b)]
        fecho = a.sugerir_visita and any(i.tipo == "imagem" for i in itens)
        return itens + ([_txt("depois_dos_varios", b)] if fecho else [])
    if t == "fotos":
        return _fotos_e_fecho(a, res, b)
    if t == "perguntar_qual":
        cands = res["qual"].dados["candidatos"] if res.get("qual") else []
        busca = bool(a.dados.get("oferta"))      # a busca deste turno achou um só: é oferta, não "É este?"
        return [_txt("confirmar_imovel" if len(cands) == 1 else "qual_deles", b, candidatos=cands,
                     da_busca=busca, citado=not busca)]
    if t == "responder_ficha":
        return _resposta(res, a)
    if t == "responder_varios":
        return [Peca("texto", texto=res["responder_varios"].texto_pronto, motivo="resposta_ficha")]
    if t == "pendencia":        # o que se sabe, o "vou precisar confirmar" do resto e a pergunta ao Tel
        return _resposta(res, a) + [
            _txt(a.template, b, faltou=a.dados.get("faltou")),
            _tel("aviso_tel_pendencia", b, codigo=a.codigo or "?", pergunta=(a.pergunta or b.texto_dele)[:300],
                 faltou=a.dados.get("faltou"))]
    if t == "visita_pedida":
        return _da_visita(a, b)
    if t == "escalar":
        return _escalar(a, b)
    return []          # silencio, fora_do_escopo


def compor_validado(a: Acao, res: dict, b: Base, perm: Permitido,
                    tr: Trace) -> tuple[list[Peca], Veredito, str | None]:
    """(peças, veredito, se vetou: None | escala | escala_duvida | silencio). `regenera` não escala."""
    isentos = ISENTOS.get(a.template or "", frozenset())
    itens = pecas(a, res, b)
    v = validar(itens, perm, isentos)
    tr.registrar("validador", "validar", [i.texto for i in itens if i.texto], v.vetos)
    if v.passou:
        return itens, v, None
    if any(i.motivo == "resposta_duvida_luna" for i in itens):
        ficha = res.get("responder_ficha")
        if ficha and ficha.dados.get("respondeu"):       # o texto da Luna caiu: vale a frase da ficha
            res.pop("duvida", None)
            return compor_validado(a, res, b, perm, tr)
        return [], v, "escala_duvida"
    acao = v.vetos[0][2]
    if acao in ("silencio", "escala"):
        return [], v, acao
    limpos = saneado(itens, perm, v, isentos)        # veto só de forma: tira o emoji e a resposta vale
    return (limpos, Veredito(), None) if limpos else ([], v, "escala_duvida")

"""Zona e vizinhos (setor cérebro), de bairro_zona e bairro_vizinho.
"Aqui perto" = vizinho cadastrado à mão; na falta, a mesma zona. "Um pouco mais longe" = bairro cujo centro (a
média dos imóveis localizados nele, imovel_geo) fica até tantos km de um dos bairros pedidos."""
from __future__ import annotations

from collections import defaultdict
from math import cos, radians, sqrt

from nay.texto import normal


class Bairros:
    def __init__(self, zonas: dict[str, str], vizinhos: list[tuple[str, str]],
                 centros: dict[str, tuple[float, float]] | None = None) -> None:
        self._centro = {normal(b): (float(p[0]), float(p[1])) for b, p in (centros or {}).items()}
        self._zona = {normal(b): z for b, z in zonas.items()}
        self._viz: dict[str, set[str]] = defaultdict(set)
        for a, b in vizinhos:
            self._viz[normal(a)].add(normal(b))
            self._viz[normal(b)].add(normal(a))

    def zona(self, bairro_norm: str) -> str | None:
        return self._zona.get(bairro_norm)

    def perto(self, bairro_norm: str) -> list[str]:
        """Vizinhos primeiro; se não houver, os da mesma zona. Nunca ele mesmo."""
        viz = sorted(self._viz.get(bairro_norm, set()) - {bairro_norm})
        if viz:
            return viz
        z = self.zona(bairro_norm)
        return sorted(b for b, zz in self._zona.items() if zz == z and b != bairro_norm) if z else []

    def km(self, a: str, b: str) -> float | None:
        """A distância em linha reta entre os centros de dois bairros (None se algum não tem imóvel localizado)."""
        p, q = self._centro.get(a), self._centro.get(b)
        if not p or not q:
            return None
        return 111.2 * sqrt((p[0] - q[0]) ** 2 + ((p[1] - q[1]) * cos(radians(p[0]))) ** 2)

    def um_pouco_mais_longe(self, pedidos: tuple[str, ...], ate_km: float, fora: set[str]) -> list[str]:
        """Os bairros até `ate_km` de algum dos pedidos, tirando os de `fora` (os pedidos e os vizinhos, que já
        foram procurados), do mais perto para o mais longe."""
        achados: dict[str, float] = {}
        for outro in self._centro:
            if outro in fora:
                continue
            d = [x for x in (self.km(p, outro) for p in pedidos) if x is not None]
            if d and min(d) <= ate_km:
                achados[outro] = min(d)
        return sorted(achados, key=achados.get)

"""O catálogo em memória (setor cérebro). Lido de core_imovel_busca (5,7 mil
linhas) e recarregado pelo worker junto com o REFRESH: toda consulta da Nay é
um filtro em memória, em microssegundos, sem ida ao banco por mensagem.

Ofertável = disponível, não bloqueado, publicado, não parceiro, com preço na
finalidade (calculado uma vez na visão, migração 005). `no_mercado` sem preço
só sai pelo código.
"""
from __future__ import annotations

from dataclasses import dataclass, replace

from nay.config import cfg
from nay.texto import normal
from nay.tipos import Imovel

TIPOS_CASA = {"casa", "casa_condominio"}
# A pergunta dela é "casa ou apartamento?": quem responde "os dois" (ou escreve "casa/apto", 13853) recebia também
# "Sala/Andar" na lista, porque tanto faz valia para qualquer tipo.
TIPOS_MORADIA = TIPOS_CASA | {"apartamento", "flat", "cobertura"}


@dataclass(frozen=True)
class Filtros:
    finalidade: str | None = None          # locacao | venda | ambos | tanto_faz
    tipo: str | None = None                # apartamento | casa | casa_condominio | ... | tanto_faz
    teto: float | None = None
    bairros: tuple[str, ...] = ()          # bairro_norm; vazio = cidade toda
    quartos: int | None = None
    mobilia: str | None = None             # mobiliado | semi | nao | tanto_faz
    # sem o piso da faixa: só na segunda busca, quando a faixa firme não achou nada (Tel, 06/10; acoes/buscar.py)
    sem_piso: bool = False
    piso: float | None = None              # o mínimo dito por ele (faixa ou "a partir de"); vale no lugar dos -25%
    tipos: tuple[str, ...] = ()            # os tipos que ele pediu de uma vez, quando "tanto faz" não os cobre


class Catalogo:
    def __init__(self, imoveis: list[Imovel]) -> None:
        # a forma normal é SEMPRE a do Python (nay.texto.normal): a da visão
        # guarda pontuação ("conj. castelo branco") e as duas divergiriam.
        self._por_codigo = {
            i.codigo: replace(i, bairro_norm=normal(i.bairro), condominio_norm=normal(i.condominio_nome))
            for i in imoveis}

    def get(self, codigo: int) -> Imovel | None:
        return self._por_codigo.get(codigo)

    def existe(self, codigo: int) -> bool:
        return codigo in self._por_codigo

    def todos(self) -> list[Imovel]:
        return list(self._por_codigo.values())

    def ofertaveis(self) -> list[Imovel]:
        return [i for i in self._por_codigo.values() if i.ofertavel]

    def bairros_ofertaveis(self) -> dict[str, str]:
        """bairro_norm -> nome como está no cadastro."""
        return {i.bairro_norm: i.bairro for i in self.ofertaveis() if i.bairro}

    def condominios(self) -> dict[str, list[int]]:
        """condominio_norm -> códigos (todo o cadastro: reconhecer o nome não é poder oferecer)."""
        saida: dict[str, list[int]] = {}
        for i in self._por_codigo.values():
            if i.condominio_norm:
                saida.setdefault(i.condominio_norm, []).append(i.codigo)
        return saida

    def buscar(self, f: Filtros) -> list[Imovel]:
        return sorted((i for i in self.ofertaveis() if serve(i, f)), key=lambda i: (preco(i, f) or 0, i.codigo))


def preco(i: Imovel, f: Filtros) -> float | None:
    """O preço do imóvel na finalidade da busca. Sem finalidade ("alugar ou comprar", "tanto faz"), o preço que
    cabe na faixa do teto: em 03/10 um corretor com "os dois" pediu apartamento até 450 mil e a busca comparou
    o teto só com o ALUGUEL -- imóvel à venda nunca aparecia."""
    if f.finalidade == "venda":
        return i.valor_venda
    if f.finalidade == "locacao" or not (f.teto or f.piso):
        return i.valor_aluguel
    if na_faixa(i.valor_aluguel, f.teto, piso=f.piso):
        return i.valor_aluguel
    return i.valor_venda if na_faixa(i.valor_venda, f.teto, piso=f.piso) else (i.valor_aluguel or i.valor_venda)


def _finalidade_serve(i: Imovel, fin: str | None) -> bool:
    if fin == "locacao":
        return i.de_locacao
    if fin == "venda":
        return i.de_venda
    return True


# "Prédio" e "Galpão/Depósito" chegam do banco como tipo "outro": casam pelo nome do cadastro (13/10)
PELO_NOME = {"predio": ("predio",), "galpao": ("galpao", "deposito")}


def _e_do_nome(i: Imovel, tipo: str) -> bool:
    return normal(i.tipo_original or "").startswith(PELO_NOME[tipo])


def _tipo_serve(i: Imovel, tipo: str | None) -> bool:
    if not tipo:
        return True
    if tipo in PELO_NOME:
        return _e_do_nome(i, tipo)
    if tipo == "comercial":                # "algo comercial": sala, loja, prédio ou galpão
        return i.tipo in ("sala", "loja") or _e_do_nome(i, "predio") or _e_do_nome(i, "galpao")
    if tipo == "tanto_faz":                # "casa ou apartamento, tanto faz" é moradia: sala e loja não entram
        return i.tipo in TIPOS_MORADIA
    if tipo == "casa":                     # "casa" cobre a de condomínio; o contrário não
        return i.tipo in TIPOS_CASA
    return i.tipo == tipo


def _tipos_servem(i: Imovel, f: Filtros) -> bool:
    """`tipos` (vários pedidos de uma vez) manda em `tipo`."""
    return any(_tipo_serve(i, t) for t in f.tipos) if f.tipos else _tipo_serve(i, f.tipo)


def tipos_pedidos(f: Filtros, tipos: tuple[str, ...]) -> tuple[str, ...]:
    """Os tipos que ele pediu e que o filtro gravado NÃO cobre: "tanto faz" é MORADIA (casa ou apartamento),
    então quem pede sala, loja, terreno, prédio ou galpão junto precisa que a busca procure esses tipos.

    20/10/2026, ...9091: "Nay, vocês tem alguma oportunidade para investimento? Sala comercial ou terreno
    apenas" recebeu "De sala nem terreno eu não tenho nesse perfil agora" seguido de cinco APARTAMENTOS de
    3 quartos. Quatro minutos depois, com o tipo já gravado como comercial, a mesma busca achou a sala 1315
    (R$ 700 mil) e o prédio 3971 (R$ 1,285 milhão): ela tinha os dois e disse que não tinha."""
    if f.tipo not in (None, "tanto_faz") or not tipos:
        return ()
    return tuple(dict.fromkeys(tipos)) if any(t not in TIPOS_MORADIA for t in tipos) else ()


def serve(i: Imovel, f: Filtros) -> bool:
    if not _finalidade_serve(i, f.finalidade) or not _tipos_servem(i, f):
        return False
    p = preco(i, f)
    if (f.teto or f.piso) and not na_faixa(p, f.teto, f.sem_piso and f.finalidade in ("locacao", "venda"), f.piso):
        return False
    if f.bairros and i.bairro_norm not in f.bairros:
        return False
    if f.quartos and (i.quartos or 0) < f.quartos:
        return False
    if f.mobilia in ("mobiliado", "semi") and i.mobilia != f.mobilia:
        return False
    return True


def na_faixa(preco_do_imovel: float | None, teto: float | None, sem_piso: bool = False,
             piso: float | None = None) -> bool:
    """A faixa do valor (config/filtros.yaml). Um valor só ("até 6 mil", "por volta de 6 mil"): de 25% abaixo a
    10% acima (Tel, 06/10: "sempre até 25% a menos ou 10% a mais"). Com `piso` ("entre 3.500 e 4.500"): do piso ao
    teto, com os 10% só em cima; piso sem teto ("a partir de 5 mil"): do piso para cima. `sem_piso`: só o limite de
    cima (a lista que ele ACEITOU ver do que é mais barato); acima da tolerância, nunca."""
    fx = cfg("filtros")
    if not preco_do_imovel:
        return False
    minimo = 0 if sem_piso else piso if piso is not None else (teto or 0) * (1 - fx["teto_faixa_abaixo_pct"] / 100)
    maximo = teto * (1 + fx["teto_faixa_acima_pct"] / 100) if teto else float("inf")
    return minimo <= preco_do_imovel <= maximo

"""A fachada do setor cérebro: o que o banco sabe, num objeto só.

Carrega o catálogo, as zonas e os vizinhos em memória (`recarregar`, chamado
pelo worker depois de cada REFRESH) e responde por eles sem ir ao banco;
ficha, fotos e citação vão à fonte na hora, uma consulta com índice cada.
"""
from __future__ import annotations

import time
from typing import Any

from nay.cerebro.apelidos import Resolucao, e_bairro, resolver_bairro, resolver_condominio, resolver_varios
from nay.cerebro.bairros import Bairros
from nay.cerebro.catalogo import Catalogo
from nay.cerebro.fonte import Fonte
from nay.cerebro.proximos import Proximos
from nay.config import cfg
from nay.texto import normal


class Cerebro:
    def __init__(self, fonte: Fonte) -> None:
        self.fonte = fonte
        self.carregado_em = 0.0
        self.recarregar()

    def recarregar(self) -> None:
        self.catalogo = Catalogo(self.fonte.imoveis())
        zonas = self.fonte.zonas()
        self.bairros = Bairros(zonas, self.fonte.vizinhos(), self.fonte.centros())
        self._zonas = zonas
        self._conhecidos = {normal(b): b for b in zonas} | {
            i.bairro_norm: i.bairro for i in self.catalogo.todos() if i.bairro}
        self._ofertaveis = self.catalogo.bairros_ofertaveis()
        self._condominios = self.catalogo.condominios()
        self.proximos = Proximos(self.fonte.condominios_proximos())   # a planilha dos condomínios próximos (433)
        self.carregado_em = time.time()

    @property
    def zonas(self) -> dict[str, str]:
        """Os bairros do catálogo (bairro_zona): nome -> zona."""
        return self._zonas

    def nome_do_bairro(self, bairro_norm: str) -> str:
        return self._conhecidos.get(bairro_norm, bairro_norm.title())

    def resolver_bairro(self, escrito: str) -> Resolucao:
        return resolver_bairro(escrito, self._conhecidos, self._ofertaveis, self._zonas)

    def resolver_varios(self, escrito: str) -> Resolucao:
        """A resposta à pergunta de região, que pode trazer vários lugares de uma vez."""
        return resolver_varios(escrito, self._conhecidos, self._ofertaveis, self._zonas)

    def resolver_condominio(self, escrito: str) -> tuple[str, list[int]] | None:
        # nome de bairro só vira condomínio se houver um condomínio com esse nome inteiro (turno 12592)
        return resolver_condominio(escrito, self._condominios, so_exato=e_bairro(escrito, self._conhecidos))

    def bairro_citado(self, texto: str, fora: tuple[str, ...] = ()) -> str | None:
        """O nome (do cadastro) do bairro que aparece escrito no texto, o mais comprido primeiro. `fora`: formas
        normais que não contam (o bairro do próprio imóvel, o nome do condomínio dele)."""
        t = f" {normal(texto)} "
        for forma in sorted(self._conhecidos, key=len, reverse=True):
            if len(forma) >= 5 and f" {forma} " in t and not any(forma in f for f in fora if f):
                return self._conhecidos[forma]
        return None

    def ficha(self, codigo: int) -> dict[str, Any] | None:
        return self.fonte.ficha(codigo)

    def fotos(self, codigo: int) -> list[str]:
        return self.fonte.fotos(codigo)

    def citacao(self, message_id: str | None) -> list[int]:
        return self.fonte.codigos_da_citacao(message_id) if message_id else []

    def enviados(self, chave: str, ate=None, desde=None) -> set[int]:
        """Os códigos que essa pessoa já recebeu (de `desde` até `ate`): a busca não os propõe de novo.
        `desde` é o começo do pedido de hoje (estado/prazos.py, `conta_desde`); None = desde sempre."""
        return self.fonte.enviados(chave, ate, desde)

    def agenda(self, de, ate) -> list[dict[str, Any]]:
        """A agenda única de visitas (nayia 497) no intervalo; sem o banco, vazia (a confirmação segue)."""
        try:
            return self.fonte.agenda(de, ate)
        except Exception:  # noqa: BLE001 -- a agenda ajuda, não trava a visita
            return []

    def ja_enviado(self, chave: str, codigo: int, ate=None, desde=None):
        """O que já saiu deste imóvel para esta pessoa (card e fotos, cada um com a sua data), de `desde` até
        `ate`. `nao_reenviar_mesmo_imovel_h: 0` = sem prazo em horas (quem limita é o `desde`)."""
        return self.fonte.ja_enviado(chave, codigo, int(cfg("limites")["nao_reenviar_mesmo_imovel_h"]), ate, desde)

"""De onde o cérebro lê (setor cérebro). Duas implementações do mesmo contrato:
`FontePostgres` (cerebro/repo.py, produção, só leitura) e `FonteMemoria`
(aqui, testes e replay: um JSON exportado do banco, sem dono nem telefone)."""
from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any, Protocol

from nay.tipos import Enviado, Imovel

CAMPOS_IMOVEL = set(Imovel.__dataclass_fields__)


def imovel_de(d: dict[str, Any]) -> Imovel:
    return Imovel(**{k: v for k, v in d.items() if k in CAMPOS_IMOVEL})


class Fonte(Protocol):
    def imoveis(self) -> list[Imovel]: ...
    def zonas(self) -> dict[str, str]: ...
    def vizinhos(self) -> list[tuple[str, str]]: ...
    def centros(self) -> dict[str, tuple[float, float]]: ...
    def ficha(self, codigo: int) -> dict[str, Any] | None: ...
    def fotos(self, codigo: int) -> list[str]: ...
    def codigos_da_citacao(self, message_id: str) -> list[int]: ...
    def chaves_irmas(self, chave: str) -> set[str]: ...
    def papel_equipe(self, chave: str) -> str | None: ...
    def e_proprietario(self, chave: str) -> bool: ...
    def corretor_da_lista(self, chave: str) -> bool: ...
    def ja_enviado(self, chave: str, codigo: int, horas: int, ate: datetime | None = None,
                   desde: datetime | None = None) -> Enviado | None: ...
    def enviados(self, chave: str, ate: datetime | None = None, desde: datetime | None = None) -> set[int]: ...
    def condominios_proximos(self) -> list[dict[str, Any]]: ...
    def agenda(self, de: datetime, ate: datetime) -> list[dict[str, Any]]: ...


class FonteMemoria:
    """Tudo em memória, a partir de um dicionário (tests/fixtures/catalogo.json)."""

    def __init__(self, dados: dict[str, Any]) -> None:
        self._d = dados

    @classmethod
    def de_arquivo(cls, caminho: str | Path) -> FonteMemoria:
        return cls(json.loads(Path(caminho).read_text(encoding="utf-8")))

    def imoveis(self) -> list[Imovel]:
        return [imovel_de(d) for d in self._d.get("imoveis", [])]

    def zonas(self) -> dict[str, str]:
        return dict(self._d.get("zonas", {}))

    def vizinhos(self) -> list[tuple[str, str]]:
        return [tuple(p) for p in self._d.get("vizinhos", [])]

    def centros(self) -> dict[str, tuple[float, float]]:
        return {b: (p[0], p[1]) for b, p in self._d.get("centros", {}).items()}

    def ficha(self, codigo: int) -> dict[str, Any] | None:
        return self._d.get("fichas", {}).get(str(codigo))

    def fotos(self, codigo: int) -> list[str]:
        f = self._d.get("fotos", {})
        if str(codigo) in f:
            return list(f[str(codigo)])
        im = next((i for i in self._d.get("imoveis", []) if i["codigo"] == codigo), None)
        n = im["qtd_fotos"] if im else 0
        return [f"https://imobeasy.com/system/pictures/{codigo}/{k}.jpg" for k in range(1, n + 1)]

    def codigos_da_citacao(self, message_id: str) -> list[int]:
        return list(self._d.get("citacoes", {}).get(message_id, []))

    def chaves_irmas(self, chave: str) -> set[str]:
        return set(self._d.get("irmas", {}).get(chave, []))

    def papel_equipe(self, chave: str) -> str | None:
        return self._d.get("equipe", {}).get(chave)

    def e_proprietario(self, chave: str) -> bool:
        return chave in self._d.get("proprietarios", self._d.get("proprietarios_com_visita", []))

    def corretor_da_lista(self, chave: str) -> bool:
        return chave not in self._d.get("fora_da_lista", [])

    def ja_enviado(self, chave: str, codigo: int, horas: int, ate: datetime | None = None,
                   desde: datetime | None = None) -> Enviado | None:
        """`enviados`: "chave:codigo" -> a data (card e fotos saíram juntos) ou {"card": data, "fotos": data}.
        `na_fila` no dicionário: já saiu da decisão mas está esperando na caixa, nada chegou à pessoa."""
        v = self._d.get("enviados", {}).get(f"{chave}:{codigo}")
        if isinstance(v, str):
            v = {"card": v, "fotos": v}
        dia = {k: datetime.fromisoformat(v[k]) if v and v.get(k) else None for k in ("card", "fotos")}
        dia = {k: q if q and (ate is None or q < ate) and (desde is None or q >= desde) else None
               for k, q in dia.items()}
        if dia["card"] is None and dia["fotos"] is None:
            return None
        return Enviado(card=dia["card"], fotos=dia["fotos"], vezes=int(v.get("vezes", 1)),
                       na_fila=bool(v.get("na_fila", False)))

    def enviados(self, chave: str, ate: datetime | None = None, desde: datetime | None = None) -> set[int]:
        codigos = {int(k.split(":")[1]) for k in self._d.get("enviados", {}) if k.startswith(f"{chave}:")}
        return {c for c in codigos if self.ja_enviado(chave, c, 0, ate, desde)}

    def condominios_proximos(self) -> list[dict[str, Any]]:
        return list(self._d.get("condominios_proximos", []))

    def agenda(self, de: datetime, ate: datetime) -> list[dict[str, Any]]:
        """`agenda`: as visitas da agenda única ({quando ISO, chave, codigo, com_motoboy}), no intervalo."""
        return [v for v in self._d.get("agenda", []) if de <= datetime.fromisoformat(v["quando"]) < ate]

    def anotar_envio(self, chave: str, codigo: int, o_que: set[str], quando: datetime) -> None:
        """Testes e replay: o card ou as fotos que saíram neste turno passam a contar nos próximos."""
        e = self._d.setdefault("enviados", {})
        v = e.get(f"{chave}:{codigo}") or {"vezes": 0}
        if isinstance(v, str):
            v = {"card": v, "fotos": v, "vezes": 1}
        for peca, campo in (("card", "card"), ("foto", "fotos")):
            if peca in o_que:
                v[campo] = quando.isoformat()
        e[f"{chave}:{codigo}"] = {**v, "vezes": int(v.get("vezes", 0)) + 1}

"""O dono do imóvel (setor cérebro), lido de core_imovel_dono (migração 005):
imoveis.proprietario_id, depois imovel_privado, depois o admin com um dono só.

Na entrega 1 ninguém fala com o dono (a visita é da entrega 2). Isto existe
para a máquina de visita saber, ao marcar VISITA_PEDIDA, se haverá com quem
falar e se o telefone é repetido entre donos (conferir antes).
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class Dono:
    codigo: int
    origem: str | None               # imovel | privado | admin | None
    tem_telefone: bool
    dois_donos: bool
    tratar_com_outra_pessoa: bool
    mesmo_telefone_em: tuple[int, ...]

    @property
    def alcancavel(self) -> bool:
        return self.tem_telefone and not self.dois_donos and not self.tratar_com_outra_pessoa

    @property
    def conferir_antes(self) -> bool:
        return bool(self.mesmo_telefone_em)


def de_linha(linha: dict[str, Any] | None) -> Dono | None:
    if not linha:
        return None
    return Dono(
        codigo=linha["codigo"], origem=linha.get("origem"),
        tem_telefone=bool(linha.get("telefone_digitos")),
        dois_donos=bool(linha.get("dois_donos")),
        tratar_com_outra_pessoa=bool(linha.get("tratar_com_outra_pessoa")),
        mesmo_telefone_em=tuple(linha.get("mesmo_telefone_em") or ()),
    )

"""OS CONDOMÍNIOS PRÓXIMOS (setor cérebro). Pedro, 20/10/2026.

"Coloquei uma planilha ... para que quando a Nay for buscar imóveis em condomínios próximos ela possa consultar ...
se o cara pede condomínio normal ela relaciona primariamente os normais, se o cara pede um imóvel em um condomínio que
é novo, ou seja feito nos últimos 5 anos, ela deve priorizar enviar os imóveis em condomínios novos ... caso ela não
ache nos condomínios novos ou normais ela pode buscar em um ou em outro, mas a prioridade é assim."

A planilha mora no naydb (nayia 433: `condominio_proximo` + `condominio_proximo_nomes`): para cada condomínio, o
bairro, se é recente e a lista dos próximos, em dois blocos (os do mesmo bairro, depois os da região). Aqui ela vira
a ORDEM da busca (acoes/buscar.py): com o condomínio que ele pediu como referência (`filtro_condominio`), vêm primeiro
os imóveis dos condomínios próximos da MESMA classe (recente com recente, normal com normal), os do mesmo bairro antes;
depois os próximos da outra classe; depois o resto, como sempre (pelo preço). Nada sai da lista: só a ordem muda.
"Condomínio novo" sem nome (frases.CONDOMINIO_NOVO) põe os recentes na frente.

Também serve para o condomínio que a planilha conhece e o catálogo não (nenhum imóvel nosso lá): o bairro dele vem da
planilha, e a busca segue por perto (contexto/lugares.py).
"""
from __future__ import annotations

import re
from typing import Any

from nay.cerebro.apelidos import resolver_condominio
from nay.texto import normal
from nay.tipos import Imovel

NORTE_SUL = re.compile(r"\s+(norte|sul|leste|oeste)$")


def _bairros(texto: str | None) -> tuple[str, ...]:
    """"Flores Norte, Parque 10 Norte" -> ("flores", "parque 10"): a planilha divide o que o catálogo não divide."""
    return tuple(dict.fromkeys(NORTE_SUL.sub("", normal(b)) for b in (texto or "").split(",") if b.strip()))


def _mesmo_bairro(a: tuple[str, ...], b: tuple[str, ...]) -> bool:
    """Pelo começo do nome, como o banco (privado.bairros_iguais, 438): "parque 10" = "parque 10 de novembro"."""
    return any(x == y or x.startswith(y + " ") or y.startswith(x + " ") for x in a for y in b if x and y)


class Proximos:
    def __init__(self, linhas: list[dict[str, Any]]) -> None:
        self._nome: dict[str, str] = {}             # chave (o nome da planilha, normal) -> o nome como está nela
        self._recente: dict[str, bool] = {}
        self._ano: dict[str, int] = {}              # o ano de lançamento (ficha do condomínio, nayia 436)
        self._bairros: dict[str, tuple[str, ...]] = {}
        self._lista: dict[str, dict[str, tuple[int, bool]]] = {}  # chave -> {próximo: (posição, mesmo bairro)}
        self._de: dict[str, str] = {}               # qualquer jeito de escrever (normal) -> chave
        for r in linhas:
            k = normal(r["nome"])
            self._nome[k], self._recente[k] = r["nome"], bool(r.get("recente"))
            self._bairros[k] = _bairros(r.get("bairro"))
            self._ano[k] = int(r.get("ano") or 0)
            for n in (r["nome"], *(r.get("normas") or ())):
                self._de.setdefault(normal(n), k)
        for r in linhas:
            k = normal(r["nome"])
            self._lista[k] = {normal(p): (pos, _mesmo_bairro(self._bairros[k], self._bairros.get(normal(p), ())))
                              for pos, p in enumerate(r.get("proximos") or ()) if normal(p) in self._nome}
        self._para_resolver = {n: [0] for n in self._de}

    def __bool__(self) -> bool:
        return bool(self._nome)

    def resolver(self, escrito: str) -> str | None:
        """O condomínio da planilha que ele escreveu (o mesmo resolvedor do catálogo: exato, apelido, núcleo...)."""
        achado = resolver_condominio(escrito, self._para_resolver) if self._de else None
        return self._de.get(achado[0]) if achado else None

    def nome(self, chave: str) -> str:
        return self._nome.get(chave, chave)

    def bairros(self, chave: str) -> tuple[str, ...]:
        return self._bairros.get(chave, ())

    def recente(self, chave: str | None) -> bool | None:
        return self._recente.get(chave) if chave else None

    def de(self, i: Imovel) -> str | None:
        """O condomínio da planilha em que o imóvel fica (pelo nome do cadastro)."""
        return self._de.get(normal(i.condominio_nome or "")) or self._de.get(i.condominio_norm or "")

    def perto_de(self, chave: str | None, i: Imovel) -> bool:
        return bool(chave) and self.de(i) in self._lista.get(chave or "", {})

    def _lancamento(self, meu: str | None) -> int:
        """Entre os recentes, "segundo a ordem de lançamento" (Pedro, 20/10): o mais novo primeiro; sem ano, depois."""
        return -self._ano.get(meu or "", 0) if self._recente.get(meu or "") else 0

    def _posto(self, chave: str | None, novo: bool, i: Imovel) -> tuple[int, int, int]:
        meu = self.de(i)
        if chave and meu == chave:
            return (0, 0, 0)
        if chave and meu in self._lista.get(chave, {}):
            _, mesmo = self._lista[chave][meu]
            classe = 1 if self._recente.get(meu) == self._recente.get(chave) else 2
            return (classe, 0 if mesmo else 1, self._lancamento(meu))
        if novo and not chave:
            return (1 if self._recente.get(meu or "") else 3, 0, self._lancamento(meu))
        return (3, 0, 0)

    def ordenar(self, imoveis: list[Imovel], chave: str | None, novo: bool = False) -> list[Imovel]:
        """A ordem da prioridade (estável: dentro de cada degrau fica a ordem de antes, o preço)."""
        if not self or not (chave or novo):
            return imoveis
        return sorted(imoveis, key=lambda i: self._posto(chave, novo, i))

"""A biblioteca de regiões do Tel (setor cérebro): conjunto ou condomínio -> bairro, e as avenidas de cada um.

Os dados moram em regioes.yaml, transcritos da nota dele (06/10, rodada 5 do treino, conversa 13910): "montei uma
biblioteca de regiões para ela saber onde ficam os condomínios ... quando alguém perguntar das ruas ou perguntar um
imóvel nessas ruas você relaciona esses condomínios".

  bairro_do_conjunto("Conjunto Eldorado")      -> "Parque 10 de Novembro"
  bairros_da_avenida("perto da Av. Max Teixeira") -> ("Flores", "Cidade Nova")
  do_bairro("Flores")                          -> os conjuntos de Flores, com as avenidas (vai na ficha que o
                                                  modelo lê para responder "fica perto de qual avenida?")

A avenida de uma palavra só ("Alvorada", "Dublin", "Torres") só vale com "av" ou "avenida" na frente: sozinha ela é
bairro, cidade ou palavra comum. As de duas palavras ou mais ("Max Teixeira", "Djalma Batista") valem sozinhas.
"""
from __future__ import annotations

import re
from functools import lru_cache
from pathlib import Path

import yaml

from nay.texto import normal, semelhanca

ROTULO = re.compile(r"^(conjunto|conj|cjto|cj|residencial|res|loteamento|condominio|cond)\s+")
ABREVIADO = {"pq": "parque", "pque": "parque", "jd": "jardim", "cel": "coronel", "prof": "professor",
             "des": "desembargador", "gen": "general", "sta": "santa", "sto": "santo"}
VIA = r"(?:av|avenida|rua|estrada)"
PISO = 0.85


def _forma(nome: str) -> str:
    """Sem acento, sem "Conjunto"/"Residencial" na frente, com as abreviações por extenso."""
    t = " ".join(ABREVIADO.get(p, p) for p in normal(nome).split())
    return ROTULO.sub("", t)


def _da_avenida(nome: str) -> str:
    return re.sub(rf"^{VIA}\s+", "", _forma(nome))


@lru_cache(maxsize=1)
def conjuntos() -> tuple[dict, ...]:
    bruto = yaml.safe_load((Path(__file__).parent / "regioes.yaml").read_text(encoding="utf-8"))
    return tuple(bruto["conjuntos"])


@lru_cache(maxsize=1)
def _por_nome() -> dict[str, str]:
    """forma do nome -> bairro. "Conjunto Japiim I e II" também atende por "japiim i", "japiim ii" e "japiim 2"."""
    saida = {}
    for c in conjuntos():
        forma = _forma(c["nome"])
        saida[forma] = c["bairro"]
        m = re.fullmatch(r"(.+) i e ii", forma)
        if m:
            saida |= {f"{m.group(1)} {n}": c["bairro"] for n in ("i", "ii", "1", "2")}
    return saida


@lru_cache(maxsize=1)
def avenidas_soltas() -> tuple[dict, ...]:
    """As ruas citadas sem conjunto (19/10: "Recife"), com os bairros e se valem escritas sozinhas."""
    bruto = yaml.safe_load((Path(__file__).parent / "regioes.yaml").read_text(encoding="utf-8"))
    return tuple(bruto.get("avenidas") or ())


@lru_cache(maxsize=1)
def _por_avenida() -> dict[str, tuple[str, ...]]:
    """núcleo do nome da avenida -> os bairros dos conjuntos que ficam nela (e os das avenidas soltas)."""
    saida: dict[str, list[str]] = {}
    for c in conjuntos():
        for av in c["avenidas"]:
            saida.setdefault(_da_avenida(av), []).append(c["bairro"])
    for a in avenidas_soltas():
        saida.setdefault(_da_avenida(a["nome"]), []).extend(a["bairros"])
    return {k: tuple(dict.fromkeys(v)) for k, v in saida.items()}


@lru_cache(maxsize=1)
def _sem_prefixo() -> frozenset[str]:
    """Os núcleos que valem sem "rua"/"av" na frente ("pq 10 ou Recife")."""
    return frozenset(_da_avenida(a["nome"]) for a in avenidas_soltas() if a.get("sem_prefixo"))


def bairro_do_conjunto(escrito: str, so_exato: bool = False) -> str | None:
    """O bairro do conjunto que ele escreveu, pelo nome inteiro (com ou sem "Conjunto") ou, se não for `so_exato`,
    com uma letra trocada."""
    t = _forma(escrito)
    nomes = _por_nome()
    if t in nomes or so_exato:
        return nomes.get(t)
    notas = sorted(((semelhanca(t, n), n) for n in nomes if len(n) >= 6), reverse=True)
    return nomes[notas[0][1]] if notas and notas[0][0] >= PISO else None


def bairros_da_avenida(texto: str) -> tuple[str, ...]:
    """Os bairros das avenidas da biblioteca citadas no texto (uma frase inteira ou só o nome da avenida)."""
    t = " ".join(ABREVIADO.get(p, p) for p in normal(texto).split())
    achados: list[str] = []
    for nucleo, bairros in _por_avenida().items():
        com_via = re.search(rf"\b{VIA}\s+(?:d[aoe]s?\s+)?{re.escape(nucleo)}\b", t)
        sozinha = (len(nucleo.split()) >= 2 and not nucleo.startswith(("do ", "da ", "das ", "dos ", "dom "))) \
            or nucleo in _sem_prefixo()
        if com_via or (sozinha and re.search(rf"\b{re.escape(nucleo)}\b", t)):
            achados += bairros
    return tuple(dict.fromkeys(achados))


def do_bairro(bairro: str | None) -> list[str]:
    """Os conjuntos do bairro, cada um com as avenidas entre as quais fica (para a ficha que o modelo lê)."""
    alvo = normal(bairro)
    return [f"{c['nome']} (entre a {c['avenidas'][0]} e a {c['avenidas'][1]})"
            for c in conjuntos() if alvo and normal(c["bairro"]) == alvo]

"""O pré-roteador (setor roteador): o que responde SEM modelo e SEM busca.

É o caminho das mensagens que não precisam de consulta (pedido do Tel, 30/09):
cortesia, resposta direta à pergunta de filtro que ela acabou de fazer, só um
código / card colado / citação resolvida, e "foto do X" com o imóvel já
resolvido. O velho passava tudo isso pelo Jev e pelo agente (pergunta 6).

A ordem importa: a resposta ao FILTRO vem antes do atalho de código, senão
"3500" em resposta a "Até que valor?" vira o card do imóvel 3500 (pergunta 12).
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime

from nay.classificador import frases, sinais, valores
from nay.config import cfg
from nay.contexto.resolver_imovel import MANDA, Contexto, pediu_envio, pediu_fotos, pediu_status, resto_trivial
from nay.estado import prazos
from nay.nos import no
from nay.texto import normal, sem_acento, teto_na_escala
from nay.tipos import Conversa

AGRADECE = re.compile(
    r"^((ok|okay|oks|obg|obrigad[oa]|muito obrigad[oa]|valeu|vlw|blz|beleza|show|top|perfeito|certo|certinho|"
    r"combinado|ta bom|tudo bem|entendi|tendi|de (qualquer|qq) forma|grato|grata|amem|isso|otimo|joia|massa|"
    r"legal|kkk+|rs+|ah sim|sim sim|lind[oa]|lindeza|maravilh\w*|amei|adorei|que lind[oa])\s*)+$")
SAUDA = re.compile(r"^((o+i+e?|ola+|opa|bom dia|boa tarde|boa noite|e ai|salve|nay|nai|tudo bem|td bem|tudo bom|"
                   r"tudo certo|como vai|com voce|querida|amiga)\s*)+$")
TANTO_FAZ = re.compile(r"\b(tanto faz|qualquer|indiferente|nao importa|sem preferencia|tanto fa)\b"
                       r"|\bo que (voce |vc |tu )?(tem|tiver|tiver ai)\b|^pode ser\b(?!.*\d)")
FINALIDADE = [(r"\b(alug|locac|locar)", "locacao"), (r"\b(compr|venda|vender)", "venda"),
              (r"\b(os dois|ambos|as duas)\b", "ambos")]
TIPOS = [(r"casa (de|em) condominio", "casa_condominio"), (r"\b(apto|apartamento|ap)\b", "apartamento"),
         (r"\bcasa\b", "casa"), (r"\bflat\b", "flat"), (r"\bcobertura\b", "cobertura"),
         (r"\bsala\b", "sala"), (r"\bloja\b", "loja"), (r"\b(terreno|lote)\b", "terreno"),
         *frases.TIPOS_COMERCIAIS]
# Depois do card sem fotos, "manda aí" quer as fotos (regra 267): as palavras são MANDA, de contexto/resolver_imovel.py.
# A mobília do cliente (Tel, 02/10). A ordem importa: "semimobiliado" e "não mobiliado" contêm "mobiliad".
# "Pelo menos ar", "com ar", "só o ar": climatizado (887); a busca dele traz o semimobiliado e o sem móveis com ar.
SEMI = re.compile(r"semi|modulad|planejad|so (os )?armario")
SO_AR = re.compile(r"\b(pelo menos|no minimo|so|apenas|somente)( com)?( o| os)? (ar|ares|climatiz)")
TEM_AR = re.compile(r"\bar\b|\bares\b|ar.?condicionad|climatiz")
SEM_MOVEIS = re.compile(r"\b(sem mobilia|sem moveis|sem movel|vazio|nao mobiliado|sem nada)\b")
AMBOS = re.compile(r"\b(os dois|os 2|ambos|as duas|as 2|qualquer um|um ou outro|sem preferencia)\b")
OS_DOIS = re.compile(r"\b(os dois|os 2|ambos|as duas|as 2)\b")
SIM = re.compile(r"^(s+i+m+|s|ss|quero|interessa|pode ser|serve|claro|isso|pode|manda|tem interesse|tenho)\b")
# pedido de OUTROS imóveis não é pedido do imóvel marcado
OUTROS = re.compile(r"\b(outr[oa]s?|parecid[oa]s?|semelhantes?|similar(es)?|mais opc|mais imove|alguma opc)")
NAO = re.compile(r"^(nao|n|nn|nem|so semi|prefiro semi|nao interessa)\b")
PERGUNTA = re.compile(r"\?|\b(tem|qual|quanto|quantos|quantas|aceita|fica|onde|quando|possui)\b")
# Pergunta SEM "?" ("VAI FICAR COMO ESTA NAS FOTOS", 8585 em 12/10): vai ao modelo; com "manda" na frase é pedido.
PERGUNTA_SEM_PONTO = re.compile(r"^(vai|vao|sera|como)\b|\b(vai ficar|vai ser|vai ter|como (esta|fica|e)|"
                                r"sera que|da pra|da para)\b|\b(e|eh|sao|fica|tem|vai)\b.+\bou\b")
# "esse", "manda esse aí" depois de uma LISTA não diz qual (Alteração 2, B)
ESSE = re.compile(r"\b(esse|essa|este|esta|desse|dessa|deste|desta)\b")
# "quero de 7", "tem de 6?", "procuro até 7 mil", "máximo 7 mil" em cima do card: é OUTRO valor, não o pedido
# deste imóvel
OUTRO_VALOR = re.compile(
    r"\b(?:(?:quero|queria|procuro|preciso|busco|tem|teria|seria)\b[^\d\n]{0,24}\b(?:de|ate|por|uns|maximo|faixa de)"
    r"|(?:no )?maximo(?: de| ate)?)\s+"
    r"(\d{1,3}(?:[.,]\d{1,3})?)\s*(mil|k)?\b(?!\s*(?:quartos?|suites?|dormitorios?|vagas?|m2|metros|andar|pessoas?))")
SEM_VALOR = re.compile(r"\b(nao (disse|falou|informou|sabe|passou|definiu)|sem valor|qualquer valor)\b")


@dataclass(frozen=True)
class Pre:
    decisao: str | None = None
    filtro_direto: dict = field(default_factory=dict)
    dados: dict = field(default_factory=dict)


def _curta(t: str, palavras: int = 8) -> bool:
    return len(t.split()) <= palavras


def _primeiro(regras: list[tuple[str, str]], t: str) -> str | None:
    return next((v for p, v in regras if re.search(p, t)), None)


def _filtro(conversa: Conversa, texto: str, resolver_bairro) -> dict:
    """A resposta curta à pergunta de filtro do estado atual, se for só isso."""
    t = normal(texto)
    est = conversa.estado
    if est == "FILTRO_TIPO" and len(t.split()) <= 20 and (OS_DOIS.search(t) or frases.OS_DOIS_TIPOS.search(t)):
        # "Os 2. Pq ele está fechando uma casa, mas não descarta apto" (13855): os dois tipos servem. Vem antes
        # do limite de palavras e de "casa" sozinha, que gravaria um tipo só.
        return {"tipo": "tanto_faz"}
    if not _curta(t):
        return {}
    if est == "FILTRO_FINALIDADE":
        v = frases.finalidade_dita(texto) or ("tanto_faz" if TANTO_FAZ.search(t) else None)
        return {"finalidade": v} if v else {}
    if est == "FILTRO_TIPO":
        v = _primeiro(TIPOS, t) or ("tanto_faz" if TANTO_FAZ.search(t) else None)
        return {"tipo": v} if v else {}
    if est == "FILTRO_TETO":
        if TANTO_FAZ.search(t) or SEM_VALOR.search(t):
            return {"teto_tanto_faz": True}
        return _valor_dito(texto, conversa)
    if est == "FILTRO_MOBILIA":
        v = "tanto_faz" if TANTO_FAZ.search(t) or AMBOS.search(t) else mobilia_dita(t)
        return {"mobilia": v} if v else {}
    if est == "FILTRO_CLIMATIZADO":      # "tenho só climatizado, interessa?": sim busca os climatizados
        return {"mobilia": "climatizado"} if SIM.search(t) else {"mobilia": "semi"} if NAO.search(t) else {}
    return _regiao_ou_valor(conversa, texto, t, resolver_bairro)


def _valor_dito(texto: str, conversa: Conversa) -> dict:
    """O valor da resposta, com a família que ele disse ("até 6 mil", "entre 2 e 3", "a partir de 5 mil"; ou só o
    número): classificador/valores.py."""
    v = valores.ler(texto, conversa.filtro_finalidade, solto=True) if valores.so_valor(texto) else None
    if not v:
        return {}
    return {k: x for k, x in (("teto", v.teto), ("piso", v.piso)) if x}


def _regiao_ou_valor(conversa: Conversa, texto: str, t: str, resolver_bairro) -> dict:
    """A resposta a "Qual região?" e a "Quer tentar outro bairro ou outro valor?" (06/10: aí o bairro ou o valor
    sozinho é a resposta, sem modelo)."""
    na_regiao = conversa.estado == "FILTRO_REGIAO"
    outro = conversa.ultima_acao in ("lista_vazia", "qual_bairro_ou_valor", "oferta_abaixo")
    if not (na_regiao or outro):
        return {}
    if na_regiao and TANTO_FAZ.search(t):
        return {"regiao_tanto_faz": True}
    v = _valor_dito(texto, conversa) if outro else {}
    if v:
        return v
    r = resolver_bairro(texto)
    certo = r.via in ("exato", "apelido", "zona", "conjunto", "avenida", "parecido")
    return {"regiao": r.bairros} if r.bairros and certo else {}


def mobilia_dita(t: str) -> str | None:
    """A mobília que ele disse, no texto já normalizado."""
    if SEMI.search(t):
        return "semi"
    if SO_AR.search(t):
        return "climatizado"
    if SEM_MOVEIS.search(t):
        return "climatizado" if TEM_AR.search(t) else "nao"
    if "mobiliad" in t:
        return "mobiliado"
    return "climatizado" if TEM_AR.search(t) else None


def _outro_valor(texto: str, conversa: Conversa) -> float | None:
    """O valor que ele disse querer no lugar do imóvel em jogo ("essa é 9 mil, quero de 7" -> 7000). Com mais de
    um ("Não tem de 6? Máximo 7 mil?"), vale o maior: é até onde ele vai."""
    valores = []
    for m in OUTRO_VALOR.finditer(sem_acento(texto).lower()):
        numero = float(m.group(1).replace(".", "").replace(",", ".")) if "," in m.group(1) else float(
            m.group(1).replace(".", ""))
        valores.append(numero * 1000 if m.group(2) else teto_na_escala(numero, conversa.filtro_finalidade))
    return max((v for v in valores if v), default=None)


def _aceitou_recomecar(t: str, conversa: Conversa, ctx: Contexto, agora: datetime | None) -> bool:
    """Ela ofereceu procurar outro (o imóvel saiu do mercado, ou o condomínio não tem oferta) e ele disse que sim."""
    ofereceu = conversa.ultima_acao in ("indisponivel", "condominio_sem_oferta")
    return (ofereceu and prazos.gatilho_vale(conversa, agora) and _curta(t) and bool(SIM.search(t))
            and not ctx.literais)


@no("entendimento.atalhos")
def decidir(texto: str, conversa: Conversa, ctx: Contexto, resolver_bairro,      # noqa: C901
            lista: tuple[int, ...] = (), agora: datetime | None = None, parecido: dict | None = None) -> Pre:
    t = normal(texto)
    if not t:
        return Pre("vazio")
    # o que a frase já diz sozinha: despedida, "manda o que tem", anúncio, visita com dia e hora... (sinais.py)
    sinal = sinais.decidir(texto, conversa, ctx, agora)
    if sinal:
        return Pre(sinal[0], dados=sinal[1])
    # O FLUXO RECOMEÇA (Pedro, 05/10: "o corretor terminou com sim, ela tem que voltar a refazer o fluxo ... já
    # que o fluxo inicial não deu em um disponível"). Ela disse "o 5720 não está mais disponível, quer que eu
    # procure outro parecido?" (ou "no condomínio X não tenho, aceita outro?") e ele respondeu que sim: a busca
    # parte do imóvel que saiu (finalidade, tipo, bairro e valor dele) e segue perguntando o que faltar. Antes o
    # "Sim" era cortesia e ela ficava calada.
    if _aceitou_recomecar(t, conversa, ctx, agora):
        return Pre("filtro_direto", dict(parecido or {}), {"recomeca": True})
    direto = _filtro(conversa, texto, resolver_bairro)
    if direto.get("teto") and ctx.literais and conversa.estado != "FILTRO_TETO":
        direto = {}         # fora da pergunta do valor, o número que é código de imóvel é o imóvel
    if direto:
        return Pre("filtro_direto", direto)
    if AGRADECE.match(t):
        return Pre("cortesia_agradece")
    # MARCOU O CARD (do grupo ou nosso). O corretor do 3878 marcou o post do 5765 em 02/10 e escreveu "Boa noite
    # mana me envia por gentileza": recebeu "não entendi"; marcou de novo com "Bom dia" e recebeu só "Bom dia!".
    # O imóvel estava resolvido nos dois turnos. Marcar o card é falar DELE.
    marcou = bool(ctx.codigo) and ctx.origem == "citacao"
    vale = prazos.gatilho_vale(conversa, agora)
    # "essa é 9 mil, quero de 7" (turno 944): em cima do card marcado, ou logo depois de ela mandar o card
    logo_depois = (bool(ctx.codigo) and ctx.origem in ("foco", "lista") and vale
                   and conversa.ultima_acao in ("card", "fotos", "status", "ja_mandei", "confirmar_imovel"))
    if (marcou or logo_depois) and (valor := _outro_valor(texto, conversa)):
        return Pre("rejeitar_com_teto", {"teto": valor})
    if SAUDA.match(t):
        # só cumprimentou em cima do card: como o card colado sem pedido, a situação e a oferta do card e das fotos
        return Pre("so_codigo", dados={"fotos": False, "status": False, "manda": False, "marcou": True}) \
            if marcou else Pre("cortesia_saudacao")
    composto = frases.segundo_pedido(texto)        # envio + pedido novo: vai ao modelo (estado/multiplos.py)
    if marcou and pediu_envio(t) and not PERGUNTA.search(texto.lower()) and not OUTROS.search(t) and not composto:
        # "me envia por gentileza", "manda pra mim mana": o pedido do imóvel marcado, com as palavras que sobrarem
        return Pre("so_codigo", dados={"fotos": pediu_fotos(texto), "status": pediu_status(texto), "manda": True})
    varios = _de_varios(texto, t, ctx, lista, vale)     # mais de um imóvel na mesma mensagem
    if varios:
        return varios
    trivial = resto_trivial(texto)
    if ctx.candidatos and trivial:
        return Pre("qual")
    # ela mandou uma LISTA e ele respondeu "manda", "esse", "envia" sem dizer qual: pergunta qual deles. Antes
    # o foco de outro pedido respondia por ele, ou a busca devolvia a mesma lista.
    depois_da_lista = conversa.ultima_acao in ("buscar", "qual_da_lista", "perguntar_qual", "varios")
    escolheu = ctx.origem in ("lista", "literal", "citacao", "card")
    if lista and depois_da_lista and not escolheu and trivial and (MANDA.search(t) or ESSE.search(t)) and vale:
        return Pre("qual_da_lista", dados={"codigos": list(lista)})
    return _do_imovel(texto, t, conversa, ctx, trivial, vale) if ctx.codigo and not composto else Pre()


def _eles(texto: str, lista: tuple[int, ...], do_lugar: tuple[int, ...], maximo: int) -> tuple[int, ...]:
    """De quais imóveis ele fala com "os dois", "todos", "ambos": a lista inteira, se a conta fecha; senão os da
    lista que ficam no lugar que ele pediu (13767: dois na Ponta Negra e um do bairro vizinho, "mande os dois")."""
    return next((g for g in (lista, do_lugar) if 2 <= len(g) <= maximo and frases.conta_fecha(texto, len(g))), ())


def _de_varios(texto: str, t: str, ctx: Contexto, lista: tuple[int, ...], vale: bool) -> Pre | None:
    """Mais de um imóvel na mesma mensagem (Tel, 06/10 e rodada 9 de 07/10): vão TODOS, o card de cada um (e as
    fotos, até `fotos_com_varios_ate`). Vários códigos digitados; vários nomes da lista; "os dois", "todos", "pode
    mandar" depois da lista; e a pergunta sobre eles ("os dois são mobiliados né"). Nunca refaz a busca."""
    maximo = int(cfg("limites").get("max_imoveis_de_uma_vez", 5))
    digitados = ctx.literais if ctx.origem == "literal" and not ctx.card_colado and not ctx.codigo else ()
    if len(digitados) > 1 and "?" not in texto:     # "Cód 2392 ⏎ 9004 ⏎ E o código 3450" (13707)
        return Pre("todos_da_lista", dados={"codigos": list(digitados)}) if len(digitados) <= maximo else Pre("qual")
    if ctx.varios and "?" not in texto:    # "Me vê o Ibza e o do Adrianópolis" (13698); pergunta não pede card
        return Pre("todos_da_lista", dados={"codigos": list(ctx.varios), "falta_escolher": list(ctx.candidatos)})
    apontou = ctx.origem in ("lista", "literal", "citacao", "card") or ESSE.search(t)
    if not lista or apontou or not vale:
        return None
    if frases.sobre_eles(texto):                    # "Pela descrição os dois são mobiliados né" (13768)
        eles = _eles(texto, lista, ctx.do_lugar, maximo)
        return Pre("pergunta_dos_varios", dados={"codigos": list(eles)}) if eles else None
    pede = frases.pede_todos(texto)
    eles = _eles(texto, lista, ctx.do_lugar, maximo) if pede else ()
    if not eles and 2 <= len(lista) <= maximo and frases.fotos_de_todos(texto):
        eles = lista
    if eles:
        return Pre("todos_da_lista", dados={"codigos": list(eles)})
    # "me envia os dois" com três na frente: ela pergunta quais, com os códigos; a busca não se refaz (13710)
    return Pre("qual_da_lista", dados={"codigos": list(lista)}) if pede and frases.diz_quantos(texto) else None


def _pergunta(texto: str, t: str) -> bool:
    return bool(PERGUNTA.search(texto.lower())) or (bool(PERGUNTA_SEM_PONTO.search(t)) and not MANDA.search(t))


def _do_imovel(texto: str, t: str, conversa: Conversa, ctx: Contexto, trivial: bool, vale: bool = True) -> Pre:
    """Há um imóvel em jogo (escolhido da lista, escrito, citado ou o de antes): o que ele quer dele?
    `vale`: o que ela fez por último ainda está dentro do prazo do gatilho (estado/prazos.py)."""
    # ele escolheu pelo nome ou pela ordem uma opção da lista que ela acabou de mandar ("manda o Milano"):
    # é pedido do imóvel, sem modelo. Pergunta sobre a opção ("o Milano tem piscina?") segue para o modelo.
    visto = {"fotos": pediu_fotos(texto) and not (PERGUNTA_SEM_PONTO.search(t) and not MANDA.search(t)),
             "status": pediu_status(texto), "manda": bool(MANDA.search(t)),
             "valendo": frases.pergunta_se_vale(texto)}
    # Ela perguntou "É este imóvel?" (o portão de coerência não tinha a prova do pedido). "Não" recusa esse
    # imóvel e a busca segue; "sim", "esse mesmo", "manda" ou o nome dele de novo confirmam, e aí sai inteiro.
    if conversa.ultima_acao == "confirmar_imovel" and ctx.codigo == conversa.foco_codigo and vale:
        if NAO.search(t) and not _pergunta(texto, t):   # "não tem foto ?" é pergunta, não recusa (21/10)
            return Pre("rejeitar")
        if trivial or ctx.origem == "lista":
            return Pre("so_codigo", dados={**visto, "manda": True, "confirmado": True})
    perguntou = conversa.ultima_acao in ("ja_mandei", "status", "confirmar_imovel")
    mesmo = ctx.codigo == conversa.foco_codigo and ctx.origem in ("literal", "citacao", "card", "lista")
    # ...mas MARCAR o card com um recado ("Vou aguardar o cliente responder", 13782) não é o sim: aí precisa de
    # um sim, de um pedido ("manda", "as fotos") ou de a mensagem não dizer mais nada
    disse_sim = ctx.origem != "citacao" or trivial or visto["manda"] or visto["fotos"] or bool(SIM.search(t))
    if perguntou and vale and mesmo and disse_sim and not _pergunta(texto, t) and not NAO.search(t):
        confirmado = {"confirmado": True} if conversa.ultima_acao == "confirmar_imovel" else {}
        return Pre("so_codigo", dados={**visto, "manda": True, **confirmado})     # escreveu o mesmo imóvel: é o sim
    if ctx.codigo and ctx.origem == "lista" and not _pergunta(texto, t):
        return Pre("so_codigo", dados={**visto, "manda": True})      # escolher da lista é pedir o imóvel
    escrito = ctx.origem in ("citacao", "literal", "card")
    if ctx.codigo and escrito and trivial:
        return Pre("so_codigo", dados=visto)
    na_frente = bool(ctx.codigo) and ctx.origem == "foco" and trivial and vale
    # ela só disse "está disponível, quer o card e as fotos?" e ele respondeu "me envia" / "top, manda aí" /
    # "sim": agora vão o card e as fotos
    # ...ou ela disse "esse eu já te enviei, você tem interesse nele?" (05/10) e ele respondeu que sim
    if na_frente and conversa.ultima_acao in ("status", "ja_mandei") and (
            visto["manda"] or visto["fotos"] or SIM.search(t)):
        return Pre("so_codigo", dados={**visto, "manda": True})
    # o foco vale 24 h para pergunta e visita; o ENVIO pelo imóvel de antes continua valendo só as 2 h do gatilho
    if ctx.codigo and visto["fotos"] and trivial and (ctx.origem != "foco" or vale):
        return Pre("fotos")
    if na_frente and conversa.ultima_acao in ("card", "fotos") and visto["manda"]:
        return Pre("fotos")
    return Pre()

"""O classificador pelo Jev (typesafe/jev, Decisions API da OpenRouter), atrás da
MESMA interface da Luna: `classificar(entrada)` devolve a Classificacao e o meta.

O Jev só responde pergunta fechada: intenção, se pediu imóvel, qual código quer,
qual recusa, finalidade, tipo, bairro (entre os do catálogo) e se respondeu à
última pergunta dela. Teto, quartos, mobília, fotos e horário saem de regex
(classificador/reserva.py): o Jev não extrai texto.

Formato (conferido na documentação em 30/09, docs/DECISOES.md): POST em
/api/alpha/decisions com {model, state, questions}; cada pergunta é {type,
instructions, criteria}; `choice` devolve choice + confidence, `noul` devolve a
probabilidade do sim. As instruções vão em inglês (é a língua em que ele mais
acerta) e os exemplos em português, como o corretor escreve.

Só entra em uso com `classificador.provedor: jev` em config/modelos.yaml. A
resposta de dúvida continua sendo da Luna."""
from __future__ import annotations

import json
import time
from typing import Any

import httpx

from nay.classificador import reserva
from nay.classificador.luna import Disjuntor, FalhaDoModelo, Modelos, OpenAIModelos
from nay.classificador.schema import Classificacao, vazia
from nay.config import cfg

URL = "https://openrouter.ai/api/alpha/decisions"
REPETE = {408, 429, 500, 502, 503, 524, 529}
CONTEXTO = ("State: a WhatsApp chat between a real-estate broker (corretor, 'ele') and Nay ('ela'), the assistant "
            "of the Imob Easy agency in Manaus. Judge ONLY his latest message ('mensagem'), using the rest as context.")
INTENCOES = {
    "pedir_imovel": "He wants to RECEIVE properties: asks for options or prices, or describes what his client is "
                    "looking for (neighborhood, budget, type, rent or buy). Ex: 'tem apartamento no Aleixo até 3 mil?'",
    "pergunta_sobre_imovel": "He asks for information or photos of ONE property already in the conversation: price, "
                             "rooms, condo fee, availability, pets. Ex: 'esse aceita pet?', 'ainda está disponível?'",
    "escolher_imovel": "He picks ONE specific property: from a list, by its code, by replying to or pasting our "
                       "card. Ex: 'o primeiro', 'quero o 5733', 'esse mesmo'",
    "rejeitar_imovel": "He refuses a property we showed. Ex: 'esse não serve', 'o cliente não gostou'",
    "visita": "He wants to schedule, change, confirm or cancel a visit, or gives its day and time.",
    "resultado_visita": "He tells how a visit that already happened went.",
    "cortesia": "Only a greeting, thanks or short acknowledgment. Ex: 'ok', 'obrigado', 'bom dia'",
    "recado": "He gives news about his client, asking nothing. Ex: 'aguardando um retorno dele', 'ela achou um', "
              "'vou falar com ela'",
    "oferta_de_imovel": "He OFFERS a property of his own to the agency, or asks how to list with us.",
    "parceria": "He asks whether the agency works in partnership with brokers, or about the commission split.",
    "assunto_geral": "Anything else: documents, contracts, complaints, personal matters.",
}
PARA_O_CORE = {"escolher_imovel": "pedir_imovel"}      # a máquina trata o imóvel escolhido como pedido dele
FINALIDADES = {"locacao": "rent (aluguel, alugar, locação)", "venda": "buy (comprar, venda, financiamento)",
               "ambos": "either rent or buy is fine", "nao_disse": "This message does not say."}
TIPOS = {"apartamento": "apartment (apto, ap, kitnet, studio)", "casa": "house on the street (casa, sobrado)",
         "casa_condominio": "house inside a gated condominium", "flat": "flat", "cobertura": "penthouse",
         "sala": "commercial room or office", "loja": "store", "terreno": "land, lot",
         "predio": "a whole building", "galpao": "warehouse, shed", "comercial": "any commercial property",
         "tanto_faz": "any type is fine", "nao_disse": "This message does not say."}
ELA_PERGUNTOU = {"finalidade": "whether his client wants to rent or to buy", "tipo": "which type of property",
                 "teto": "up to what price his client can pay", "regiao": "which neighborhood his client wants",
                 "qual_imovel": "which of the properties she showed he wants"}


def _choice(pergunta: str, criteria: dict) -> dict:
    return {"type": "choice", "instructions": {"question": pergunta, "context": CONTEXTO}, "criteria": criteria}


def _noul(pergunta: str, sim: str, nao: str) -> dict:
    return {"type": "noul", "instructions": {"question": pergunta, "context": CONTEXTO},
            "criteria": {"true": sim, "false": nao}}


def perguntas(entrada: dict[str, Any], bairros: dict[str, str], rotulos: dict[int, str]) -> dict[str, dict]:
    """As perguntas deste turno, numa requisição só. `bairros`: nome -> zona; `rotulos`: código -> descrição."""
    codigos = {str(c): r for c, r in rotulos.items()}
    lugares = {**{b: f"neighborhood ({z})" for b, z in list(bairros.items())[:250]},
               "tanto_faz": "any neighborhood is fine, or the whole city",
               "nao_disse": "This message names no neighborhood."}
    q = {
        "intencao": _choice("What does he want in THIS message?", INTENCOES),
        "pediu_imovel": _noul("Does he want to RECEIVE a property (card, photos or a list of options) now?",
                              "He asks for options, a card, photos, or describes a search so we send properties.",
                              "He asks about a property already sent, greets, thanks, talks about a visit, or else."),
        "codigo_quer": _choice("Which property does he want or talk about in THIS message?",
                               {**codigos, "nenhum": "No specific property in this message.",
                                "outro_nao_listado": "A specific property that is not in this list."}),
        "finalidade": _choice("In this message, does his client want to rent or to buy?", FINALIDADES),
        "tipo": _choice("Which type of property does he ask for in this message?", TIPOS),
        "bairro": _choice("Which neighborhood (bairro) does he ask for in this message?", lugares),
    }
    ultima = entrada.get("ultima_pergunta_da_nay")
    if ultima in ELA_PERGUNTOU:
        q["responde_ultima_pergunta"] = _noul(
            f"Nay's last message asked {ELA_PERGUNTOU[ultima]}. Does his message answer it?",
            "His message gives that information, even as a bare number, one word or 'tanto faz'.",
            "He ignores the question or talks about something else.")
    if codigos:
        q["codigo_rejeita"] = _choice("Which property is he REFUSING in this message? Only when he says it does "
                                      "not fit or the client did not like it.",
                                      {**codigos, "nenhum": "He refuses no property in this message."})
    return q


def _escolha(answers: dict, chave: str, limiar: float) -> tuple[str | None, float]:
    a = answers.get(chave) or {}
    conf = float(a.get("confidence") or 0.0)
    return (a.get("choice") if conf >= limiar else None), conf


def ler(answers: dict, entrada: dict[str, Any], bairros: dict[str, str]) -> tuple[Classificacao, dict[str, Any]]:
    """Das respostas do Jev (e da regex, para o que ele não extrai), a Classificacao e o que ficou de fora dela."""
    lim = cfg("modelos")["jev"]["limiares"]
    texto, ultima = entrada.get("mensagem") or "", entrada.get("ultima_pergunta_da_nay")
    intencao, c_int = _escolha(answers, "intencao", lim["intencao"])
    finalidade, _ = _escolha(answers, "finalidade", lim["finalidade"])
    tipo, _ = _escolha(answers, "tipo", lim["tipo"])
    bairro, _ = _escolha(answers, "bairro", lim["bairro"])
    quer, _ = _escolha(answers, "codigo_quer", lim["codigo"])
    rejeita, _ = _escolha(answers, "codigo_rejeita", lim["codigo"])
    tanto_faz = [campo for campo, v in (("tipo", tipo), ("bairro", bairro)) if v == "tanto_faz"]
    por_regex = reserva.extrair(texto, ultima)
    cl = vazia(
        PARA_O_CORE.get(intencao or "", intencao) or "nao_da_para_saber",
        finalidade=finalidade if finalidade in ("locacao", "venda", "ambos") else None,
        tipo=tipo if tipo in TIPOS and tipo not in ("tanto_faz", "nao_disse") else None,
        bairros=[bairro] if bairro in bairros else [],
        tanto_faz=tanto_faz + (["teto"] if por_regex["teto_tanto_faz"] else []),
        codigos_citados=[int(quer)] if quer and quer.isdigit() else [],
        codigo_rejeitado=int(rejeita) if rejeita and rejeita.isdigit() else None,
        teto=por_regex["teto"], quartos=por_regex["quartos"], mobilia=por_regex["mobilia"],
        pede_fotos=por_regex["pede_fotos"], pede_lista_de_valores=por_regex["pede_lista"],
        horario_visita=por_regex["horario"] if intencao == "visita" else None)
    fora = {"confianca_intencao": round(c_int, 3), "intencao_do_jev": intencao,
            "pediu_imovel": (answers.get("pediu_imovel") or {}).get("noul"),
            "responde_ultima_pergunta": (answers.get("responde_ultima_pergunta") or {}).get("noul")}
    return cl, fora


class JevModelos:
    """`cer` dá os bairros do catálogo e o rótulo de cada código candidato; `luna` responde a dúvida."""

    def __init__(self, chave: str, cer, luna: Modelos | None = None, cliente: httpx.Client | None = None) -> None:
        if not chave:
            raise FalhaDoModelo("sem OPENROUTER_API_KEY")
        self.cer, self.luna = cer, luna
        self.cli = cliente or httpx.Client(headers={"Authorization": f"Bearer {chave}",
                                                    "Content-Type": "application/json"})
        self.disjuntor = Disjuntor()

    def _rotulos(self, codigos: list[int]) -> dict[int, str]:
        saida = {}
        for c in codigos[:20]:
            i = self.cer.catalogo.get(c)
            if i:
                saida[c] = f"{i.condominio_nome or i.tipo_original or 'imóvel'}, {i.bairro or 'Manaus'}"
        return saida

    def _post(self, corpo: dict, orcamento_s: float) -> tuple[dict, int]:
        inicio = time.monotonic()
        prazo, erro = inicio + orcamento_s, "sem tempo"
        for _ in range(2):          # uma retentativa, só se sobrar tempo e só para erro que passa sozinho
            resta = prazo - time.monotonic()
            if resta < 0.5:
                break
            try:
                r = self.cli.post(URL, json=corpo, timeout=resta)
            except httpx.HTTPError as x:
                erro = f"conexão: {type(x).__name__}"
                continue
            if r.status_code == 200:
                return r.json(), int((time.monotonic() - inicio) * 1000)
            erro = f"HTTP {r.status_code}: {r.text[:160]}"
            if r.status_code not in REPETE:
                break
        raise FalhaDoModelo(f"jev: {erro}")

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        c = cfg("modelos")["jev"]
        if not self.disjuntor.permite():
            raise FalhaDoModelo("jev: circuito aberto")
        bairros = dict(self.cer.zonas)
        estado = {k: entrada.get(k) for k in ("mensagem", "ultima_pergunta_da_nay", "estado", "filtros",
                                              "imovel_em_foco")}
        q = perguntas(entrada, bairros, self._rotulos(list(entrada.get("codigos_candidatos") or [])))
        try:
            d, ms = self._post({"model": c["modelo"], "state": estado, "questions": q}, float(c["orcamento_s"]))
        except FalhaDoModelo:
            self.disjuntor.falha()
            raise
        answers = d.get("answers")
        if not isinstance(answers, dict) or not answers:
            self.disjuntor.falha()
            raise FalhaDoModelo("jev: resposta sem answers")
        self.disjuntor.sucesso()
        cl, fora = ler(answers, entrada, bairros)
        uso = d.get("usage") or {}
        return cl, {"modelo": d.get("model") or c["modelo"], "ms": ms, "custo": uso.get("cost"),
                    "tokens_entrada": uso.get("input_tokens"), "cru": answers, **fora}

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        if self.luna is None:
            raise FalhaDoModelo("a dúvida é da Luna e ela não foi configurada")
        return self.luna.duvida(instrucao, usuario)


class JevJuiz:
    """Uma pergunta fechada (noul) ao Jev, fora do classificador: o veto do portão de coerência e a avaliação do
    dia. Devolve a probabilidade do sim, ou None quando ele não respondeu a tempo (quem chama segue sem ele)."""

    def __init__(self, chave: str, cliente: httpx.Client | None = None) -> None:
        self.cli = cliente or httpx.Client(headers={"Authorization": f"Bearer {chave}",
                                                    "Content-Type": "application/json"})
        self.disjuntor = Disjuntor()

    def responde(self, pergunta: str, sim: str, nao: str, estado: dict[str, Any],
                 orcamento_s: float) -> tuple[float | None, dict[str, Any]]:
        modelo = cfg("modelos")["jev"]["modelo"]
        if not self.disjuntor.permite():
            return None, {"modelo": modelo, "erro": "circuito aberto"}
        inicio = time.monotonic()
        # o estado vai como JSON: Decimal e data viram texto, e nunca derrubam a chamada
        estado = json.loads(json.dumps(estado, ensure_ascii=False, default=str))
        corpo = {"model": modelo, "state": estado, "questions": {"resposta": _noul(pergunta, sim, nao)}}
        try:
            r = self.cli.post(URL, json=corpo, timeout=orcamento_s)
            if r.status_code != 200:
                raise FalhaDoModelo(f"HTTP {r.status_code}")
            d = r.json()
            prob = ((d.get("answers") or {}).get("resposta") or {}).get("noul")
            if prob is None:
                raise FalhaDoModelo("resposta sem noul")
        except (httpx.HTTPError, FalhaDoModelo, ValueError) as x:
            self.disjuntor.falha()
            return None, {"modelo": modelo, "ms": int((time.monotonic() - inicio) * 1000),
                          "erro": f"{type(x).__name__}: {x}"[:120]}
        self.disjuntor.sucesso()
        return float(prob), {"modelo": d.get("model") or modelo, "ms": int((time.monotonic() - inicio) * 1000),
                             "custo": (d.get("usage") or {}).get("cost")}


def juiz_do_core(conf) -> JevJuiz | None:
    """O juiz do veto, quando há chave da OpenRouter e o veto está ligado em config/modelos.yaml."""
    ligado = ((cfg("modelos").get("jev") or {}).get("veto") or {}).get("ligado")
    return JevJuiz(conf.openrouter_api_key) if conf.openrouter_api_key and ligado else None


def modelos_do_core(conf, cer, provedor: str | None = None) -> Modelos | None:
    """O cliente que o core usa, conforme `classificador.provedor`: a Luna (padrão) ou o Jev
    nas perguntas fechadas com a Luna só na dúvida. Sem chave da OpenAI, nenhum (regex)."""
    if not conf.openai_api_key:
        return None
    luna = OpenAIModelos(conf.openai_api_key)
    reserva = (cfg("modelos").get("reserva") or {}).get("texto") or {}
    if conf.openrouter_api_key and reserva.get("ligado"):
        from nay.classificador.openrouter import ComReserva, OpenRouterModelos
        luna.tentativas_max = 1
        luna = ComReserva(luna, OpenRouterModelos(conf.openrouter_api_key))
    if (provedor or cfg("modelos")["classificador"].get("provedor", "luna")) == "jev":
        return JevModelos(conf.openrouter_api_key, cer, luna)
    return luna

"""O cliente do modelo (gpt-6-luna, config/modelos.yaml). Só duas chamadas
existem: `classificar` (JSON fechado) e `duvida` (texto curto com a ficha).

- `OpenAIModelos`: API de Responses da OpenAI, com o timeout e as tentativas do
  arquivo. Caiu: o modelo reserva da OpenRouter (classificador/openrouter.py); caiu
  também, a regex classifica (classificador/reserva.py) e a dúvida vira NAO_SEI.
- Disjuntor: 3 falhas seguidas abrem o circuito por 60 s; aberto, nem tenta.
- `Gravado`: reproduz respostas gravadas (tests/fixtures/llm) pela chave da
  entrada; `Gravador` embrulha o cliente vivo e grava o que ele respondeu.
Toda chamada devolve também `meta` (modelo, ms, texto cru) para o trace.
"""
from __future__ import annotations

import hashlib
import json
import time
from pathlib import Path
from typing import Any, Protocol

import httpx

from nay.classificador.schema import Classificacao, json_schema
from nay.config import cfg

PROMPT = (Path(__file__).parent / "prompt.md").read_text(encoding="utf-8")
URL = "https://api.openai.com/v1/responses"


class FalhaDoModelo(Exception):
    pass


class Modelos(Protocol):
    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]: ...
    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]: ...


def chave_da_entrada(entrada: dict[str, Any]) -> str:
    bruto = json.dumps(entrada, sort_keys=True, ensure_ascii=False, default=str)
    return hashlib.sha1(bruto.encode("utf-8")).hexdigest()[:16]


class Disjuntor:
    def __init__(self, limite: int = 3, pausa_s: float = 60) -> None:
        self.limite, self.pausa_s, self.falhas, self.aberto_ate = limite, pausa_s, 0, 0.0

    def permite(self) -> bool:
        return time.monotonic() >= self.aberto_ate

    def sucesso(self) -> None:
        self.falhas = 0

    def falha(self) -> None:
        self.falhas += 1
        if self.falhas >= self.limite:
            self.aberto_ate, self.falhas = time.monotonic() + self.pausa_s, 0


def _texto_da_resposta(corpo: dict[str, Any]) -> str:
    if corpo.get("output_text"):
        return corpo["output_text"]
    for item in corpo.get("output", []):
        for c in item.get("content", []) or []:
            if c.get("type") in ("output_text", "text") and c.get("text"):
                return c["text"]
    raise FalhaDoModelo("resposta sem texto")


def _uso(u: dict[str, Any], preco: dict[str, float]) -> dict[str, Any]:
    """Tokens da chamada e o custo em dólar, pelo preço de config/modelos.yaml."""
    entrada, saida = int(u.get("input_tokens") or 0), int(u.get("output_tokens") or 0)
    cache = int((u.get("input_tokens_details") or {}).get("cached_tokens") or 0)
    custo = ((entrada - cache) * preco.get("entrada", 0) + cache * preco.get("entrada_em_cache", 0)
             + saida * preco.get("saida", 0)) / 1e6
    return {"tokens_entrada": entrada, "tokens_saida": saida, "custo": round(custo, 6) if preco else None}


class OpenAIModelos:
    def __init__(self, chave: str) -> None:
        self._cli = httpx.Client(headers={"Authorization": f"Bearer {chave}"})
        self.disjuntor = Disjuntor()
        self._uso: dict[str, Any] = {}
        self.tentativas_max = 9           # com reserva, 1: a segunda tentativa é a reserva (Alteração 2, H)

    def _chamar(self, c: dict, instrucao: str, usuario: str, formato: dict | None) -> str:
        corpo: dict[str, Any] = {"model": c["modelo"], "input": [
            {"role": "system", "content": instrucao}, {"role": "user", "content": usuario}]}
        if formato:
            corpo["text"] = {"format": formato}
        r = self._cli.post(URL, json=corpo, timeout=c["timeout_s"])
        if r.status_code >= 400:
            raise FalhaDoModelo(f"{c['modelo']}: HTTP {r.status_code} {r.text[:160]}")
        d = r.json()
        self._uso = _uso(d.get("usage") or {}, c.get("preco_por_milhao") or {})
        return _texto_da_resposta(d)

    def _tentar(self, qual: str, instrucao: str, usuario: str, formato: dict | None) -> tuple[str, dict]:
        c = cfg("modelos")[qual]
        if not self.disjuntor.permite():
            raise FalhaDoModelo("circuito aberto")
        erros = []
        for _ in range(max(min(int(c.get("tentativas", 1)), self.tentativas_max), 1)):
            inicio = time.perf_counter()
            try:
                txt = self._chamar(c, instrucao, usuario, formato)
                self.disjuntor.sucesso()
                return txt, {"modelo": c["modelo"], "ms": int((time.perf_counter() - inicio) * 1000),
                             "erros": erros, **self._uso}
            except (httpx.HTTPError, FalhaDoModelo, ValueError) as e:
                erros.append(f"{type(e).__name__}: {str(e)[:120]}")
        self.disjuntor.falha()
        raise FalhaDoModelo("; ".join(erros))

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        formato = {"type": "json_schema", "name": "classificacao", "schema": json_schema(), "strict": True}
        txt, meta = self._tentar("classificador", PROMPT, json.dumps(entrada, ensure_ascii=False, default=str), formato)
        meta["cru"] = txt
        return Classificacao.model_validate_json(txt), meta

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        txt, meta = self._tentar("duvida", instrucao, usuario, None)
        meta["cru"] = txt
        return txt.strip(), meta


class Gravado:
    """Reproduz respostas gravadas. Entrada sem gravação = falha (o teste diz qual falta)."""

    def __init__(self, pasta: str | Path, fixas: dict[str, Any] | None = None) -> None:
        self.pasta, self.fixas = Path(pasta), fixas or {}

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        if "classificacao" in self.fixas:
            return Classificacao(**self.fixas["classificacao"]), {"modelo": "gravado", "ms": 0}
        arq = self.pasta / f"{chave_da_entrada(entrada)}.json"
        if not arq.exists():
            raise FalhaDoModelo(f"sem gravação: {arq.name}")
        return Classificacao.model_validate_json(arq.read_text(encoding="utf-8")), {"modelo": "gravado", "ms": 0}

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        return self.fixas.get("duvida", "NAO_SEI"), {"modelo": "gravado", "ms": 0}


class Gravador:
    """Embrulha o cliente vivo e grava cada classificação em `pasta` (replay e violações)."""

    def __init__(self, vivo: Modelos, pasta: str | Path) -> None:
        self.vivo, self.pasta = vivo, Path(pasta)
        self.pasta.mkdir(parents=True, exist_ok=True)

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        arq = self.pasta / f"{chave_da_entrada(entrada)}.json"
        if arq.exists():
            return Classificacao.model_validate_json(arq.read_text(encoding="utf-8")), {"modelo": "gravado", "ms": 0}
        c, meta = self.vivo.classificar(entrada)
        arq.write_text(c.model_dump_json(indent=1), encoding="utf-8")
        return c, meta

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        return self.vivo.duvida(instrucao, usuario)

"""O provedor RESERVA dos dois lugares onde o modelo entra (Alteração 2, H).

A Luna (OpenAI) continua sendo a principal. Quando ela falha ou não responde em 8 s (o timeout do classificador em
config/modelos.yaml, sem segunda tentativa quando há reserva), a mesma pergunta vai ao DeepSeek pela OpenRouter,
com o mesmo prompt, o mesmo JSON fechado (json_schema estrito) e o raciocínio desligado. Se a reserva também
cair, segue como antes: a regex classifica (classificador/reserva.py) e a dúvida vira NAO_SEI.

O trace registra quem respondeu (`provedor`) e, quando foi a reserva, o erro da principal.
"""
from __future__ import annotations

import json
import re
import time
from typing import Any

import httpx

from nay.classificador.luna import PROMPT, Disjuntor, FalhaDoModelo, Modelos
from nay.classificador.schema import Classificacao, json_schema
from nay.config import cfg

URL = "https://openrouter.ai/api/v1/chat/completions"
CERCA = re.compile(r"^\s*```(?:json)?\s*|\s*```\s*$")


class OpenRouterModelos:
    def __init__(self, chave: str, cliente: httpx.Client | None = None) -> None:
        self._cli = cliente or httpx.Client(headers={"Authorization": f"Bearer {chave}"})
        self.disjuntor = Disjuntor()

    def _chamar(self, instrucao: str, usuario: str, formato: dict | None) -> tuple[str, dict[str, Any]]:
        c = cfg("modelos")["reserva"]["texto"]
        if not self.disjuntor.permite():
            raise FalhaDoModelo("reserva: circuito aberto")
        corpo: dict[str, Any] = {"model": c["modelo"], "messages": [
            {"role": "system", "content": instrucao}, {"role": "user", "content": usuario}],
            "reasoning": {"enabled": False}, "usage": {"include": True}}
        if formato:
            corpo["response_format"] = {"type": "json_schema", "json_schema": {**formato, "strict": True}}
        inicio = time.perf_counter()
        try:
            r = self._cli.post(URL, json=corpo, timeout=c["timeout_s"])
            if r.status_code >= 400:
                raise FalhaDoModelo(f"{c['modelo']}: HTTP {r.status_code} {r.text[:160]}")
            d = r.json()
            txt = d["choices"][0]["message"]["content"] or ""
        except (httpx.HTTPError, KeyError, IndexError, TypeError, ValueError, FalhaDoModelo) as e:
            self.disjuntor.falha()
            raise FalhaDoModelo(f"reserva: {type(e).__name__}: {str(e)[:160]}") from e
        self.disjuntor.sucesso()
        u = d.get("usage") or {}
        return CERCA.sub("", txt), {"modelo": d.get("model") or c["modelo"], "provedor": "openrouter",
                                    "ms": int((time.perf_counter() - inicio) * 1000),
                                    "tokens_entrada": u.get("prompt_tokens"),
                                    "tokens_saida": u.get("completion_tokens"), "custo": u.get("cost")}

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        txt, meta = self._chamar(PROMPT, json.dumps(entrada, ensure_ascii=False, default=str),
                                 {"name": "classificacao", "schema": json_schema()})
        meta["cru"] = txt
        try:
            return Classificacao.model_validate_json(txt), meta
        except ValueError as e:
            raise FalhaDoModelo(f"reserva: JSON fora do esquema: {str(e)[:160]}") from e

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        txt, meta = self._chamar(instrucao, usuario, None)
        meta["cru"] = txt
        return txt.strip(), meta


class ComReserva:
    """A principal; se ela cair, a reserva. As duas caídas = FalhaDoModelo, e quem chama segue sem modelo."""

    def __init__(self, principal: Modelos, reserva: Modelos) -> None:
        self.principal, self.reserva = principal, reserva

    def _um_ou_outro(self, qual: str, *args) -> tuple[Any, dict[str, Any]]:
        try:
            r, meta = getattr(self.principal, qual)(*args)
            return r, {"provedor": "openai", **meta}
        except FalhaDoModelo as x:
            r, meta = getattr(self.reserva, qual)(*args)
            return r, {**meta, "erro_principal": str(x)[:200]}

    def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
        return self._um_ou_outro("classificar", entrada)

    def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
        return self._um_ou_outro("duvida", instrucao, usuario)

"""Os sinais que a frase dá sem modelo (setor roteador), achados no painel de treino de 06/10.

Cada um é uma situação em que a Nay respondia com a pergunta de filtro seguinte, com "não entendi" ou subindo ao
Tel, e a frase do corretor já dizia o que ele queria:

  despedida      "Qualquer coisa aciono vc. Obrigada", "Não, quer quintal gramado mesmo. Obrigada" (Samara, 13842)
  anuncio        "se tiver para anúncio me manda aqui", "posso anunciar?" (13874)
  tentar_outro   o "Sim" depois de "Quer tentar outro bairro ou outro valor?" (13809, 13810)
  ja_disse       "Deixei descrito" depois de um pedido comprido (13810)
  interessado    "Tenho um cliente interessado nesse apartamento" com o card colado (13907)
  visita_*       o dia e a hora da visita, e o "sim" que confirma os dados (13806, 13830, 13882)

`decidir` devolve (decisão, dados) para o pré-roteador (classificador/atalhos.py) ou None. As frases de quem
ajusta o filtro ("casa/apto", "mobiliado ou semi", "é venda, não locação", "manda o que você tem") moram em
classificador/frases.py: essas passam pelo classificador, porque a mesma mensagem pode trazer bairro e valor.
"""
from __future__ import annotations

import re
from datetime import datetime

from nay.classificador import frases
from nay.contexto.resolver_imovel import Contexto
from nay.estado import filtros, prazos, visita
from nay.texto import normal
from nay.tipos import Conversa

DESPEDIDA = re.compile(
    r"\bqualquer coisa (eu )?(te |lhe )?(aciono|chamo|aviso|falo|procuro|retorno|grito|volto)\b"
    r"|\b(aciono|chamo|procuro) (voce|vc|tu) (depois|qualquer coisa|se precisar)\b"
    r"|^(infelizmente nao|nao precisa mais|deixa (pra la|quieto)|fica (pra|para) (a )?proxima)( obrigad[oa])?$")
AGRADECEU_NO_FIM = re.compile(r"\b(obrigad[oa]|obg|valeu|vlw|grat[oa]|agradeco)$")
PEDE_ANUNCIO = re.compile(
    r"\b(posso|podemos|pode|da pra|da para|consigo|tem como)\s+(?:\w+\s+){0,2}?(anunciar|divulgar|publicar|postar)\b"
    r"|\b(pra|para|p) (eu |mim |a gente |nos )(anunciar|divulgar|publicar|postar)\b"
    r"|\b(pra|para|p) anuncio\b")
# "tenho um apto pra anunciar": o imóvel é DELE (oferta de imóvel, vai ao Tel), não pedido de autorização
IMOVEL_DELE = re.compile(r"\b(tenho|temos|estou com|to com|peguei|captei) (um|uma|uns|umas|\d+) (?!client)"
                         r"|\b(meu|minha) (imovel|apto|ap|apartamento|casa|terreno|sala)\b")
INTERESSADO = re.compile(
    r"\b(client\w+|ele|ela|casal|comprador\w*|inquilin\w+)\b.{0,25}\b(interessad[oa]s?|tem interesse|com interesse|"
    r"se interessou|interessou)\b"
    r"|\b(interessad[oa]s?|interesse) (ness[ea]|nest[ea]|nele|nela|no|na|em)\b"
    r"|\b(gostou|gostaram|amou|adorou|curtiu) (muito |bastante |demais )?(d[eoa]|dess[ea]|dest[ea]|dele|dela)\b")
SEM_INTERESSE = re.compile(r"\bnao (tem|teve|ficou|esta|ta|gostou|gostaram|se interessou|interessou)\b"
                           r"|\bsem interesse\b|\bdesinteress")
# pergunta sobre o imóvel no meio da frase: quem responde é a ficha ("cliente interessado até 4000, mas vi que já
# está incluso a taxa de condomínio né", 13840)
OUTRO_ASSUNTO = re.compile(r"\d|\b(valor|preco|quanto|taxa|iptu|incluso|aceita|pet|andar|vagas?|garagem|mas)\b")
JA_DISSE = re.compile(
    r"\b(deixei|esta|ta) (tudo )?(descrito|escrito|explicado|detalhado|dito)\b"
    r"|\bja (te )?(falei|disse|informei|descrevi|passei|mandei|expliquei)\b(?! (pra|para|pro|a|ao|o) ?(ela|ele|client))"
    r"|\bcomo (eu )?(te )?(falei|disse|descrevi|informei)\b"
    r"|\b(esta|ta) (tudo )?(ai |la )?(em cima|acima|na mensagem|no audio|no texto)\b"
    r"|\b(mensagem|texto|audio) (acima|anterior|de cima)\b")
SIM = re.compile(r"^(s+i+m+|s|ss|sim sim|quero|pode ser|pode|podemos|claro|isso|vamos|bora|ok|certo|correto|"
                 r"confirmo|confirmado|isso mesmo|esta certo|ta certo|tudo certo|perfeito)\b")
NAO = re.compile(r"^(nao|n|nn|errado|ta errado|esta errado)\b")
QUER_VER = re.compile(r"\b(manda|mande|mandar|envia|envie|enviar|quero ver|quero|pode|mostra|mostre|passa|bora)\b")
# "Qual o seu nome por gentileza?? Você de imobiliária??" (13884) subiu ao Tel com 24 h de pausa: ela mesma responde
QUEM_E = re.compile(
    r"\b(qual|como) (e |eh )?(o )?(seu|teu) nome\b|\bcomo (voce|vc|tu) (se )?chama\b|\bquem (e|eh) (voce|vc|tu)\b"
    r"|\bcom quem (eu )?(falo|estou falando|to falando)\b"
    r"|\b(voce|vc|tu) (e |eh )?(de |da |de qual |de que )imobiliaria\b"
    r"|\b(qual|que) (e |eh )?(a )?(sua |tua )?imobiliaria\b|\b(voce|vc|tu) (e |eh )?corretor[a]?\b")


# "Tenho 11 fotos no tirei no grupo, se tiver mais" (13567, rodada 9): ele já tem as fotos, não se manda de novo
TEM_AS_FOTOS = re.compile(
    r"\b(ja )?tenho (as |umas |algumas |\d+ )fotos\b"
    r"|\b(peguei|tirei|baixei|salvei|copiei) (as fotos )?(do|no|pelo) grupo\b"
    r"|\b(ja )?(peguei|tirei|baixei|salvei) as fotos\b|\bas fotos eu (ja )?tenho\b|\bfotos (eu )?ja tenho\b")
# Ela ofereceu "Quer que eu te mande as informações e as fotos?" e ele dispensou ou disse que já tem (13778: "não
# tenho, pra eu atualizar os anuncios disponiveis"). Com pedido de envio na mesma frase, o imóvel vai.
DISPENSOU = re.compile(r"^(nao|n|nn)\b|\bnao precisa\b|\bja tenho\b|^tenho( (sim|aqui|ja|todos|todas|tudo))?$"
                       r"|\btenho (sim|aqui)\b")
PEDE_ENVIO = re.compile(r"(?<!nao )(?<!nao precisa )\b(manda|mande|mandar|envia|envie|enviar|me passa|me passe|"
                        r"quero|queria)\b")
MANDA_AGORA = re.compile(r"(?<!nao )(?<!nao precisa )\b(manda|mande|mandar|envia|envie|enviar|me passa|me passe)\b")
# a confirmação de visita está esperando e ele insiste ("Nay cliente que ir ver assim mesmo ainda da tempo?", 13762)
AINDA_QUER_VISITAR = re.compile(r"\bainda da tempo\b|\b(assim mesmo|mesmo assim)\b"
                                r"|\bpode (confirmar|marcar|agendar)\b|\b(quer|que|vai|vamos) ir\b")
# a visita "no Smile Cidade Nova e Smile Flores" diz ONDE pelo nome: quem lê os nomes é o classificador (13723)
VISITA_EM = re.compile(
    r"\b(visita|visitar|agendar|agendamento|marcar)\b.{0,25}?\b(n[oa]s?|d[oa]s?|em)\s+(?!(?:dia|hoje|amanha|manha|"
    r"tarde|noite|sabado|domingo|segunda|terca|quarta|quinta|sexta|horario|imovel|apartamento|apto|casa|mesmo|"
    r"parte|periodo|final|fim|comeco|inicio|proxim[oa]|semana|mes|cliente|client[ea]s?|\d+)\b)[a-z]{3,}")


def tem_as_fotos(texto: str) -> bool:
    return bool(TEM_AS_FOTOS.search(normal(texto)))


def dispensou(texto: str, c: Conversa, vale: bool) -> bool | None:
    """A resposta à oferta dela ("Quer que eu te mande as informações e as fotos?") é "não" ou "já tenho": True.
    Com o pedido de envio na mesma frase ("não tenho, manda"): False, e o imóvel vai. None: não é resposta à oferta."""
    t = normal(texto)
    if not (c.ultima_acao == "status" and vale and "?" not in (texto or "") and len(t.split()) <= 12
            and DISPENSOU.search(t)):
        return None
    if not PEDE_ENVIO.search(t):
        return True
    return False if MANDA_AGORA.search(t) else None     # "não, quero saber do condomínio": quem lê é o modelo


def perguntou_quem_e(texto: str) -> bool:
    """Ele só quer saber com quem fala (nome, se é de imobiliária). Mensagem curta, sem outro assunto junto."""
    t = normal(texto)
    return len(t.split()) <= 14 and bool(QUEM_E.search(t))


def despedida(texto: str) -> bool:
    """Ele encerrou o pedido: ela se despede e fica à disposição, sem a pergunta de filtro seguinte."""
    t = normal(texto)
    if "?" in (texto or "") or len(t.split()) > 16:
        return False
    return bool(DESPEDIDA.search(t)) or bool(frases.NEGOU.search(t) and AGRADECEU_NO_FIM.search(t))


def pede_anuncio(texto: str) -> bool:
    t = normal(texto)
    return bool(PEDE_ANUNCIO.search(t)) and not IMOVEL_DELE.search(t)


def cliente_interessado(texto: str) -> bool:
    """O cliente tem interesse NESTE imóvel, e a frase não pergunta mais nada (o card colado não conta)."""
    t = normal((texto or "").split("📍")[0])
    return (bool(INTERESSADO.search(t)) and not SEM_INTERESSE.search(t) and not OUTRO_ASSUNTO.search(t)
            and "?" not in (texto or "").split("📍")[0])


def ja_disse(texto: str) -> bool:
    t = normal(texto)
    return len(t.split()) <= 8 and bool(JA_DISSE.search(t))


def pedido_aberto(c: Conversa) -> bool:
    """Há uma ficha de solicitação em andamento: ela está perguntando filtro ou acabou de buscar."""
    return c.estado.startswith("FILTRO_") or c.estado == "BUSCA"


VOCATIVO = re.compile(r"^(amiga|mulher|mana|miga|querida|linda|nay|nai)\b[ ,!.]*")


def _quando_bate(texto: str, pedido: dict, agora: datetime | None) -> bool:
    """O dia e a hora que o sim traz (se traz) são os da confirmação. "Ok, amanhã às 10h" para uma visita das 8h é
    outro horário, não confirmação."""
    hoje = agora.astimezone(visita.MANAUS).date() if agora else None
    hora, dia = visita.hora_dita(texto), (visita.dia_dito(texto, hoje) if hoje else None)
    return (hora is None or hora == pedido.get("hora")) and (dia is None or str(dia) == pedido.get("dia"))


def _sim_que_repete_o_quando(texto: str, t: str, pedido: dict, agora: datetime | None) -> bool:
    """"Mulher, tudo certo amanhã às 8 da manhã" (6220, 23/10): o sim que traz de novo o dia e a hora da confirmação
    passa de 6 palavras e caía no modelo, que montava a confirmação outra vez. Só vale se repete o que ela pediu."""
    t = VOCATIVO.sub("", t)
    if len(t.split()) > 14 or "?" in texto or not SIM.search(t) or not visita.disse_quando(texto):
        return False
    return _quando_bate(texto, pedido, agora)


def _da_visita(texto: str, t: str, c: Conversa, ctx: Contexto, agora: datetime | None) -> tuple[str, dict] | None:
    pedido = visita.aberto(c, agora)
    curta = len(t.split()) <= 6
    esperando = bool(pedido) and pedido.get("etapa") == "confirmar"
    if esperando and curta and "?" not in texto:
        if SIM.search(t) and _quando_bate(texto, pedido, agora):
            return "visita_confirmada", {}
        if NAO.search(t) and not visita.disse_quando(texto):
            return "visita_corrigir", {}
    if esperando and len(t.split()) <= 14 and AINDA_QUER_VISITAR.search(t) and not visita.disse_quando(texto):
        return "visita_confirmada", {}      # "cliente quer ir ver assim mesmo, ainda dá tempo?": é o sim (13762)
    if esperando and _sim_que_repete_o_quando(texto, t, pedido, agora):
        return "visita_confirmada", {}
    escrito = bool(ctx.literais) or ctx.origem in ("literal", "citacao", "card", "lista")
    if PEDE_OUTROS.search(t) and not escrito:
        return None         # pede imóvel (com data junto): o modelo lê (test_pedido_de_busca_na_visita_aberta.py)
    # a resposta à pergunta dela ("As 14:30"): só enquanto a visita é o assunto (o estado muda quando ele fala de
    # outra coisa; aí "tem outro para hoje?" não é horário de visita)
    if pedido and c.estado == "VISITA_PEDIDA" and visita.disse_quando(texto):
        return "visita_dados", {}
    if visita.pediu(texto) and not escrito and VISITA_EM.search(t):
        return None         # o lugar da visita veio pelo NOME: o classificador lê os condomínios (13723)
    if visita.pediu(texto):
        return "visita_dados", {}
    if c.ultima_acao == "interessado" and prazos.gatilho_vale(c, agora) and curta and SIM.search(t):
        return "visita_dados", {}       # ela perguntou se ele quer agendar e ele disse que sim
    return None


PEDE_OUTROS = re.compile(r"\b(alguem com|tem outr[oa]s?|tem mais|tem algo|busco|procuro|opc(ao|oes))\b"
                         r"|\b(para|pra) (locacao|venda|compra)\b")
MESMO_CLIENTE = re.compile(r"\b(o mesmo|a mesma|mesm[oa] client[ea]|e o mesmo|e a mesma)\b")
E_OUTRO = re.compile(r"^(e |eh |sim |isso )*(e |eh )?(para |pra |pro )?(um |uma )?outr[oa]\b")


def _do_outro_cliente(texto: str, t: str, c: Conversa, vale: bool) -> tuple[str, dict] | None:
    """A resposta a "Está perguntando para outro cliente, certo?" (10/10). Só a resposta curta e direta: o resto
    (um pedido novo, uma pergunta) segue o caminho de sempre."""
    if c.ultima_pergunta != "outro_cliente" or not vale or len(t.split()) > 6 or "?" in texto:
        return None
    if frases.pede_todos(texto):        # "pode mandar os 5" (3202, 12/10): quer os da lista, e a lista saía de novo
        return None
    if MESMO_CLIENTE.search(t):
        return "outro_cliente_nao", {}
    if filtros.OUTRO_CLIENTE.search(t) or E_OUTRO.search(t) or SIM.search(t):
        return "outro_cliente_sim", {}
    return ("outro_cliente_nao", {}) if NAO.search(t) else None


def _da_busca(texto: str, t: str, c: Conversa, vale: bool) -> tuple[str, dict] | None:
    """A resposta ao que ela disse quando a busca não achou nada, e o "deixei descrito"."""
    outro = _do_outro_cliente(texto, t, c, vale)
    if outro:
        return outro
    curta = len(t.split()) <= 4
    if c.ultima_acao == "oferta_abaixo" and vale and curta and "?" not in texto:
        # "Nessa faixa de valor eu não tenho agora. Tenho opções a partir de R$ 2.750. Quer que eu te mande?"
        if SIM.search(t) or QUER_VER.search(t):
            return "abaixo_sim", {}
        if NAO.search(t):
            return "tentar_outro", {}
    if c.ultima_acao in ("lista_vazia", "bairro_desconhecido") and vale and len(t.split()) <= 3 and SIM.search(t):
        return "tentar_outro", {}
    if pedido_aberto(c) and ja_disse(texto):
        return "ja_disse", {}
    return None


def decidir(texto: str, c: Conversa, ctx: Contexto, agora: datetime | None) -> tuple[str, dict] | None:
    t = normal(texto)
    da_visita = _da_visita(texto, t, c, ctx, agora)
    if da_visita:
        return da_visita
    if perguntou_quem_e(texto):
        return "quem_sou", {}
    vale = prazos.gatilho_vale(c, agora)
    if ctx.codigo and tem_as_fotos(texto):      # o que ele já tem não se manda de novo (rodada 9)
        return "tem_as_fotos", {}
    resposta = dispensou(texto, c, vale)
    if resposta is not None and (resposta or ctx.codigo):
        return ("dispensou", {}) if resposta else ("so_codigo", {"fotos": False, "status": False, "manda": True})
    if despedida(texto):
        return "despedida", {}
    if pede_anuncio(texto):
        return "anuncio", {}
    fora = None if ctx.codigo else frases.tipo_fora_do_catalogo(texto)
    if fora:                                    # "tem chácara pra vender?" (13/10): a gente não trabalha com isso
        return "tipo_fora", {"tipo": fora}
    escrito = ctx.origem in ("literal", "citacao", "card", "lista")
    da_busca = _da_busca(texto, t, c, vale)
    if da_busca:
        return da_busca
    do_imovel = escrito or (ctx.origem == "foco" and vale)
    if ctx.codigo and do_imovel and cliente_interessado(texto):
        return "interessado", {}
    return None

"""O valor que o corretor disse, lido sem modelo (setor classificador). As expressões moram em valores.yaml.

Tel, 06/10 (rodada 5 do treino): "ela bugou; 'até 6 mil' é de 6 mil para BAIXO, não é 6000 fechado; ela precisa ser
flexível com valores e entender as expressões 'até', 'próximo', 'por volta'". E, no mesmo dia: "sempre usa até 25%
a menos ou 10% a mais nos filtros quando ela recebe um valor".

`ler(texto, finalidade)` devolve o Valor, já em reais:

  teto / por_volta   teto = o valor              a busca usa de -25% a +10% (catálogo, `na_faixa`)
  faixa              piso = o menor, teto = o maior   do menor ao maior, com +10% só em cima
  piso               piso = o valor, sem teto    do valor para cima

Número sem unidade segue a escala da finalidade (`texto.teto_na_escala`): "480" na venda é R$ 480 mil, "3,5" no
aluguel é R$ 3.500. `solto`: a mensagem responde ao "Até que valor?" e o número sozinho já é o valor.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

import yaml

from nay.texto import sem_acento, teto_na_escala

MILHAO = {"milhao", "milhoes", "mi", "kk"}
MINIMO, MAXIMO = 300, 50_000_000        # fora disto não é preço de imóvel


@dataclass(frozen=True)
class Valor:
    familia: str                     # teto | por_volta | faixa | piso
    teto: float | None = None
    piso: float | None = None


@dataclass(frozen=True)
class _Numero:
    inicio: int
    fim: int
    valor: float
    com_unidade: bool                # "6 mil", "1,2 milhão": já está em reais


@lru_cache(maxsize=1)
def tabela() -> dict:
    return yaml.safe_load((Path(__file__).parent / "valores.yaml").read_text(encoding="utf-8"))


def _ou(palavras) -> str:
    return "|".join(re.escape(p) for p in sorted(palavras, key=len, reverse=True))


@lru_cache(maxsize=1)
def _padroes() -> dict[str, re.Pattern]:
    t = tabela()
    uni, cen = _ou(t["unidades"]), _ou(t["centenas"])
    resto = rf"(?:\s+e\s+(?P<r>meio|meia|\d{{3}}|{cen}))?"
    # sem unidade, o "e ..." só vale por extenso ("4 e quinhentos", "4 e meio"): "entre 400 e 500" são dois valores
    digitos = (rf"(?:r\$\s*)?(?P<n>\d{{1,3}}(?:\.\d{{3}})+(?:,\d{{1,2}})?|\d+(?:[.,]\d{{1,2}})?)"
               rf"(?:\s*(?P<u>mil|k|kk|milhoes|milhao|mi)\b{resto}|\s+e\s+(?P<r2>meio|meia|{cen})\b)?")
    extenso = rf"\b(?P<w>meio|{uni})(?:\s+e\s+(?P<wm>meio|meia))?\s+(?P<wu>mil|milhoes|milhao)\b"
    sem_mil = rf"\b(?P<x>{uni})\s+e\s+(?P<xr>{cen})\b"          # "quatro e quinhentos"
    saida = {"numero": re.compile(rf"(?:{extenso}{resto.replace('<r>', '<wr>')}|{sem_mil}|(?<![\w.,]){digitos})"),
             "nao_e_valor": re.compile(rf"^\s*(?:{_ou(t['nao_e_valor'])})\b|^[º°]"),
             "lugar_antes": re.compile(rf"\b(?:{_ou(t['lugar_antes'])})\.?\s*$"),
             "ligacao": re.compile(rf"^\s*(?:{_ou(t['faixa']['ligacao'])})\s*$"),
             "faixa_antes": re.compile(rf"\b(?:{_ou(t['faixa']['antes'])})\s*$")}
    for familia in ("teto", "por_volta", "piso"):
        saida[f"{familia}_antes"] = re.compile(rf"\b(?:{_ou(t[familia]['antes'])})\s*(?:de\s+|os\s+|uns\s+)?$")
        saida[f"{familia}_depois"] = re.compile(rf"^\s*(?:reais\s+)?(?:{_ou(t[familia]['depois'])})\b")
    return saida


def _em_numero(n: str) -> float:
    """'3.500' -> 3500; '4.00' e '4,5' -> 4.0 e 4.5; '1.089,50' -> 1089.5."""
    if re.fullmatch(r"\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?", n):
        return float(n.replace(".", "").replace(",", "."))
    return float(n.replace(",", "."))


def _resto(r: str | None, unidade: float) -> float:
    if not r:
        return 0.0
    if r in ("meio", "meia"):
        return unidade / 2
    return float(r) if r.isdigit() else float(tabela()["centenas"][r])


def _valor_de(m: re.Match) -> tuple[float, bool]:
    """(o valor, veio com unidade?) de um achado do padrão `numero`."""
    g, t = m.groupdict(), tabela()
    if g["w"]:
        unidade = 1e6 if g["wu"] in MILHAO else 1e3
        base = 0.5 if g["w"] == "meio" else float(t["unidades"][g["w"]])
        return (base + (0.5 if g["wm"] else 0)) * unidade + _resto(g["wr"], unidade), True
    if g["x"]:
        return t["unidades"][g["x"]] * 1e3 + t["centenas"][g["xr"]], True
    n = _em_numero(g["n"])
    if g["u"]:
        unidade = 1e6 if g["u"] in MILHAO else 1e3
        return n * unidade + _resto(g["r"], unidade), True
    if g["r2"]:                        # "4 e quinhentos", "4 e meio": o número é de milhar
        return n * 1e3 + _resto(g["r2"], 1e3), True
    return n, False


def _numeros(t: str) -> list[_Numero]:
    p = _padroes()
    achados = []
    for m in p["numero"].finditer(t):
        if p["nao_e_valor"].search(t[m.end():]):
            continue
        valor, com_unidade = _valor_de(m)
        if not com_unidade and p["lugar_antes"].search(t[:m.start()]):
            continue                    # "no parque 10 ate 3 mil": o 10 é do bairro
        achados.append(_Numero(m.start(), m.end(), valor, com_unidade))
    return achados


def _plano(texto: str) -> str:
    t = re.sub(r"(?<=\d)\s?M\b", " milhao", sem_acento(texto or ""))       # "1.2M": só o M maiúsculo é milhão
    return re.sub(r"\s+", " ", t.lower()).strip()


def _na_escala(n: _Numero, finalidade: str | None, do_vizinho: _Numero | None = None) -> float | None:
    """Em reais. "2 a 3 mil": o primeiro pega a unidade do segundo."""
    v = n.valor
    if not n.com_unidade:
        if do_vizinho and do_vizinho.com_unidade and v < 1000:
            v *= 1e6 if do_vizinho.valor >= 1e6 else 1e3
        else:
            v = teto_na_escala(v, finalidade) or 0
    return v if MINIMO <= v <= MAXIMO else None


def _crescente(valores: list[float]) -> list[float]:
    """O segundo número de uma faixa é o maior. "Entre 900 a 1.2k" (07/10) saía teto de 900 mil e piso de 1.200:
    se o segundo veio menor e, mil vezes maior, cabe logo acima do primeiro (até 10 vezes), ele foi dito na unidade
    de cima: 900 mil a 1,2 milhão. "Entre 3 mil e 2.500" não muda (2,5 milhões não é vizinho de 3 mil)."""
    if len(valores) == 2 and valores[1] < valores[0] <= valores[1] * 1000 <= min(valores[0] * 10, MAXIMO):
        return [valores[0], valores[1] * 1000]
    return valores


def _faixa(t: str, ns: list[_Numero], finalidade: str | None, solto: bool) -> Valor | None:
    """Dois ou mais valores ligados ("entre 3.500 e 4.500", "de 2 a 3 mil", "3.500 / 4.00 / 4.500 máximo")."""
    p = _padroes()
    for k in range(len(ns) - 1):
        cadeia = [ns[k]]
        while len(cadeia) + k < len(ns) and p["ligacao"].match(t[cadeia[-1].fim:ns[k + len(cadeia)].inicio]):
            cadeia.append(ns[k + len(cadeia)])
        if len(cadeia) < 2:
            continue
        dita = bool(p["faixa_antes"].search(t[:cadeia[0].inicio])) or any(n.com_unidade for n in cadeia) or solto
        com_unidade = next((n for n in reversed(cadeia) if n.com_unidade), None)
        valores = _crescente([v for n in cadeia if (v := _na_escala(n, finalidade, com_unidade))])
        if dita and len(valores) >= 2 and min(valores) < max(valores):
            return Valor("faixa", teto=max(valores), piso=min(valores))
    return None


def _da_familia(t: str, ns: list[_Numero], finalidade: str | None) -> Valor | None:
    """O primeiro número com uma expressão de família antes ou depois. No teto vale o MAIOR dos valores ditos dali
    em diante ("Até quatro mil, quatro mil, cinco mil": até onde ele vai)."""
    p = _padroes()
    for k, n in enumerate(ns):
        antes, depois = t[max(0, n.inicio - 40):n.inicio], t[n.fim:n.fim + 24]
        for familia in ("piso", "teto", "por_volta"):
            if not (p[f"{familia}_antes"].search(antes) or p[f"{familia}_depois"].search(depois)):
                continue
            if familia == "piso":
                v = _na_escala(n, finalidade)
                return Valor("piso", piso=v) if v else None
            ditos = [v for x in ns[k:] if (v := _na_escala(x, finalidade))] if familia == "teto" else []
            v = max(ditos, default=None) if familia == "teto" else _na_escala(n, finalidade)
            return Valor(familia, teto=v) if v else None
    return None


def ler(texto: str, finalidade: str | None = None, solto: bool = False) -> Valor | None:
    t = _plano(texto)
    ns = _numeros(t)
    if not ns:
        return None
    achado = _faixa(t, ns, finalidade, solto) or _da_familia(t, ns, finalidade)
    if achado or not solto:
        return achado
    # respondendo ao "Até que valor?": o número é o valor, se a mensagem for só ele (e uma ou outra palavra)
    sobra = re.sub(r"[\s.,!?]+", " ", t[:ns[0].inicio] + t[ns[-1].fim:]).split()
    if len(ns) == 1 and len(sobra) <= 3 and (v := _na_escala(ns[0], finalidade)):
        return Valor("teto", teto=v)
    return None


SO_DE_VALOR = frozenset("reais real r mil k kk milhao milhoes mi mes mensal o a e de da do dos das ou no na em um uma "
                        "valor aluguel venda mais menos tipo assim acho que ele ela cliente pode ser seria fica "
                        "ficaria quer paga pagar ate uns umas so meio meia".split())


@lru_cache(maxsize=1)
def _palavras_de_valor() -> frozenset[str]:
    t = tabela()
    das_familias = {p for f in ("teto", "por_volta", "piso") for lado in t[f].values() for e in lado for p in e.split()}
    return SO_DE_VALOR | das_familias | set(t["faixa"]["antes"]) | set(t["unidades"]) | set(t["centenas"])


def so_valor(texto: str) -> bool:
    """A mensagem só fala do valor? "até 4.500, semimobiliado" traz mais coisa: aí quem lê é o classificador."""
    palavras = re.findall(r"[a-z]+", _plano(texto))
    return all(p in _palavras_de_valor() for p in palavras)

"""O compositor: toda frase da Nay é um arquivo em templates/ (formato em
templates/README.md). Nenhum modelo passa por aqui.

`{{var}}` é variável; `{{#lista}}...{{/lista}}` repete para cada item;
`{{#campo}}...{{/campo}}` só aparece se o campo tiver valor. Variável que não
veio vira vazio: nunca `{{nome}}` cru na tela do corretor.
"""
from __future__ import annotations

import re
from datetime import datetime
from functools import lru_cache
from pathlib import Path
from zoneinfo import ZoneInfo

PASTA = Path(__file__).resolve().parent.parent.parent / "templates"
MANAUS = ZoneInfo("America/Manaus")
RE_BLOCO = re.compile(r"\{\{#(\w+)\}\}(.*?)\{\{/\1\}\}", re.S)
RE_VAR = re.compile(r"\{\{(\w+)\}\}")


@lru_cache(maxsize=None)
def template(nome: str) -> str:
    return (PASTA / f"{nome}.md").read_text(encoding="utf-8").rstrip("\n")


def existe(nome: str) -> bool:
    return (PASTA / f"{nome}.md").exists()


def saudacao(agora: datetime | None = None) -> str:
    h = (agora or datetime.now(MANAUS)).astimezone(MANAUS).hour
    return "Bom dia" if h < 12 else "Boa tarde" if h < 18 else "Boa noite"


def _render(txt: str, ctx: dict) -> str:
    def bloco(m: re.Match) -> str:
        chave, corpo = m.group(1), m.group(2)
        v = ctx.get(chave)
        if isinstance(v, list):
            return "".join(_render(corpo, {**ctx, **(item if isinstance(item, dict) else {"item": item})})
                           for item in v)
        return _render(corpo, ctx) if v else ""
    txt = RE_BLOCO.sub(bloco, txt)
    return RE_VAR.sub(lambda m: "" if ctx.get(m.group(1)) is None else str(ctx[m.group(1)]), txt)


def compor(nome: str, ctx: dict | None = None) -> str:
    """O texto do template `nome` com as variáveis de `ctx`. `saudacao` e
    `saudacao_se_primeira` (só na primeira mensagem do dia, com o nome) vêm prontas."""
    ctx = ctx or {}
    quando = ctx.get("agora")
    base = {"saudacao": saudacao(quando), "saudacao_se_primeira": ""}
    if ctx.get("primeira_do_dia") and ctx.get("nome"):
        base["saudacao_se_primeira"] = f"{saudacao(quando)}, {ctx['nome']}! "
    out = _render(template(nome), {**base, **ctx})
    return re.sub(r"\n{3,}", "\n\n", out).strip()

"""Configuração. Segredo e endereço vêm do ambiente (.env); o que o Tel muda vem de
config/*.yaml: `cfg("filtros")`, `cfg("limites")`, `cfg("modelos")`.
Único lugar que lê os.environ."""
from __future__ import annotations

import os
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path
from typing import Any

import yaml

RAIZ = Path(__file__).resolve().parent.parent


@lru_cache(maxsize=None)
def cfg(nome: str) -> dict[str, Any]:
    """cfg("filtros") lê config/filtros.yaml; cfg("limites") e cfg("modelos") idem."""
    return yaml.safe_load((RAIZ / "config" / f"{nome}.yaml").read_text(encoding="utf-8")) or {}


def modo() -> str:
    """sombra | real. O ambiente (MODO) ganha do arquivo: a volta atrás é uma linha do .env."""
    return os.environ.get("MODO") or cfg("limites").get("modo", "sombra")


def _lista(nome: str) -> tuple[str, ...]:
    return tuple(x.strip() for x in os.environ.get(nome, "").split(",") if x.strip())


@dataclass(frozen=True)
class Config:
    database_url: str
    openai_api_key: str
    entrada: str                       # espelho_mensagens | webhook
    tel_telefones: tuple[str, ...]
    zapi_base_url: str                 # https://api.z-api.io/instances/<instância>/token/<token>
    zapi_client_token: str
    openrouter_api_key: str            # só para o Jev


@lru_cache(maxsize=1)
def config() -> Config:
    e = os.environ.get
    return Config(
        database_url=e("DATABASE_URL", ""),
        openai_api_key=e("OPENAI_API_KEY", ""),
        entrada=e("ENTRADA", "espelho_mensagens"),
        tel_telefones=_lista("TEL_TELEFONES"),
        zapi_base_url=e("ZAPI_BASE_URL", ""),
        zapi_client_token=e("ZAPI_CLIENT_TOKEN", ""),
        openrouter_api_key=e("OPENROUTER_API_KEY", ""),
    )

arquivos.doc:
De qual imóvel se fala (setor contexto).

Ordem, a primeira que resolver ganha:
  1. citação: ele marcou uma mensagem nossa e o id resolve por envios/nai_saida;
  2. código literal no texto ("tem o 5717?", "5717", "#5717", "cód 5717");
  3. card colado ("Código: 5717" dentro do card do grupo);
  4. o foco gravado em core_conversa.
NUNCA por semelhança de nome de bairro ("Adrianópolis" virou o 5748 no velho,
pergunta 41) e nunca por número que é preço, área, andar ou quantidade
("tava por 300" virou o imóvel 300, turno 12186).

arquivos.codigo:
"""A rajada (setor entrada): junta as mensagens da mesma pessoa até
RAJADA_SEGUNDOS sem mensagem nova. Roda no worker, fora do caminho do
webhook: esperar não ocupa vaga de nada (pergunta 6: no velho a espera de
20 s segurava uma das 5 vagas do n8n e a fila chegou a 15 min)."""
from __future__ import annotations

from collections import defaultdict
from datetime import datetime, timedelta

from nay.tipos import Mensagem, Rajada


def prontas(pendentes: list[Mensagem], agora: datetime, janela_s: int) -> list[Rajada]:
    """As rajadas cuja última mensagem já tem mais de `janela_s` segundos."""
    por_pessoa: dict[str, list[Mensagem]] = defaultdict(list)
    for m in pendentes:
        if m.direcao == "recebida":
            por_pessoa[m.chave].append(m)
    saida = []
    for ch, ms in por_pessoa.items():
        ms.sort(key=lambda m: m.recebida_em)
        if agora - ms[-1].recebida_em >= timedelta(seconds=janela_s):
            saida.append(Rajada(chave=ch, mensagens=tuple(ms)))
    return sorted(saida, key=lambda r: r.quando)

"""Os filtros da busca (setor estado): quais já foram respondidos, qual vem
agora, e como a mensagem nova os preenche. Um valor novo sobrescreve o antigo,
menos o bairro, que SOMA aos da ficha (06/10: o pedido é como o filtro do site, com
vários bairros marcados); "tanto faz" é valor válido e conta como preenchido."""
from __future__ import annotations

import re

from nay.classificador import frases, valores
from nay.classificador.schema import Classificacao
from nay.config import cfg
from nay.texto import _numero, normal, teto_na_escala
from nay.tipos import Conversa, Imovel

# "é para outro cliente", "agora é outro pedido": os filtros de antes não valem mais (Alteração 2, D)
OUTRO_CLIENTE = re.compile(r"\b(outr[oa] client[ea]|client[ea] nov[oa]|nov[oa] client[ea]|outro pedido|"
                           r"outra busca|outro perfil|outra procura)\b")
FINALIDADE_DITA = re.compile(r"\b(alug\w*|loca\w*|compr\w*|venda|vender|os dois|ambos)\b")
TIPO_DITO = re.compile(r"\b(apto|apartamento|ap|casa|flat|cobertura|sala|loja|terreno|lote|predios?|galpao|"
                       r"deposito|comercial)\b")
VALOR_SOLTO = re.compile(r"(\d+(?:[.,]\d+)?)\s*(mil|k|milhao|milhoes|mi)\b")
SEM_MOBILIA = ("comercial", "sala", "loja", "predio", "galpao", "terreno")
TROCA_A_REGIAO = re.compile(r"^(e|ou) (no|na|nos|nas|em)\b|\b(so|somente|apenas|na verdade|em vez|ao inves|muda|mudou|"
                            r"troca|trocar)\b")


def ordem(c: Conversa) -> tuple[str, ...]:
    """config/filtros.yaml: quem veio do grupo é perguntado da região antes do teto."""
    f = cfg("filtros")
    return tuple(f["ordem_veio_do_grupo"] if c.veio_do_grupo else f["ordem_padrao"])


def preenchido(c: Conversa, filtro: str) -> bool:
    return {
        "finalidade": c.filtro_finalidade is not None,
        "tipo": c.filtro_tipo is not None,
        "teto": c.filtro_teto is not None or c.filtro_piso is not None or c.filtro_teto_tanto_faz,
        "regiao": bool(c.filtro_regiao) or c.filtro_regiao_tanto_faz,
        # A mobília só é perguntada na locação (Tel, 02/10): mobiliado e semimobiliado são clientes
        # diferentes. "tanto_faz" dito uma vez NÃO preenche: ela pergunta a preferência; dito de novo
        # depois dessa pergunta vira "sem_preferencia" e aí sim vai a busca com os dois.
        # Imóvel comercial não tem a pergunta (20/10, 559291792460: clínica de fisioterapia ouviria "mobiliado ou
        # semimobiliado?").
        "mobilia": c.filtro_finalidade != "locacao" or c.filtro_tipo in SEM_MOBILIA
                   or c.filtro_mobilia not in (None, "tanto_faz"),
    }[filtro]


def primeiro_vazio(c: Conversa) -> str | None:
    for f in ordem(c):
        if not preenchido(c, f):
            return f
    return None


def finalidade_pelo_valor(teto: float | None) -> str | None:
    """Regra do Tel (144/190): até R$ 30 mil é aluguel; de R$ 100 mil para cima é venda."""
    r = cfg("filtros").get("finalidade_pelo_valor") or {}
    if not teto:
        return None
    if teto <= r.get("locacao_ate", 30000):
        return "locacao"
    if teto >= r.get("venda_desde", 100000):
        return "venda"
    return None


def _do_classificador(cl: Classificacao) -> dict:
    tf = set(cl.tanto_faz)
    return {"finalidade": cl.finalidade or ("tanto_faz" if "finalidade" in tf else None),
            "tipo": cl.tipo or ("tanto_faz" if "tipo" in tf else None),
            "teto": cl.teto, "teto_tanto_faz": "teto" in tf, "regiao_tanto_faz": "bairro" in tf,
            "quartos": cl.quartos, "mobilia": cl.mobilia or ("tanto_faz" if "mobilia" in tf else None)}


def _faixa(d: dict, campo: str, valor) -> dict:
    """teto e região: valor dito ganha de 'tanto faz'; 'tanto faz' apaga o valor antigo."""
    if d.get(campo):
        return {f"filtro_{campo}": valor(d[campo]), f"filtro_{campo}_tanto_faz": False}
    if d.get(f"{campo}_tanto_faz"):
        return {f"filtro_{campo}": None, f"filtro_{campo}_tanto_faz": True}
    return {}


def _mudancas(d: dict) -> dict:
    mud = {f"filtro_{k}": d[k] for k in ("finalidade", "tipo", "mobilia") if d.get(k)}
    if d.get("quartos"):
        mud["filtro_quartos"] = int(d["quartos"])
    mud |= _faixa(d, "teto", float) | _faixa(d, "regiao", tuple)
    if "filtro_teto" in mud or d.get("piso"):
        # o valor novo leva o piso junto: o da faixa ("entre 3.500 e 4.500"), o do "a partir de", ou nenhum
        mud["filtro_piso"] = float(d["piso"]) if d.get("piso") else None
    if d.get("piso") and not d.get("teto"):
        mud |= {"filtro_teto": None, "filtro_teto_tanto_faz": False}
    return mud


def _valor(c: Conversa, d: dict, cl: Classificacao | None, texto: str) -> dict:
    """O valor desta mensagem, em reais, com a família que a frase diz (classificador/valores.py). A faixa e o
    piso só a biblioteca vê; o teto é o do modelo (ou o da resposta direta) e, sem ele, o que a frase disser."""
    fin = d.get("finalidade") if d.get("finalidade") in ("locacao", "venda") else c.filtro_finalidade
    dito = valores.ler(texto, fin) if texto and (cl is None or cl.intencao == "pedir_imovel") else None
    if dito and dito.familia in ("faixa", "piso"):
        return {"teto": dito.teto, "piso": dito.piso}
    if d.get("teto"):       # "até 900" num pedido de compra é R$ 900 mil; "3" no aluguel é R$ 3 mil (texto.py)
        return {"teto": teto_na_escala(float(d["teto"]), fin)}
    return {"teto": dito.teto} if dito else {}


def _regiao(c: Conversa, novos: tuple[str, ...], texto: str) -> tuple[str, ...]:
    """A ficha de solicitação é como o filtro do site, com vários bairros marcados (Tel, 06/10): o bairro dito
    depois SOMA aos que já estavam, em vez de ficar só o último. Troca quando ele diz que é troca ("só no Aleixo",
    "e no Parque 10?", "na verdade...") ou quando só repete um dos que já estavam (ele estreitou)."""
    antes = tuple(c.filtro_regiao or ())
    if not antes or TROCA_A_REGIAO.search(normal(texto)) or set(novos) <= set(antes):
        return novos
    return tuple(dict.fromkeys((*antes, *novos)))


def aplicar(c: Conversa, cl: Classificacao | None, bairros: tuple[str, ...],
            direto: dict | None = None, texto: str = "", soma: bool = True) -> Conversa:
    """Preenche os filtros com o que veio NESTA mensagem (classificador e/ou pré-roteador). `soma`: os bairros
    novos entram junto dos que já estavam (falso quando o pedido recomeça de um imóvel que saiu)."""
    d = {**(_do_classificador(cl) if cl else {}), **{k: v for k, v in (direto or {}).items() if v}}
    d |= _valor(c, d, cl, texto)
    if d.get("mobilia") == "tanto_faz" and c.ultima_acao == "pergunta_mobilia_preferencia":
        d["mobilia"] = "sem_preferencia"      # ela já perguntou a preferência e ele manteve: vale os dois
    if frases.AS_DUAS_MOBILIAS.search(normal(texto)):
        # "mobiliado ou semi mobiliado" (13853): ele já disse que servem os dois, a pergunta não se faz
        d["mobilia"] = "sem_preferencia"
    if bairros:
        d["regiao"] = bairros
    if d.get("regiao") and soma:
        d["regiao"] = _regiao(c, tuple(d["regiao"]), texto)
    pedidos = frases.extras(texto) if cl is None or cl.intencao == "pedir_imovel" else ()
    c = c.com(filtro_extras=tuple(dict.fromkeys((*c.filtro_extras, *pedidos)))) if pedidos else c
    novo = c.com(**_mudancas(d))
    if novo.filtro_finalidade is None:
        pelo_valor = finalidade_pelo_valor(novo.filtro_teto or novo.filtro_piso)
        if pelo_valor:
            novo = novo.com(filtro_finalidade=pelo_valor)
    return novo


CAMPOS = ("filtro_finalidade", "filtro_tipo", "filtro_teto", "filtro_teto_tanto_faz", "filtro_piso", "filtro_regiao",
          "filtro_regiao_tanto_faz", "filtro_quartos", "filtro_mobilia", "filtro_extras")


def mudou(antes: Conversa, depois: Conversa) -> bool:
    """A mensagem trouxe filtro novo ou diferente?"""
    return any(getattr(antes, k) != getattr(depois, k) for k in CAMPOS)


def zerar(c: Conversa, agora=None) -> Conversa:
    """Nova busca do zero (ele começou outro pedido): filtros, recusados e a lista de antes limpos. Com `agora`,
    o pedido novo começa nesse instante: o que foi enviado ANTES era de outro cliente e pode sair de novo."""
    # a pergunta de filtro que estava no ar era do pedido de antes: no novo ela ainda não saiu (pedido._ja_perguntou)
    estado = "IDENTIFICANDO" if c.estado.startswith("FILTRO_") else c.estado
    return c.com(estado=estado, filtro_finalidade=None, filtro_tipo=None, filtro_teto=None, filtro_teto_tanto_faz=False,
                 filtro_piso=None, filtro_regiao=None, filtro_regiao_tanto_faz=False, filtro_quartos=None,
                 filtro_mobilia=None, filtro_extras=(), filtro_condominio=None, rejeitados=(), ultima_lista=(),
                 pedido_desde=agora if agora is not None else c.pedido_desde)


def sem_resposta(c: Conversa, filtro: str) -> Conversa:
    """Ela já perguntou este filtro e a resposta não o preencheu: vale como tanto faz (a pergunta não se repete)."""
    return c.com(**{"finalidade": {"filtro_finalidade": "tanto_faz"}, "tipo": {"filtro_tipo": "tanto_faz"},
                    "teto": {"filtro_teto_tanto_faz": True}, "regiao": {"filtro_regiao_tanto_faz": True},
                    "mobilia": {"filtro_mobilia": "sem_preferencia"}}[filtro])


def algum(c: Conversa) -> bool:
    """A ficha de solicitação tem alguma coisa anotada?"""
    return any(getattr(c, k) for k in CAMPOS)


def fechar(c: Conversa) -> Conversa:
    """"Manda o que você tem" (13872): o que ele não disse vira tanto faz e a busca sai com o que já se sabe."""
    mud: dict = {}
    if c.filtro_finalidade is None:
        mud["filtro_finalidade"] = "tanto_faz"
    if c.filtro_tipo is None:
        mud["filtro_tipo"] = "tanto_faz"
    if c.filtro_teto is None and c.filtro_piso is None:
        mud["filtro_teto_tanto_faz"] = True
    if not c.filtro_regiao:
        mud["filtro_regiao_tanto_faz"] = True
    if c.filtro_mobilia in (None, "tanto_faz"):
        mud["filtro_mobilia"] = "sem_preferencia"
    return c.com(**mud)


def corrigir_finalidade(c: Conversa, finalidade: str) -> Conversa:
    """"Amiga é venda não locação" (13852): o MESMO pedido com a finalidade certa. Tipo, região e quartos ficam; o
    valor só fica se for da escala da finalidade nova (teto de aluguel não serve para compra); a mobília é da
    locação. O que ela mostrou na finalidade errada sai da frente."""
    teto = c.filtro_teto if finalidade_pelo_valor(c.filtro_teto) == finalidade else None
    # o valor que ela perguntou era o da outra finalidade: o desta ainda não foi perguntado (pedido._ja_perguntou)
    estado = "IDENTIFICANDO" if c.estado.startswith("FILTRO_") else c.estado
    return c.com(estado=estado, filtro_finalidade=finalidade, filtro_teto=teto, filtro_teto_tanto_faz=False,
                 filtro_piso=c.filtro_piso if teto else None,
                 filtro_mobilia=c.filtro_mobilia if finalidade == "locacao" else None, ultima_lista=())


def _familia(tipo: str | None) -> str | None:
    return "casa" if tipo == "casa_condominio" else tipo


def pedido_novo(c: Conversa, cl: Classificacao | None, texto: str) -> bool:
    """O pedido desta mensagem é OUTRO, e não um ajuste do de antes (levantamento de 05/10, turno 939: pediu
    "casa de aluguel com proposta de compra" e a busca usou a venda até R$ 1 milhão em Flores de três dias antes).

    Novo: "outro cliente"; a finalidade escrita é outra (locação x venda x os dois; quem tinha dito "os dois"
    e agora diz "alugar" só estreitou); o tipo escrito é outro E veio com valor NOVO ou bairro (um perfil
    inteiro). Mudar um filtro só ("e no Parque 10?", "até 3 mil") é ajuste: os outros continuam.

    O valor tem que ser OUTRO, como já valia para a finalidade: repetir o mesmo teto não é cliente novo.
    22/10/2026, ...2349: "Ela quer mais nessa região mesmo // Pode ser apartamento" veio com o teto de 7 mil
    que já estava na ficha. O pedido foi zerado, e ela perguntou a região e a mobília de novo, as duas coisas
    que ele já tinha respondido (a região, na mesma mensagem em que disse que era a MESMA)."""
    t = normal(texto)
    if OUTRO_CLIENTE.search(t):
        return True
    if cl is None:
        return False
    if (cl.finalidade and c.filtro_finalidade in ("locacao", "venda") and cl.finalidade != c.filtro_finalidade
            and FINALIDADE_DITA.search(t)):
        return True
    antes = _familia(c.filtro_tipo)
    valor_novo = bool(cl.teto) and float(cl.teto) != float(c.filtro_teto or 0)
    return bool(cl.tipo and antes not in (None, "tanto_faz") and _familia(cl.tipo) != antes and TIPO_DITO.search(t)
                and (valor_novo or cl.bairros))


def _valor_solto(texto: str) -> float | None:
    m = VALOR_SOLTO.search(normal(texto))
    if not m:
        return None
    return _numero(m.group(1)) * (1e3 if m.group(2) in ("mil", "k") else 1e6)


def do_imovel(i: Imovel, texto_dele: str = "", finalidade: str | None = None) -> dict:
    """Os filtros que o card colado diz (turno 921: colou o card do Morada dos Pássaros e ouviu "Até que
    valor?" e "Em qual bairro?"). A finalidade: a única do imóvel, ou a do valor que ele escreveu ("900 mil, né?")."""
    if i.de_locacao != i.de_venda:
        fin = "locacao" if i.de_locacao else "venda"
    else:       # serve aos dois: a finalidade da conversa, ou a do valor que ele escreveu
        fin = finalidade if finalidade in ("locacao", "venda") else finalidade_pelo_valor(_valor_solto(texto_dele))
    teto = i.valor_aluguel if fin == "locacao" else i.valor_venda if fin == "venda" else None
    return {"finalidade": fin, "tipo": i.tipo, "teto": teto, "regiao": (i.bairro_norm,) if i.bairro_norm else ()}


def do_digitado(i: Imovel | None) -> dict:
    """Os quartos, os valores e o tipo do imóvel cujo código ele DIGITOU: quem escreve "Portinari cod 5551 / 2
    quartos / 1.8k" (13776) descreve o próprio imóvel, não um perfil de busca (estado/maquina.py, _perfil_novo)."""
    if i is None:
        return {}
    casa = ("casa", "casa_condominio")
    return {"quartos": i.quartos, "valores": tuple(v for v in (i.valor_aluguel, i.valor_venda) if v),
            "tipos": casa if i.tipo in casa else (i.tipo,)}


def completar(c: Conversa, d: dict) -> Conversa:
    """Só os filtros VAZIOS, com o que veio do card colado: o que ele disse continua valendo."""
    if not d:
        return c
    mud = {}
    if c.filtro_finalidade is None and d.get("finalidade"):
        mud["filtro_finalidade"] = d["finalidade"]
    if c.filtro_tipo is None and d.get("tipo"):
        mud["filtro_tipo"] = d["tipo"]
    if c.filtro_teto is None and not c.filtro_teto_tanto_faz and d.get("teto"):
        mud["filtro_teto"] = float(d["teto"])
    if not c.filtro_regiao and not c.filtro_regiao_tanto_faz and d.get("regiao"):
        mud["filtro_regiao"] = tuple(d["regiao"])
    return c.com(**mud) if mud else c

arquivos.doc:
A máquina de estados da conversa (setor estado). O coração da entrega 1.
Função pura: (conversa, evento) -> (conversa nova, ação). Quem decide o caminho é ela, com dado gravado em
core_conversa -- nunca o modelo, nunca regex sobre o que a Nay mesma enviou (perguntas 12 e 13).

Ordem de cada turno (a mesma do pedido do Tel):
  a. papel que não é corretor, Tel com a conversa ou escalação em vigor -> para;
  b. pré-roteador (sem modelo): cortesia, só código/card/citação, fotos, filtro respondido, e os sinais da
     frase (despedida, anúncio, visita com dia e hora, cliente interessado: classificador/sinais.py);
  c. classificador: pergunta sobre imóvel -> ficha; pedir imóvel -> a ficha de solicitação (estado/pedido.py):
     filtros na ORDEM_FILTROS, UMA pergunta por turno, e só lista com os quatro preenchidos (ou "tanto faz");
     visita -> pergunta o dia e a hora, confirma e anota (estado/visita.py); o resto -> template.

arquivos.codigo:
"""A máquina de estados da conversa (setor estado). O coração da entrega 1.
Função pura: (conversa, evento) -> (conversa nova, ação). Quem decide o caminho é ela, com dado gravado em
core_conversa -- nunca o modelo, nunca regex sobre o que a Nay mesma enviou (perguntas 12 e 13).

Ordem de cada turno (a mesma do pedido do Tel):
  a. papel que não é corretor, Tel com a conversa ou escalação em vigor -> para;
  b. pré-roteador (sem modelo): cortesia, só código/card/citação, fotos, filtro respondido, e os sinais da
     frase (despedida, anúncio, visita com dia e hora, cliente interessado: classificador/sinais.py);
  c. classificador: pergunta sobre imóvel -> ficha; pedir imóvel -> a ficha de solicitação (estado/pedido.py):
     filtros na ORDEM_FILTROS, UMA pergunta por turno, e só lista com os quatro preenchidos (ou "tanto faz");
     visita -> pergunta o dia e a hora, confirma e anota (estado/visita.py); o resto -> template.
"""
from __future__ import annotations

from datetime import datetime

from nay.estado import filtros, memoria, multiplos, pedido, prazos, visita
from nay.estado.acao import Acao, Evento
from nay.estado.apresentar import (
    apresentar,
    apresentar_varios,
    do_card_colado,
    esta_valendo,
    origem_de,
    so_fotos,
)
from nay.estado.escalada import escalar
from nay.estado.pedido import pedir_imovel, pediu, rejeitar, rejeitar_com_teto
from nay.estado.pergunta import do_escrito, dos_varios, pergunta_sobre_imovel
from nay.nos import no
from nay.texto import cumprimentou
from nay.tipos import Conversa


def _vigente(ate: datetime | None, agora: datetime) -> bool:
    return bool(ate) and ate > agora


def qual_da_lista(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela mandou uma LISTA e ele respondeu "manda", "esse", "envia", sem dizer qual: a mesma pergunta de
    quando a busca devolveria a mesma lista ("Qual deles eu te mando?"; de novo, sobe ao Tel). Quem escreve a
    pergunta, com os nomes da lista curta, é acoes/preparo.py (`mesma_lista`). O foco de outro pedido sai."""
    return (c.com(foco_codigo=None, foco_origem=None),
            Acao("template", template="qual_da_lista", dados={"codigos": list(ev.dados_pre.get("codigos") or ())}))


def _perfil_novo(ev: Evento) -> bool:
    """A mensagem traz um perfil de busca (tipo, teto ou quartos) além do imóvel escrito? O card colado tem tipo,
    quartos e valor: é o card que o modelo leu, não um perfil (920). E quem escreve "Bosque Residencial Portinari
    cod 5551 / 2 quartos / 1.8k" (13776) está descrevendo o próprio imóvel: os quartos e o valor são os dele."""
    cl, dele = ev.classificacao, ev.do_escrito
    if ev.contexto.card_colado:
        return False
    if dele and cl.quartos in (None, dele.get("quartos")) and (cl.teto is None or cl.teto in dele.get("valores", ())):
        return bool(cl.teto is None and cl.quartos is None and cl.tipo and cl.tipo not in dele.get("tipos", ()))
    return bool(cl.tipo or cl.teto or cl.quartos)


def por_intencao(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    cl = ev.classificacao
    i = cl.intencao
    if i in DIRETAS:
        return DIRETAS[i](c, ev)
    escrito = ev.contexto.origem in ("literal", "card", "citacao", "lista")   # o foco antigo não conta aqui
    # O código (ou a opção da lista) que ele escreveu é o pedido mais exato que existe: vale mesmo com o
    # bairro na mesma frase ("Parque dez Milano código 9005" recebeu a lista de novo em 02/10). Só vira
    # busca nova quando ele traz perfil junto (tipo, teto ou quartos): "algo como o 5717 até 3 mil".
    perfil_novo = _perfil_novo(ev)
    if i == "pedir_imovel" and ev.contexto.codigo and escrito and not perfil_novo:
        return apresentar(c, ev, ev.contexto.codigo, pediu(ev), False)
    if i == "pedir_imovel" and ev.contexto.candidatos and not perfil_novo:     # marcou a lista: qual deles?
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.contexto.candidatos)
    if i == "pedir_imovel":
        return multiplos.com_o_envio(c, ev, pedir_imovel(c, ev))
    nosso = bool(ev.contexto.codigo) and ev.contexto.origem in ("literal", "card")
    if nosso and i in ("oferta_de_imovel", "assunto_geral", "nao_da_para_saber"):
        return do_escrito(c, ev)        # o código ou o card é NOSSO: não é oferta dele e não sobe ao Tel (13776)
    if i in ("oferta_de_imovel", "assunto_geral", "resultado_visita"):
        return escalar(c, ev, i.replace("_", " "))      # resultado de visita: quem cuida é gente (entrega 2)
    if ev.contexto.origem == "citacao" and ev.contexto.codigo and (
            i == "nao_da_para_saber" or (i == "cortesia" and cumprimentou(ev.texto))):
        # ele MARCOU o card e o que escreveu não diz o que quer: a resposta é sobre aquele imóvel, nunca
        # "não entendi" (corretor do 3878, 02/10). Diz que está disponível e oferece o card e as fotos.
        return apresentar(c, ev, ev.contexto.codigo, False, True, so_status=True)
    if i == "cortesia" and cumprimentou(ev.texto):
        return saudar(c)
    if i in SIMPLES:        # a parceria que já diz o que quer recebe o que pediu (estado/multiplos.py)
        return multiplos.parceria(c, ev, pedir_imovel) if i == "parceria" else (c, SIMPLES[i])
    return nao_entendi(c, ev)


# a intenção que leva direto a uma situação, sem olhar mais nada
DIRETAS = {"pergunta_sobre_imovel": lambda c, ev: pergunta_sobre_imovel(c, ev),
           "rejeitar_imovel": lambda c, ev: rejeitar(c, ev), "visita": visita.pedir,
           "recado": lambda c, ev: recado(c, ev)}
SIMPLES = {
    "cortesia": Acao("silencio", motivo="cortesia"),       # agradecimento ou "ok": sem resposta
    "parceria": Acao("template", template="parceria"),
}


def recado(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Notícia do cliente ("aguardando um retorno dele", "ela achou um"): ela acusa o recado uma vez e espera.
    Recado em cima do recado, calada. Nunca "não entendi", nunca sobe ao Tel (Alteração 2, E)."""
    # O recado que diz o nome de UM imóvel põe esse imóvel na frente (rodada 9, 13570: "vou mostrar o Smille Flores
    # para um cliente" e, horas depois, "Conseguimos agendar para amanhã?" ouviu "De qual imóvel você fala?")
    ctx = ev.contexto
    dito = ctx.codigo if ctx.origem in ("literal", "citacao", "card", "lista") else (
        ev.condominio_codigos[0] if len(ev.condominio_codigos) == 1 else None)
    if dito:
        c = c.com(foco_codigo=dito, foco_origem=origem_de(c, ev, dito))
    if c.ultima_acao == "recado" and prazos.gatilho_vale(c, ev.agora):
        return c, Acao("silencio", motivo="recado: ela já acusou")
    return c, Acao("template", template="recado", codigo=dito)


def saudar(c: Conversa) -> tuple[Conversa, Acao]:
    """Ele só cumprimentou: ela cumprimenta de volta e espera (Tel, 15/09). Em 02/10 "Oii Boa tarde"
    passou pelo modelo como cortesia e ficou sem resposta: cumprimento NUNCA é silêncio."""
    return (c.com(estado="IDENTIFICANDO" if c.estado == "NOVO" else c.estado),
            Acao("template", template="saudacao"))


def _so_codigo(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Só a pergunta ("ainda está disponível?", o card colado ou o card MARCADO sem pedido nenhum): só a
    resposta. Com "me envia", "manda aí" ou pedido de foto junto: card e fotos."""
    ctx, d = ev.contexto, ev.dados_pre
    pediu = bool(d.get("fotos") or d.get("manda"))
    espera = visita.aberto(c, ev.agora)
    if espera and espera.get("etapa") == "falta" and not espera.get("codigo") and not pediu:
        return visita.pedir(c, ev)      # 22/10, ...9660: "Podemos agendar as 14" + "Esse aqui": o imóvel chegou, a visita segue
    so_status = (bool(d.get("status")) or ctx.card_colado or bool(d.get("marcou"))) and not pediu
    if d.get("fotos") and c.ultima_acao == "varios" and ctx.codigo in c.ultima_lista:
        return so_fotos(c, ev, ctx.codigo)      # o card dele acabou de sair junto com os outros: agora só as fotos
    if d.get("valendo") and not pediu:          # "tá valendo?": sim, por quanto, e o card (13653)
        return esta_valendo(c, ev, ctx.codigo)
    if ctx.card_colado and not pediu and not d.get("status") and not d.get("marcou"):
        return do_card_colado(c, ev, ctx.codigo)        # colou o nosso card e mais nada: as fotos (13764)
    # ela perguntou "É este imóvel?" e ele respondeu que sim: a origem passa a ser dele (portão de coerência).
    # O mesmo quando ela acabou de dizer "Sim, está disponível. Quer que eu te mande?" (ou "já te enviei, quer de
    # novo?") e ele respondeu "manda": é a resposta à pergunta DELA sobre este imóvel, e "É este imóvel?" em cima
    # disso é conversa de robô (8585, 12/10: os filtros eram de um pedido antigo).
    # 20/10: a pergunta "serve para o seu cliente?" da Nay Captação dos Grupos vale o dia (o foco), não 2 h
    serve = c.ultima_acao == "pergunta_serve" and prazos.foco_vale(c, ev.agora)
    respondeu = (pediu and ctx.codigo == c.foco_codigo and c.ultima_acao in ("status", "ja_mandei", "pergunta_serve")
                 and (prazos.gatilho_vale(c, ev.agora) or serve))
    return apresentar(c, ev, ctx.codigo, pediu, bool(d.get("status")), so_status=so_status,
                      origem="confirmado" if d.get("confirmado") or respondeu else None)


def _calada(motivo: str):
    return lambda c, ev: (c, Acao("silencio", motivo=motivo))


# decisão do pré-roteador -> (a situação, precisa de um imóvel resolvido?)
DO_PRE = {
    "vazio": (_calada("mensagem sem texto (figurinha, reação ou mídia sem leitura)"), False),
    "cortesia_agradece": (_calada("agradecimento"), False),
    "cortesia_saudacao": (lambda c, ev: saudar(c), False),
    "so_codigo": (_so_codigo, True),
    "rejeitar": (lambda c, ev: rejeitar(c, ev), False),
    "rejeitar_com_teto": (lambda c, ev: rejeitar_com_teto(c, ev), True),
    "qual_da_lista": (lambda c, ev: qual_da_lista(c, ev), False),
    "fotos": (lambda c, ev: so_fotos(c, ev, ev.contexto.codigo), True),
    "filtro_direto": (lambda c, ev: pedir_imovel(c, ev), False),
    # os sinais da frase (classificador/sinais.py, painel de 06/10)
    "despedida": (pedido.despedida, False), "anuncio": (pedido.anuncio, False),
    "quem_sou": (lambda c, ev: (c, Acao("template", template="quem_sou")), False),
    "tentar_outro": (pedido.tentar_outro, False), "ja_disse": (pedido.ja_disse, False),
    "abaixo_sim": (pedido.abaixo_da_faixa, False),
    "outro_cliente_sim": (pedido.outro_cliente, False), "outro_cliente_nao": (pedido.mesmo_cliente, False),
    "interessado": (pedido.interessado, True),
    "visita_dados": (visita.pedir, False), "visita_confirmada": (visita.confirmar, False),
    "visita_corrigir": (visita.corrigir, False),
    # rodada 9 (07/10): o que ele já tem não se manda de novo; a pergunta sobre os que estão na frente dele
    "tem_as_fotos": (pedido.tem_as_fotos, True), "dispensou": (pedido.dispensou, False),
    "pergunta_dos_varios": (dos_varios, False), "tipo_fora": (multiplos.tipo_fora, False),
}


def por_pre(c: Conversa, ev: Evento) -> tuple[Conversa, Acao] | None:
    ctx, p = ev.contexto, ev.pre
    if p == "qual" and ctx.candidatos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ctx.candidatos)
    if p == "todos_da_lista" and ev.dados_pre.get("codigos"):
        return apresentar_varios(c, ev, tuple(ev.dados_pre["codigos"]),
                                 tuple(ev.dados_pre.get("falta_escolher") or ()))
    situacao, com_imovel = DO_PRE.get(p or "", (None, False))
    if situacao is None or (com_imovel and not ctx.codigo):
        return None
    return situacao(c, ev)


def precisa_classificar(c: Conversa, ev: Evento) -> bool:
    """Chamar o modelo só quando a máquina vai usar o que ele disser."""
    return (ev.papel == "corretor" and ev.na_lista and (not ev.midia_visual or bool(ev.texto.strip()))
            and not _vigente(c.humano_ate, ev.agora)
            and not (c.estado == "ESCALADO" and _vigente(c.escalado_ate, ev.agora)))


@no("decisao.transicao")
def transicao(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    if ev.papel != "corretor":
        return c, Acao("fora_do_escopo", motivo=f"papel {ev.papel}")
    if _vigente(c.humano_ate, ev.agora):
        return c, Acao("silencio", motivo="o Tel está com a conversa")
    if c.estado == "ESCALADO" and _vigente(c.escalado_ate, ev.agora):
        return c, Acao("silencio", motivo=f"escalado: {c.escalado_motivo}")
    if not ev.na_lista:
        return c, Acao("fora_da_lista", motivo="não está em corretores",
                       dados={"perguntou": ev.perguntou_de_imovel})
    if ev.midia_visual and not ev.texto.strip():
        # SÓ a imagem, sem texto: ela não lê imagem (01/10). Diz que recebeu e a conversa segue aberta. Com texto,
        # o texto é atendido como sempre. Nos dois casos o Tel é avisado (acoes/imagem.py; Pedro, 07/10).
        return c, Acao("template", template="recebi_midia")
    c = filtros.completar(c, ev.do_card)        # o card colado preenche os filtros vazios (921)
    c = memoria.da_frase(c, ev.texto, ev.contexto.card_colado)     # "pra alugar" dito em qualquer frase fica na ficha
    pre = por_pre(c, ev)
    if pre:
        return pre
    if ev.classificador_falhou or ev.classificacao is None:
        return nao_entendi(c, ev)
    if ev.classificacao.intencao in memoria.OUVE and not ev.contexto.codigo:
        # "tem casa no Ponta Negra ou Tarumã? Se sim aceita parceria?" (1885): o perfil dito fora do pedido fica
        # na ficha, e a pergunta "casa ou apartamento?" não se faz depois
        c = memoria.completar(c, memoria.ouvido(ev.classificacao, ev.bairros))
    return multiplos.dois_clientes(c, ev, pedido.perguntar_proximo_filtro) or por_intencao(c, ev)


PERGUNTA_DA_ACAO = {"buscar": "qual_imovel", "perguntar_qual": "qual_imovel"}
PERGUNTA_DO_TEMPLATE = {"pergunta_qual_imovel": "qual_imovel", "qual_da_lista": "qual_imovel",
                        "pergunta_so_climatizado": "mobilia", "ja_mandei": "interesse",
                        "bairro_ambiguo": "regiao", "bairro_desconhecido": "regiao", "condominio_sem_oferta": "regiao",
                        "qual_bairro_ou_valor": "bairro_ou_valor", "condominio_sem_oferta_ainda": "regiao",
                        "mesma_lista_do_filtro": "qual_imovel"}
# ela repetiu que no condomínio não tem nada: a pergunta "aceita outro condomínio ou bairro?" continua no ar
FICA_COMO = {"condominio_sem_oferta_ainda": "condominio_sem_oferta", "mesma_lista_do_filtro": "qual_da_lista"}


@no("decisao.anotar")
def anotar(c: Conversa, a: Acao) -> Conversa:
    """Grava o que ela acabou de fazer e de perguntar. É por este dado, e não por regex sobre
    o que ela enviou, que o turno seguinte sabe que "manda aí" depois do card quer as fotos."""
    if a.tipo in ("silencio", "fora_do_escopo", "fora_da_lista"):
        return c
    if a.tipo == "template" and a.template == "quem_sou":
        return c            # ela só disse quem é: a pergunta que estava no ar continua valendo
    if a.tipo == "perguntar_filtro":
        # a pergunta repetida porque a resposta não deu para entender fica marcada: a terceira não existe
        repetiu = a.motivo == "de_novo" and a.filtro != "mobilia_preferencia"
        mesma = c.ultima_pergunta == a.filtro and c.ultima_acao in (f"pergunta_{a.filtro}", "repetiu_pergunta")
        return c.com(ultima_pergunta=a.filtro, pergunta_vezes=c.pergunta_vezes + 1 if mesma else 1,
                     ultima_acao="repetiu_pergunta" if repetiu else f"pergunta_{a.filtro}")
    if a.tipo == "visita_pedida":       # visita_entregue, visita_qual_horario, visita_confirmar, visita_anotada
        return c.com(ultima_pergunta=None if a.template == "visita_anotada" else "visita", ultima_acao=a.template)
    if a.tipo == "apresentar" and a.dados.get("oferece_visita"):
        return c.com(ultima_pergunta="visita", ultima_acao="interessado")
    if a.tipo == "apresentar":
        feito = "fotos" if a.com_fotos else "card" if a.com_card else "status"
        return c.com(ultima_pergunta=None, ultima_acao=feito)
    if a.tipo == "apresentar_varios":
        # os cards que a busca mandou fecham com "se quiser as fotos de algum, me diz qual": a pergunta está no ar
        escolher = a.dados.get("falta_escolher") or a.dados.get("da_busca")
        return c.com(ultima_pergunta="qual_imovel" if escolher else None, ultima_acao="varios")
    if a.tipo == "template":
        return c.com(ultima_pergunta=PERGUNTA_DO_TEMPLATE.get(a.template or ""),
                     ultima_acao=FICA_COMO.get(a.template or "", a.template))
    if a.tipo == "perguntar_qual" and a.dados.get("confirmar"):      # "É este imóvel?" (portão de coerência)
        return c.com(ultima_pergunta="qual_imovel", ultima_acao="confirmar_imovel")
    return c.com(ultima_pergunta=PERGUNTA_DA_ACAO.get(a.tipo), ultima_acao=a.tipo)


def nao_entendi(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Não deu para entender: pergunta UMA vez. Se a resposta seguinte também não der, não repete
    "não entendi" (replay de 02/10: 18% dos turnos cairiam aqui): sobe ao Tel com a mensagem.
    Com pedido aberto (ela está perguntando filtro ou acabou de buscar) a frase "você procura um imóvel ou quer
    saber de algum imóvel nosso?" não existe (Tel, 06/10): ela retoma o pedido (estado/pedido.py)."""
    if ev.contexto.codigo and ev.contexto.origem in ("literal", "card"):
        # ele ESCREVEU o código de um imóvel: o que mais vier na mensagem não muda isso ("3078 ⏎ Smile parque de
        # flores" ouviu "não entendi" na rodada de 06/10 à noite, turno 13914). Código digitado apresenta, sempre;
        # com pergunta em volta, a ficha responde (rodada 9).
        return do_escrito(c, ev)
    if ev.condominio_codigos:
        # ele escreveu só o nome de um condomínio que tem oferta ("Smile parque das flores", 13916, rodada 5: o
        # modelo não soube a intenção e saiu "não entendi"): o nome É o pedido
        if len(ev.condominio_codigos) == 1:
            return apresentar(c, ev, ev.condominio_codigos[0], pediu(ev), False, origem="condominio")
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.condominio_codigos)
    retomada = pedido.retomar(c, ev)
    if retomada:
        return retomada
    if c.ultima_acao in ("esclarecer", "repetiu_pergunta", "retomar_pedido"):
        return escalar(c, ev, "não entendi duas vezes seguidas")
    return c, Acao("template", template="esclarecer")

"""A memória do pedido, com redundância (Pedro, 12/10/2026: "estou tendo problemas na memória de sessão da Nay,
precisa resolver com redundância").

O caso (turno 1885): "Boa noite Nay, pergunto se tem casa no Ponta Negra ou Tarumã? Se sim aceita parceria?". O
classificador leu certo (tipo casa, os dois bairros), mas a intenção era "parceria", e só o pedido de imóvel guardava
filtro. Três mensagens depois ela perguntou "Seu cliente procura casa ou apartamento?".

Duas camadas, e as duas só preenchem o que está VAZIO (o que ele disse no pedido continua mandando):

1. `ouvido`: o que o classificador leu numa mensagem que NÃO é pedido (parceria, recado, cumprimento, "não deu para
   saber") fica anotado na ficha na hora.
2. `ja_dito`: antes de fazer uma pergunta de filtro, as mensagens dele neste pedido são relidas, sem modelo. Se a
   resposta já está escrita ali, a pergunta não é feita. É a rede para quando a camada 1 não pegou (o modelo falhou,
   a mensagem passou pelo pré-roteador, a Nay velha ou o Tel é que estavam na conversa).
"""
from __future__ import annotations

import re
from datetime import datetime

from nay.classificador import frases
from nay.classificador.atalhos import AMBOS, TANTO_FAZ, TIPOS, _primeiro, mobilia_dita
from nay.classificador.schema import Classificacao
from nay.texto import normal
from nay.tipos import Conversa

# a mensagem que não é pedido, mas pode trazer o perfil junto
OUVE = ("parceria", "recado", "cortesia", "nao_da_para_saber")
QUARTOS = re.compile(r"\b([1-6]|um|dois|tres|quatro|cinco)\s*(quartos?|qts?|qtos?|dormitorios?|dorms?)\b")
NUMERO = {"um": 1, "dois": 2, "tres": 3, "quatro": 4, "cinco": 5}
# fala de UM imóvel ("essa casa tem piscina?", o card colado): não é o perfil do cliente
DE_UM_IMOVEL = re.compile(r"\b(ess[ea]|est[ea]|dess[ea]|dest[ea]|aquel[ea]|codigo|cod)\b")


def para_o_modelo(historico: tuple) -> list[dict]:
    """A conversa de hoje como o modelo a recebe: sem o instante (`quando`), que é só desta memória."""
    return [{k: v for k, v in m.items() if k != "quando"} for m in historico or ()]


# "tenho 3 clientes", "meus clientes", "são 3 famílias vindo": mais de um perfil no mesmo pedido
VARIOS = re.compile(r"\b(clientes|familias|casais|pessoas procurando)\b")


def fala_de_varios(texto: str) -> bool:
    return bool(VARIOS.search(normal(texto or "")))


def varios_clientes(ja_dito: dict, texto: str) -> bool:
    """Ele está atendendo MAIS DE UM cliente neste pedido (disse agora ou mais acima na conversa)."""
    return bool(ja_dito.get("varios")) or fala_de_varios(texto)


# a frase ACRESCENTA um perfil ao que já estava ("E por último apartamento", "apartamento também")
ACRESCENTA = re.compile(r"^(e|ou)\b|\b(por ultimo|tambem|alem d[aeo]s?|mais um\w*|o outro|a outra|o segundo|"
                        r"a segunda|o terceiro|a terceira)\b")
MORADIA = ("casa", "apartamento", "flat", "cobertura")


def _familia(t: str | None) -> str | None:
    return "casa" if t == "casa_condominio" else t


def acrescenta(texto: str) -> bool:
    return bool(ACRESCENTA.search(normal(texto or "")))


def tipos_ditos(texto: str) -> tuple[str, ...]:
    """Os tipos que a frase escreve, na ordem ("casa em condomínio" é casa)."""
    t = normal(texto or "")
    return tuple(dict.fromkeys(_familia(v) for p, v in TIPOS if re.search(p, t)))


def somar_perfis(antes: Conversa, depois: Conversa, texto: str = "") -> Conversa:
    """Pedido para vários clientes: o tipo SOMA ao de antes só quando a frase ACRESCENTA ("Casa" e, depois, "E por
    último apartamento de 3 quartos": servem os dois, e os quartos de um não estreitam a busca dos outros).

    Sem a palavra de acréscimo, o tipo e os quartos que ele disse são os da busca (Pedro, 13/10, turno 1934: "meus
    clientes procuram casa de 3 quartos" saiu como casa ou apartamento de qualquer tamanho, e foram apartamentos)."""
    a, d = antes.filtro_tipo, depois.filtro_tipo
    mud: dict = {}
    if acrescenta(texto) and a is not None and d not in (None, "tanto_faz") and _familia(a) != _familia(d):
        mud["filtro_tipo"] = "tanto_faz"
        if depois.filtro_quartos is not None:
            mud["filtro_quartos"] = None
    if depois.filtro_mobilia in (None, "tanto_faz"):
        mud["filtro_mobilia"] = "sem_preferencia"   # cada cliente tem a sua: a busca sai com os dois, sem perguntar
    return depois.com(**mud) if mud else depois


def tipo_da_frase(c: Conversa, texto: str) -> Conversa:
    """A parede: a frase escreve UM tipo de moradia, sem "tanto faz" nem acréscimo, e a ficha ficou em "casa ou
    apartamento". Vale o que ele escreveu: quem pede casa nunca recebe apartamento."""
    t = normal(texto or "")
    ditos = tipos_ditos(texto)
    if (c.filtro_tipo != "tanto_faz" or len(ditos) != 1 or ditos[0] not in MORADIA or acrescenta(texto)
            or DE_UM_IMOVEL.search(t) or TANTO_FAZ.search(t) or AMBOS.search(t) or len(t.split()) > 60):
        return c
    return c.com(filtro_tipo=ditos[0])


def perfil_inteiro(c: Conversa, cl: Classificacao | None, texto: str) -> bool:
    """A frase traz um perfil INTEIRO (tipo, valor e bairro) de tipo diferente do da ficha, e não é acréscimo: é
    outro pedido. A mobília, os quartos e os recusados do de antes não passam para este."""
    if cl is None or not (cl.tipo and cl.teto and cl.bairros) or acrescenta(texto) or c.filtro_tipo is None:
        return False
    return bool(tipos_ditos(texto)) and _familia(cl.tipo) != _familia(c.filtro_tipo)


def para_a_busca(ja_dito: dict, texto: str) -> tuple[bool, tuple[str, ...]]:
    """O que a busca precisa saber do pedido: são vários clientes? quais tipos ele pediu?"""
    return varios_clientes(ja_dito, texto), tuple(dict.fromkeys((*(ja_dito.get("tipos") or ()), *tipos_ditos(texto))))


def ouvido(cl: Classificacao | None, bairros: tuple[str, ...]) -> dict:
    """Camada 1: os filtros que o classificador leu nesta mensagem."""
    if cl is None:
        return {}
    return {"finalidade": cl.finalidade if cl.finalidade in ("locacao", "venda") else None, "tipo": cl.tipo,
            "regiao": tuple(bairros), "quartos": cl.quartos,
            "mobilia": cl.mobilia if cl.mobilia not in (None, "tanto_faz") else None}


def _do_pedido(historico: tuple, desde: datetime | None) -> list[str]:
    """As mensagens DELE neste pedido (depois de `desde`), da mais antiga para a mais nova."""
    textos = []
    for m in historico or ():
        quando = m.get("quando")
        if m.get("de") != "corretor" or not (m.get("texto") or "").strip():
            continue
        comparavel = desde is not None and quando is not None and (quando.tzinfo is None) == (desde.tzinfo is None)
        if comparavel and quando < desde:
            continue
        textos.append(m["texto"])
    return textos


def ja_dito(historico: tuple, desde: datetime | None = None) -> dict:
    """Camada 2: o que ele já escreveu neste pedido, lido sem modelo. A mais nova vale sobre a mais antiga."""
    d: dict = {}
    for texto in _do_pedido(historico, desde):
        t = normal(texto)
        if VARIOS.search(t):
            d["varios"] = True
        if DE_UM_IMOVEL.search(t) or len(t.split()) > 60:
            continue
        fin = frases.finalidade_dita(texto)
        if fin in ("locacao", "venda"):
            d["finalidade"] = fin
        tipo = _primeiro(TIPOS, t)
        if tipo:
            d["tipo"] = tipo
            d["tipos"] = tuple(dict.fromkeys((*d.get("tipos", ()), *tipos_ditos(texto))))
        m = QUARTOS.search(t)
        if m:
            d["quartos"] = NUMERO.get(m.group(1)) or int(m.group(1))
        mob = mobilia_dita(t)
        if mob:
            d["mobilia"] = mob
    return d


def da_frase(c: Conversa, texto: str, card_colado: bool = False) -> Conversa:
    """"Aluguel ou alugar é aluguel" (Pedro, 12/10): a finalidade que a frase DELE afirma fica na ficha quando ela
    está vazia, seja qual for o assunto da mensagem (parceria, pergunta sobre um imóvel, recado, recusa). O card
    colado não conta: quem diz a finalidade ali é o imóvel (filtros.do_imovel)."""
    if c.filtro_finalidade is not None or card_colado or not (texto or "").strip():
        return c
    fin = frases.finalidade_dita(texto)
    return c.com(filtro_finalidade=fin) if fin in ("locacao", "venda") else c


def completar(c: Conversa, d: dict) -> Conversa:
    """Só os filtros VAZIOS. Devolve a mesma conversa quando não há o que acrescentar."""
    if not d:
        return c
    mud: dict = {}
    if c.filtro_finalidade is None and d.get("finalidade"):
        mud["filtro_finalidade"] = d["finalidade"]
    if c.filtro_tipo is None and d.get("tipo"):
        mud["filtro_tipo"] = d["tipo"]
    if not c.filtro_regiao and not c.filtro_regiao_tanto_faz and d.get("regiao"):
        mud["filtro_regiao"] = tuple(d["regiao"])
    if c.filtro_quartos is None and d.get("quartos"):
        mud["filtro_quartos"] = int(d["quartos"])
    if c.filtro_mobilia is None and d.get("mobilia"):
        mud["filtro_mobilia"] = d["mobilia"]
    return c.com(**mud) if mud else c

"""A ficha de solicitação (setor estado): o pedido de imóvel do corretor, do primeiro filtro até a lista.

Saiu de maquina.py em 06/10 (uma situação = uma função, como estado/apresentar.py), com o que o Tel escreveu no
painel de treino: o pedido é como o filtro do site, com vários bairros e condomínios marcados. Tudo o que ele diz
fica anotado e SOMA ao que já estava; a busca roda com tudo de uma vez; e a ficha tem começo e fim:

  pedir_imovel        preenche a ficha com o que veio na mensagem e pergunta o que falta (uma pergunta por turno);
                      com "manda o que você tem", o que falta vira tanto faz e a lista sai agora (13872)
  ja_disse            "Deixei descrito": o pedido está na ficha; segue de onde parou (13850)
  tentar_outro        o "Sim" a "Quer tentar outro bairro ou outro valor?": pergunta qual (13816)
  retomar             não deu para entender, mas há pedido aberto: nunca "você procura imóvel ou quer saber de um?"
  despedida           "Qualquer coisa aciono vc. Obrigada": ela se despede e a pergunta em aberto cai (13844)
  anuncio             "posso anunciar?": pode, todos estão disponíveis para parceria (13876)
  interessado         "tenho um cliente interessado nesse": o card e a pergunta da visita (13913)
"""
from __future__ import annotations

from dataclasses import replace

from nay.classificador import frases
from nay.contexto.resolver_imovel import pediu_envio, so_uma_parte
from nay.estado import filtros, memoria
from nay.estado.acao import Acao, Evento
from nay.estado.apresentar import apresentar, apresentar_varios, origem_de
from nay.tipos import Conversa

FINALIDADE_TEXTO = {"locacao": "locação", "venda": "venda"}


def _ja_perguntou(c: Conversa, falta: str) -> bool:
    """A pergunta deste filtro já saiu neste pedido (a conversa está parada nela) e a resposta não o preencheu."""
    if c.estado != "FILTRO_" + falta.upper():
        return False
    # "tanto faz" à pergunta da mobília: a da preferência ainda não saiu
    return not (falta == "mobilia" and c.filtro_mobilia == "tanto_faz"
                and c.ultima_acao != "pergunta_mobilia_preferencia")


def perguntar_proximo_filtro(c: Conversa) -> tuple[Conversa, Acao]:
    falta = filtros.primeiro_vazio(c)
    while falta is not None and _ja_perguntou(c, falta):
        # A MESMA PERGUNTA NÃO SAI DUAS VEZES (Tel, 20/10, 559291792460: "Até que valor o seu cliente quer?" quatro
        # vezes, e a corretora tinha dito "aí tu vai dizer o valor"). Perguntou e a resposta não trouxe: o filtro
        # vira tanto faz e ela segue para o próximo, ou para a lista.
        c = filtros.sem_resposta(c, falta)
        falta = filtros.primeiro_vazio(c)
    if falta is None:
        return c.com(estado="BUSCA"), Acao("buscar")
    if falta == "mobilia" and c.filtro_mobilia == "tanto_faz":
        # "os dois / sem preferência" na mobília: são clientes diferentes, ela pergunta a preferência UMA vez
        return c.com(estado="FILTRO_MOBILIA"), Acao("perguntar_filtro", filtro="mobilia_preferencia")
    return c.com(estado="FILTRO_" + falta.upper()), Acao("perguntar_filtro", filtro=falta)


def pediu_fotos(ev: Evento) -> bool:
    return ev.pre == "fotos" or bool(ev.classificacao and ev.classificacao.pede_fotos and not so_uma_parte(ev.texto))


def pediu(ev: Evento) -> bool:
    """Pediu foto ou pediu para mandar: é o que leva as fotos junto do card (`_com_fotos`)."""
    return pediu_fotos(ev) or pediu_envio(ev.texto)


def _do_mesmo_pedido(c: Conversa, ev: Evento) -> Conversa:
    """A ficha em que a mensagem entra: a mesma com a finalidade corrigida ("é venda, não locação"), uma nova
    (outro pedido: os filtros de antes saem) ou a que já estava."""
    corrigida = frases.corrigiu_finalidade(ev.texto)
    if corrigida and c.filtro_finalidade in ("locacao", "venda") and corrigida != c.filtro_finalidade:
        return filtros.corrigir_finalidade(c, corrigida)
    cl = ev.classificacao
    if cl is not None and memoria.varios_clientes(ev.ja_dito, ev.texto):
        cl = cl.model_copy(update={"tipo": None})      # vários clientes: outro TIPO é mais um perfil, não outro pedido
    if filtros.pedido_novo(c, cl, ev.texto) or memoria.perfil_inteiro(c, ev.classificacao, ev.texto):
        # a finalidade que ESTA frase diz já entra no pedido novo ("Japiim venda")
        return memoria.da_frase(filtros.completar(filtros.zerar(c, ev.agora), ev.do_card), ev.texto)
    return c


def _quer_a_lista_agora(ev: Evento) -> bool:
    return bool(ev.classificacao and ev.classificacao.quer_resultado_ja) or frases.quer_resultado_ja(ev.texto)


def _lista_do_pedido_que_mudou(acao: Acao, trocou: bool) -> Acao:
    """O pedido MUDOU (bairro, valor, tipo): a resposta é a lista deste pedido, mesmo que saia igual à de antes
    (rodada 8, 13830: "Parque dez nesse valor de até 6 mil" ouviu "Qual deles eu te mando?")."""
    return replace(acao, dados={**acao.dados, "repete_lista": True}) if trocou and acao.tipo == "buscar" else acao


def pedir_imovel(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    # "Amiga é venda não locação" quando o pedido JÁ é de venda (13852, rodada da noite de 06/10: a busca dava a
    # mesma lista, a pergunta "qual deles?" já tinha saído e o turno subiu ao Tel). Ela confirma a finalidade e
    # repete o que tem para ela, ou a pergunta que falta. Nunca escala.
    corrigida = frases.corrigiu_finalidade(ev.texto)
    ja_era = FINALIDADE_TEXTO.get(corrigida or "") if corrigida == c.filtro_finalidade else None
    era_desde = c.pedido_desde
    c = _do_mesmo_pedido(c, ev)
    continua = c.pedido_desde == era_desde      # recomeçou agora: o que ele disse antes era de outro cliente
    c, ev = _recusados_pelo_nome(c, ev)
    c = _tambem_recusou(c, ev)      # o que ele recusou vale mesmo quando a intenção é pedir outro (22/10)
    # o condomínio que ele pediu e não tem oferta empresta o bairro: a busca segue nas proximidades
    sem_oferta = ev.condominio_sem_oferta and not ev.condominio_ja_visto
    bairros = tuple(dict.fromkeys((*ev.bairros, *(ev.condominio_bairros if sem_oferta else ()))))
    nova = filtros.aplicar(c, ev.classificacao, bairros, ev.filtro_direto, ev.texto,
                           soma=not ev.dados_pre.get("recomeca"))
    if memoria.varios_clientes(ev.ja_dito if continua else {}, ev.texto):
        nova = memoria.somar_perfis(c, nova, ev.texto)
    nova = memoria.tipo_da_frase(nova, ev.texto)       # ele escreveu "casa": a busca é de casa (13/10, 1934)
    nova = _com_o_condominio(nova, ev)
    if filtros.mudou(c, nova):
        # pedido com filtro novo: o imóvel de antes não é mais o assunto (o foco velho respondia "manda aí")
        nova = nova.com(foco_codigo=None, foco_origem=None)
    if ev.bairro_ambiguo:
        return nova.com(estado="FILTRO_REGIAO"), Acao("template", template="bairro_ambiguo",
                                                      dados={"candidatos": list(ev.bairro_ambiguo)})
    if ev.bairro_desconhecido and not nova.filtro_regiao:
        return nova.com(estado="FILTRO_REGIAO"), Acao("template", template="bairro_desconhecido",
                                                      dados={"bairro": ev.bairro_desconhecido})
    if ev.condominio_ja_visto:
        return nova.com(estado="IDENTIFICANDO"), Acao("template", template="condominio_sem_oferta",
                                                      dados={"condominio": ev.condominio_sem_oferta})
    if ev.condominio_codigos:
        return _do_condominio(nova, ev)
    if _quer_a_lista_agora(ev) and filtros.algum(nova):
        # "você pode mandar o que você tem de piscina que eu envio pra eles?" no meio das perguntas: ele fechou a
        # ficha. As perguntas param e a busca sai com o que já se sabe.
        nova = filtros.fechar(nova)
    nova = memoria.completar(nova, ev.ja_dito if continua else {})     # já está escrito mais acima: não pergunta
    trocou = filtros.mudou(c, nova)
    nova, acao = perguntar_proximo_filtro(nova)
    acao = _lista_do_pedido_que_mudou(acao, trocou)
    if ja_era:
        acao = replace(acao, dados={**acao.dados, "finalidade_certa": {"para": ja_era}, "repete_lista": True})
    if sem_oferta:
        # "No Life Parque Dez não tenho para venda no momento." e o pedido segue: a pergunta que falta ou a lista
        # do que há por perto, em vez de "aceita outro condomínio?" (13846, 13918)
        aviso = {"condominios": ev.condominio_sem_oferta, "para": ev.condominio_sem_finalidade,
                 "geral": not ev.condominio_sem_finalidade}
        acao = replace(acao, dados={**acao.dados, "sem_oferta": aviso})
    return nova, acao


def _com_o_condominio(nova: Conversa, ev: Evento) -> Conversa:
    """20/10: o condomínio que ele citou vira a referência; os próximos dele vêm primeiro (cerebro/proximos.py)."""
    return nova.com(filtro_condominio=ev.condominio_ref) if ev.condominio_ref else nova


def _do_condominio(nova: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """O condomínio que ele citou tem oferta. Um imóvel só: apresenta. Dois ou mais condomínios com UM imóvel em
    oferta em cada ("me manda o Jardim das Cerejeiras e o Ariranhas", instrução do Tel de 01/10): vão todos, pela
    regra dos vários (até 2 com fotos, mais que isso só os cards). Senão, "qual deles?"."""
    codigos = ev.condominio_codigos
    if len(codigos) == 1:
        return apresentar(nova, ev, codigos[0], pediu(ev), False, origem="condominio")
    um_de_cada = tuple(dict.fromkeys(g[0] for g in ev.condominio_grupos if len(g) == 1))
    if len(um_de_cada) > 1 and len(um_de_cada) == len(ev.condominio_grupos):
        return apresentar_varios(nova, ev, um_de_cada)
    # quem tira da pergunta o que não cabe no valor dele é a ação, que tem o catálogo (acoes/preparo.py)
    return nova.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=codigos,
                                                  dados={"do_condominio": True, "pediu": pediu(ev)})


def ja_disse(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Deixei descrito": está tudo na mensagem de antes, que já foi para a ficha. Segue de onde parou."""
    return perguntar_proximo_filtro(c)


def tentar_outro(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela perguntou "Quer tentar outro bairro ou outro valor?" e ele respondeu só "Sim"."""
    return c.com(estado="FILTRO_REGIAO"), Acao("template", template="qual_bairro_ou_valor")


def abaixo_da_faixa(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela disse "Nessa faixa de valor eu não tenho agora. Tenho opções a partir de R$ X. Quer que eu te mande?" e
    ele respondeu que sim: aí, e só aí, sai a lista do que é mais barato (os outros filtros e o limite de cima
    continuam valendo)."""
    return c.com(estado="BUSCA"), Acao("buscar", dados={"sem_piso": True})


def outro_cliente(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela perguntou "Está perguntando para outro cliente, certo?" e ele disse que sim (Pedro, 10/10): o pedido é
    outro. Os filtros que ele acabou de dizer ficam; o que foi enviado ou recusado para o cliente de antes deixa
    de contar, e a lista sai de novo, agora com tudo o que cabe."""
    return (c.com(estado="BUSCA", rejeitados=(), ultima_lista=(), pedido_desde=ev.agora),
            Acao("buscar", dados={"repete_lista": True, "outro_cliente": True}))


def mesmo_cliente(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """...e ele disse que não: é o mesmo cliente. O que ele já recebeu hoje continua fora da lista."""
    return c, Acao("template", template="mesmo_cliente")


def retomar(c: Conversa, ev: Evento) -> tuple[Conversa, Acao] | None:
    """Não deu para entender a mensagem e há um pedido aberto: ela repete a pergunta que estava fazendo (ou diz o
    que dá para ajustar na busca), UMA vez. None = não há pedido aberto, ou ela já repetiu (aí sobe ao Tel)."""
    if c.estado.startswith("FILTRO_") and c.ultima_acao != "repetiu_pergunta":
        nova, acao = perguntar_proximo_filtro(c)
        return nova, replace(acao, motivo="de_novo") if acao.tipo == "perguntar_filtro" else acao
    if c.estado == "BUSCA" and c.ultima_acao != "retomar_pedido":
        return c, Acao("template", template="retomar_pedido")
    return None


def despedida(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele encerrou: ela se despede e fica à disposição. A pergunta de filtro que estava em aberto cai (o que
    ele já disse continua na ficha, para o caso de ele voltar ao mesmo pedido)."""
    return (c.com(estado="APRESENTADO" if c.foco_codigo else "IDENTIFICANDO"),
            Acao("template", template="despedida"))


def anuncio(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Se tiver para anúncio me manda aqui", "posso anunciar?": ela autoriza, sem começar os filtros."""
    return c, Acao("template", template="pode_anunciar")


def interessado(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """O cliente dele tem interesse NESTE imóvel: as informações (se ele ainda não as tem de nós) e a pergunta da
    visita. Quem tira o card repetido é acoes/executar.py."""
    codigo = ev.contexto.codigo
    origem = origem_de(c, ev, codigo)
    nova = c.com(estado="APRESENTADO", foco_codigo=codigo, foco_origem=origem,
                 mostrados=tuple(dict.fromkeys((*c.mostrados, codigo))), visita_sugerida_em=ev.agora)
    return nova, Acao("apresentar", codigo=codigo, com_card=True, com_fotos=False,
                      dados={"origem": origem, "oferece_visita": True})


def tem_as_fotos(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Tenho 11 fotos no tirei no grupo, se tiver mais" (13567, rodada 9): ele já tem as fotos. Ela não manda de
    novo: diz que as do grupo são todas as que tem."""
    return (c.com(foco_codigo=ev.contexto.codigo, foco_origem=origem_de(c, ev, ev.contexto.codigo)),
            Acao("template", template="fotos_sao_essas", codigo=ev.contexto.codigo))


def dispensou(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela ofereceu as informações e as fotos e ele disse que não precisa ou que já tem ("não tenho, pra eu
    atualizar os anúncios disponíveis", 13778): "Combinado!", e nada é enviado. Nunca "não entendi"."""
    return c, Acao("template", template="combinado_se_precisar")


def _tambem_recusou(c: Conversa, ev: Evento) -> Conversa:
    """`codigo_rejeitado` vale mesmo fora de rejeitar_imovel (test_recusa_fora_do_rejeitar.py)."""
    cod = ev.classificacao.codigo_rejeitado if ev.classificacao else None
    if not cod or cod in c.rejeitados:
        return c
    return c.com(rejeitados=(*c.rejeitados, cod), foco_codigo=None if c.foco_codigo == cod else c.foco_codigo)


def _recusados_pelo_nome(c: Conversa, ev: Evento) -> tuple[Conversa, Evento]:
    """"Esse Parque Golf fica distante pra ela, tem que ser Parque Dez" (13582, rodada 9): o imóvel que ele recusou
    DIZENDO o nome entra nos rejeitados, não é apresentado e não empresta o bairro; o resto da frase (bairro,
    tipo) segue no pedido."""
    ditos = _recusados(ev)
    if not ditos:
        return c, ev
    return (c.com(rejeitados=tuple(dict.fromkeys((*c.rejeitados, *ditos))),
                  foco_codigo=None if c.foco_codigo in ditos else c.foco_codigo),
            replace(ev, condominio_codigos=(), condominio_bairros=(), condominio_sem_oferta=None))


def _recusados(ev: Evento) -> tuple[int, ...]:
    """Os imóveis dos condomínios que a frase recusa pelo nome (todos os nomes citados têm de ser recusa)."""
    nomes = list(ev.classificacao.condominios) if ev.classificacao else []
    if not nomes or not ev.condominio_codigos or not all(frases.rejeitou_o(ev.texto, n) for n in nomes):
        return ()
    return ev.condominio_codigos


def _disse_filtro(cl) -> bool:
    """A mensagem trouxe filtro novo além do bairro? (`filtros.aplicar` só usa o que não é vazio.)"""
    return any((cl.finalidade, cl.tipo, cl.teto, cl.quartos, cl.mobilia, cl.tanto_faz))


def rejeitar(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    cl = ev.classificacao
    recusados = _recusados(ev)
    cod = (cl.codigo_rejeitado if cl else None) or (recusados[0] if recusados else None) \
        or ev.contexto.codigo or c.foco_codigo or next(iter(c.mostrados[-1:]), None)
    nova = c.com(foco_codigo=None,
                 rejeitados=tuple(dict.fromkeys((*c.rejeitados, cod, *recusados))) if cod else c.rejeitados)
    if (ev.dados_pre or {}).get("mobilia"):
        # "N serve totalmente mobiliado, só quer modulados e climatização" (Júlio, 19/10): a mobília da recusa vale
        nova = nova.com(filtro_mobilia=ev.dados_pre["mobilia"])
    if cl and (ev.bairros or _disse_filtro(cl)):
        # a recusa que já diz o que serve ("fica longe, tem que ser Parque Dez"; "é locação, 2 quartos, até
        # 3.800") segue no pedido. Até 20/10/2026 só o BAIRRO entrava, e o bairro que o cadastro não conhece
        # levava o resto embora: no turno 2921 (...5516, 09h15) a corretora disse "essa locação tá? É locação...
        # ela quer apartamento... o valor dela é até uns 3.800... Dois quartos serve", o classificador leu tudo
        # certo (locacao, apartamento, teto 3800, 2 quartos), "Flex Park 10" não é bairro do cadastro, e a busca
        # rodou com o perfil velho (casa, ambos, R$ 900 mil): saíram dois cards de VENDA, de R$ 780 mil e R$ 900
        # mil. Nove minutos depois ela respondeu "Amiga é locação, não é venda!".
        nova = filtros.aplicar(nova, cl, ev.bairros, None, ev.texto)
    return perguntar_proximo_filtro(nova)     # filtros completos: busca de novo, sem o rejeitado


def rejeitar_com_teto(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Ha mas essa é 9 mil, quero de 7" em cima do card (turno 944): recusa ESTE imóvel, grava o valor que ele
    disse e a busca segue. Antes, "quero" contava como "manda" e o card saía pela quarta vez."""
    cod = ev.contexto.codigo
    nova = c.com(foco_codigo=None, foco_origem=None, filtro_teto=float(ev.filtro_direto["teto"]),
                 filtro_teto_tanto_faz=False, rejeitados=tuple(dict.fromkeys((*c.rejeitados, cod))))
    return perguntar_proximo_filtro(nova)

"""A pergunta sobre um imóvel (setor estado): de qual ele fala e o que responder.

Saiu de maquina.py em 07/10 (uma situação = uma função), com o que o Tel marcou na rodada 9 do treino:

  pergunta_sobre_imovel   o imóvel resolvido: fotos, "tá valendo?", "ainda está disponível?" ou a ficha
  sem_dizer_qual          nada resolvido: o condomínio sem oferta, o "qual deles?" da lista que está na frente dele,
                          e só no fim "De qual imóvel você fala?" (13715: "Mobiliado ?" logo depois de ela dizer que
                          no condomínio não tem nada; 13768: a pergunta sobre os dois que ela acabou de mandar)
  do_escrito              ele escreveu o código de um imóvel NOSSO, ou colou o nosso card: nunca é oferta de imóvel
                          dele e nunca sobe ao Tel (13764, 13776). Com pergunta, a ficha responde; sem, é pedido
  dos_varios              a mesma pergunta para os imóveis que estão na frente ("os dois são mobiliados né")
"""
from __future__ import annotations

import re
from dataclasses import replace

from nay.classificador import frases
from nay.contexto.resolver_imovel import pediu_fotos as texto_pede_fotos
from nay.contexto.resolver_imovel import sem_card
from nay.estado import prazos
from nay.estado.acao import Acao, Evento
from nay.estado.apresentar import (
    apresentar,
    do_card_colado,
    esta_valendo,
    so_fotos,
    so_perguntou_se_esta_disponivel,
)
from nay.estado.escalada import escalar
from nay.estado.pedido import pediu, pediu_fotos
from nay.texto import normal
from nay.tipos import Conversa

LISTA_CURTA = 5
VALOR_SEM_INTERROGACAO = re.compile(r"\b(qual|quais|quanto|valor|preco)\b")


def sem_dizer_qual(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """A pergunta não diz de qual imóvel é."""
    if ev.condominio_sem_oferta:
        return c.com(estado="IDENTIFICANDO"), Acao("template", template="condominio_sem_oferta",
                                                   dados={"condominio": ev.condominio_sem_oferta,
                                                          "para": ev.condominio_sem_finalidade})
    if ev.condominio_codigos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.condominio_codigos)
    if c.ultima_acao == "condominio_sem_oferta" and prazos.gatilho_vale(c, ev.agora):
        # ela acabou de dizer que no condomínio não tem nada e ele pergunta "Mobiliado ?": é do mesmo condomínio
        return c, Acao("template", template="condominio_sem_oferta_ainda")
    if 2 <= len(ev.lista_na_frente) <= LISTA_CURTA:
        # a pergunta é sobre um dos que ela acabou de mostrar: qual deles? (nunca "De qual imóvel você fala?")
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.lista_na_frente)
    if c.ultima_acao == "pergunta_qual_imovel":    # perguntou e ele de novo não disse qual: sobe ao Tel
        return escalar(c, ev, "perguntou de imóvel sem dizer qual, duas vezes")
    return c.com(estado="IDENTIFICANDO"), Acao("template", template="pergunta_qual_imovel")


def pergunta_sobre_imovel(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    ctx = ev.contexto
    if ctx.candidatos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ctx.candidatos)
    codigo = ctx.codigo or (ev.condominio_codigos[0] if len(ev.condominio_codigos) == 1 else None)
    if ctx.origem == "foco" and (ev.condominio_codigos or ev.condominio_sem_oferta):
        # ele escreveu o nome de um condomínio AGORA: é dele que fala, não do imóvel de antes
        nomeados = ev.condominio_codigos
        codigo = ctx.codigo if ctx.codigo in nomeados else nomeados[0] if len(nomeados) == 1 else None
    if codigo is None:
        return sem_dizer_qual(c, ev)
    if pediu_fotos(ev) and not ev.classificacao.pede_lista_de_valores:
        if ctx.origem == "foco" and codigo == ctx.codigo and not prazos.gatilho_vale(c, ev.agora):
            # o foco vale 24 h para pergunta e visita; o ENVIO pelo imóvel de antes continua valendo só 2 h
            return sem_dizer_qual(c, ev)
        c, a = so_fotos(c, ev, codigo)
        # "Qual andar? / Manda as fotos por favor" numa rajada só (Adriana, 12/10): as fotos iam e a pergunta era
        # jogada fora. A pergunta que sobra fora do pedido de fotos vai junto, respondida pela ficha.
        resto = pergunta_alem_das_fotos(ev.texto)
        return c, (replace(a, pergunta=resto) if resto else a)
    if frases.pergunta_se_vale(ev.texto):           # "tá valendo?": sim, por quanto, e o card (13653)
        return esta_valendo(c, ev, codigo)
    if so_perguntou_se_esta_disponivel(ev.texto):      # responde e oferece as informações e as fotos
        return apresentar(c, ev, codigo, False, True, so_status=True)
    return (c.com(estado="APRESENTADO", foco_codigo=codigo, foco_origem=ctx.origem or c.foco_origem),
            Acao("responder_ficha", codigo=codigo, pergunta=ev.texto))


def pergunta_alem_das_fotos(texto: str) -> str | None:
    """O que a mensagem pergunta além de pedir as fotos: as frases com "?" que não são o pedido das fotos."""
    pedacos = [p.strip() for p in re.split(r"(?<=\?)|\n", texto or "") if p.strip()]
    perguntas = [p for p in pedacos if "?" in p and not texto_pede_fotos(p)]
    if not perguntas and VALOR_SEM_INTERROGACAO.search(normal(texto or "")):
        return (texto or "").strip()                # "Qual valor e fotos" (Estefânia, 23/10): o valor sem o "?"
    return " ".join(perguntas) or None


def do_escrito(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele escreveu o código de um imóvel nosso ou colou o nosso card, e o modelo leu oferta de imóvel, assunto
    geral ou nada. Com pergunta em volta ("...Código: 9001 ⏎ Mobiliado?"), a ficha responde; o card colado sozinho
    recebe as fotos; o código digitado é o pedido do imóvel."""
    ctx = ev.contexto
    resto = sem_card(ev.texto).strip() if ctx.card_colado else ev.texto
    if "?" in resto:
        if frases.pergunta_se_vale(resto):
            return esta_valendo(c, ev, ctx.codigo)
        if so_perguntou_se_esta_disponivel(resto):
            return apresentar(c, ev, ctx.codigo, False, True, so_status=True)
        return (c.com(estado="APRESENTADO", foco_codigo=ctx.codigo, foco_origem=ctx.origem),
                Acao("responder_ficha", codigo=ctx.codigo, pergunta=resto))
    if ctx.card_colado:
        return do_card_colado(c, ev, ctx.codigo)
    return apresentar(c, ev, ctx.codigo, pediu(ev), False)


def dos_varios(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Pela descrição os dois são mobiliados né" depois de ela mandar dois (13768): a ficha de cada um responde
    (acoes/varios.py). O foco continua vazio: ele fala de todos."""
    return c, Acao("responder_varios", candidatos=tuple(ev.dados_pre.get("codigos") or ()), pergunta=ev.texto)

"""Os prazos da conversa (setor estado): o foco e os gatilhos têm validade.

Levantamento de 05/10: o imóvel em foco não vencia nunca. Uma corretora escreveu "Envia amiga" no dia seguinte
ao card e recebeu de novo as fotos do imóvel que tinha recusado pelo preço (turno 941); outro pediu fotos "de
um apartamento no Mosaico" e recebeu as do imóvel que estava em foco desde a véspera (934).

- O FOCO vale `foco_vale_h` (config/limites.yaml: eram 2 h, são 24 h desde 07/10) desde a última vez que a
  conversa tocou nele: card, fotos, resposta sobre ele. Vencido, sai antes de o turno resolver de qual imóvel se
  fala. As 24 h servem à pergunta e à visita; o ENVIO pelo imóvel de antes segue o prazo do gatilho.
- O GATILHO ("manda aí" depois do card, o "sim" depois de uma pergunta dela) só vale se o que ela fez por
  último foi há menos de `gatilho_vale_h`.
- Os FILTROS valem `filtros_valem_dias` (3) desde a última vez que ela falou: depois disso o pedido é outro
  (Alteração 2, D: o 939 herdou a busca de três dias antes).

Conversa gravada antes de 05/10 não tem os carimbos; a migração 015 preenche com a última atualização. Carimbo
vazio conta como dentro do prazo: é o caso dos testes e nunca o de uma conversa real depois da migração.
"""
from __future__ import annotations

from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

from nay.config import cfg
from nay.estado import filtros
from nay.estado.acao import Acao
from nay.nos import no
from nay.tipos import Conversa

CALADAS = ("silencio", "fora_do_escopo", "fora_da_lista")
MANAUS = ZoneInfo("America/Manaus")


def inicio_do_dia(agora: datetime) -> datetime:
    """A meia-noite de Manaus do dia de `agora` (relógio sem fuso, como o dos testes antigos, fica como está)."""
    if agora.tzinfo is None:
        return agora.replace(hour=0, minute=0, second=0, microsecond=0)
    return agora.astimezone(MANAUS).replace(hour=0, minute=0, second=0, microsecond=0)


def conta_desde(c: Conversa, agora: datetime | None) -> datetime | None:
    """Desde quando o "já te enviei" vale. Pedro, 10/10/2026: "esse filtro de imóveis já enviado é imóveis
    enviados por solicitação ... põe um filtro de não enviar o mesmo no dia a não ser que ele cite que é para
    outro cliente e mude a solicitação". O envio só conta se foi HOJE e DENTRO DO PEDIDO ATUAL: o que saiu em
    outro dia, ou para outro cliente, pode ser oferecido e enviado de novo."""
    if agora is None:
        return c.pedido_desde
    dia = inicio_do_dia(agora)
    if c.pedido_desde is None or (c.pedido_desde.tzinfo is None) != (dia.tzinfo is None):
        return dia
    return max(dia, c.pedido_desde)


def recente(quando: datetime | None, agora: datetime | None, horas: float) -> bool:
    if quando is None or agora is None:
        return True
    return agora - quando <= timedelta(hours=horas)


def foco_vale(c: Conversa, agora: datetime | None) -> bool:
    return recente(c.foco_desde, agora, float(cfg("limites").get("foco_vale_h", 24)))


def gatilho_vale(c: Conversa, agora: datetime | None) -> bool:
    """O que ela fez por último (card, fotos, pergunta) ainda está valendo para um "manda aí" ou um "sim"?"""
    return recente(c.ultima_acao_em, agora, float(cfg("limites").get("gatilho_vale_h", 2)))


def _pedido_do_dia(c: Conversa, agora: datetime) -> Conversa:
    """O que ele recusou ONTEM não esconde imóvel HOJE (10/10: o corretor recusou o Maison Rochelle na quarta,
    para um cliente de compra, e na quinta ela não o ofereceu a um cliente de locação). Na primeira mensagem de
    um dia novo os recusados saem; os filtros continuam, com o prazo deles. Conversa sem o carimbo (a primeira
    mensagem de quem nunca falou, e os testes) só ganha o carimbo do dia."""
    dia = inicio_do_dia(agora)
    if c.pedido_desde is None:
        return c.com(pedido_desde=dia)
    if (c.pedido_desde.tzinfo is None) == (dia.tzinfo is None) and c.pedido_desde < dia:
        return c.com(rejeitados=(), pedido_desde=dia)
    return c


@no("estado.prazos_de_entrada")
def entrada(c: Conversa, agora: datetime) -> Conversa:
    """Antes do turno: o foco vencido sai; a conversa parada há dias recomeça os filtros; e o pedido é do dia."""
    if not recente(c.ultima_acao_em, agora, 24 * float(cfg("limites").get("filtros_valem_dias", 3))):
        c = filtros.zerar(c, agora)
    c = _pedido_do_dia(c, agora)
    if c.foco_codigo and not foco_vale(c, agora):
        return c.com(foco_codigo=None, foco_origem=None, foco_desde=None)
    return c


@no("estado.prazos_de_saida")
def saida(antes: Conversa, nova: Conversa, a: Acao, agora: datetime) -> Conversa:
    """Depois do turno: carimba o foco (quando mudou ou a ação falou dele) e a hora do que ela fez."""
    if nova.foco_codigo is None:
        foco_desde = None
    elif nova.foco_codigo != antes.foco_codigo or (a.tipo not in CALADAS and a.codigo == nova.foco_codigo):
        foco_desde = agora
    else:
        foco_desde = nova.foco_desde
    falou = a.tipo not in CALADAS
    return nova.com(foco_desde=foco_desde, ultima_acao_em=agora if falou else nova.ultima_acao_em)

"""SQL do setor estado: core_conversa, com trava otimista (coluna versao).
Duas rajadas da mesma pessoa não se sobrescrevem: a segunda a gravar com a
versão velha perde e o turno dela é refeito pelo worker."""
from __future__ import annotations

from dataclasses import fields
from typing import Any

from psycopg.types.json import Jsonb

from nay.tipos import Conversa

COLUNAS = [f.name for f in fields(Conversa) if f.name not in ("chave", "versao")]
LISTAS = ("filtro_regiao", "filtro_extras", "mostrados", "rejeitados", "ultima_lista")


def ler(conn, chave: str) -> Conversa:
    r = conn.execute("SELECT * FROM core_conversa WHERE chave = %s", (chave,)).fetchone()
    if not r:
        return Conversa(chave=chave)
    dados: dict[str, Any] = {k: r[k] for k in ("chave", "versao", *COLUNAS)}
    for k in LISTAS:
        dados[k] = tuple(dados[k]) if dados[k] is not None else (None if k == "filtro_regiao" else ())
    for k in ("filtro_teto", "filtro_piso"):
        dados[k] = float(dados[k]) if dados[k] is not None else None
    return Conversa(**dados)


def _valor(c: Conversa, k: str) -> Any:
    v = getattr(c, k)
    if k == "visita_pedida" and v is not None:
        return Jsonb(v)
    if k in LISTAS and v is not None:
        return list(v)
    return v


class ConflitoDeVersao(Exception):
    pass


def gravar(conn, antes: Conversa, depois: Conversa) -> None:
    cols = ", ".join(COLUNAS)
    ph = ", ".join(["%s"] * len(COLUNAS))
    sets = ", ".join(f"{c} = EXCLUDED.{c}" for c in COLUNAS)
    cur = conn.execute(
        f"""INSERT INTO core_conversa (chave, {cols}, versao, estado_desde, atualizado_em)
            VALUES (%s, {ph}, 1, now(), now())
            ON CONFLICT (chave) DO UPDATE SET {sets}, versao = core_conversa.versao + 1, atualizado_em = now(),
              estado_desde = CASE WHEN core_conversa.estado = EXCLUDED.estado THEN core_conversa.estado_desde
                                  ELSE now() END
            WHERE core_conversa.versao = %s""",
        (depois.chave, *[_valor(depois, k) for k in COLUNAS], antes.versao))
    if cur.rowcount != 1:
        raise ConflitoDeVersao(depois.chave)

"""O pedido de visita do corretor (setor estado).

Até 06/10 a visita com dia e horário subia ao Tel e a conversa parava 24 h ("Já te respondo por aqui"). O painel de
treino mostrou que a Nay velha fazia certo (13806, 13830, 13882) e o Tel pediu o mesmo aqui:

  falta o dia ou a hora   -> pergunta ("Qual horário do começo da noite fica bom para o seu cliente hoje?")
  imóvel, dia e hora      -> a mensagem padrão de confirmação (templates/visita_confirmar.md)
  ele confirma ("Sim")    -> "Certo! Anotei a sua visita..." e o aviso ao Tel com os dados; a conversa NÃO para

O pedido fica em `core_conversa.visita_pedida` (codigo, dia, hora, parte, etapa: falta | confirmar | anotada) e
vale 24 h. O dia e a hora são lidos do texto DELE por regex; o modelo só diz que é visita.

Falar com o proprietário, chamar o motoboy e pôr a visita na aba do CRM continuam no sistema velho (fase 4).
"""
from __future__ import annotations

import re
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

from nay.estado.acao import Acao, Evento
from nay.texto import sem_acento
from nay.tipos import Conversa

MANAUS = ZoneInfo("America/Manaus")
VALE_H = 24
DIAS = ("segunda", "terca", "quarta", "quinta", "sexta", "sabado", "domingo")
NOME_DO_DIA = ("segunda", "terça", "quarta", "quinta", "sexta", "sábado", "domingo")
HORA_E_MINUTO = re.compile(r"\b([01]?\d|2[0-3])\s*(?::|h|hs|hrs|horas?)\s*([0-5]\d)\b")
HORA_CHEIA = re.compile(r"\b([01]?\d|2[0-3])\s*(?:h|hs|hrs|horas?)\b")
AS_TANTAS = re.compile(r"\b(?:as|pelas|umas|por volta das?|a partir das?)\s+([01]?\d|2[0-3])(\s+e\s+meia)?\b"
                       r"(?!\s*(?:mil|k\b|reais|quartos?|/|\.\d|,\d))")
DATA = re.compile(r"\b([0-3]?\d)/([01]?\d)\b")
DIA_DO_MES = re.compile(r"\bdia\s+([0-3]?\d)\b")
# "boa tarde" e "mais tarde" não dizem a parte do dia
PARTE = re.compile(r"\b(?:(comeco|inicio|final|fim|meio)\s+d[ae]\s+)?(?:(?:de|da|pela|a|na)\s+)?"
                   r"(?<!boa )(?<!mais )(manha|tarde|noite)\b")
MOMENTO = {"comeco": "começo", "inicio": "início", "final": "final", "fim": "fim", "meio": "meio"}
PERIODO = {"manha": "manhã", "tarde": "tarde", "noite": "noite"}
# pedir a visita com data ou hora: sai sem modelo. Contar como foi a visita ("visitamos ontem, ele gostou") não é.
PEDE = re.compile(r"\b(visita|visitar|agendar|agendamento|agenda|marcar)\b")
JA_FOI = re.compile(r"\b(visitou|visitamos|visitaram|ontem|gostou|gostaram|achou|acharam|foi (boa|otima|ruim))\b")
# "só estou aguardando a confirmação do horário" (13867): ele ainda não tem a hora; perguntar de novo não ajuda
AGUARDA_A_HORA = re.compile(r"\b(aguard\w+|esperando|vou (ver|confirmar|checar)|te (confirmo|aviso|falo|passo)|"
                            r"depois (te )?(confirmo|aviso|falo|passo))\b.{0,40}\b(horario|hora)\b"
                            r"|\b(horario|hora)\b.{0,30}\b(a confirmar|depois|ainda nao sei)\b")


def _plano(texto: str) -> str:
    return sem_acento(texto or "").lower()


def hora_dita(texto: str) -> str | None:
    """"19:00", "19h", "19h30", "10 horas", "às 14", "meio dia" -> "HH:MM"."""
    t = _plano(texto)
    m = HORA_E_MINUTO.search(t)
    if m:
        return f"{int(m.group(1)):02d}:{m.group(2)}"
    m = HORA_CHEIA.search(t)
    if m:
        return f"{int(m.group(1)):02d}:00"
    m = AS_TANTAS.search(t)
    if m:
        return f"{int(m.group(1)):02d}:{'30' if m.group(2) else '00'}"
    return "12:00" if re.search(r"\bmeio[- ]dia\b", t) else None


def _do_calendario(dia: int, mes: int | None, hoje: date) -> date | None:
    """"08/10" ou "dia 8": a próxima data com esse dia (este mês, ou o seguinte se já passou). Data que não
    existe ("31/02", "dia 40") não é data."""
    try:
        if mes:
            d = date(hoje.year, mes, dia)
            return d if d >= hoje else d.replace(year=hoje.year + 1)
        d = hoje.replace(day=dia)
        return d if d >= hoje else (d.replace(day=1) + timedelta(days=32)).replace(day=dia)
    except ValueError:
        return None


def dia_dito(texto: str, hoje: date) -> date | None:
    """"hoje", "amanhã", "sábado", "08/10", "dia 8" -> a data. O dia da semana é o próximo (hoje conta)."""
    t = _plano(texto)
    if "depois de amanha" in t:
        return hoje + timedelta(days=2)
    if re.search(r"\bamanha\b", t):
        return hoje + timedelta(days=1)
    if re.search(r"\b(hoje|hj|agora)\b", t):
        return hoje
    m = DATA.search(t) or DIA_DO_MES.search(t)
    if m:
        do_mes = _do_calendario(int(m.group(1)), int(m.group(2)) if m.re is DATA else None, hoje)
        if do_mes:
            return do_mes
    for n, nome in enumerate(DIAS):
        if re.search(rf"\b{nome}(?:[- ]feira)?\b", t):
            # "no outro sábado", "sábado da semana que vem" (...0305, 23/10): não é o sábado mais próximo
            outro = rf"\boutr[oa]\s+{nome}\b|\b{nome}(?:[- ]feira)?\s+(?:da\s+)?(?:semana\s+que\s+vem|outra\s+semana)"
            return hoje + timedelta(days=(n - hoje.weekday()) % 7 + (7 if re.search(outro, t) else 0))
    return None


def parte_dita(texto: str) -> str | None:
    """"no começo da noite" -> "do começo da noite"; "de manhã" -> "da manhã"."""
    m = PARTE.search(_plano(texto))
    if not m:
        return None
    periodo = PERIODO[m.group(2)]
    artigo = "da"
    return f"do {MOMENTO[m.group(1)]} {artigo} {periodo}" if m.group(1) else f"{artigo} {periodo}"


def disse_quando(texto: str) -> bool:
    return bool(hora_dita(texto) or dia_dito(texto, date(2026, 1, 1)) or parte_dita(texto))


def pediu(texto: str) -> bool:
    """Pediu a visita dizendo quando ("vou agendar a visita para amanhã", "quer visitar esse no começo da noite")."""
    t = _plano(texto)
    return bool(PEDE.search(t)) and not JA_FOI.search(t) and disse_quando(texto)


def aberto(c: Conversa, agora: datetime | None) -> dict | None:
    """O pedido de visita que ainda está em andamento (falta dado ou falta confirmar), se houver."""
    p = c.visita_pedida or {}
    if p.get("etapa") not in ("falta", "confirmar"):
        return None
    try:
        feito = datetime.fromisoformat(p.get("quando") or "")
    except ValueError:
        return None
    return p if agora is None or agora - feito <= timedelta(hours=VALE_H) else None


def data_texto(d: date) -> str:
    """06/10 (terça)."""
    return f"{d.strftime('%d/%m')} ({NOME_DO_DIA[d.weekday()]})"


def _quando(d: date, hoje: date) -> tuple[str, str]:
    """(como entra depois de "cliente", como entra depois de "horário"): ("no sábado", "de sábado")."""
    dias = (d - hoje).days
    if dias in (0, 1):
        nome = "hoje" if dias == 0 else "amanhã"
        return nome, f"de {nome}"
    if 0 < dias < 7:
        return f"n{'o' if d.weekday() >= 5 else 'a'} {NOME_DO_DIA[d.weekday()]}", f"de {NOME_DO_DIA[d.weekday()]}"
    return f"no dia {d.strftime('%d/%m')}", f"do dia {d.strftime('%d/%m')}"


def _codigos(c: Conversa, ev: Evento, antes: dict) -> list[int]:
    """Os imóveis da visita. Mais de um quando ele colou dois cards ou escreveu dois códigos (13789: "Estão
    disponíveis? Querem visitar dia 07/10 às 14:30"), ou citou dois condomínios com um imóvel em oferta cada."""
    ctx = ev.contexto
    if len(ctx.literais) > 1:
        return list(ctx.literais)
    if len(ctx.varios) > 1:      # nomeou dois da lista ("Residencial Tapajós e Reserva das Flores", 21/10)
        return list(ctx.varios)
    if ctx.codigo and ctx.origem in ("literal", "citacao", "card", "lista"):
        return [ctx.codigo]
    um_de_cada = [g[0] for g in ev.condominio_grupos if len(g) == 1]
    if um_de_cada and len(um_de_cada) == len(ev.condominio_grupos):
        return list(dict.fromkeys(um_de_cada))
    if len(ev.condominio_codigos) == 1:
        return [ev.condominio_codigos[0]]
    de_antes = list(antes.get("codigos") or ([antes["codigo"]] if antes.get("codigo") else []))
    return de_antes or [x for x in (ctx.codigo or c.foco_codigo,) if x]


def codigos_texto(codigos: list[int] | tuple[int, ...], marca: str = "#") -> str:
    """[2228, 5758] -> "#2228 e #5758"."""
    nomes = [f"{marca}{x}" for x in codigos]
    return nomes[0] if len(nomes) == 1 else ", ".join(nomes[:-1]) + " e " + nomes[-1]


def _dados(p: dict) -> dict:
    """O que a confirmação e o "anotei" mostram: a data, a hora e TODOS os códigos (a ponte da visita lê
    `codigos`, a lista de inteiros)."""
    codigos = list(p.get("codigos") or ([p["codigo"]] if p.get("codigo") else []))
    return {"data": data_texto(date.fromisoformat(p["dia"])), "horario": p["hora"].replace(":", "h"),
            "codigos": codigos, "codigos_texto": codigos_texto(codigos), "codigos_tel": codigos_texto(codigos, "")}


def _lido(c: Conversa, ev: Evento, antes: dict) -> dict:
    """O pedido com o que esta mensagem trouxe por cima do que já estava anotado."""
    agora = ev.agora.astimezone(MANAUS)
    do_modelo = (ev.classificacao.horario_visita if ev.classificacao else None) or ""
    hora = hora_dita(ev.texto) or hora_dita(do_modelo) or antes.get("hora")
    dia = dia_dito(ev.texto, agora.date()) or dia_dito(do_modelo, agora.date())
    dia = dia or (date.fromisoformat(antes["dia"]) if antes.get("dia") else None)
    parte = None if hora else (parte_dita(ev.texto) or antes.get("parte"))
    if dia is None and (parte or (hora and hora > agora.strftime("%H:%M"))):
        dia = agora.date()          # "às 19:00", "no começo da noite": é hoje (como a Nay velha entendia)
    codigos = _codigos(c, ev, antes)
    return {"codigo": codigos[0] if codigos else None, "codigos": codigos, "dia": dia.isoformat() if dia else None,
            "hora": hora, "parte": parte, "quando": ev.agora.isoformat()}


def _falta(p: dict, hoje: date, texto: str = "") -> Acao:
    """A pergunta do que falta: o horário daquele dia, o dia daquela hora, ou os dois. Se ele disse que ainda
    espera o horário do cliente, ela não pergunta: diz que fica no aguardo (a hora que vier depois completa)."""
    dia = date.fromisoformat(p["dia"]) if p["dia"] else None
    if not dia and not p["hora"]:
        return Acao("visita_pedida", template="visita_entregue", codigo=p["codigo"])
    quando, de_dia = _quando(dia, hoje) if dia else (None, None)
    aguarda = bool(dia) and not p["hora"] and bool(AGUARDA_A_HORA.search(_plano(texto)))
    dados = {"aguarda": aguarda, "com_parte": bool(p["parte"]) and not aguarda, "parte": p["parte"], "quando": quando,
             "so_dia": bool(dia) and not p["parte"] and not aguarda, "de_dia": de_dia,
             "so_hora": not dia, "hora": (p["hora"] or "").replace(":", "h")}
    return Acao("visita_pedida", template="visita_qual_horario", codigo=p["codigo"], dados=dados)


def pedir(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele quer visitar: junta o que já se sabe e pergunta o que falta, ou manda a confirmação."""
    p = _lido(c, ev, aberto(c, ev.agora) or {})
    if p["codigo"] is None:      # não se sabe de qual imóvel: o dia e a hora ficam anotados para a resposta dele
        return (c.com(visita_pedida={**p, "etapa": "falta"}),
                Acao("template", template="pergunta_qual_imovel"))
    foco = {"foco_codigo": p["codigo"], "foco_origem": c.foco_origem if c.foco_codigo == p["codigo"] else "visita"}
    if not (p["dia"] and p["hora"]):
        return (c.com(estado="VISITA_PEDIDA", visita_pedida={**p, "etapa": "falta"}, **foco),
                _falta(p, ev.agora.astimezone(MANAUS).date(), ev.texto))
    return (c.com(estado="VISITA_PEDIDA", visita_pedida={**p, "etapa": "confirmar"}, **foco),
            Acao("visita_pedida", template="visita_confirmar", codigo=p["codigo"], dados=_dados(p)))


def confirmar(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele confirmou os dados: ela anota e avisa o Tel. A conversa segue (não escala, não para)."""
    p = c.visita_pedida or {}
    return (c.com(estado="APRESENTADO", visita_pedida={**p, "etapa": "anotada", "quando": ev.agora.isoformat()}),
            Acao("visita_pedida", template="visita_anotada", codigo=p.get("codigo"), dados=_dados(p)))


def corrigir(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele disse que os dados não estão certos, sem dizer os certos: ela pergunta o dia e a hora de novo."""
    p = {**(c.visita_pedida or {}), "dia": None, "hora": None, "parte": None, "etapa": "falta",
         "quando": ev.agora.isoformat()}
    return c.com(visita_pedida=p), Acao("visita_pedida", template="visita_entregue", codigo=p.get("codigo"))

"""A chave da pessoa (setor identidade).

Telefone brasileiro vira 55 + DDD + os 8 últimos dígitos: a Z-API entrega o
mesmo número ora com o 9 na frente (13 dígitos), ora sem (12). O @lid vira
`lid:<dígitos>`, SEM o sufixo (a migração 193 do velho: o grupo grava só os
dígitos e o webhook manda "<dígitos>@lid").
"""
from __future__ import annotations

import re
from typing import Protocol

from nay.nos import no


def chave(telefone: str | None) -> str | None:
    if not telefone:
        return None
    t = telefone.strip().lower()
    if "@lid" in t or t.startswith("lid:"):
        d = re.sub(r"\D", "", t.split("@")[0])
        return f"lid:{d}" if d else None
    d = re.sub(r"\D", "", t)
    if len(d) < 10:
        return None
    if d.startswith("55") and len(d) in (12, 13):
        return "55" + d[2:4] + d[-8:]
    if len(d) in (10, 11):                      # sem DDI
        return "55" + d[:2] + d[-8:]
    return d


def e_lid(ch: str | None) -> bool:
    return bool(ch) and ch.startswith("lid:")


def lid_digitos(ch: str) -> str:
    return ch[4:] if e_lid(ch) else ch


def mascarar(ch: str | None) -> str:
    """Só os 4 últimos dígitos, para log e relatório."""
    if not ch:
        return "?"
    return "…" + re.sub(r"\D", "", ch)[-4:]


class FontePapel(Protocol):
    def papel_equipe(self, chave: str) -> str | None: ...
    def e_proprietario(self, chave: str) -> bool: ...
    def chaves_irmas(self, chave: str) -> set[str]: ...


@no("identidade.papel")
def papel(ch: str, fonte: FontePapel, tel_telefones: tuple[str, ...]) -> str:
    irmas = fonte.chaves_irmas(ch) | {ch}
    tels = {chave(t) for t in tel_telefones}
    if irmas & tels:
        return "tel"
    for c in irmas:
        p = fonte.papel_equipe(c)
        if p:
            return "acompanhante" if p == "acompanhante" else "equipe"
    if any(fonte.e_proprietario(c) for c in irmas):   # dono de imóvel: a Nay não atende (Tel, 22/10/2026)
        return "proprietario"
    return "corretor"


@no("porta.lista")
def corretor_da_lista(ch: str, fonte) -> bool:
    """A pessoa (por qualquer das suas chaves: telefone ou @lid) está na lista de corretores."""
    return any(fonte.corretor_da_lista(c) for c in fonte.chaves_irmas(ch) | {ch})


def telefone_da(ch: str, fonte) -> str:
    """O telefone para mostrar ao Tel: o da própria chave, ou o irmão quando ela é @lid."""
    if not e_lid(ch):
        return ch
    return next((c for c in sorted(fonte.chaves_irmas(ch)) if not e_lid(c)), ch)

arquivos.doc:
Executar a instrução da equipe num turno (setor comandos).

O CRM guarda a instrução ("Nay atender com instrução") e reentrega o que o corretor escreveu por último; a porta do
sistema velho entrega esse turno ao núcleo, e é aqui que a instrução vira ação, UMA vez (o worker marca em
core_instrucao_feita):

  1. o modelo traduz a instrução num plano (instrucao/plano.py): pedido, dizer, seguir, nao_sei;
  2. o `pedido` roda pelo turno normal, como se o corretor tivesse escrito aquilo: card, fotos, busca e ficha saem
     do catálogo, com as mesmas paredes de sempre. Se a Nay não entender o pedido, o "não entendi" NÃO vai para o
     corretor (não foi ele quem escreveu): sobe ao Tel;
  3. o `dizer` (recado ou pergunta da equipe) sai na frente, na voz dela, se passou na conferência;
  4. sem pedido e sem recado, a instrução só liberou: ela responde a última mensagem dele, como num turno comum;
  5. o que ela não faz por instrução vira um aviso ao Tel, dizendo qual parte ficou de fora.

arquivos.codigo:
"""Os nós da Nay (Nova Nay, fase 1).

Um nó é uma função de uma etapa, marcada com `@no("id")`. O decorador faz três coisas e nenhuma muda o que a
função devolve: (1) registra a função no mapa do painel (aba Nós do site); (2) grava no trace do turno a entrada,
a saída, o tempo e o erro, com o id do nó; (3) liga a função a um id estável, que os testes, o painel e o
inventário usam.

O nome, a etapa, a descrição (em português simples, para o Tel), as configs, os templates e as linhas do
inventário de cada nó moram em `painel/nos.yaml`: o código não é escrito "em nós", o nó aponta para uma função
real (D14). Função auxiliar pequena não precisa ser nó; o que toma decisão ou fala com o mundo é.
"""
from __future__ import annotations

import json
from collections.abc import Callable
from contextvars import ContextVar
from dataclasses import dataclass
from functools import lru_cache, wraps
from pathlib import Path
from time import perf_counter
from typing import Any

import yaml

from nay.trace.trace import Trace, _json

ETAPAS = {
    "e01_entrada": "1. Entrada", "e02_eco": "2. Eco", "e03_porta": "3. Porta", "e04_comandos": "4. Comandos",
    "e05_contexto": "5. Contexto", "e06_entendimento": "6. Entendimento", "e07_decisao": "7. Decisão",
    "e08_acoes": "8. Ações", "e09_composicao": "9. Composição", "e10_validacao": "10. Validação",
    "e11_saida": "11. Saída", "e12_relogio": "12. Relógio",
}
ARQUIVO = Path(__file__).resolve().parent.parent / "painel" / "nos.yaml"
LIMITE_DO_RESUMO = 600      # caracteres de entrada e de saída guardados por nó (o trace não é cópia do banco)
# só valores da conversa entram inteiros no resumo; catálogo, cérebro e modelo viram o nome do tipo
VALORES = ("nay.tipos", "nay.estado.acao", "nay.contexto.resolver_imovel", "nay.classificador.schema",
           "nay.classificador.atalhos", "nay.validador.validar", "nay.saida.caixa", "nay.pipeline",
           "nay.cerebro.apelidos")


@dataclass(frozen=True)
class InfoNo:
    id: str                 # "contexto.imovel_em_jogo": estável, nunca muda depois de criado
    nome: str
    etapa: str
    descricao: str
    entra: str = ""
    sai: str = ""
    configs: tuple = ()
    templates: tuple = ()
    inventario: tuple = ()  # linhas do inventário que o nó cumpre; ("infra",) se nenhuma
    funcao: str = ""        # "nay/arquivo.py:funcao", conferido pelo teste do mapa


REGISTRO: dict[str, tuple[InfoNo, Callable]] = {}
_trace: ContextVar[Trace | None] = ContextVar("trace_do_turno", default=None)


@lru_cache(maxsize=1)
def descritos() -> dict[str, InfoNo]:
    cru = yaml.safe_load(ARQUIVO.read_text(encoding="utf-8")) or {}
    return {i: InfoNo(id=i, nome=d["nome"], etapa=d["etapa"], descricao=d["descricao"], entra=d.get("entra", ""),
                      sai=d.get("sai", ""), configs=tuple(d.get("configs") or ()),
                      templates=tuple(d.get("templates") or ()), inventario=tuple(d.get("inventario") or ()),
                      funcao=d.get("funcao", "")) for i, d in cru.items()}


def _resumo(v: Any) -> Any:
    """Um resumo curto do valor: o que cabe em JSON, cortado; o resto vira o nome do tipo."""
    if v is None or isinstance(v, bool | int | float):
        return v
    if isinstance(v, str):
        return v if len(v) <= LIMITE_DO_RESUMO else v[:LIMITE_DO_RESUMO] + "…"
    de_valor = type(v).__module__ in VALORES and (hasattr(v, "__dataclass_fields__") or hasattr(v, "model_dump"))
    if not (de_valor or isinstance(v, dict | list | tuple | set | frozenset)):
        return f"<{type(v).__name__}>"
    if isinstance(v, dict | list | tuple | set | frozenset) and len(v) > 40:
        return f"<{type(v).__name__} com {len(v)} itens>"
    try:
        limpo = _json([_resumo(x) for x in v] if isinstance(v, list | tuple | set | frozenset)
                      else {str(k): _resumo(x) for k, x in v.items()} if isinstance(v, dict) else v)
        txt = json.dumps(limpo, ensure_ascii=False, default=str)
    except (TypeError, ValueError, RecursionError):
        return f"<{type(v).__name__}>"
    return limpo if len(txt) <= LIMITE_DO_RESUMO else txt[:LIMITE_DO_RESUMO] + "…"


def _entrada(args: tuple, kwargs: dict) -> Any:
    partes = [_resumo(a) for a in args] + [{k: _resumo(v)} for k, v in kwargs.items()]
    return partes[0] if len(partes) == 1 else partes


def no(id_do_no: str) -> Callable[[Callable], Callable]:
    """Marca a função como o nó `id_do_no`. Fora de um turno (sem trace ligado) ela roda como sempre rodou."""
    meta = descritos().get(id_do_no)
    if meta is None:
        raise ValueError(f"nó {id_do_no} não está em painel/nos.yaml")
    if meta.etapa not in ETAPAS:
        raise ValueError(f"nó {id_do_no}: etapa desconhecida {meta.etapa}")

    def decorar(f: Callable) -> Callable:
        if id_do_no in REGISTRO and REGISTRO[id_do_no][1].__qualname__ != f.__qualname__:
            raise ValueError(f"nó repetido: {id_do_no}")

        @wraps(f)
        def rodar(*args: Any, **kwargs: Any) -> Any:
            tr = _trace.get()
            if tr is None:
                return f(*args, **kwargs)
            e = tr.registrar(meta.etapa, meta.id, _entrada(args, kwargs), no_id=meta.id)
            ini = perf_counter()
            try:
                saida = f(*args, **kwargs)
            except Exception as x:
                e.erro = f"{type(x).__name__}: {x}"[:500]
                raise
            finally:
                e.ms = int((perf_counter() - ini) * 1000)
            e.saida = _resumo(saida)
            return saida

        rodar.no = meta                      # type: ignore[attr-defined]
        REGISTRO[id_do_no] = (meta, f)
        return rodar

    return decorar


class turno:
    """`with nos.turno(tr): ...` liga o trace do turno aos nós chamados lá dentro."""

    def __init__(self, tr: Trace) -> None:
        self.tr, self.ficha = tr, None

    def __enter__(self) -> Trace:
        self.ficha = _trace.set(self.tr)
        return self.tr

    def __exit__(self, *_: Any) -> None:
        _trace.reset(self.ficha)

