"""Cliente mínimo da Z-API. Conferido em 02/10 com o nó "Enviar Z-API" do fluxo
velho: POST em <base>/send-text e <base>/send-image, cabeçalho Client-Token,
corpo {phone, message} e {phone, image}. A base (com instância e token) e o
Client-Token só existem no .env do servidor."""
from __future__ import annotations

import httpx

from nay.config import config
from nay.identidade.contato import e_lid, lid_digitos


def telefone_de(chave: str) -> str:
    """A chave da pessoa no formato que a Z-API recebe: dígitos, ou <dígitos>@lid."""
    return lid_digitos(chave) + "@lid" if e_lid(chave) else chave


def _post(rota: str, corpo: dict, timeout: float) -> dict:
    c = config()
    if not c.zapi_base_url or not c.zapi_client_token:
        raise RuntimeError("ZAPI_BASE_URL ou ZAPI_CLIENT_TOKEN não definidos no .env")
    r = httpx.post(f"{c.zapi_base_url.rstrip('/')}/{rota}", json=corpo, timeout=timeout,
                   headers={"Client-Token": c.zapi_client_token, "Content-Type": "application/json"})
    r.raise_for_status()
    return r.json()


def enviar_texto(chave: str, texto: str) -> dict:
    return _post("send-text", {"phone": telefone_de(chave), "message": texto}, 20)


def enviar_imagem(chave: str, url: str) -> dict:
    return _post("send-image", {"phone": telefone_de(chave), "image": url}, 30)

"""Utilidades de texto usadas por mais de um setor. Sem regra de negócio."""
from __future__ import annotations

import re
import unicodedata


def sem_acento(s: str) -> str:
    nfkd = unicodedata.normalize("NFKD", s or "")
    return "".join(c for c in nfkd if not unicodedata.combining(c))


def normal(s: str | None) -> str:
    """minúsculo, sem acento, pontuação vira espaço, espaços simples."""
    t = sem_acento(s or "").lower()
    t = re.sub(r"[^\w\s]", " ", t)
    return re.sub(r"\s+", " ", t).strip()


def levenshtein(a: str, b: str) -> int:
    if a == b:
        return 0
    if len(a) < len(b):
        a, b = b, a
    anterior = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        atual = [i]
        for j, cb in enumerate(b, 1):
            atual.append(min(anterior[j] + 1, atual[j - 1] + 1, anterior[j - 1] + (ca != cb)))
        anterior = atual
    return anterior[-1]


def semelhanca(a: str, b: str) -> float:
    """1 - distância/maior comprimento (a régua de letras que o velho mediu melhor)."""
    if not a or not b:
        return 0.0
    return 1 - levenshtein(a, b) / max(len(a), len(b))


def reais(valor: float | None) -> str:
    """1900 -> 'R$ 1.900'."""
    if valor is None:
        return ""
    return "R$ " + f"{int(round(valor)):,}".replace(",", ".")


_EXTENSO = {"um": 1, "uma": 1, "dois": 2, "duas": 2, "tres": 3, "quatro": 4, "cinco": 5, "seis": 6,
            "sete": 7, "oito": 8, "nove": 9, "dez": 10, "quinze": 15, "vinte": 20, "trinta": 30}


def valor_em_reais(t: str | None) -> float | None:
    """Um valor escrito como resposta: '3500', '3.500', 'R$ 2.500,00', '3 mil',
    '2,5 mil', '5k', 'quatro mil', '1,5 milhão'. None se não for só um valor."""
    s = sem_acento(t or "").lower().strip().rstrip("!?.").strip()
    s = re.sub(r"r\$\s*", "", s)
    s = re.sub(r"^(ate|uns|umas|na media de|media de|mais ou menos|no maximo|maximo|max)\s+", "", s)
    s = re.sub(r"\s*(reais|por mes|mensal|/mes|mes)$", "", s).strip()
    m = re.fullmatch(r"(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d{1,2}))?\s*(mil|k|milhao|milhoes|mi)?", s)
    if m:
        numero = float(m.group(1).replace(".", "") + ("." + m.group(2) if m.group(2) else ""))
        mult = {"mil": 1e3, "k": 1e3, "milhao": 1e6, "milhoes": 1e6, "mi": 1e6}.get(m.group(3) or "", 1)
        return numero * mult
    m = re.fullmatch(r"(\w+)\s+(mil|milhao|milhoes)", s)
    if m and m.group(1) in _EXTENSO:
        return _EXTENSO[m.group(1)] * (1e3 if m.group(2) == "mil" else 1e6)
    return None


_FAIXA = re.compile(r"(?:entre|de|dos|das)?\s*(\d+(?:[.,]\d+)?)\s*(mil|k)?\s*(?:e|a|ate|-|/)\s*"
                    r"(\d+(?:[.,]\d+)?)\s*(mil|k|milhao|milhoes|mi)?")


def faixa_em_reais(t: str | None) -> float | None:
    """A faixa como resposta ao "Até que valor?": 'entre 2 e 3 mil', 'de 2 a 3', '2 a 3 mil', '2-3 mil'. O teto é
    o maior. Sem unidade, volta o número cru e quem pergunta põe na escala (`teto_na_escala`): em 03/10 a
    Marciléia respondeu "Entre 2 e 3" e ouviu "Até que valor?" três vezes."""
    s = sem_acento(t or "").lower().strip().rstrip("!?.").strip()
    s = re.sub(r"r\$\s*", "", s)
    s = re.sub(r"\s*(reais|por mes|mensal|/mes|mes)$", "", s).strip()
    m = _FAIXA.fullmatch(s)
    if not m:
        return None
    mult = {"mil": 1e3, "k": 1e3, "milhao": 1e6, "milhoes": 1e6, "mi": 1e6}.get(m.group(4) or m.group(2) or "", 1)
    return max(_numero(m.group(1)), _numero(m.group(3))) * mult


def _numero(x: str) -> float:
    """'2,5' -> 2.5; '3.500' -> 3500."""
    return float(x.replace(".", "").replace(",", ".")) if "," in x else float(x.replace(".", ""))


def teto_na_escala(v: float | None, finalidade: str | None) -> float | None:
    """Número pequeno na resposta do teto é mil (ou milhão, na venda): "3" no aluguel é R$ 3 mil, "450" na venda é
    R$ 450 mil, "1,5" na venda é R$ 1,5 milhão. Valor que já parece reais fica como está."""
    if not v:
        return v
    if finalidade == "venda":
        return v * 1e6 if v < 10 else v * 1e3 if v < 1000 else v
    if finalidade == "locacao":
        return v * 1e3 if v < 100 else v
    # alugar OU comprar ("os dois"), ou ainda sem saber: abaixo de mil não é preço de nada, é milhar. Em 03/10 um
    # corretor com "os dois" respondeu "450" e a busca procurou até R$ 450: nada, duas vezes.
    return v * 1e3 if v < 1000 else v


_CUMPRIMENTO = re.compile(r"\b(o+i+e?|ola+|opa|bom dia|boa tarde|boa noite|e ai|salve)\b")


def cumprimentou(texto: str | None) -> bool:
    """Tem um cumprimento na mensagem ("oi", "oii", "olá", "bom dia", "boa tarde"...)."""
    return bool(_CUMPRIMENTO.search(normal(texto)))


def primeiro_nome(nome: str | None) -> str | None:
    if not nome:
        return None
    limpo = re.sub(r"[^\wÀ-ÿ\s]", " ", nome).split()
    for p in limpo:
        if p.isalpha() and len(p) >= 2 and p.lower() not in {"corretor", "corretora", "creci", "imob", "imoveis"}:
            return p.capitalize()
    return None


_EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+")
_DOCUMENTO = re.compile(r"(?i)\b(cpf|rg|cnh|cnpj)\b\s*(?:n[ºo°.]*)?\s*[:=-]?\s*[\d.\-/ ]{5,}\d")
_CPF = re.compile(r"\b\d{3}\.\d{3}\.\d{3}-\d{2}\b")
_TELEFONE = re.compile(r"(?<![\d.,])(?:\+?55[\s.-]*)?\(?\d{2}\)?[\s.-]*9?\s?\d{4}[\s.-]?\d{4}(?!\d)|\d{9,}")


def sem_dado_pessoal(t: str | None) -> str:
    """O que sai do sistema (Jev, relatório, trace) sem e-mail, CPF, RG nem
    telefone. Código de imóvel (3 a 5 dígitos) e valor ("R$ 3.500") ficam."""
    s = _EMAIL.sub("[email]", t or "")
    s = _DOCUMENTO.sub(lambda m: f"{m.group(1).upper()}: [documento]", s)
    s = _CPF.sub("[cpf]", s)
    return _TELEFONE.sub("[telefone]", s)

"""O trace (setor trace): uma linha por etapa por turno, gravada em core_trace.
Guarda o que a pergunta 53 diz que o velho não deixava reconstruir: o texto cru
do modelo, os argumentos e o retorno de cada ferramenta, a versão do prompt e
das regras, o modelo e o tempo de cada etapa.

Nunca derruba o turno: o registro é em memória e a gravação é do worker, que
engole a falha e segue."""
from __future__ import annotations

import time
from contextlib import contextmanager
from dataclasses import asdict, dataclass, field, is_dataclass
from typing import Any


def _json(v: Any) -> Any:
    if is_dataclass(v):
        return _json(asdict(v))
    if hasattr(v, "model_dump"):
        return v.model_dump()
    if isinstance(v, dict):
        return {str(k): _json(x) for k, x in v.items()}
    if isinstance(v, list | tuple | set | frozenset):
        return [_json(x) for x in v]
    if isinstance(v, str | int | float | bool) or v is None:
        return v
    return str(v)


@dataclass
class Etapa:
    seq: int
    setor: str
    etapa: str
    entrada: Any = None
    saida: Any = None
    ms: int | None = None
    modelo: str | None = None
    versao_prompt: str | None = None
    erro: str | None = None
    no_id: str | None = None        # o nó (nay/nos.py) que gerou a linha; None nas antigas


@dataclass
class Trace:
    etapas: list[Etapa] = field(default_factory=list)

    def registrar(self, setor: str, etapa: str, entrada: Any = None, saida: Any = None, **extra: Any) -> Etapa:
        e = Etapa(len(self.etapas) + 1, setor, etapa, _json(entrada), _json(saida), **extra)
        self.etapas.append(e)
        return e

    @contextmanager
    def medir(self, setor: str, etapa: str, entrada: Any = None):
        e = self.registrar(setor, etapa, entrada)
        inicio = time.perf_counter()
        try:
            yield e
        except Exception as x:
            e.erro = f"{type(x).__name__}: {x}"[:500]
            raise
        finally:
            e.ms = int((time.perf_counter() - inicio) * 1000)
            e.saida = _json(e.saida)

"""O portão de coerência (setor validador): o imóvel que vai sair é o que ele pediu?

Levantamento de 05/10: em 15 de 21 envios o código não veio dele (veio do foco gravado, do nome de um
condomínio, da opção da lista ou da busca), e nada conferia se o imóvel batia com os filtros da conversa. Uma
corretora pediu "casa na faixa de seis mil", citou um condomínio e recebeu a de R$ 9.000 (turno 896); outro
pediu fotos "de um apartamento no Mosaico" e recebeu as do imóvel que estava em foco desde o dia anterior (934).

A prova, antes de qualquer card ou foto:
  PASSA      o código veio dele (digitou, marcou a mensagem ou colou o card), ou ele acabou de confirmar; ou a
             origem não é dele mas finalidade, tipo, teto e bairro (ou vizinho) batem com os filtros gravados.
  CONFIRMAR  a origem não é dele e alguma coisa não bate: ela mostra a ficha curta e pergunta "É este imóvel?".
  LISTAR     não bate e há uma lista na frente da qual esse imóvel não faz parte: pergunta qual da lista.
  NEGAR      o imóvel não existe ou é de parceiro (quem responde é o card: recusa e sobe ao Tel).

Só compara o filtro que ESTÁ gravado: conversa sem filtro nenhum não contradiz nada. No teto, só o imóvel mais
caro que a faixa barra; mais barato que o pedido não é o erro que este portão existe para pegar.

Função pura. Quem chama, grava o motivo no trace (etapa "coerencia") e pergunta ao Jev quando passa por origem
que não é dele é `acoes/portao.py`.
"""
from __future__ import annotations

from dataclasses import dataclass

from nay.cerebro.catalogo import Filtros, _tipo_serve, preco
from nay.config import cfg
from nay.estado.filtros import finalidade_pelo_valor
from nay.texto import reais
from nay.tipos import Conversa, Imovel

EXPLICITAS = ("literal", "citacao", "card")      # código digitado, mensagem marcada, card colado
ROTULO_DO_TIPO = {"casa_condominio": "casa em condomínio", "predio": "prédio", "galpao": "galpão",
                  "comercial": "imóvel comercial"}


@dataclass(frozen=True)
class Prova:
    veredito: str               # PASSA | CONFIRMAR | LISTAR | NEGAR
    motivo: str
    explicita: bool = False     # a origem é dele: não vai ao Jev


def _finalidade(c: Conversa) -> str | None:
    if c.filtro_finalidade in ("locacao", "venda"):
        return c.filtro_finalidade
    return finalidade_pelo_valor(c.filtro_teto)


def diferencas(c: Conversa, i: Imovel, perto: tuple[str, ...] = ()) -> list[str]:
    """O que o imóvel tem de diferente dos filtros gravados na conversa (lista vazia = bate)."""
    difs: list[str] = []
    fin = _finalidade(c)
    if fin == "locacao" and not i.de_locacao:
        difs.append("ele procura locação e o imóvel é só de venda")
    if fin == "venda" and not i.de_venda:
        difs.append("ele procura compra e o imóvel é só de locação")
    tipo = c.filtro_tipo
    if tipo and tipo != "tanto_faz" and not _tipo_serve(i, tipo):
        difs.append(f"ele pediu {ROTULO_DO_TIPO.get(tipo, tipo)} e o imóvel é {ROTULO_DO_TIPO.get(i.tipo, i.tipo)}")
    if c.filtro_teto:
        p = preco(i, Filtros(finalidade=fin, teto=c.filtro_teto))
        limite = c.filtro_teto * (1 + cfg("filtros")["teto_faixa_acima_pct"] / 100)
        if p and p > limite:
            difs.append(f"ele disse até {reais(c.filtro_teto)} e o imóvel é {reais(p)}")
    regiao = tuple(c.filtro_regiao or ())
    if regiao and i.bairro_norm and i.bairro_norm not in regiao and i.bairro_norm not in perto:
        difs.append(f"ele pediu {', '.join(regiao)} e o imóvel fica em {i.bairro or i.bairro_norm}")
    return difs


def provar_pedido(codigo: int, origem: str | None, conversa: Conversa, imovel: Imovel | None,
                  perto: tuple[str, ...] = (), lista: tuple[int, ...] = ()) -> Prova:
    """`origem`: literal | citacao | card | confirmado | lista | condominio | busca | foco.
    `perto`: os bairros vizinhos dos que ele pediu. `lista`: os códigos da lista que está na frente dele."""
    if imovel is None:
        return Prova("NEGAR", f"o imóvel {codigo} não existe no catálogo")
    if imovel.e_parceiro:
        return Prova("NEGAR", "imóvel de parceiro nunca é oferecido")
    if origem in EXPLICITAS:
        return Prova("PASSA", f"o código veio dele ({origem})", explicita=True)
    if origem == "confirmado":
        return Prova("PASSA", "ele confirmou que é este imóvel", explicita=True)
    difs = diferencas(conversa, imovel, perto)
    if not difs:
        return Prova("PASSA", f"origem {origem or 'foco'}: bate com os filtros gravados")
    motivo = f"origem {origem or 'foco'}: " + "; ".join(difs)
    if lista and codigo not in lista:
        return Prova("LISTAR", motivo + "; há uma lista na frente e ele não faz parte dela")
    return Prova("CONFIRMAR", motivo)

"""O validador (setor validador): VETA, nunca substitui (princípio 2).

Grounding: todo código, valor em R$ e "N fotos" do texto tem que ter saído de
uma ferramenta deste turno; imóvel de outra finalidade não entra (menos o que
ele mesmo citou). Mais as paredes de forma: promessa, citar o Tel, "parceria",
markdown, emoji fora dos do sistema, uma pergunta por mensagem, visita fora da
máquina. As regras e a ação ao vetar vêm de regras.yaml.
"""
from __future__ import annotations

import re
from collections.abc import Callable
from dataclasses import dataclass, field, replace

from nay import regras
from nay.cerebro.catalogo import Catalogo
from nay.nos import no
from nay.tipos import Peca

EMOJI_DO_SISTEMA = set("📍🏢📌🏠💰✅⏰🔑📅🕐🛏🛋•")
EMOJI = re.compile("[\U0001F300-\U0001FAFF☀-➿\U0001F000-\U0001F2FF]")


@dataclass(frozen=True)
class Permitido:
    codigos: frozenset[int] = frozenset()
    valores: frozenset[int] = frozenset()
    fotos: frozenset[str] = frozenset()
    codigos_dele: frozenset[int] = frozenset()      # o que ele mesmo escreveu ou marcou
    finalidade: str | None = None
    acao: str = ""
    catalogo: Catalogo | None = None


@dataclass
class Veredito:
    passou: bool = True
    vetos: list[tuple[str, str, str]] = field(default_factory=list)   # (regra, motivo, acao_ao_vetar)


def _codigos(t: str) -> set[int]:
    return {int(x) for x in re.findall(r"(?:c[oó]digo:\s*|#|\bo |\bdo |\bno )(\d{3,5})\b", t, re.I)}


VALOR = re.compile(r"R\$\s*(\d{1,3}(?:\.\d{3})+|\d+)(?:,(\d{1,2}))?(?:\s*(mil(?:h[oõ]es|h[aã]o)?|mi|k)\b)?", re.I)


def _valores(t: str) -> set[int]:
    """Os valores em R$ do texto, em reais. "R$ 470 mil" é 470.000 e "R$ 1,2 milhão" é 1.200.000: em 03/10 a
    resposta certa sobre o Maison Rochelle ("à venda por R$ 470 mil") foi vetada porque aqui se lia 470, e o
    corretor recebeu "vou precisar confirmar". Sem escala, os centavos não contam (R$ 1.089,50 é 1089)."""
    achados = set()
    for inteiro, decimais, escala in VALOR.findall(t):
        n = int(inteiro.replace(".", ""))
        if escala:
            vezes = 1_000 if escala.lower() in ("mil", "k") else 1_000_000
            n = round(float(f"{n}.{decimais or 0}") * vezes)
        achados.add(n)
    return achados


def promessa(t, p):
    return re.search(r"\bvou (ver|verificar|confirmar|checar|consultar|conferir)\b|\bte (aviso|retorno)\b"
                     r"|j[aá] (te )?(retorno|aviso)|assim que (eu )?souber", t, re.I)


def citou_o_tel(t, p):
    return re.search(r"\btel\b", t, re.I)


def parceria(t, p):
    return re.search(r"(im[oó]ve(l|is)|[eé]) de parceri|parceir[oa]s?\b", t, re.I)


def markdown(t, p):
    return re.search(r"\*\*|^#{1,6}\s", t, re.M)


def uma_pergunta(t, p):
    return t.count("?") > 1


def visita(t, p):
    return p.acao != "visita_pedida" and re.search(
        r"visita (confirmada|agendada|marcada)|hor[aá]rio j[aá] passou", t, re.I)


def emoji(t, p):
    return any(e not in EMOJI_DO_SISTEMA for e in EMOJI.findall(t))


def codigo_so_de_ferramenta(t, p):
    return _codigos(t) - p.codigos - p.codigos_dele


def valor_so_de_ferramenta(t, p):
    return _valores(t) - p.valores


def nega_imovel(t, p):
    return re.search(r"n[aã]o (encontrei|achei|temos esse|existe)", t, re.I) and _codigos(t) & (
        p.codigos | p.codigos_dele)


def finalidade(t, p):
    if p.finalidade not in ("locacao", "venda") or not p.catalogo:
        return None
    campo = "de_locacao" if p.finalidade == "locacao" else "de_venda"
    return {c for c in _codigos(t) - p.codigos_dele
            if (i := p.catalogo.get(c)) and not getattr(i, campo)}


CHECAS: dict[str, Callable] = {f.__name__: f for f in (
    promessa, citou_o_tel, parceria, markdown, uma_pergunta, visita, emoji, codigo_so_de_ferramenta,
    valor_so_de_ferramenta, nega_imovel, finalidade)}


def _foto_ok(item: Peca, p: Permitido) -> bool:
    return item.codigo in p.codigos and item.imagem_url in p.fotos


@no("validacao.regras")
def validar(itens: list[Peca], p: Permitido, isentos: frozenset[str] = frozenset()) -> Veredito:
    """`isentos`: regras que não valem para um template específico (ex.: a frase fixa
    de parceria do Tel usa a palavra 'parceria' no sentido certo)."""
    v = Veredito()
    ativas = [r for r in regras.regras() if r.get("onde") == "validador" and r.get("checa") in CHECAS]
    for item in itens:
        if item.papel_destino in ("tel", "grupo"):   # o aviso ao Tel (e ao grupo) cita o telefone, de propósito
            continue
        if item.tipo == "imagem":
            if not _foto_ok(item, p):
                v.vetos.append(("foto_so_do_imovel", f"foto {item.codigo} fora do turno", "silencio"))
            continue
        for r in ativas:
            if r["id"] in isentos:
                continue
            achou = CHECAS[r["checa"]](item.texto or "", p)
            if achou:
                v.vetos.append((r["id"], f"{r['descricao']}: {achou if isinstance(achou, set) else 'sim'}",
                                r.get("acao_ao_vetar", "regenera")))
    v.passou = not v.vetos
    return v


# ------------------------------------------------------- o veto de forma que se conserta sozinho
# Regras de `tipo: ajuste` em regras.yaml: o texto está certo, só a FORMA é proibida. Limpar a forma
# resolve; vetar não. 20/10/2026: `compor_validado` mandava todo veto para a escalada, que cala o
# corretor por até 24 h, e um emoji bastava. Quatro conversas do dia caíram assim, duas delas por uma
# resposta de uma palavra ("Aluguel", ...9293, 12h29; "9045", ...2884, 12h45) — e o Tel teve de entrar
# no painel e disparar o imóvel à mão 3 minutos depois (nai_turno, 12h32) e 7 h depois (19h47).
SANEAVEIS = frozenset({"voz_sem_emoji", "markdown"})


def _sem_emoji(t: str) -> str:
    return EMOJI.sub(lambda m: m.group(0) if m.group(0) in EMOJI_DO_SISTEMA else "", t)


def _sem_markdown(t: str) -> str:
    return re.sub(r"^#{1,6}\s*", "", t.replace("**", ""), flags=re.M)


def sanear(t: str) -> str:
    """Tira só a forma proibida (emoji fora dos do sistema, markdown). O conteúdo não muda."""
    limpo = _sem_markdown(_sem_emoji(t))
    return re.sub(r"[ \t]{2,}", " ", limpo).strip()


def saneado(itens: list[Peca], p: Permitido, v: Veredito,
            isentos: frozenset[str] = frozenset()) -> list[Peca] | None:
    """As peças com a forma limpa, quando isso basta para passar; None se há veto de CONTEÚDO, que o
    saneamento não resolve (aí quem decide é `acao_ao_vetar`)."""
    if not v.vetos or any(regra not in SANEAVEIS for regra, _, _ in v.vetos):
        return None
    limpos = [replace(i, texto=sanear(i.texto)) if i.texto else i for i in itens]
    return limpos if validar(limpos, p, isentos).passou else None

acoes/agenda.py:_quando.codigo:
def _quando(p: dict) -> datetime | None:
    try:
        d = date.fromisoformat(p["dia"])
        h, m = (int(x) for x in str(p["hora"]).split(":")[:2])
    except (KeyError, TypeError, ValueError):
        return None
    return datetime(d.year, d.month, d.day, h, m, tzinfo=MANAUS)

acoes/agenda.py:conflito.codigo:
def conflito(alvo: datetime, ocupados: list[tuple[datetime, bool]], mesmo_min: int, outro_min: int) -> bool:
    """`ocupados`: (quando, é do mesmo cliente). Mesmo cliente: `mesmo_min` de folga; outro cliente: `outro_min`."""
    return any(abs((q - alvo).total_seconds()) < (mesmo_min if mesmo else outro_min) * 60 for q, mesmo in ocupados)

acoes/agenda.py:vagos.codigo:
def vagos(alvo: datetime, ocupados: list[tuple[datetime, bool]], agora: datetime, lim: dict) -> list[datetime]:
    """Os dois horários vagos mais perto do pedido, no mesmo dia, no horário de visitas, a partir de 1 h daqui."""
    ini_h, ini_m = (int(x) for x in str(lim.get("agenda_inicio", "08:00")).split(":"))
    fim_h, fim_m = (int(x) for x in str(lim.get("agenda_fim", "18:00")).split(":"))
    t, fim = alvo.replace(hour=ini_h, minute=ini_m), alvo.replace(hour=fim_h, minute=fim_m)
    mesmo, outro = int(lim.get("agenda_mesmo_cliente_min", 45)), int(lim.get("agenda_outro_cliente_min", 60))
    livres = []
    while t <= fim:
        if t != alvo and t >= agora + timedelta(hours=1) and not conflito(t, ocupados, mesmo, outro):
            livres.append(t)
        t += timedelta(minutes=PASSO_MIN)
    livres.sort(key=lambda x: (abs((x - alvo).total_seconds()), x))
    return sorted(livres[:2])

acoes/agenda.py:conferir.codigo:
def conferir(cer, conv: Conversa, ev: Evento, a: Acao) -> tuple[Conversa, Acao]:
    """Troca a confirmação pela pergunta do horário vago quando a agenda já tem visita perto."""
    lim = cfg("limites")
    modo = str(lim.get("agenda_motoboy") or "desligada")
    if modo not in ("todas", "com_motoboy") or a.tipo != "visita_pedida" or a.template != "visita_confirmar":
        return conv, a
    p = conv.visita_pedida or {}
    alvo = _quando(p)
    if alvo is None:
        return conv, a
    meus = {conv.chave} | set(cer.chaves_irmas(conv.chave) if hasattr(cer, "chaves_irmas") else ())
    codigos = set(p.get("codigos") or ([p["codigo"]] if p.get("codigo") else []))
    ocupados = []
    for v in cer.agenda(alvo - timedelta(hours=3), alvo + timedelta(hours=12)):
        q = v["quando"] if isinstance(v["quando"], datetime) else datetime.fromisoformat(str(v["quando"]))
        if modo == "com_motoboy" and not v.get("com_motoboy"):
            continue
        mesmo = v.get("chave") in meus
        if mesmo and v.get("codigo") in codigos and abs((q - alvo).total_seconds()) < 60:
            continue                    # é esta mesma visita, já na agenda
        ocupados.append((q.astimezone(MANAUS), mesmo))
    mesmo_min, outro_min = int(lim.get("agenda_mesmo_cliente_min", 45)), int(lim.get("agenda_outro_cliente_min", 60))
    if not conflito(alvo, ocupados, mesmo_min, outro_min):
        return conv, a
    livres = vagos(alvo, ocupados, ev.agora.astimezone(MANAUS), lim)
    texto = " ou ".join(_hora(t) for t in livres) if livres else None
    nova = conv.com(visita_pedida={**p, "hora": None, "etapa": "falta"})
    return nova, Acao("visita_pedida", template="visita_horario_ocupado", codigo=a.codigo,
                      dados={"hora": _hora(alvo), "vagos": texto, "sem_vagos": not texto})

acoes/buscar.py:quartos_texto.codigo:
def quartos_texto(i: Imovel) -> str | None:
    if not i.quartos:
        return None
    return f"{i.quartos} quarto{'s' if i.quartos > 1 else ''}"

acoes/buscar.py:linha.codigo:
def linha(i: Imovel, finalidade: str | None) -> dict:
    """Um imóvel numa linha de lista (lista.md, qual_deles.md, confirmar_imovel.md)."""
    return {"codigo": i.codigo, "condominio": i.condominio_nome or ROTULO.get(i.tipo, "Imóvel").capitalize(),
            "bairro": i.bairro or "Manaus", "quartos": quartos_texto(i), "valor": valor_texto(i, finalidade)}

acoes/buscar.py:artigo.codigo:
def artigo(nome: str) -> str:
    """'No Aleixo', 'Na Ponta Negra', 'Na Cidade Nova', 'No bairro Da Paz'."""
    primeira = nome.split()[0].lower() if nome.strip() else ""
    if primeira in ("da", "do", "de", "das", "dos"):
        return f"No bairro {nome}"
    return f"{'Na' if primeira.endswith('a') or primeira == 'cidade' else 'No'} {nome}"

acoes/buscar.py:onde.codigo:
def onde(cer: Cerebro, bairros: tuple[str, ...]) -> str:
    """'No Aleixo' / 'Na Ponta Negra' / 'Na região que você pediu' / 'Em Manaus'."""
    if len(bairros) == 1:
        return artigo(cer.nome_do_bairro(bairros[0]))
    return "Na região que você pediu" if bairros else "Em Manaus"

acoes/buscar.py:_tem_ar.codigo:
def _tem_ar(cer: Cerebro, i: Imovel) -> bool:
    fi = cer.ficha(i.codigo) or {}
    return any(re.search(r"climatiz|ar.?condicionado", normal(str(x)))
               for x in (fi.get("car_imovel") or []) + (fi.get("car_condominio") or []))

acoes/buscar.py:_achar.codigo:
def _achar(cer: Cerebro, f: Filtros, fora: set[int], so_climatizado: bool) -> list[Imovel]:
    """Os imóveis do filtro. `so_climatizado`: sem mobília no cadastro, mas com ar (o "só climatizado" do Tel)."""
    if not so_climatizado:
        return [i for i in cer.catalogo.buscar(f) if i.codigo not in fora]
    # "pelo menos ar" (Alteração 2, D): o semimobiliado tem o ar, e o sem móveis serve se tiver
    sem_mobilia = Filtros(**{**f.__dict__, "mobilia": None})
    return [i for i in cer.catalogo.buscar(sem_mobilia)
            if i.codigo not in fora and (i.mobilia == "semi" or (i.mobilia != "mobiliado" and _tem_ar(cer, i)))]

acoes/buscar.py:filtrantes.codigo:
def filtrantes(extras: tuple[str, ...]) -> tuple[str, ...]:
    """Os que as CARACTERÍSTICAS precisam ter; fino acabamento só ordena e financiamento é campo do cadastro."""
    return tuple(e for e in extras if e not in PRIORIDADES and e != "financiavel")

acoes/buscar.py:_so_financiaveis.codigo:
def _so_financiaveis(cer: Cerebro, lado: list[Imovel]) -> list[Imovel]:
    # 21/10: quem disse "financiável" não recebe imóvel cujo cadastro diz que não aceita financiamento
    return [i for i in lado if not nao_aceita_financiamento(cer.ficha(i.codigo) or {})]

acoes/buscar.py:_fino_primeiro.codigo:
def _fino_primeiro(lado: list[Imovel]) -> list[Imovel]:
    """Os de fino acabamento na frente, sem mudar a ordem (o preço) dentro de cada grupo."""
    return sorted(lado, key=lambda i: not i.fino_acabamento)

acoes/buscar.py:tem_extras.codigo:
def tem_extras(cer: Cerebro, i: Imovel, extras: tuple[str, ...]) -> bool:
    """O imóvel (ou o condomínio dele) tem o que ele pediu a mais? Lido das características do anúncio."""
    fi = cer.ficha(i.codigo) or {}
    ditas = " ".join(normal(str(x)) for x in (fi.get("car_imovel") or []) + (fi.get("car_condominio") or []))
    return all(e in ditas for e in extras)

acoes/buscar.py:_passa_nos_pilares.codigo:
def _passa_nos_pilares(cer: Cerebro, i: Imovel, extras: tuple[str, ...]) -> bool:
    """Os extras que são pilar: o vertical precisa ter; a casa passa (não se cobra elevador de casa)."""
    pilares = tuple(e for e in extras if e in PILARES)
    if not pilares or not VERTICAL.match(normal(i.tipo or "")):
        return True
    return tem_extras(cer, i, pilares)

acoes/buscar.py:_dos_proximos.codigo:
def _dos_proximos(cer: Cerebro, f: Filtros, fora: set[int], so_climatizado: bool, ref: str | None,
                  ja: list[Imovel]) -> list[Imovel]:
    """Os imóveis dos condomínios próximos (planilha) que ficam fora dos bairros procurados, com os mesmos filtros."""
    if not ref or not cer.proximos:
        return []
    tem = {i.codigo for i in ja}
    em_toda_parte = Filtros(**{**f.__dict__, "bairros": ()})
    return [i for i in _achar(cer, em_toda_parte, fora, so_climatizado)
            if i.codigo not in tem and cer.proximos.perto_de(ref, i)]

acoes/buscar.py:_escondidos.codigo:
def _escondidos(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> dict:
    """O que cabe no pedido (no lugar ou perto) e ficou de fora só porque ele já recebeu hoje ou recusou. É com
    isso que ela decide perguntar "Está perguntando para outro cliente, certo?" (acoes/preparo.py)."""
    if not fora:
        return {}
    aqui, perto = _aqui_e_perto(cer, f, set(), c.filtro_mobilia == "climatizado", c.filtro_extras)
    fora_daqui = [i for i in aqui + perto if i.codigo in fora]
    if not fora_daqui:
        return {}
    nomes = ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})" for i in fora_daqui[:3])
    return {"escondidos": [i.codigo for i in fora_daqui], "escondidos_texto": nomes}

acoes/buscar.py:_mais_longe.codigo:
def _mais_longe(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> list[Imovel]:
    """Nem no lugar pedido nem nos vizinhos há nada NA FAIXA. Antes de negar, os bairros um pouco mais longe (até
    `raio_medio_km` dos pedidos), com os MESMOS filtros e a MESMA faixa de valor, do mais perto para o mais longe.
    Tel, 06/10, rodada 8: "é melhor priorizar faixa de preço mesmo em bairros mais longe, porém não muito, uma
    média só; um cliente de 6 mil não quer apartamento de 2 mil"."""
    if not f.bairros:
        return []
    vistos = set(f.bairros) | {v for b in f.bairros for v in cer.bairros.perto(b)}
    medios = cer.bairros.um_pouco_mais_longe(f.bairros, float(cfg("filtros").get("raio_medio_km", 10)), vistos)
    if not medios:
        return []
    la = _achar(cer, Filtros(**{**f.__dict__, "bairros": tuple(medios)}), fora, c.filtro_mobilia == "climatizado")
    la = _so_financiaveis(cer, la) if "financiavel" in c.filtro_extras else la
    ordem = {b: n for n, b in enumerate(medios)}
    return sorted(la, key=lambda i: ordem.get(i.bairro_norm, len(ordem)))[:cfg("filtros")["max_ao_redor"]]

acoes/buscar.py:_abaixo_da_faixa.codigo:
def _abaixo_da_faixa(cer: Cerebro, c: Conversa, f: Filtros, fora: set[int]) -> dict:
    """A faixa do valor não achou NADA, nem nos vizinhos: existe coisa mais barata com os outros filtros? Ela NÃO
    lista por conta própria (Tel, 06/10, rodada 5: "ela mandou um monte de apartamento barato, a pessoa não quer
    isso"): diz que nessa faixa não tem, a partir de quanto tem, e pergunta se ele quer ver. Devolve o que o
    template precisa, ou {} se não há nada abaixo (ou não se sabe se é aluguel ou compra)."""
    if not f.teto or f.finalidade not in ("locacao", "venda"):
        return {}
    sem_piso = Filtros(**{**f.__dict__, "sem_piso": True})
    aqui, perto = _aqui_e_perto(cer, sem_piso, fora, c.filtro_mobilia == "climatizado", c.filtro_extras)
    if not (aqui or perto):
        return {}
    mais_barato = min(aqui + perto, key=lambda i: preco(i, sem_piso) or 0)
    return {"nada": False, "tem_abaixo": True, "a_partir": reais(preco(mais_barato, sem_piso)),
            "valores_do_mais_barato": valores(mais_barato)}

acoes/buscar.py:_vazia_ou_de_antes.codigo:
def _vazia_ou_de_antes(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int], base: dict) -> dict:
    """Nada novo na faixa. Se nesse perfil só existe o que ele já tem, ela diz isso, em vez de "não tenho"."""
    if not ja:
        return base
    lados = _aqui_e_perto(cer, f, set(c.rejeitados), c.filtro_mobilia == "climatizado")
    tinha = [i for lado in lados for i in lado]
    if not tinha:
        return base
    nomes = ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})" for i in tinha[:3])
    return {**base, "nada": False, "so_enviados": True, "enviados_texto": nomes}

acoes/buscar.py:_ja_no_lugar.codigo:
def _ja_no_lugar(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int]) -> str:
    """O que cabe no pedido NO LUGAR PEDIDO mas ele já recebeu (Hilário, 06/10, rodada 7: pediu Parque 10 e ouviu
    "não tenho imóvel nesse perfil"; os dois que cabiam já tinham ido para ele). Ela diz quais são, em vez de negar."""
    if not ja:
        return ""
    aqui, _ = _aqui_e_perto(cer, f, set(c.rejeitados), c.filtro_mobilia == "climatizado", c.filtro_extras)
    return ", ".join(f"{i.condominio_nome or ROTULO.get(i.tipo, 'imóvel')} ({i.codigo})"
                     for i in aqui if i.codigo in ja)

acoes/buscar.py:_sem_tipo.codigo:
def _sem_tipo(f: Filtros, todos: list[Imovel], pedidos: tuple[str, ...]) -> str | None:
    """Ele pediu casa E apartamento (vários clientes) e de um dos tipos não há nada: a lista diz isso, em vez de
    sair só com o outro tipo como se fosse a resposta (Pedro, 13/10: quem pediu casa não recebe apartamento calado)."""
    if f.tipo != "tanto_faz" or len(pedidos) < 2:
        return None
    tem = {"casa" if i.tipo == "casa_condominio" else i.tipo for i in todos}
    return " nem ".join(ROTULO.get(t, t) for t in pedidos if t not in tem) or None

acoes/buscar.py:_nada.codigo:
def _nada(cer: Cerebro, c: Conversa, f: Filtros, ja: set[int], fora: set[int], base: dict) -> ResultadoFerramenta:
    """A busca não achou nada novo. Na ordem: só existe o que ele já tem; quer semimobiliado e há "só climatizado"
    (pergunta se interessa: Tel, 02/10, uma vez); há coisa abaixo da faixa do valor (pergunta se ele quer ver);
    ou não há nada mesmo ("Quer tentar outro bairro ou outro valor?")."""
    base = _vazia_ou_de_antes(cer, c, f, ja, base)
    if c.filtro_mobilia == "semi" and c.ultima_acao != "pergunta_so_climatizado":
        if any(_aqui_e_perto(cer, f, fora, True)):
            return ResultadoFerramenta("buscar", "", dados={**base, "so_climatizado": True})
    # Tel, 06/10, rodada 8: fora da faixa ela NÃO oferece ("se não tiver, só avisar que não tem, sem problema").
    # A oferta do que há abaixo só volta se `oferecer_abaixo_da_faixa` for ligado em config/filtros.yaml.
    oferece = cfg("filtros").get("oferecer_abaixo_da_faixa", False) and base["nada"] and not f.sem_piso
    abaixo = _abaixo_da_faixa(cer, c, f, fora) if oferece else {}
    return ResultadoFerramenta("buscar", "", valores=abaixo.pop("valores_do_mais_barato", frozenset()),
                               dados={**base, **abaixo, "vazio": True})

