acoes/card_perguntas.py:tem_elevador.codigo:
def tem_elevador(fi: dict[str, Any]) -> bool:
    """O cadastro, a ficha do condomínio ou o anúncio dizem que tem elevador."""
    car = [normal(str(x)) for x in (fi.get("car_condominio") or []) + (fi.get("car_imovel") or [])]
    if any("elevador" in c for c in car):
        return True
    if normal(_campo(fi, "elevador") or "").startswith("sim"):
        return True
    n = re.sub(r"\D", "", _campo(fi, "elevadores") or "")
    return bool(n) and int(n) > 0

acoes/card_perguntas.py:_andares.codigo:
def _andares(fi: dict[str, Any]) -> int | None:
    n = re.sub(r"\D", "", _campo(fi, "andares do predio") or _campo(fi, "andares") or "")
    return int(n) if n else None

acoes/card_perguntas.py:altura.codigo:
def altura(andar: int, andares: int | None) -> str:
    """baixo, médio ou alto: pelo terço do prédio quando se sabe quantos andares ele tem."""
    if andares and andares >= andar:
        return "baixo" if andar <= andares / 3 else "médio" if andar <= 2 * andares / 3 else "alto"
    return "baixo" if andar <= BAIXO_ATE else "médio" if andar <= MEDIO_ATE else "alto"

acoes/card_perguntas.py:andar_no_card.codigo:
def andar_no_card(i: Imovel, fi: dict[str, Any] | None) -> str | None:
    """"3 lances de escada" | "Andar alto, com elevador" | "Térreo" | None."""
    if not fi or i.tipo in SEM_ANDAR:
        return None
    lances = lances_de_escada(fi)
    if lances:
        return "1 lance de escada" if lances == "1" else f"{lances} lances de escada"
    a = andar_do_imovel(fi)
    if a and "terr" in normal(a):
        return "Térreo"
    if rf.faixa_do_andar(a):   # Tel, 23/10: o corretor disse só "andar alto"
        return f"Andar {rf.faixa_do_andar(a)}" + (", com elevador" if tem_elevador(fi) else "")
    if not (a and a.isdigit() and int(a) > 0 and tem_elevador(fi)):
        return None
    return f"Andar {altura(int(a), _andares(fi))}, com elevador"

acoes/card_perguntas.py:_item.codigo:
def _item(x: str) -> str:
    """"Taxa de Gás" -> "gás"; "Água" -> "água"."""
    return re.sub(r"^taxas? d[eao]s?\s+", "", x.strip(), flags=re.I).lower()

acoes/duvida.py:rotulos.codigo:
def rotulos(faltou: list[str]) -> str | None:
    """["andar", "varanda"] -> "o andar e a varanda". Vazio = a pergunta inteira ficou sem resposta."""
    nomes = list(dict.fromkeys(ROTULO.get(f, f) for f in faltou if f and f not in NAO_ROTULA))
    if not nomes:
        return None
    return nomes[0] if len(nomes) == 1 else ", ".join(nomes[:-1]) + " e " + nomes[-1]

acoes/duvida.py:pendencia.codigo:
def pendencia(conv: Conversa, codigo: int | None, pergunta: str, faltou: list[str]) -> tuple[Conversa, Acao]:
    """O que ninguém soube responder vai ao Tel e fica registrado; a conversa segue sem pausa."""
    nomes = rotulos(faltou)
    nova = conv.com(estado="APRESENTADO", foco_codigo=codigo) if codigo else conv
    return nova, Acao("pendencia", codigo=codigo, pergunta=pergunta, template="nao_sei_parte" if nomes else "nao_sei",
                      dados={"faltou": nomes, "faltou_lista": list(faltou)})

acoes/duvida.py:luna.codigo:
def luna(cer: Cerebro, a: Acao, modelos, tr: Trace, sugestao: str | None = None) -> ResultadoFerramenta | None:
    """A Luna responde com a ficha na mão, toda ou em parte (o que faltou vem em `dados["faltou"]`), ou nada.
    Com `sugestao` (a frase pronta da ficha), ela a usa só como apoio."""
    i = cer.catalogo.get(a.codigo)
    if modelos is None or i is None or i.e_parceiro:
        return None
    ficha = ficha_completa(i, cer.ficha(a.codigo))
    with tr.medir("acoes", "responder_duvida", {"codigo": a.codigo, "pergunta": a.pergunta}) as e:
        texto, meta = responder_duvida.responder(modelos, a.pergunta or "", ficha, sugestao)
        e.modelo, e.saida = meta.get("modelo"), {"texto": texto, **meta}
    if texto == responder_duvida.NAO_SEI:
        return None
    numeros = {int(x.replace(".", "")) for x in re.findall(r"\d{1,3}(?:\.\d{3})+|\d+", json.dumps(ficha, default=str))}
    return ResultadoFerramenta("duvida", texto, frozenset({a.codigo}), valores=valores(i) | frozenset(numeros),
                               dados={"faltou": list(meta.get("faltou") or [])})

acoes/duvida.py:ficha_ou_duvida.codigo:
@no("acoes.responder_sobre_imovel")
def ficha_ou_duvida(cer: Cerebro, conv: Conversa, ev: Evento, a: Acao, res: dict, tr: Trace,
                    modelos) -> tuple[Conversa, Acao]:
    """A ficha responde sozinha o que tem; a Luna, com a ficha na mão, responde o que foi perguntado (a frase da
    ficha é sugestão, não texto fixo: Pedro, 02/10). O que sobrar sem resposta vira pendência."""
    with tr.medir("acoes", "responder_ficha", {"codigo": a.codigo, "pergunta": a.pergunta}) as e:
        r = res["responder_ficha"] = e.saida = responder_ficha(cer, a.codigo, a.pergunta or "")
        outro = _e_o_de_outro_bairro(cer, a, r)
        if outro:       # "Aquele da cidade nova?": não, fica em Flores. Ela mesma responde, sem modelo e sem Tel
            res["responder_ficha"] = e.saida = outro
            return conv, a
    respondeu = bool(r.dados.get("respondeu"))
    d = luna(cer, a, modelos, tr, sugestao=r.texto_pronto if respondeu else None)
    if d:
        res["duvida"] = d
        faltou = d.dados["faltou"]
    else:
        faltou = list(r.dados.get("faltou") or []) if respondeu else ["assunto nao reconhecido"]
    if not faltou and (d or respondeu):
        return conv, a
    if not d and not respondeu:
        conv = replace(conv, foco_codigo=a.codigo)
    return pendencia(conv, a.codigo, a.pergunta or ev.texto, faltou if (d or respondeu) else [])

acoes/enviar_imovel.py:finalidade_de.codigo:
def finalidade_de(i: Imovel, pedida: str | None = None) -> str | None:
    """A finalidade em que o imóvel é mostrado: a da conversa, se ele serve a ela; senão a dele."""
    if pedida == "venda" and i.de_venda:
        return "venda"
    if pedida == "locacao" and i.de_locacao:
        return "locacao"
    return "locacao" if i.de_locacao else "venda" if i.de_venda else None

acoes/enviar_imovel.py:valor_texto.codigo:
def valor_texto(i: Imovel, pedida: str | None = None) -> str:
    fin = finalidade_de(i, pedida)
    v = i.valor_venda if fin == "venda" else i.valor_aluguel
    if not v:
        return "valor sob consulta"
    return reais(v) + ("/mês" if fin == "locacao" else "")

acoes/enviar_imovel.py:taxa_inclusa_no_a.codigo:
def taxa_inclusa_no_aluguel(fi: dict | None) -> bool:
    """O cadastro diz que a taxa de condomínio já está no aluguel (campo "incluso no aluguel")."""
    return "condom" in normal(_campo(fi or {}, "incluso no aluguel") or "")

acoes/enviar_imovel.py:observacao_curta.codigo:
def observacao_curta(i: Imovel) -> str | None:
    """A observação do cadastro numa linha só, até 300 caracteres (Pedro, 11/10: "vai o card com essas informações
    e o texto da observação junto")."""
    o = re.sub(r"\s*\n+\s*", " / ", (i.observacao or "").strip())
    return (o[:297].rstrip() + "…") if len(o) > 300 else (o or None)

acoes/enviar_imovel.py:_antes_do_valor.codigo:
def _antes_do_valor(card: str, novas: list[str]) -> str:
    """Bullets novos no card do anúncio, antes das linhas de valor (ou do código)."""
    if not novas:
        return card
    linhas = card.splitlines()
    onde = next((k for k, ln in enumerate(linhas) if SECAO_DE_VALOR.match(ln) or ln.lower().startswith("código:")),
                len(linhas))
    return "\n".join(linhas[:onde] + [f"• {x}" for x in novas] + linhas[onde:])

acoes/enviar_imovel.py:com_observacao.codigo:
def com_observacao(card: str, i: Imovel) -> str:
    """O card do anúncio (imovel_ficha.card) não tem a observação: entra como bullet antes das linhas de valor."""
    o = observacao_curta(i)
    return card if not o or o.lower() in card.lower() else _antes_do_valor(card, [o])

acoes/enviar_imovel.py:_card_da_ficha.codigo:
def _card_da_ficha(i: Imovel, ficha: dict | None) -> str | None:
    card = (ficha or {}).get("card")
    if not card or f"Código: {i.codigo}" not in card:
        return None
    preco = i.valor_aluguel if i.de_locacao else i.valor_venda
    return card if preco and reais(preco) in card else None

acoes/enviar_imovel.py:so_da_finalidade.codigo:
def so_da_finalidade(card: str, i: Imovel, pedida: str | None) -> str:
    """O card do imóvel que serve à locação E à venda, para quem pediu uma das duas (Tel, 06/10, rodada 5, turno
    13879: pedido de LOCAÇÃO recebeu "Venda: R$ 350.000 • não aceita financiamento"). Sai a linha do outro valor
    com os itens dela (financiamento, permuta); sem finalidade conhecida, ficam os dois."""
    if pedida not in ("locacao", "venda") or not (i.de_locacao and i.de_venda):
        return card
    linhas, fora = [], False
    for linha in card.splitlines():
        secao = SECAO_DE_VALOR.match(linha)
        if secao:
            fora = secao.group(1).lower().startswith("venda") == (pedida == "locacao")
        elif not linha.lstrip().startswith("•"):
            fora = False                 # "Código: ...": a seção do valor acabou
        if not fora and not (pedida == "locacao" and "financiamento" in linha.lower()):
            linhas.append(linha)
    return "\n".join(linhas)

acoes/enviar_imovel.py:card.codigo:
@no("acoes.card")
def card(cer: Cerebro, codigo: int, pedida: str | None = None) -> ResultadoFerramenta:
    i = cer.catalogo.get(codigo)
    if i is None:
        return ResultadoFerramenta("card", "", dados={"recusa": "nao_existe"})
    if i.e_parceiro:
        return ResultadoFerramenta("card", "", dados={"recusa": "parceiro"})
    if not i.no_mercado:
        return fora_do_mercado(cer, i)
    fi = cer.ficha(codigo)
    da_ficha = _card_da_ficha(i, fi)
    texto = (com_perguntas(com_observacao(so_da_finalidade(da_ficha, i, pedida), i), i, fi, pedida) if da_ficha
             else card_do_cadastro(i, pedida, fi))
    return ResultadoFerramenta("card", texto, frozenset({codigo}), valores=valores(i),
                               bairros=frozenset({i.bairro_norm}), dados={"qtd_fotos": i.qtd_fotos})

acoes/enviar_imovel.py:e_condominio.codigo:
def e_condominio(nome_norm: str | None) -> bool:
    """O nome diz QUAL condomínio é? ("casa" e "condominio nao identificado" não dizem.)"""
    return bool(set((nome_norm or "").split()) - NOME_QUE_NAO_E_CONDOMINIO)

acoes/enviar_imovel.py:fotos.codigo:
@no("acoes.fotos")
def fotos(cer: Cerebro, codigo: int) -> ResultadoFerramenta:
    i = cer.catalogo.get(codigo)
    if i is None or i.e_parceiro or not i.no_mercado:
        return ResultadoFerramenta("fotos", "", dados={"recusa": "fora do mercado ou parceiro"})
    urls = cer.fotos(codigo)
    limite = int(cfg("limites").get("max_fotos_por_envio") or 0)
    if limite:
        urls = urls[:limite]
    return ResultadoFerramenta("fotos", "", frozenset({codigo}), fotos=tuple((codigo, u) for u in urls),
                               dados={"qtd": len(urls)})

