def _qual(cer: Cerebro, candidatos: tuple[int, ...], finalidade: str | None) -> ResultadoFerramenta:
    ims = [i for c in candidatos if (i := cer.catalogo.get(c)) and i.no_mercado and not i.e_parceiro][:5]
    return ResultadoFerramenta("qual", "", frozenset(i.codigo for i in ims),
                               valores=frozenset().union(*(valores(i) for i in ims)) if ims else frozenset(),
                               dados={"candidatos": [linha(i, finalidade) for i in ims]})

acoes/executar.py:ferramentas.codigo:
@no("acoes.ferramentas")
def ferramentas(cer: Cerebro, conv: Conversa, ev: Evento, a: Acao, tr: Trace,
                modelos=None, juiz=None) -> tuple[Conversa, Acao, dict]:
    """Chama o que a ação precisa. Pode trocar a ação quando o resultado pede (busca com
    1 resultado vira apresentar; imóvel sem prova de pedido vira "É este?"; imóvel já mandado
    vira aviso; dúvida sem resposta vira pendência)."""
    res: dict[str, ResultadoFerramenta] = {}
    conv, a = preparo.antes_de_tudo(cer, conv, ev, a, res)
    if a.tipo == "buscar":
        with tr.medir("acoes", "buscar", conv) as e:
            res["buscar"] = e.saida = buscar(cer, conv, bool(a.dados.get("sem_piso")), ev.agora,
                                             *memoria.para_a_busca(ev.ja_dito, ev.texto))
        conv, a = preparo.depois_da_busca(cer, conv, ev, a, res["buscar"])
    if a.tipo == "template" and a.template == "qual_da_lista" and "codigos" in a.dados:
        conv, a = preparo.mesma_lista(cer, conv, ev)               # "manda esse aí" depois da lista: qual deles?
    # já saiu para essa pessoa: "já te enviei, tem interesse?" (vem antes do portão: do imóvel que ele já tem, a
    # pergunta certa é essa, e o sim dele vale como a prova do pedido)
    a = ja_enviei.aplicar(cer, conv, a, res, ev.agora, ev.texto)
    conv, a = portao.aplicar(cer, conv, ev, a, tr, juiz)    # é o imóvel que ele pediu? senão, "É este imóvel?"
    if a.tipo == "apresentar":
        with tr.medir("acoes", "card", a.codigo) as e:
            res["card"] = e.saida = card(cer, a.codigo, conv.filtro_finalidade)
        if res["card"].dados.get("recusa"):
            conv, a = maquina.escalar(conv, ev, f"imóvel {a.codigo}: {res['card'].dados['recusa']}")
    if a.tipo in ("apresentar", "fotos") and (a.com_fotos or a.tipo == "fotos"):
        _fotos(cer, a, res, tr)
    multiplos.ferramenta(cer, conv, a, res, tr)       # o imóvel que vai na frente do pedido novo (12/10)
    if a.tipo == "responder_varios":        # "os dois são mobiliados né": a ficha de cada um, ou "qual deles?"
        conv, a = varios.responder(cer, conv, a, res)
    if a.tipo == "perguntar_qual":
        res["qual"] = _qual(cer, a.candidatos, conv.filtro_finalidade)
    if a.tipo == "responder_ficha":
        conv, a = duvida.ficha_ou_duvida(cer, conv, ev, a, res, tr, modelos)
    if a.tipo == "apresentar_varios":
        conv, a = varios.preparar(cer, conv, ev, a, res, tr)
    return conv, a, res

acoes/executar.py:_escalar.codigo:
def _escalar(a: Acao, b: Base) -> list[Peca]:
    if a.template == "recebi_midia":
        aviso = _tel("aviso_tel_midia", b, codigo=b.conversa.foco_codigo, texto=b.texto_dele[:200] or None, **a.dados)
    elif a.dados.get("aviso"):
        aviso = _tel(a.dados["aviso"], b, codigo=a.codigo or b.conversa.foco_codigo, texto=b.texto_dele[:200],
                     **{k: v for k, v in a.dados.items() if k != "aviso"})
    else:
        aviso = _tel("aviso_tel_duvida", b, codigo=a.codigo or b.conversa.foco_codigo or "?",
                     pergunta=(a.pergunta or b.texto_dele)[:200])
    return [_txt(a.template or "escalado", b), aviso, *grupo.aviso(a, b)]   # 24/10: e ao grupo da equipe

acoes/executar.py:_fotos.codigo:
def _fotos(cer: Cerebro, a: Acao, res: dict, tr: Trace) -> None:
    with tr.medir("acoes", "fotos", a.codigo) as e:
        res["fotos"] = e.saida = fotos(cer, a.codigo)
    if a.tipo == "fotos" and a.pergunta:        # "qual andar? manda as fotos": a ficha responde junto (12/10)
        with tr.medir("acoes", "responder_ficha", a.codigo) as e:
            res["responder_ficha"] = e.saida = responder_ficha(cer, a.codigo, a.pergunta)

acoes/executar.py:_resposta.codigo:
def _resposta(res: dict, a: Acao) -> list[Peca]:
    if res.get("duvida"):
        return [Peca("texto", texto=res["duvida"].texto_pronto, codigo=a.codigo, motivo="resposta_duvida_luna")]
    r = res.get("responder_ficha")
    if not r or not r.texto_pronto:
        return []
    return [Peca("texto", texto=r.texto_pronto, codigo=a.codigo, motivo="resposta_ficha")]

acoes/executar.py:pecas.codigo:
@no("composicao.pecas")
def pecas(a: Acao, res: dict[str, ResultadoFerramenta], b: Base) -> list[Peca]:
    """Da ação e do que ela buscou, as mensagens na ordem em que saem."""
    aviso = res.get("aviso")
    antes = [Peca("texto", texto=aviso.texto_pronto, motivo="condominio_sem_oferta")] if aviso else []
    return antes + multiplos.pecas(a, res) + _pecas(a, res, b)

acoes/executar.py:_pecas.codigo:
def _pecas(a: Acao, res: dict[str, ResultadoFerramenta], b: Base) -> list[Peca]:      # noqa: C901
    t = a.tipo
    if t == "fora_da_lista":
        return [_tel("aviso_tel_fora_da_lista", b, texto=b.texto_dele[:200])] if a.dados.get("perguntou") else []
    if t == "template":
        dados = {**a.dados, **({"opcoes": " ou ".join(a.dados["candidatos"])} if "candidatos" in a.dados else {})}
        return [_txt(a.template, b, codigo=dados.pop("codigo", a.codigo), **dados)]
    if t == "perguntar_filtro":
        return _filtro(a, b)
    if t == "buscar":
        d = res["buscar"].dados
        # o pedido mudou e o que cabe ele já tem de hoje: "Está perguntando para outro cliente, certo?" (10/10)
        outro = [_txt("outro_cliente", b)] if a.dados.get("pergunta_outro_cliente") else []
        if d.get("vazio"):
            return [_txt("so_o_de_hoje", b, **d)] + outro if outro else [_txt("lista_vazia", b, **d)]
        # os bairros ao redor vão em mensagem separada (Pedro, 02/10); a pergunta fecha a última
        ao_redor = [_txt("lista_ao_redor", b, **d)] if d.get("tem_ao_redor") else []
        return [_txt("lista", b, **d, fecha=not ao_redor)] + ao_redor + outro
    if t == "apresentar":
        return _apresentar(a, res, b)
    if t == "apresentar_varios":
        itens = varios.pecas(a, res)
        if a.dados.get("opcoes"):           # um dos nomes serve a dois da lista: os certos, e "qual deles?" do resto
            return itens + [_txt("qual_da_lista", b, opcoes=a.dados["opcoes"])]
        if a.dados.get("da_busca"):         # a busca achou 2 ou 3: os cards completos no lugar da lista (12/10)
            abre = _txt("achei_poucos", b, qtd_texto=a.dados.get("qtd_texto"), onde=a.dados.get("onde"))
            return [abre] + itens + [_txt("depois_dos_cards", b)]
        if a.dados.get("so_cards"):         # mais de 2 de uma vez: só os cards, e as fotos quando ele pedir
            return itens + [_txt("depois_dos_cards", b)]
        fecho = a.sugerir_visita and any(i.tipo == "imagem" for i in itens)
        return itens + ([_txt("depois_dos_varios", b)] if fecho else [])
    if t == "fotos":
        return _fotos_e_fecho(a, res, b)
    if t == "perguntar_qual":
        cands = res["qual"].dados["candidatos"] if res.get("qual") else []
        busca = bool(a.dados.get("oferta"))      # a busca deste turno achou um só: é oferta, não "É este?"
        return [_txt("confirmar_imovel" if len(cands) == 1 else "qual_deles", b, candidatos=cands,
                     da_busca=busca, citado=not busca)]
    if t == "responder_ficha":
        return _resposta(res, a)
    if t == "responder_varios":
        return [Peca("texto", texto=res["responder_varios"].texto_pronto, motivo="resposta_ficha")]
    if t == "pendencia":        # o que se sabe, o "vou precisar confirmar" do resto e a pergunta ao Tel
        return _resposta(res, a) + [
            _txt(a.template, b, faltou=a.dados.get("faltou")),
            _tel("aviso_tel_pendencia", b, codigo=a.codigo or "?", pergunta=(a.pergunta or b.texto_dele)[:300],
                 faltou=a.dados.get("faltou"))]
    if t == "visita_pedida":
        return _da_visita(a, b)
    if t == "escalar":
        return _escalar(a, b)
    return []          # silencio, fora_do_escopo

