def compor_validado(a: Acao, res: dict, b: Base, perm: Permitido,
                    tr: Trace) -> tuple[list[Peca], Veredito, str | None]:
    """(peças, veredito, se vetou: None | escala | escala_duvida | silencio). `regenera` não escala."""
    isentos = ISENTOS.get(a.template or "", frozenset())
    itens = pecas(a, res, b)
    v = validar(itens, perm, isentos)
    tr.registrar("validador", "validar", [i.texto for i in itens if i.texto], v.vetos)
    if v.passou:
        return itens, v, None
    if any(i.motivo == "resposta_duvida_luna" for i in itens):
        ficha = res.get("responder_ficha")
        if ficha and ficha.dados.get("respondeu"):       # o texto da Luna caiu: vale a frase da ficha
            res.pop("duvida", None)
            return compor_validado(a, res, b, perm, tr)
        return [], v, "escala_duvida"
    acao = v.vetos[0][2]
    if acao in ("silencio", "escala"):
        return [], v, acao
    limpos = saneado(itens, perm, v, isentos)        # veto só de forma: tira o emoji e a resposta vale
    return (limpos, Veredito(), None) if limpos else ([], v, "escala_duvida")

