cerebro/catalogo.py:preco.codigo:
def preco(i: Imovel, f: Filtros) -> float | None:
    """O preço do imóvel na finalidade da busca. Sem finalidade ("alugar ou comprar", "tanto faz"), o preço que
    cabe na faixa do teto: em 03/10 um corretor com "os dois" pediu apartamento até 450 mil e a busca comparou
    o teto só com o ALUGUEL -- imóvel à venda nunca aparecia."""
    if f.finalidade == "venda":
        return i.valor_venda
    if f.finalidade == "locacao" or not (f.teto or f.piso):
        return i.valor_aluguel
    if na_faixa(i.valor_aluguel, f.teto, piso=f.piso):
        return i.valor_aluguel
    return i.valor_venda if na_faixa(i.valor_venda, f.teto, piso=f.piso) else (i.valor_aluguel or i.valor_venda)

cerebro/catalogo.py:_finalidade_serve.codigo:
def _finalidade_serve(i: Imovel, fin: str | None) -> bool:
    if fin == "locacao":
        return i.de_locacao
    if fin == "venda":
        return i.de_venda
    return True

cerebro/catalogo.py:_tipo_serve.codigo:
def _tipo_serve(i: Imovel, tipo: str | None) -> bool:
    if not tipo:
        return True
    if tipo in PELO_NOME:
        return _e_do_nome(i, tipo)
    if tipo == "comercial":                # "algo comercial": sala, loja, prédio ou galpão
        return i.tipo in ("sala", "loja") or _e_do_nome(i, "predio") or _e_do_nome(i, "galpao")
    if tipo == "tanto_faz":                # "casa ou apartamento, tanto faz" é moradia: sala e loja não entram
        return i.tipo in TIPOS_MORADIA
    if tipo == "casa":                     # "casa" cobre a de condomínio; o contrário não
        return i.tipo in TIPOS_CASA
    return i.tipo == tipo

cerebro/catalogo.py:_tipos_servem.codigo:
def _tipos_servem(i: Imovel, f: Filtros) -> bool:
    """`tipos` (vários pedidos de uma vez) manda em `tipo`."""
    return any(_tipo_serve(i, t) for t in f.tipos) if f.tipos else _tipo_serve(i, f.tipo)

cerebro/catalogo.py:tipos_pedidos.codigo:
def tipos_pedidos(f: Filtros, tipos: tuple[str, ...]) -> tuple[str, ...]:
    """Os tipos que ele pediu e que o filtro gravado NÃO cobre: "tanto faz" é MORADIA (casa ou apartamento),
    então quem pede sala, loja, terreno, prédio ou galpão junto precisa que a busca procure esses tipos.

    20/10/2026, ...9091: "Nay, vocês tem alguma oportunidade para investimento? Sala comercial ou terreno
    apenas" recebeu "De sala nem terreno eu não tenho nesse perfil agora" seguido de cinco APARTAMENTOS de
    3 quartos. Quatro minutos depois, com o tipo já gravado como comercial, a mesma busca achou a sala 1315
    (R$ 700 mil) e o prédio 3971 (R$ 1,285 milhão): ela tinha os dois e disse que não tinha."""
    if f.tipo not in (None, "tanto_faz") or not tipos:
        return ()
    return tuple(dict.fromkeys(tipos)) if any(t not in TIPOS_MORADIA for t in tipos) else ()

cerebro/catalogo.py:serve.codigo:
def serve(i: Imovel, f: Filtros) -> bool:
    if not _finalidade_serve(i, f.finalidade) or not _tipos_servem(i, f):
        return False
    p = preco(i, f)
    if (f.teto or f.piso) and not na_faixa(p, f.teto, f.sem_piso and f.finalidade in ("locacao", "venda"), f.piso):
        return False
    if f.bairros and i.bairro_norm not in f.bairros:
        return False
    if f.quartos and (i.quartos or 0) < f.quartos:
        return False
    if f.mobilia in ("mobiliado", "semi") and i.mobilia != f.mobilia:
        return False
    return True

