def bairro_citado(self, texto: str, fora: tuple[str, ...] = ()) -> str | None:
    """O nome (do cadastro) do bairro que aparece escrito no texto, o mais comprido primeiro. `fora`: formas
    normais que não contam (o bairro do próprio imóvel, o nome do condomínio dele)."""
    t = f" {normal(texto)} "
    for forma in sorted(self._conhecidos, key=len, reverse=True):
        if len(forma) >= 5 and f" {forma} " in t and not any(forma in f for f in fora if f):
            return self._conhecidos[forma]
    return None

