def ja_enviado(self, chave: str, codigo: int, horas: int, ate: datetime | None = None,
               desde: datetime | None = None) -> Enviado | None:
    """`enviados`: "chave:codigo" -> a data (card e fotos saíram juntos) ou {"card": data, "fotos": data}.
    `na_fila` no dicionário: já saiu da decisão mas está esperando na caixa, nada chegou à pessoa."""
    v = self._d.get("enviados", {}).get(f"{chave}:{codigo}")
    if isinstance(v, str):
        v = {"card": v, "fotos": v}
    dia = {k: datetime.fromisoformat(v[k]) if v and v.get(k) else None for k in ("card", "fotos")}
    dia = {k: q if q and (ate is None or q < ate) and (desde is None or q >= desde) else None
           for k, q in dia.items()}
    if dia["card"] is None and dia["fotos"] is None:
        return None
    return Enviado(card=dia["card"], fotos=dia["fotos"], vezes=int(v.get("vezes", 1)),
                   na_fila=bool(v.get("na_fila", False)))

