    """Testes e replay: o card ou as fotos que saíram neste turno passam a contar nos próximos."""
    e = self._d.setdefault("enviados", {})
    v = e.get(f"{chave}:{codigo}") or {"vezes": 0}
    if isinstance(v, str):
        v = {"card": v, "fotos": v, "vezes": 1}
    for peca, campo in (("card", "card"), ("foto", "fotos")):
        if peca in o_que:
            v[campo] = quando.isoformat()
    e[f"{chave}:{codigo}"] = {**v, "vezes": int(v.get("vezes", 0)) + 1}

