def __init__(self, linhas: list[dict[str, Any]]) -> None:
    self._nome: dict[str, str] = {}             # chave (o nome da planilha, normal) -> o nome como está nela
    self._recente: dict[str, bool] = {}
    self._ano: dict[str, int] = {}              # o ano de lançamento (ficha do condomínio, nayia 436)
    self._bairros: dict[str, tuple[str, ...]] = {}
    self._lista: dict[str, dict[str, tuple[int, bool]]] = {}  # chave -> {próximo: (posição, mesmo bairro)}
    self._de: dict[str, str] = {}               # qualquer jeito de escrever (normal) -> chave
    for r in linhas:
        k = normal(r["nome"])
        self._nome[k], self._recente[k] = r["nome"], bool(r.get("recente"))
        self._bairros[k] = _bairros(r.get("bairro"))
        self._ano[k] = int(r.get("ano") or 0)
        for n in (r["nome"], *(r.get("normas") or ())):
            self._de.setdefault(normal(n), k)
    for r in linhas:
        k = normal(r["nome"])
        self._lista[k] = {normal(p): (pos, _mesmo_bairro(self._bairros[k], self._bairros.get(normal(p), ())))
                          for pos, p in enumerate(r.get("proximos") or ()) if normal(p) in self._nome}
    self._para_resolver = {n: [0] for n in self._de}

