def _lancamento(self, meu: str | None) -> int:
    """Entre os recentes, "segundo a ordem de lançamento" (Pedro, 20/10): o mais novo primeiro; sem ano, depois."""
    return -self._ano.get(meu or "", 0) if self._recente.get(meu or "") else 0

cerebro/proximos.py:Proximos._posto.codigo:
def _posto(self, chave: str | None, novo: bool, i: Imovel) -> tuple[int, int, int]:
    meu = self.de(i)
    if chave and meu == chave:
        return (0, 0, 0)
    if chave and meu in self._lista.get(chave, {}):
        _, mesmo = self._lista[chave][meu]
        classe = 1 if self._recente.get(meu) == self._recente.get(chave) else 2
        return (classe, 0 if mesmo else 1, self._lancamento(meu))
    if novo and not chave:
        return (1 if self._recente.get(meu or "") else 3, 0, self._lancamento(meu))
    return (3, 0, 0)

