@lru_cache(maxsize=1)
def _por_nome() -> dict[str, str]:
    """forma do nome -> bairro. "Conjunto Japiim I e II" também atende por "japiim i", "japiim ii" e "japiim 2"."""
    saida = {}
    for c in conjuntos():
        forma = _forma(c["nome"])
        saida[forma] = c["bairro"]
        m = re.fullmatch(r"(.+) i e ii", forma)
        if m:
            saida |= {f"{m.group(1)} {n}": c["bairro"] for n in ("i", "ii", "1", "2")}
    return saida

