cerebro/regioes.py:_por_avenida.codigo:
@lru_cache(maxsize=1)
def _por_avenida() -> dict[str, tuple[str, ...]]:
    """núcleo do nome da avenida -> os bairros dos conjuntos que ficam nela (e os das avenidas soltas)."""
    saida: dict[str, list[str]] = {}
    for c in conjuntos():
        for av in c["avenidas"]:
            saida.setdefault(_da_avenida(av), []).append(c["bairro"])
    for a in avenidas_soltas():
        saida.setdefault(_da_avenida(a["nome"]), []).extend(a["bairros"])
    return {k: tuple(dict.fromkeys(v)) for k, v in saida.items()}

