classificador/atalhos.py:_filtro.codigo:
def _filtro(conversa: Conversa, texto: str, resolver_bairro) -> dict:
    """A resposta curta à pergunta de filtro do estado atual, se for só isso."""
    t = normal(texto)
    est = conversa.estado
    if est == "FILTRO_TIPO" and len(t.split()) <= 20 and (OS_DOIS.search(t) or frases.OS_DOIS_TIPOS.search(t)):
        # "Os 2. Pq ele está fechando uma casa, mas não descarta apto" (13855): os dois tipos servem. Vem antes
        # do limite de palavras e de "casa" sozinha, que gravaria um tipo só.
        return {"tipo": "tanto_faz"}
    if not _curta(t):
        return {}
    if est == "FILTRO_FINALIDADE":
        v = frases.finalidade_dita(texto) or ("tanto_faz" if TANTO_FAZ.search(t) else None)
        return {"finalidade": v} if v else {}
    if est == "FILTRO_TIPO":
        v = _primeiro(TIPOS, t) or ("tanto_faz" if TANTO_FAZ.search(t) else None)
        return {"tipo": v} if v else {}
    if est == "FILTRO_TETO":
        if TANTO_FAZ.search(t) or SEM_VALOR.search(t):
            return {"teto_tanto_faz": True}
        return _valor_dito(texto, conversa)
    if est == "FILTRO_MOBILIA":
        v = "tanto_faz" if TANTO_FAZ.search(t) or AMBOS.search(t) else mobilia_dita(t)
        return {"mobilia": v} if v else {}
    if est == "FILTRO_CLIMATIZADO":      # "tenho só climatizado, interessa?": sim busca os climatizados
        return {"mobilia": "climatizado"} if SIM.search(t) else {"mobilia": "semi"} if NAO.search(t) else {}
    return _regiao_ou_valor(conversa, texto, t, resolver_bairro)

classificador/atalhos.py:_valor_dito.codigo:
def _valor_dito(texto: str, conversa: Conversa) -> dict:
    """O valor da resposta, com a família que ele disse ("até 6 mil", "entre 2 e 3", "a partir de 5 mil"; ou só o
    número): classificador/valores.py."""
    v = valores.ler(texto, conversa.filtro_finalidade, solto=True) if valores.so_valor(texto) else None
    if not v:
        return {}
    return {k: x for k, x in (("teto", v.teto), ("piso", v.piso)) if x}

classificador/atalhos.py:_regiao_ou_valo.codigo:
def _regiao_ou_valor(conversa: Conversa, texto: str, t: str, resolver_bairro) -> dict:
    """A resposta a "Qual região?" e a "Quer tentar outro bairro ou outro valor?" (06/10: aí o bairro ou o valor
    sozinho é a resposta, sem modelo)."""
    na_regiao = conversa.estado == "FILTRO_REGIAO"
    outro = conversa.ultima_acao in ("lista_vazia", "qual_bairro_ou_valor", "oferta_abaixo")
    if not (na_regiao or outro):
        return {}
    if na_regiao and TANTO_FAZ.search(t):
        return {"regiao_tanto_faz": True}
    v = _valor_dito(texto, conversa) if outro else {}
    if v:
        return v
    r = resolver_bairro(texto)
    certo = r.via in ("exato", "apelido", "zona", "conjunto", "avenida", "parecido")
    return {"regiao": r.bairros} if r.bairros and certo else {}

classificador/atalhos.py:mobilia_dita.codigo:
def mobilia_dita(t: str) -> str | None:
    """A mobília que ele disse, no texto já normalizado."""
    if SEMI.search(t):
        return "semi"
    if SO_AR.search(t):
        return "climatizado"
    if SEM_MOVEIS.search(t):
        return "climatizado" if TEM_AR.search(t) else "nao"
    if "mobiliad" in t:
        return "mobiliado"
    return "climatizado" if TEM_AR.search(t) else None

classificador/atalhos.py:_outro_valor.codigo:
def _outro_valor(texto: str, conversa: Conversa) -> float | None:
    """O valor que ele disse querer no lugar do imóvel em jogo ("essa é 9 mil, quero de 7" -> 7000). Com mais de
    um ("Não tem de 6? Máximo 7 mil?"), vale o maior: é até onde ele vai."""
    valores = []
    for m in OUTRO_VALOR.finditer(sem_acento(texto).lower()):
        numero = float(m.group(1).replace(".", "").replace(",", ".")) if "," in m.group(1) else float(
            m.group(1).replace(".", ""))
        valores.append(numero * 1000 if m.group(2) else teto_na_escala(numero, conversa.filtro_finalidade))
    return max((v for v in valores if v), default=None)

classificador/atalhos.py:_aceitou_recome.codigo:
def _aceitou_recomecar(t: str, conversa: Conversa, ctx: Contexto, agora: datetime | None) -> bool:
    """Ela ofereceu procurar outro (o imóvel saiu do mercado, ou o condomínio não tem oferta) e ele disse que sim."""
    ofereceu = conversa.ultima_acao in ("indisponivel", "condominio_sem_oferta")
    return (ofereceu and prazos.gatilho_vale(conversa, agora) and _curta(t) and bool(SIM.search(t))
            and not ctx.literais)

classificador/atalhos.py:decidir.codigo:
@no("entendimento.atalhos")
def decidir(texto: str, conversa: Conversa, ctx: Contexto, resolver_bairro,      # noqa: C901
            lista: tuple[int, ...] = (), agora: datetime | None = None, parecido: dict | None = None) -> Pre:
    t = normal(texto)
    if not t:
        return Pre("vazio")
    # o que a frase já diz sozinha: despedida, "manda o que tem", anúncio, visita com dia e hora... (sinais.py)
    sinal = sinais.decidir(texto, conversa, ctx, agora)
    if sinal:
        return Pre(sinal[0], dados=sinal[1])
    # O FLUXO RECOMEÇA (Pedro, 05/10: "o corretor terminou com sim, ela tem que voltar a refazer o fluxo ... já
    # que o fluxo inicial não deu em um disponível"). Ela disse "o 5720 não está mais disponível, quer que eu
    # procure outro parecido?" (ou "no condomínio X não tenho, aceita outro?") e ele respondeu que sim: a busca
    # parte do imóvel que saiu (finalidade, tipo, bairro e valor dele) e segue perguntando o que faltar. Antes o
    # "Sim" era cortesia e ela ficava calada.
    if _aceitou_recomecar(t, conversa, ctx, agora):
        return Pre("filtro_direto", dict(parecido or {}), {"recomeca": True})
    direto = _filtro(conversa, texto, resolver_bairro)
    if direto.get("teto") and ctx.literais and conversa.estado != "FILTRO_TETO":
        direto = {}         # fora da pergunta do valor, o número que é código de imóvel é o imóvel
    if direto:
        return Pre("filtro_direto", direto)
    if AGRADECE.match(t):
        return Pre("cortesia_agradece")
    # MARCOU O CARD (do grupo ou nosso). O corretor do 3878 marcou o post do 5765 em 02/10 e escreveu "Boa noite
    # mana me envia por gentileza": recebeu "não entendi"; marcou de novo com "Bom dia" e recebeu só "Bom dia!".
    # O imóvel estava resolvido nos dois turnos. Marcar o card é falar DELE.
    marcou = bool(ctx.codigo) and ctx.origem == "citacao"
    vale = prazos.gatilho_vale(conversa, agora)
    # "essa é 9 mil, quero de 7" (turno 944): em cima do card marcado, ou logo depois de ela mandar o card
    logo_depois = (bool(ctx.codigo) and ctx.origem in ("foco", "lista") and vale
                   and conversa.ultima_acao in ("card", "fotos", "status", "ja_mandei", "confirmar_imovel"))
    if (marcou or logo_depois) and (valor := _outro_valor(texto, conversa)):
        return Pre("rejeitar_com_teto", {"teto": valor})
    if SAUDA.match(t):
        # só cumprimentou em cima do card: como o card colado sem pedido, a situação e a oferta do card e das fotos
        return Pre("so_codigo", dados={"fotos": False, "status": False, "manda": False, "marcou": True}) \
            if marcou else Pre("cortesia_saudacao")
    composto = frases.segundo_pedido(texto)        # envio + pedido novo: vai ao modelo (estado/multiplos.py)
    if marcou and pediu_envio(t) and not PERGUNTA.search(texto.lower()) and not OUTROS.search(t) and not composto:
        # "me envia por gentileza", "manda pra mim mana": o pedido do imóvel marcado, com as palavras que sobrarem
        return Pre("so_codigo", dados={"fotos": pediu_fotos(texto), "status": pediu_status(texto), "manda": True})
    varios = _de_varios(texto, t, ctx, lista, vale)     # mais de um imóvel na mesma mensagem
    if varios:
        return varios
    trivial = resto_trivial(texto)
    if ctx.candidatos and trivial:
        return Pre("qual")
    # ela mandou uma LISTA e ele respondeu "manda", "esse", "envia" sem dizer qual: pergunta qual deles. Antes
    # o foco de outro pedido respondia por ele, ou a busca devolvia a mesma lista.
    depois_da_lista = conversa.ultima_acao in ("buscar", "qual_da_lista", "perguntar_qual", "varios")
    escolheu = ctx.origem in ("lista", "literal", "citacao", "card")
    if lista and depois_da_lista and not escolheu and trivial and (MANDA.search(t) or ESSE.search(t)) and vale:
        return Pre("qual_da_lista", dados={"codigos": list(lista)})
    return _do_imovel(texto, t, conversa, ctx, trivial, vale) if ctx.codigo and not composto else Pre()

classificador/atalhos.py:_eles.codigo:
def _eles(texto: str, lista: tuple[int, ...], do_lugar: tuple[int, ...], maximo: int) -> tuple[int, ...]:
    """De quais imóveis ele fala com "os dois", "todos", "ambos": a lista inteira, se a conta fecha; senão os da
    lista que ficam no lugar que ele pediu (13767: dois na Ponta Negra e um do bairro vizinho, "mande os dois")."""
    return next((g for g in (lista, do_lugar) if 2 <= len(g) <= maximo and frases.conta_fecha(texto, len(g))), ())

classificador/atalhos.py:_de_varios.codigo:
def _de_varios(texto: str, t: str, ctx: Contexto, lista: tuple[int, ...], vale: bool) -> Pre | None:
    """Mais de um imóvel na mesma mensagem (Tel, 06/10 e rodada 9 de 07/10): vão TODOS, o card de cada um (e as
    fotos, até `fotos_com_varios_ate`). Vários códigos digitados; vários nomes da lista; "os dois", "todos", "pode
    mandar" depois da lista; e a pergunta sobre eles ("os dois são mobiliados né"). Nunca refaz a busca."""
    maximo = int(cfg("limites").get("max_imoveis_de_uma_vez", 5))
    digitados = ctx.literais if ctx.origem == "literal" and not ctx.card_colado and not ctx.codigo else ()
    if len(digitados) > 1 and "?" not in texto:     # "Cód 2392 ⏎ 9004 ⏎ E o código 3450" (13707)
        return Pre("todos_da_lista", dados={"codigos": list(digitados)}) if len(digitados) <= maximo else Pre("qual")
    if ctx.varios and "?" not in texto:    # "Me vê o Ibza e o do Adrianópolis" (13698); pergunta não pede card
        return Pre("todos_da_lista", dados={"codigos": list(ctx.varios), "falta_escolher": list(ctx.candidatos)})
    apontou = ctx.origem in ("lista", "literal", "citacao", "card") or ESSE.search(t)
    if not lista or apontou or not vale:
        return None
    if frases.sobre_eles(texto):                    # "Pela descrição os dois são mobiliados né" (13768)
        eles = _eles(texto, lista, ctx.do_lugar, maximo)
        return Pre("pergunta_dos_varios", dados={"codigos": list(eles)}) if eles else None
    pede = frases.pede_todos(texto)
    eles = _eles(texto, lista, ctx.do_lugar, maximo) if pede else ()
    if not eles and 2 <= len(lista) <= maximo and frases.fotos_de_todos(texto):
        eles = lista
    if eles:
        return Pre("todos_da_lista", dados={"codigos": list(eles)})
    # "me envia os dois" com três na frente: ela pergunta quais, com os códigos; a busca não se refaz (13710)
    return Pre("qual_da_lista", dados={"codigos": list(lista)}) if pede and frases.diz_quantos(texto) else None

classificador/atalhos.py:_do_imovel.codigo:
def _do_imovel(texto: str, t: str, conversa: Conversa, ctx: Contexto, trivial: bool, vale: bool = True) -> Pre:
    """Há um imóvel em jogo (escolhido da lista, escrito, citado ou o de antes): o que ele quer dele?
    `vale`: o que ela fez por último ainda está dentro do prazo do gatilho (estado/prazos.py)."""
    # ele escolheu pelo nome ou pela ordem uma opção da lista que ela acabou de mandar ("manda o Milano"):
    # é pedido do imóvel, sem modelo. Pergunta sobre a opção ("o Milano tem piscina?") segue para o modelo.
    visto = {"fotos": pediu_fotos(texto) and not (PERGUNTA_SEM_PONTO.search(t) and not MANDA.search(t)),
             "status": pediu_status(texto), "manda": bool(MANDA.search(t)),
             "valendo": frases.pergunta_se_vale(texto)}
    # Ela perguntou "É este imóvel?" (o portão de coerência não tinha a prova do pedido). "Não" recusa esse
    # imóvel e a busca segue; "sim", "esse mesmo", "manda" ou o nome dele de novo confirmam, e aí sai inteiro.
    if conversa.ultima_acao == "confirmar_imovel" and ctx.codigo == conversa.foco_codigo and vale:
        if NAO.search(t) and not _pergunta(texto, t):   # "não tem foto ?" é pergunta, não recusa (21/10)
            return Pre("rejeitar")
        if trivial or ctx.origem == "lista":
            return Pre("so_codigo", dados={**visto, "manda": True, "confirmado": True})
    perguntou = conversa.ultima_acao in ("ja_mandei", "status", "confirmar_imovel")
    mesmo = ctx.codigo == conversa.foco_codigo and ctx.origem in ("literal", "citacao", "card", "lista")
    # ...mas MARCAR o card com um recado ("Vou aguardar o cliente responder", 13782) não é o sim: aí precisa de
    # um sim, de um pedido ("manda", "as fotos") ou de a mensagem não dizer mais nada
    disse_sim = ctx.origem != "citacao" or trivial or visto["manda"] or visto["fotos"] or bool(SIM.search(t))
    if perguntou and vale and mesmo and disse_sim and not _pergunta(texto, t) and not NAO.search(t):
        confirmado = {"confirmado": True} if conversa.ultima_acao == "confirmar_imovel" else {}
        return Pre("so_codigo", dados={**visto, "manda": True, **confirmado})     # escreveu o mesmo imóvel: é o sim
    if ctx.codigo and ctx.origem == "lista" and not _pergunta(texto, t):
        return Pre("so_codigo", dados={**visto, "manda": True})      # escolher da lista é pedir o imóvel
    escrito = ctx.origem in ("citacao", "literal", "card")
    if ctx.codigo and escrito and trivial:
        return Pre("so_codigo", dados=visto)
    na_frente = bool(ctx.codigo) and ctx.origem == "foco" and trivial and vale
    # ela só disse "está disponível, quer o card e as fotos?" e ele respondeu "me envia" / "top, manda aí" /
    # "sim": agora vão o card e as fotos
    # ...ou ela disse "esse eu já te enviei, você tem interesse nele?" (05/10) e ele respondeu que sim
    if na_frente and conversa.ultima_acao in ("status", "ja_mandei") and (
            visto["manda"] or visto["fotos"] or SIM.search(t)):
        return Pre("so_codigo", dados={**visto, "manda": True})
    # o foco vale 24 h para pergunta e visita; o ENVIO pelo imóvel de antes continua valendo só as 2 h do gatilho
    if ctx.codigo and visto["fotos"] and trivial and (ctx.origem != "foco" or vale):
        return Pre("fotos")
    if na_frente and conversa.ultima_acao in ("card", "fotos") and visto["manda"]:
        return Pre("fotos")
    return Pre()

classificador/frases.py:sobre_eles.codigo:
def sobre_eles(texto: str) -> bool:
    """A frase fala DOS imóveis da lista, não pede o envio: "Pela descrição os dois são mobiliados né" (13768)."""
    t = normal(texto)
    return bool(SOBRE_ELES.search(t) or ATRIBUTO_DOS.search(t))

classificador/frases.py:negou.codigo:
def negou(texto: str) -> bool:
    """Ele respondeu NÃO. Serve para não tomar recusa por aceite (estado/apresentar.py, `_confirmou`)."""
    return bool(NEGOU.search(normal(texto)))

classificador/frases.py:pede_todos.codigo:
def pede_todos(texto: str) -> bool:
    """A frase pede o envio de todos ("os dois", "ambos", "pode mandar")? Com "?" só quando pede o envio ("vc pode
    me mandar todos?"); a pergunta SOBRE eles ("os dois são mobiliados?") não é pedido."""
    t = normal(texto)
    if not (QUER_TODOS.search(t) or QUER_N.search(t)) or SOBRE_ELES.search(t):
        return False
    return "?" not in (texto or "") or bool(PEDE_ENVIO.search(t))

classificador/frases.py:diz_quantos.codigo:
def diz_quantos(texto: str) -> bool:
    t = normal(texto)
    return bool(DOIS.search(t) or TRES.search(t))

classificador/frases.py:conta_fecha.codigo:
def conta_fecha(texto: str, quantos: int) -> bool:
    """"Os dois" só fala de um grupo de dois; "os três", de três; "todos" e "ambos... " de qualquer tamanho."""
    t = normal(texto)
    return not (DOIS.search(t) and quantos != 2) and not (TRES.search(t) and quantos != 3)

classificador/frases.py:quer_todos.codigo:
def quer_todos(texto: str, quantos: int) -> bool:
    """Ele quer todas as `quantos` opções da lista? "Os dois" numa lista de três não diz quais (replay de 05/10:
    saíram os três)."""
    return pede_todos(texto) and conta_fecha(texto, quantos)

classificador/frases.py:pergunta_se_vale.codigo:
def pergunta_se_vale(texto: str) -> bool:
    t = normal(texto)
    return bool(SE_VALE.search(t)) and not re.search(r"\bainda\b", t)

classificador/frases.py:rejeitou_o.codigo:
def rejeitou_o(texto: str, nome: str) -> bool:
    """A frase recusa o imóvel DESTE nome: o nome e, logo depois, o que não serviu ("esse Parque Golf fica distante
    pra ela"), ou o contrário ("não gostou do Parque Golf"). "Tem que ser no Parque Golf" não recusa: pede."""
    t, n = normal(texto), re.escape(normal(nome))
    return bool(n) and bool(re.search(rf"\b{n}\b.{{0,30}}?\b{RUIM}\b|\b{RUIM}\b.{{0,20}}?\b{n}\b", t))

classificador/frases.py:quer_resultado_j.codigo:
def quer_resultado_ja(texto: str) -> bool:
    """"Manda o que você tem": ele fechou os filtros e quer a lista agora."""
    return bool(QUER_JA.search(normal(texto))) and not pediu_fotos(texto)

classificador/frases.py:extras.codigo:
def extras(texto: str) -> tuple[str, ...]:
    """O que ele pediu além dos filtros e o cadastro sabe dizer: a piscina e o elevador (19/10), o financiamento
    (21/10) e o fino acabamento (20/10), que só põe os de alto padrão primeiro."""
    t = normal(texto)
    return tuple(nome for nome, rx in (("piscina", PISCINA), ("elevador", ELEVADOR),
                                       ("financiavel", FINANCIAVEL),
                                       ("fino acabamento", FINO_ACABAMENTO), ("condominio novo", CONDOMINIO_NOVO))
                 if rx.search(t))

classificador/jev.py:_noul.codigo:
def _noul(pergunta: str, sim: str, nao: str) -> dict:
    return {"type": "noul", "instructions": {"question": pergunta, "context": CONTEXTO},
            "criteria": {"true": sim, "false": nao}}

classificador/jev.py:_escolha.codigo:
def _escolha(answers: dict, chave: str, limiar: float) -> tuple[str | None, float]:
    a = answers.get(chave) or {}
    conf = float(a.get("confidence") or 0.0)
    return (a.get("choice") if conf >= limiar else None), conf

classificador/jev.py:JevModelos._rotulos.codigo:
def _rotulos(self, codigos: list[int]) -> dict[int, str]:
    saida = {}
    for c in codigos[:20]:
        i = self.cer.catalogo.get(c)
        if i:
            saida[c] = f"{i.condominio_nome or i.tipo_original or 'imóvel'}, {i.bairro or 'Manaus'}"
    return saida

classificador/jev.py:JevModelos._post.codigo:
def _post(self, corpo: dict, orcamento_s: float) -> tuple[dict, int]:
    inicio = time.monotonic()
    prazo, erro = inicio + orcamento_s, "sem tempo"
    for _ in range(2):          # uma retentativa, só se sobrar tempo e só para erro que passa sozinho
        resta = prazo - time.monotonic()
        if resta < 0.5:
            break
        try:
            r = self.cli.post(URL, json=corpo, timeout=resta)
        except httpx.HTTPError as x:
            erro = f"conexão: {type(x).__name__}"
            continue
        if r.status_code == 200:
            return r.json(), int((time.monotonic() - inicio) * 1000)
        erro = f"HTTP {r.status_code}: {r.text[:160]}"
        if r.status_code not in REPETE:
            break
    raise FalhaDoModelo(f"jev: {erro}")

classificador/jev.py:JevModelos.classifi.codigo:
def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
    c = cfg("modelos")["jev"]
    if not self.disjuntor.permite():
        raise FalhaDoModelo("jev: circuito aberto")
    bairros = dict(self.cer.zonas)
    estado = {k: entrada.get(k) for k in ("mensagem", "ultima_pergunta_da_nay", "estado", "filtros",
                                          "imovel_em_foco")}
    q = perguntas(entrada, bairros, self._rotulos(list(entrada.get("codigos_candidatos") or [])))
    try:
        d, ms = self._post({"model": c["modelo"], "state": estado, "questions": q}, float(c["orcamento_s"]))
    except FalhaDoModelo:
        self.disjuntor.falha()
        raise
    answers = d.get("answers")
    if not isinstance(answers, dict) or not answers:
        self.disjuntor.falha()
        raise FalhaDoModelo("jev: resposta sem answers")
    self.disjuntor.sucesso()
    cl, fora = ler(answers, entrada, bairros)
    uso = d.get("usage") or {}
    return cl, {"modelo": d.get("model") or c["modelo"], "ms": ms, "custo": uso.get("cost"),
                "tokens_entrada": uso.get("input_tokens"), "cru": answers, **fora}

classificador/jev.py:JevModelos.duvida.codigo:
def duvida(self, instrucao: str, usuario: str) -> tuple[str, dict[str, Any]]:
    if self.luna is None:
        raise FalhaDoModelo("a dúvida é da Luna e ela não foi configurada")
    return self.luna.duvida(instrucao, usuario)

classificador/jev.py:JevJuiz.responde.codigo:
def responde(self, pergunta: str, sim: str, nao: str, estado: dict[str, Any],
             orcamento_s: float) -> tuple[float | None, dict[str, Any]]:
    modelo = cfg("modelos")["jev"]["modelo"]
    if not self.disjuntor.permite():
        return None, {"modelo": modelo, "erro": "circuito aberto"}
    inicio = time.monotonic()
    # o estado vai como JSON: Decimal e data viram texto, e nunca derrubam a chamada
    estado = json.loads(json.dumps(estado, ensure_ascii=False, default=str))
    corpo = {"model": modelo, "state": estado, "questions": {"resposta": _noul(pergunta, sim, nao)}}
    try:
        r = self.cli.post(URL, json=corpo, timeout=orcamento_s)
        if r.status_code != 200:
            raise FalhaDoModelo(f"HTTP {r.status_code}")
        d = r.json()
        prob = ((d.get("answers") or {}).get("resposta") or {}).get("noul")
        if prob is None:
            raise FalhaDoModelo("resposta sem noul")
    except (httpx.HTTPError, FalhaDoModelo, ValueError) as x:
        self.disjuntor.falha()
        return None, {"modelo": modelo, "ms": int((time.monotonic() - inicio) * 1000),
                      "erro": f"{type(x).__name__}: {x}"[:120]}
    self.disjuntor.sucesso()
    return float(prob), {"modelo": d.get("model") or modelo, "ms": int((time.monotonic() - inicio) * 1000),
                         "custo": (d.get("usage") or {}).get("cost")}

classificador/jev.py:modelos_do_core.codigo:
def modelos_do_core(conf, cer, provedor: str | None = None) -> Modelos | None:
    """O cliente que o core usa, conforme `classificador.provedor`: a Luna (padrão) ou o Jev
    nas perguntas fechadas com a Luna só na dúvida. Sem chave da OpenAI, nenhum (regex)."""
    if not conf.openai_api_key:
        return None
    luna = OpenAIModelos(conf.openai_api_key)
    reserva = (cfg("modelos").get("reserva") or {}).get("texto") or {}
    if conf.openrouter_api_key and reserva.get("ligado"):
        from nay.classificador.openrouter import ComReserva, OpenRouterModelos
        luna.tentativas_max = 1
        luna = ComReserva(luna, OpenRouterModelos(conf.openrouter_api_key))
    if (provedor or cfg("modelos")["classificador"].get("provedor", "luna")) == "jev":
        return JevModelos(conf.openrouter_api_key, cer, luna)
    return luna

classificador/luna.py:chave_da_entrada.codigo:
def chave_da_entrada(entrada: dict[str, Any]) -> str:
    bruto = json.dumps(entrada, sort_keys=True, ensure_ascii=False, default=str)
    return hashlib.sha1(bruto.encode("utf-8")).hexdigest()[:16]

classificador/luna.py:Disjuntor.falha.codigo:
def falha(self) -> None:
    self.falhas += 1
    if self.falhas >= self.limite:
        self.aberto_ate, self.falhas = time.monotonic() + self.pausa_s, 0

classificador/luna.py:_texto_da_resposta.codigo:
def _texto_da_resposta(corpo: dict[str, Any]) -> str:
    if corpo.get("output_text"):
        return corpo["output_text"]
    for item in corpo.get("output", []):
        for c in item.get("content", []) or []:
            if c.get("type") in ("output_text", "text") and c.get("text"):
                return c["text"]
    raise FalhaDoModelo("resposta sem texto")

classificador/luna.py:OpenAIModelos.__in.codigo:
def __init__(self, chave: str) -> None:
    self._cli = httpx.Client(headers={"Authorization": f"Bearer {chave}"})
    self.disjuntor = Disjuntor()
    self._uso: dict[str, Any] = {}
    self.tentativas_max = 9           # com reserva, 1: a segunda tentativa é a reserva (Alteração 2, H)

classificador/luna.py:OpenAIModelos._cha.codigo:
def _chamar(self, c: dict, instrucao: str, usuario: str, formato: dict | None) -> str:
    corpo: dict[str, Any] = {"model": c["modelo"], "input": [
        {"role": "system", "content": instrucao}, {"role": "user", "content": usuario}]}
    if formato:
        corpo["text"] = {"format": formato}
    r = self._cli.post(URL, json=corpo, timeout=c["timeout_s"])
    if r.status_code >= 400:
        raise FalhaDoModelo(f"{c['modelo']}: HTTP {r.status_code} {r.text[:160]}")
    d = r.json()
    self._uso = _uso(d.get("usage") or {}, c.get("preco_por_milhao") or {})
    return _texto_da_resposta(d)

classificador/luna.py:OpenAIModelos._ten.codigo:
def _tentar(self, qual: str, instrucao: str, usuario: str, formato: dict | None) -> tuple[str, dict]:
    c = cfg("modelos")[qual]
    if not self.disjuntor.permite():
        raise FalhaDoModelo("circuito aberto")
    erros = []
    for _ in range(max(min(int(c.get("tentativas", 1)), self.tentativas_max), 1)):
        inicio = time.perf_counter()
        try:
            txt = self._chamar(c, instrucao, usuario, formato)
            self.disjuntor.sucesso()
            return txt, {"modelo": c["modelo"], "ms": int((time.perf_counter() - inicio) * 1000),
                         "erros": erros, **self._uso}
        except (httpx.HTTPError, FalhaDoModelo, ValueError) as e:
            erros.append(f"{type(e).__name__}: {str(e)[:120]}")
    self.disjuntor.falha()
    raise FalhaDoModelo("; ".join(erros))

