def __init__(self, chave: str, cliente: httpx.Client | None = None) -> None:
    self._cli = cliente or httpx.Client(headers={"Authorization": f"Bearer {chave}"})
    self.disjuntor = Disjuntor()

def _chamar(self, instrucao: str, usuario: str, formato: dict | None) -> tuple[str, dict[str, Any]]:
    c = cfg("modelos")["reserva"]["texto"]
    if not self.disjuntor.permite():
        raise FalhaDoModelo("reserva: circuito aberto")
    corpo: dict[str, Any] = {"model": c["modelo"], "messages": [
        {"role": "system", "content": instrucao}, {"role": "user", "content": usuario}],
        "reasoning": {"enabled": False}, "usage": {"include": True}}
    if formato:
        corpo["response_format"] = {"type": "json_schema", "json_schema": {**formato, "strict": True}}
    inicio = time.perf_counter()
    try:
        r = self._cli.post(URL, json=corpo, timeout=c["timeout_s"])
        if r.status_code >= 400:
            raise FalhaDoModelo(f"{c['modelo']}: HTTP {r.status_code} {r.text[:160]}")
        d = r.json()
        txt = d["choices"][0]["message"]["content"] or ""
    except (httpx.HTTPError, KeyError, IndexError, TypeError, ValueError, FalhaDoModelo) as e:
        self.disjuntor.falha()
        raise FalhaDoModelo(f"reserva: {type(e).__name__}: {str(e)[:160]}") from e
    self.disjuntor.sucesso()
    u = d.get("usage") or {}
    return CERCA.sub("", txt), {"modelo": d.get("model") or c["modelo"], "provedor": "openrouter",
                                "ms": int((time.perf_counter() - inicio) * 1000),
                                "tokens_entrada": u.get("prompt_tokens"),
                                "tokens_saida": u.get("completion_tokens"), "custo": u.get("cost")}

def classificar(self, entrada: dict[str, Any]) -> tuple[Classificacao, dict[str, Any]]:
    txt, meta = self._chamar(PROMPT, json.dumps(entrada, ensure_ascii=False, default=str),
                             {"name": "classificacao", "schema": json_schema()})
    meta["cru"] = txt
    try:
        return Classificacao.model_validate_json(txt), meta
    except ValueError as e:
        raise FalhaDoModelo(f"reserva: JSON fora do esquema: {str(e)[:160]}") from e

