def _quando_bate(texto: str, pedido: dict, agora: datetime | None) -> bool:
    """O dia e a hora que o sim traz (se traz) são os da confirmação. "Ok, amanhã às 10h" para uma visita das 8h é
    outro horário, não confirmação."""
    hoje = agora.astimezone(visita.MANAUS).date() if agora else None
    hora, dia = visita.hora_dita(texto), (visita.dia_dito(texto, hoje) if hoje else None)
    return (hora is None or hora == pedido.get("hora")) and (dia is None or str(dia) == pedido.get("dia"))

classificador/sinais.py:_sim_que_repete_.codigo:
def _sim_que_repete_o_quando(texto: str, t: str, pedido: dict, agora: datetime | None) -> bool:
    """"Mulher, tudo certo amanhã às 8 da manhã" (6220, 23/10): o sim que traz de novo o dia e a hora da confirmação
    passa de 6 palavras e caía no modelo, que montava a confirmação outra vez. Só vale se repete o que ela pediu."""
    t = VOCATIVO.sub("", t)
    if len(t.split()) > 14 or "?" in texto or not SIM.search(t) or not visita.disse_quando(texto):
        return False
    return _quando_bate(texto, pedido, agora)

classificador/sinais.py:_da_visita.codigo:
def _da_visita(texto: str, t: str, c: Conversa, ctx: Contexto, agora: datetime | None) -> tuple[str, dict] | None:
    pedido = visita.aberto(c, agora)
    curta = len(t.split()) <= 6
    esperando = bool(pedido) and pedido.get("etapa") == "confirmar"
    if esperando and curta and "?" not in texto:
        if SIM.search(t) and _quando_bate(texto, pedido, agora):
            return "visita_confirmada", {}
        if NAO.search(t) and not visita.disse_quando(texto):
            return "visita_corrigir", {}
    if esperando and len(t.split()) <= 14 and AINDA_QUER_VISITAR.search(t) and not visita.disse_quando(texto):
        return "visita_confirmada", {}      # "cliente quer ir ver assim mesmo, ainda dá tempo?": é o sim (13762)
    if esperando and _sim_que_repete_o_quando(texto, t, pedido, agora):
        return "visita_confirmada", {}
    escrito = bool(ctx.literais) or ctx.origem in ("literal", "citacao", "card", "lista")
    if PEDE_OUTROS.search(t) and not escrito:
        return None         # pede imóvel (com data junto): o modelo lê (test_pedido_de_busca_na_visita_aberta.py)
    # a resposta à pergunta dela ("As 14:30"): só enquanto a visita é o assunto (o estado muda quando ele fala de
    # outra coisa; aí "tem outro para hoje?" não é horário de visita)
    if pedido and c.estado == "VISITA_PEDIDA" and visita.disse_quando(texto):
        return "visita_dados", {}
    if visita.pediu(texto) and not escrito and VISITA_EM.search(t):
        return None         # o lugar da visita veio pelo NOME: o classificador lê os condomínios (13723)
    if visita.pediu(texto):
        return "visita_dados", {}
    if c.ultima_acao == "interessado" and prazos.gatilho_vale(c, agora) and curta and SIM.search(t):
        return "visita_dados", {}       # ela perguntou se ele quer agendar e ele disse que sim
    return None

classificador/sinais.py:_do_outro_client.codigo:
def _do_outro_cliente(texto: str, t: str, c: Conversa, vale: bool) -> tuple[str, dict] | None:
    """A resposta a "Está perguntando para outro cliente, certo?" (10/10). Só a resposta curta e direta: o resto
    (um pedido novo, uma pergunta) segue o caminho de sempre."""
    if c.ultima_pergunta != "outro_cliente" or not vale or len(t.split()) > 6 or "?" in texto:
        return None
    if frases.pede_todos(texto):        # "pode mandar os 5" (3202, 12/10): quer os da lista, e a lista saía de novo
        return None
    if MESMO_CLIENTE.search(t):
        return "outro_cliente_nao", {}
    if filtros.OUTRO_CLIENTE.search(t) or E_OUTRO.search(t) or SIM.search(t):
        return "outro_cliente_sim", {}
    return ("outro_cliente_nao", {}) if NAO.search(t) else None

classificador/sinais.py:_da_busca.codigo:
def _da_busca(texto: str, t: str, c: Conversa, vale: bool) -> tuple[str, dict] | None:
    """A resposta ao que ela disse quando a busca não achou nada, e o "deixei descrito"."""
    outro = _do_outro_cliente(texto, t, c, vale)
    if outro:
        return outro
    curta = len(t.split()) <= 4
    if c.ultima_acao == "oferta_abaixo" and vale and curta and "?" not in texto:
        # "Nessa faixa de valor eu não tenho agora. Tenho opções a partir de R$ 2.750. Quer que eu te mande?"
        if SIM.search(t) or QUER_VER.search(t):
            return "abaixo_sim", {}
        if NAO.search(t):
            return "tentar_outro", {}
    if c.ultima_acao in ("lista_vazia", "bairro_desconhecido") and vale and len(t.split()) <= 3 and SIM.search(t):
        return "tentar_outro", {}
    if pedido_aberto(c) and ja_disse(texto):
        return "ja_disse", {}
    return None

classificador/sinais.py:decidir.codigo:
def decidir(texto: str, c: Conversa, ctx: Contexto, agora: datetime | None) -> tuple[str, dict] | None:
    t = normal(texto)
    da_visita = _da_visita(texto, t, c, ctx, agora)
    if da_visita:
        return da_visita
    if perguntou_quem_e(texto):
        return "quem_sou", {}
    vale = prazos.gatilho_vale(c, agora)
    if ctx.codigo and tem_as_fotos(texto):      # o que ele já tem não se manda de novo (rodada 9)
        return "tem_as_fotos", {}
    resposta = dispensou(texto, c, vale)
    if resposta is not None and (resposta or ctx.codigo):
        return ("dispensou", {}) if resposta else ("so_codigo", {"fotos": False, "status": False, "manda": True})
    if despedida(texto):
        return "despedida", {}
    if pede_anuncio(texto):
        return "anuncio", {}
    fora = None if ctx.codigo else frases.tipo_fora_do_catalogo(texto)
    if fora:                                    # "tem chácara pra vender?" (13/10): a gente não trabalha com isso
        return "tipo_fora", {"tipo": fora}
    escrito = ctx.origem in ("literal", "citacao", "card", "lista")
    da_busca = _da_busca(texto, t, c, vale)
    if da_busca:
        return da_busca
    do_imovel = escrito or (ctx.origem == "foco" and vale)
    if ctx.codigo and do_imovel and cliente_interessado(texto):
        return "interessado", {}
    return None

classificador/valores.py:_resto.codigo:
def _resto(r: str | None, unidade: float) -> float:
    if not r:
        return 0.0
    if r in ("meio", "meia"):
        return unidade / 2
    return float(r) if r.isdigit() else float(tabela()["centenas"][r])

classificador/valores.py:_numeros.codigo:
def _numeros(t: str) -> list[_Numero]:
    p = _padroes()
    achados = []
    for m in p["numero"].finditer(t):
        if p["nao_e_valor"].search(t[m.end():]):
            continue
        valor, com_unidade = _valor_de(m)
        if not com_unidade and p["lugar_antes"].search(t[:m.start()]):
            continue                    # "no parque 10 ate 3 mil": o 10 é do bairro
        achados.append(_Numero(m.start(), m.end(), valor, com_unidade))
    return achados

classificador/valores.py:_plano.codigo:
def _plano(texto: str) -> str:
    t = re.sub(r"(?<=\d)\s?M\b", " milhao", sem_acento(texto or ""))       # "1.2M": só o M maiúsculo é milhão
    return re.sub(r"\s+", " ", t.lower()).strip()

classificador/valores.py:_na_escala.codigo:
def _na_escala(n: _Numero, finalidade: str | None, do_vizinho: _Numero | None = None) -> float | None:
    """Em reais. "2 a 3 mil": o primeiro pega a unidade do segundo."""
    v = n.valor
    if not n.com_unidade:
        if do_vizinho and do_vizinho.com_unidade and v < 1000:
            v *= 1e6 if do_vizinho.valor >= 1e6 else 1e3
        else:
            v = teto_na_escala(v, finalidade) or 0
    return v if MINIMO <= v <= MAXIMO else None

classificador/valores.py:_faixa.codigo:
def _faixa(t: str, ns: list[_Numero], finalidade: str | None, solto: bool) -> Valor | None:
    """Dois ou mais valores ligados ("entre 3.500 e 4.500", "de 2 a 3 mil", "3.500 / 4.00 / 4.500 máximo")."""
    p = _padroes()
    for k in range(len(ns) - 1):
        cadeia = [ns[k]]
        while len(cadeia) + k < len(ns) and p["ligacao"].match(t[cadeia[-1].fim:ns[k + len(cadeia)].inicio]):
            cadeia.append(ns[k + len(cadeia)])
        if len(cadeia) < 2:
            continue
        dita = bool(p["faixa_antes"].search(t[:cadeia[0].inicio])) or any(n.com_unidade for n in cadeia) or solto
        com_unidade = next((n for n in reversed(cadeia) if n.com_unidade), None)
        valores = _crescente([v for n in cadeia if (v := _na_escala(n, finalidade, com_unidade))])
        if dita and len(valores) >= 2 and min(valores) < max(valores):
            return Valor("faixa", teto=max(valores), piso=min(valores))
    return None

classificador/valores.py:_da_familia.codigo:
def _da_familia(t: str, ns: list[_Numero], finalidade: str | None) -> Valor | None:
    """O primeiro número com uma expressão de família antes ou depois. No teto vale o MAIOR dos valores ditos dali
    em diante ("Até quatro mil, quatro mil, cinco mil": até onde ele vai)."""
    p = _padroes()
    for k, n in enumerate(ns):
        antes, depois = t[max(0, n.inicio - 40):n.inicio], t[n.fim:n.fim + 24]
        for familia in ("piso", "teto", "por_volta"):
            if not (p[f"{familia}_antes"].search(antes) or p[f"{familia}_depois"].search(depois)):
                continue
            if familia == "piso":
                v = _na_escala(n, finalidade)
                return Valor("piso", piso=v) if v else None
            ditos = [v for x in ns[k:] if (v := _na_escala(x, finalidade))] if familia == "teto" else []
            v = max(ditos, default=None) if familia == "teto" else _na_escala(n, finalidade)
            return Valor(familia, teto=v) if v else None
    return None

classificador/valores.py:ler.codigo:
def ler(texto: str, finalidade: str | None = None, solto: bool = False) -> Valor | None:
    t = _plano(texto)
    ns = _numeros(t)
    if not ns:
        return None
    achado = _faixa(t, ns, finalidade, solto) or _da_familia(t, ns, finalidade)
    if achado or not solto:
        return achado
    # respondendo ao "Até que valor?": o número é o valor, se a mensagem for só ele (e uma ou outra palavra)
    sobra = re.sub(r"[\s.,!?]+", " ", t[:ns[0].inicio] + t[ns[-1].fim:]).split()
    if len(ns) == 1 and len(sobra) <= 3 and (v := _na_escala(ns[0], finalidade)):
        return Valor("teto", teto=v)
    return None

