@lru_cache(maxsize=1)
def _palavras_de_valor() -> frozenset[str]:
    t = tabela()
    das_familias = {p for f in ("teto", "por_volta", "piso") for lado in t[f].values() for e in lado for p in e.split()}
    return SO_DE_VALOR | das_familias | set(t["faixa"]["antes"]) | set(t["unidades"]) | set(t["centenas"])

classificador/valores.py:so_valor.codigo:
def so_valor(texto: str) -> bool:
    """A mensagem só fala do valor? "até 4.500, semimobiliado" traz mais coisa: aí quem lê é o classificador."""
    palavras = re.findall(r"[a-z]+", _plano(texto))
    return all(p in _palavras_de_valor() for p in palavras)

