def prontas(pendentes: list[Mensagem], agora: datetime, janela_s: int) -> list[Rajada]:
    """As rajadas cuja última mensagem já tem mais de `janela_s` segundos."""
    por_pessoa: dict[str, list[Mensagem]] = defaultdict(list)
    for m in pendentes:
        if m.direcao == "recebida":
            por_pessoa[m.chave].append(m)
    saida = []
    for ch, ms in por_pessoa.items():
        ms.sort(key=lambda m: m.recebida_em)
        if agora - ms[-1].recebida_em >= timedelta(seconds=janela_s):
            saida.append(Rajada(chave=ch, mensagens=tuple(ms)))
    return sorted(saida, key=lambda r: r.quando)

