            "tipo": cl.tipo or ("tanto_faz" if "tipo" in tf else None),
            "teto": cl.teto, "teto_tanto_faz": "teto" in tf, "regiao_tanto_faz": "bairro" in tf,
            "quartos": cl.quartos, "mobilia": cl.mobilia or ("tanto_faz" if "mobilia" in tf else None)}

estado/filtros.py:_faixa.codigo:
def _faixa(d: dict, campo: str, valor) -> dict:
    """teto e região: valor dito ganha de 'tanto faz'; 'tanto faz' apaga o valor antigo."""
    if d.get(campo):
        return {f"filtro_{campo}": valor(d[campo]), f"filtro_{campo}_tanto_faz": False}
    if d.get(f"{campo}_tanto_faz"):
        return {f"filtro_{campo}": None, f"filtro_{campo}_tanto_faz": True}
    return {}

estado/filtros.py:_mudancas.codigo:
def _mudancas(d: dict) -> dict:
    mud = {f"filtro_{k}": d[k] for k in ("finalidade", "tipo", "mobilia") if d.get(k)}
    if d.get("quartos"):
        mud["filtro_quartos"] = int(d["quartos"])
    mud |= _faixa(d, "teto", float) | _faixa(d, "regiao", tuple)
    if "filtro_teto" in mud or d.get("piso"):
        # o valor novo leva o piso junto: o da faixa ("entre 3.500 e 4.500"), o do "a partir de", ou nenhum
        mud["filtro_piso"] = float(d["piso"]) if d.get("piso") else None
    if d.get("piso") and not d.get("teto"):
        mud |= {"filtro_teto": None, "filtro_teto_tanto_faz": False}
    return mud

estado/filtros.py:_valor.codigo:
def _valor(c: Conversa, d: dict, cl: Classificacao | None, texto: str) -> dict:
    """O valor desta mensagem, em reais, com a família que a frase diz (classificador/valores.py). A faixa e o
    piso só a biblioteca vê; o teto é o do modelo (ou o da resposta direta) e, sem ele, o que a frase disser."""
    fin = d.get("finalidade") if d.get("finalidade") in ("locacao", "venda") else c.filtro_finalidade
    dito = valores.ler(texto, fin) if texto and (cl is None or cl.intencao == "pedir_imovel") else None
    if dito and dito.familia in ("faixa", "piso"):
        return {"teto": dito.teto, "piso": dito.piso}
    if d.get("teto"):       # "até 900" num pedido de compra é R$ 900 mil; "3" no aluguel é R$ 3 mil (texto.py)
        return {"teto": teto_na_escala(float(d["teto"]), fin)}
    return {"teto": dito.teto} if dito else {}

estado/filtros.py:_regiao.codigo:
def _regiao(c: Conversa, novos: tuple[str, ...], texto: str) -> tuple[str, ...]:
    """A ficha de solicitação é como o filtro do site, com vários bairros marcados (Tel, 06/10): o bairro dito
    depois SOMA aos que já estavam, em vez de ficar só o último. Troca quando ele diz que é troca ("só no Aleixo",
    "e no Parque 10?", "na verdade...") ou quando só repete um dos que já estavam (ele estreitou)."""
    antes = tuple(c.filtro_regiao or ())
    if not antes or TROCA_A_REGIAO.search(normal(texto)) or set(novos) <= set(antes):
        return novos
    return tuple(dict.fromkeys((*antes, *novos)))

estado/filtros.py:aplicar.codigo:
def aplicar(c: Conversa, cl: Classificacao | None, bairros: tuple[str, ...],
            direto: dict | None = None, texto: str = "", soma: bool = True) -> Conversa:
    """Preenche os filtros com o que veio NESTA mensagem (classificador e/ou pré-roteador). `soma`: os bairros
    novos entram junto dos que já estavam (falso quando o pedido recomeça de um imóvel que saiu)."""
    d = {**(_do_classificador(cl) if cl else {}), **{k: v for k, v in (direto or {}).items() if v}}
    d |= _valor(c, d, cl, texto)
    if d.get("mobilia") == "tanto_faz" and c.ultima_acao == "pergunta_mobilia_preferencia":
        d["mobilia"] = "sem_preferencia"      # ela já perguntou a preferência e ele manteve: vale os dois
    if frases.AS_DUAS_MOBILIAS.search(normal(texto)):
        # "mobiliado ou semi mobiliado" (13853): ele já disse que servem os dois, a pergunta não se faz
        d["mobilia"] = "sem_preferencia"
    if bairros:
        d["regiao"] = bairros
    if d.get("regiao") and soma:
        d["regiao"] = _regiao(c, tuple(d["regiao"]), texto)
    pedidos = frases.extras(texto) if cl is None or cl.intencao == "pedir_imovel" else ()
    c = c.com(filtro_extras=tuple(dict.fromkeys((*c.filtro_extras, *pedidos)))) if pedidos else c
    novo = c.com(**_mudancas(d))
    if novo.filtro_finalidade is None:
        pelo_valor = finalidade_pelo_valor(novo.filtro_teto or novo.filtro_piso)
        if pelo_valor:
            novo = novo.com(filtro_finalidade=pelo_valor)
    return novo

