def fechar(c: Conversa) -> Conversa:
    """"Manda o que você tem" (13872): o que ele não disse vira tanto faz e a busca sai com o que já se sabe."""
    mud: dict = {}
    if c.filtro_finalidade is None:
        mud["filtro_finalidade"] = "tanto_faz"
    if c.filtro_tipo is None:
        mud["filtro_tipo"] = "tanto_faz"
    if c.filtro_teto is None and c.filtro_piso is None:
        mud["filtro_teto_tanto_faz"] = True
    if not c.filtro_regiao:
        mud["filtro_regiao_tanto_faz"] = True
    if c.filtro_mobilia in (None, "tanto_faz"):
        mud["filtro_mobilia"] = "sem_preferencia"
    return c.com(**mud)

