estado/filtros.py:do_imovel.codigo:
def do_imovel(i: Imovel, texto_dele: str = "", finalidade: str | None = None) -> dict:
    """Os filtros que o card colado diz (turno 921: colou o card do Morada dos Pássaros e ouviu "Até que
    valor?" e "Em qual bairro?"). A finalidade: a única do imóvel, ou a do valor que ele escreveu ("900 mil, né?")."""
    if i.de_locacao != i.de_venda:
        fin = "locacao" if i.de_locacao else "venda"
    else:       # serve aos dois: a finalidade da conversa, ou a do valor que ele escreveu
        fin = finalidade if finalidade in ("locacao", "venda") else finalidade_pelo_valor(_valor_solto(texto_dele))
    teto = i.valor_aluguel if fin == "locacao" else i.valor_venda if fin == "venda" else None
    return {"finalidade": fin, "tipo": i.tipo, "teto": teto, "regiao": (i.bairro_norm,) if i.bairro_norm else ()}

estado/filtros.py:do_digitado.codigo:
def do_digitado(i: Imovel | None) -> dict:
    """Os quartos, os valores e o tipo do imóvel cujo código ele DIGITOU: quem escreve "Portinari cod 5551 / 2
    quartos / 1.8k" (13776) descreve o próprio imóvel, não um perfil de busca (estado/maquina.py, _perfil_novo)."""
    if i is None:
        return {}
    casa = ("casa", "casa_condominio")
    return {"quartos": i.quartos, "valores": tuple(v for v in (i.valor_aluguel, i.valor_venda) if v),
            "tipos": casa if i.tipo in casa else (i.tipo,)}

estado/filtros.py:completar.codigo:
def completar(c: Conversa, d: dict) -> Conversa:
    """Só os filtros VAZIOS, com o que veio do card colado: o que ele disse continua valendo."""
    if not d:
        return c
    mud = {}
    if c.filtro_finalidade is None and d.get("finalidade"):
        mud["filtro_finalidade"] = d["finalidade"]
    if c.filtro_tipo is None and d.get("tipo"):
        mud["filtro_tipo"] = d["tipo"]
    if c.filtro_teto is None and not c.filtro_teto_tanto_faz and d.get("teto"):
        mud["filtro_teto"] = float(d["teto"])
    if not c.filtro_regiao and not c.filtro_regiao_tanto_faz and d.get("regiao"):
        mud["filtro_regiao"] = tuple(d["regiao"])
    return c.com(**mud) if mud else c

estado/maquina.py:qual_da_lista.codigo:
def qual_da_lista(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela mandou uma LISTA e ele respondeu "manda", "esse", "envia", sem dizer qual: a mesma pergunta de
    quando a busca devolveria a mesma lista ("Qual deles eu te mando?"; de novo, sobe ao Tel). Quem escreve a
    pergunta, com os nomes da lista curta, é acoes/preparo.py (`mesma_lista`). O foco de outro pedido sai."""
    return (c.com(foco_codigo=None, foco_origem=None),
            Acao("template", template="qual_da_lista", dados={"codigos": list(ev.dados_pre.get("codigos") or ())}))

estado/maquina.py:_perfil_novo.codigo:
def _perfil_novo(ev: Evento) -> bool:
    """A mensagem traz um perfil de busca (tipo, teto ou quartos) além do imóvel escrito? O card colado tem tipo,
    quartos e valor: é o card que o modelo leu, não um perfil (920). E quem escreve "Bosque Residencial Portinari
    cod 5551 / 2 quartos / 1.8k" (13776) está descrevendo o próprio imóvel: os quartos e o valor são os dele."""
    cl, dele = ev.classificacao, ev.do_escrito
    if ev.contexto.card_colado:
        return False
    if dele and cl.quartos in (None, dele.get("quartos")) and (cl.teto is None or cl.teto in dele.get("valores", ())):
        return bool(cl.teto is None and cl.quartos is None and cl.tipo and cl.tipo not in dele.get("tipos", ()))
    return bool(cl.tipo or cl.teto or cl.quartos)

estado/maquina.py:por_intencao.codigo:
def por_intencao(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    cl = ev.classificacao
    i = cl.intencao
    if i in DIRETAS:
        return DIRETAS[i](c, ev)
    escrito = ev.contexto.origem in ("literal", "card", "citacao", "lista")   # o foco antigo não conta aqui
    # O código (ou a opção da lista) que ele escreveu é o pedido mais exato que existe: vale mesmo com o
    # bairro na mesma frase ("Parque dez Milano código 9005" recebeu a lista de novo em 02/10). Só vira
    # busca nova quando ele traz perfil junto (tipo, teto ou quartos): "algo como o 5717 até 3 mil".
    perfil_novo = _perfil_novo(ev)
    if i == "pedir_imovel" and ev.contexto.codigo and escrito and not perfil_novo:
        return apresentar(c, ev, ev.contexto.codigo, pediu(ev), False)
    if i == "pedir_imovel" and ev.contexto.candidatos and not perfil_novo:     # marcou a lista: qual deles?
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.contexto.candidatos)
    if i == "pedir_imovel":
        return multiplos.com_o_envio(c, ev, pedir_imovel(c, ev))
    nosso = bool(ev.contexto.codigo) and ev.contexto.origem in ("literal", "card")
    if nosso and i in ("oferta_de_imovel", "assunto_geral", "nao_da_para_saber"):
        return do_escrito(c, ev)        # o código ou o card é NOSSO: não é oferta dele e não sobe ao Tel (13776)
    if i in ("oferta_de_imovel", "assunto_geral", "resultado_visita"):
        return escalar(c, ev, i.replace("_", " "))      # resultado de visita: quem cuida é gente (entrega 2)
    if ev.contexto.origem == "citacao" and ev.contexto.codigo and (
            i == "nao_da_para_saber" or (i == "cortesia" and cumprimentou(ev.texto))):
        # ele MARCOU o card e o que escreveu não diz o que quer: a resposta é sobre aquele imóvel, nunca
        # "não entendi" (corretor do 3878, 02/10). Diz que está disponível e oferece o card e as fotos.
        return apresentar(c, ev, ev.contexto.codigo, False, True, so_status=True)
    if i == "cortesia" and cumprimentou(ev.texto):
        return saudar(c)
    if i in SIMPLES:        # a parceria que já diz o que quer recebe o que pediu (estado/multiplos.py)
        return multiplos.parceria(c, ev, pedir_imovel) if i == "parceria" else (c, SIMPLES[i])
    return nao_entendi(c, ev)

estado/maquina.py:recado.codigo:
def recado(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Notícia do cliente ("aguardando um retorno dele", "ela achou um"): ela acusa o recado uma vez e espera.
    Recado em cima do recado, calada. Nunca "não entendi", nunca sobe ao Tel (Alteração 2, E)."""
    # O recado que diz o nome de UM imóvel põe esse imóvel na frente (rodada 9, 13570: "vou mostrar o Smille Flores
    # para um cliente" e, horas depois, "Conseguimos agendar para amanhã?" ouviu "De qual imóvel você fala?")
    ctx = ev.contexto
    dito = ctx.codigo if ctx.origem in ("literal", "citacao", "card", "lista") else (
        ev.condominio_codigos[0] if len(ev.condominio_codigos) == 1 else None)
    if dito:
        c = c.com(foco_codigo=dito, foco_origem=origem_de(c, ev, dito))
    if c.ultima_acao == "recado" and prazos.gatilho_vale(c, ev.agora):
        return c, Acao("silencio", motivo="recado: ela já acusou")
    return c, Acao("template", template="recado", codigo=dito)

estado/maquina.py:saudar.codigo:
def saudar(c: Conversa) -> tuple[Conversa, Acao]:
    """Ele só cumprimentou: ela cumprimenta de volta e espera (Tel, 15/09). Em 02/10 "Oii Boa tarde"
    passou pelo modelo como cortesia e ficou sem resposta: cumprimento NUNCA é silêncio."""
    return (c.com(estado="IDENTIFICANDO" if c.estado == "NOVO" else c.estado),
            Acao("template", template="saudacao"))

estado/maquina.py:_so_codigo.codigo:
def _so_codigo(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Só a pergunta ("ainda está disponível?", o card colado ou o card MARCADO sem pedido nenhum): só a
    resposta. Com "me envia", "manda aí" ou pedido de foto junto: card e fotos."""
    ctx, d = ev.contexto, ev.dados_pre
    pediu = bool(d.get("fotos") or d.get("manda"))
    espera = visita.aberto(c, ev.agora)
    if espera and espera.get("etapa") == "falta" and not espera.get("codigo") and not pediu:
        return visita.pedir(c, ev)      # 22/10, ...9660: "Podemos agendar as 14" + "Esse aqui": o imóvel chegou, a visita segue
    so_status = (bool(d.get("status")) or ctx.card_colado or bool(d.get("marcou"))) and not pediu
    if d.get("fotos") and c.ultima_acao == "varios" and ctx.codigo in c.ultima_lista:
        return so_fotos(c, ev, ctx.codigo)      # o card dele acabou de sair junto com os outros: agora só as fotos
    if d.get("valendo") and not pediu:          # "tá valendo?": sim, por quanto, e o card (13653)
        return esta_valendo(c, ev, ctx.codigo)
    if ctx.card_colado and not pediu and not d.get("status") and not d.get("marcou"):
        return do_card_colado(c, ev, ctx.codigo)        # colou o nosso card e mais nada: as fotos (13764)
    # ela perguntou "É este imóvel?" e ele respondeu que sim: a origem passa a ser dele (portão de coerência).
    # O mesmo quando ela acabou de dizer "Sim, está disponível. Quer que eu te mande?" (ou "já te enviei, quer de
    # novo?") e ele respondeu "manda": é a resposta à pergunta DELA sobre este imóvel, e "É este imóvel?" em cima
    # disso é conversa de robô (8585, 12/10: os filtros eram de um pedido antigo).
    # 20/10: a pergunta "serve para o seu cliente?" da Nay Captação dos Grupos vale o dia (o foco), não 2 h
    serve = c.ultima_acao == "pergunta_serve" and prazos.foco_vale(c, ev.agora)
    respondeu = (pediu and ctx.codigo == c.foco_codigo and c.ultima_acao in ("status", "ja_mandei", "pergunta_serve")
                 and (prazos.gatilho_vale(c, ev.agora) or serve))
    return apresentar(c, ev, ctx.codigo, pediu, bool(d.get("status")), so_status=so_status,
                      origem="confirmado" if d.get("confirmado") or respondeu else None)

estado/maquina.py:por_pre.codigo:
def por_pre(c: Conversa, ev: Evento) -> tuple[Conversa, Acao] | None:
    ctx, p = ev.contexto, ev.pre
    if p == "qual" and ctx.candidatos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ctx.candidatos)
    if p == "todos_da_lista" and ev.dados_pre.get("codigos"):
        return apresentar_varios(c, ev, tuple(ev.dados_pre["codigos"]),
                                 tuple(ev.dados_pre.get("falta_escolher") or ()))
    situacao, com_imovel = DO_PRE.get(p or "", (None, False))
    if situacao is None or (com_imovel and not ctx.codigo):
        return None
    return situacao(c, ev)

estado/maquina.py:precisa_classificar.codigo:
def precisa_classificar(c: Conversa, ev: Evento) -> bool:
    """Chamar o modelo só quando a máquina vai usar o que ele disser."""
    return (ev.papel == "corretor" and ev.na_lista and (not ev.midia_visual or bool(ev.texto.strip()))
            and not _vigente(c.humano_ate, ev.agora)
            and not (c.estado == "ESCALADO" and _vigente(c.escalado_ate, ev.agora)))

estado/maquina.py:transicao.codigo:
@no("decisao.transicao")
def transicao(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    if ev.papel != "corretor":
        return c, Acao("fora_do_escopo", motivo=f"papel {ev.papel}")
    if _vigente(c.humano_ate, ev.agora):
        return c, Acao("silencio", motivo="o Tel está com a conversa")
    if c.estado == "ESCALADO" and _vigente(c.escalado_ate, ev.agora):
        return c, Acao("silencio", motivo=f"escalado: {c.escalado_motivo}")
    if not ev.na_lista:
        return c, Acao("fora_da_lista", motivo="não está em corretores",
                       dados={"perguntou": ev.perguntou_de_imovel})
    if ev.midia_visual and not ev.texto.strip():
        # SÓ a imagem, sem texto: ela não lê imagem (01/10). Diz que recebeu e a conversa segue aberta. Com texto,
        # o texto é atendido como sempre. Nos dois casos o Tel é avisado (acoes/imagem.py; Pedro, 07/10).
        return c, Acao("template", template="recebi_midia")
    c = filtros.completar(c, ev.do_card)        # o card colado preenche os filtros vazios (921)
    c = memoria.da_frase(c, ev.texto, ev.contexto.card_colado)     # "pra alugar" dito em qualquer frase fica na ficha
    pre = por_pre(c, ev)
    if pre:
        return pre
    if ev.classificador_falhou or ev.classificacao is None:
        return nao_entendi(c, ev)
    if ev.classificacao.intencao in memoria.OUVE and not ev.contexto.codigo:
        # "tem casa no Ponta Negra ou Tarumã? Se sim aceita parceria?" (1885): o perfil dito fora do pedido fica
        # na ficha, e a pergunta "casa ou apartamento?" não se faz depois
        c = memoria.completar(c, memoria.ouvido(ev.classificacao, ev.bairros))
    return multiplos.dois_clientes(c, ev, pedido.perguntar_proximo_filtro) or por_intencao(c, ev)

estado/maquina.py:anotar.codigo:
@no("decisao.anotar")
def anotar(c: Conversa, a: Acao) -> Conversa:
    """Grava o que ela acabou de fazer e de perguntar. É por este dado, e não por regex sobre
    o que ela enviou, que o turno seguinte sabe que "manda aí" depois do card quer as fotos."""
    if a.tipo in ("silencio", "fora_do_escopo", "fora_da_lista"):
        return c
    if a.tipo == "template" and a.template == "quem_sou":
        return c            # ela só disse quem é: a pergunta que estava no ar continua valendo
    if a.tipo == "perguntar_filtro":
        # a pergunta repetida porque a resposta não deu para entender fica marcada: a terceira não existe
        repetiu = a.motivo == "de_novo" and a.filtro != "mobilia_preferencia"
        mesma = c.ultima_pergunta == a.filtro and c.ultima_acao in (f"pergunta_{a.filtro}", "repetiu_pergunta")
        return c.com(ultima_pergunta=a.filtro, pergunta_vezes=c.pergunta_vezes + 1 if mesma else 1,
                     ultima_acao="repetiu_pergunta" if repetiu else f"pergunta_{a.filtro}")
    if a.tipo == "visita_pedida":       # visita_entregue, visita_qual_horario, visita_confirmar, visita_anotada
        return c.com(ultima_pergunta=None if a.template == "visita_anotada" else "visita", ultima_acao=a.template)
    if a.tipo == "apresentar" and a.dados.get("oferece_visita"):
        return c.com(ultima_pergunta="visita", ultima_acao="interessado")
    if a.tipo == "apresentar":
        feito = "fotos" if a.com_fotos else "card" if a.com_card else "status"
        return c.com(ultima_pergunta=None, ultima_acao=feito)
    if a.tipo == "apresentar_varios":
        # os cards que a busca mandou fecham com "se quiser as fotos de algum, me diz qual": a pergunta está no ar
        escolher = a.dados.get("falta_escolher") or a.dados.get("da_busca")
        return c.com(ultima_pergunta="qual_imovel" if escolher else None, ultima_acao="varios")
    if a.tipo == "template":
        return c.com(ultima_pergunta=PERGUNTA_DO_TEMPLATE.get(a.template or ""),
                     ultima_acao=FICA_COMO.get(a.template or "", a.template))
    if a.tipo == "perguntar_qual" and a.dados.get("confirmar"):      # "É este imóvel?" (portão de coerência)
        return c.com(ultima_pergunta="qual_imovel", ultima_acao="confirmar_imovel")
    return c.com(ultima_pergunta=PERGUNTA_DA_ACAO.get(a.tipo), ultima_acao=a.tipo)

estado/maquina.py:nao_entendi.codigo:
def nao_entendi(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Não deu para entender: pergunta UMA vez. Se a resposta seguinte também não der, não repete
    "não entendi" (replay de 02/10: 18% dos turnos cairiam aqui): sobe ao Tel com a mensagem.
    Com pedido aberto (ela está perguntando filtro ou acabou de buscar) a frase "você procura um imóvel ou quer
    saber de algum imóvel nosso?" não existe (Tel, 06/10): ela retoma o pedido (estado/pedido.py)."""
    if ev.contexto.codigo and ev.contexto.origem in ("literal", "card"):
        # ele ESCREVEU o código de um imóvel: o que mais vier na mensagem não muda isso ("3078 ⏎ Smile parque de
        # flores" ouviu "não entendi" na rodada de 06/10 à noite, turno 13914). Código digitado apresenta, sempre;
        # com pergunta em volta, a ficha responde (rodada 9).
        return do_escrito(c, ev)
    if ev.condominio_codigos:
        # ele escreveu só o nome de um condomínio que tem oferta ("Smile parque das flores", 13916, rodada 5: o
        # modelo não soube a intenção e saiu "não entendi"): o nome É o pedido
        if len(ev.condominio_codigos) == 1:
            return apresentar(c, ev, ev.condominio_codigos[0], pediu(ev), False, origem="condominio")
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.condominio_codigos)
    retomada = pedido.retomar(c, ev)
    if retomada:
        return retomada
    if c.ultima_acao in ("esclarecer", "repetiu_pergunta", "retomar_pedido"):
        return escalar(c, ev, "não entendi duas vezes seguidas")
    return c, Acao("template", template="esclarecer")

estado/memoria.py:para_o_modelo.codigo:
def para_o_modelo(historico: tuple) -> list[dict]:
    """A conversa de hoje como o modelo a recebe: sem o instante (`quando`), que é só desta memória."""
    return [{k: v for k, v in m.items() if k != "quando"} for m in historico or ()]

estado/memoria.py:varios_clientes.codigo:
def varios_clientes(ja_dito: dict, texto: str) -> bool:
    """Ele está atendendo MAIS DE UM cliente neste pedido (disse agora ou mais acima na conversa)."""
    return bool(ja_dito.get("varios")) or fala_de_varios(texto)

estado/memoria.py:tipos_ditos.codigo:
def tipos_ditos(texto: str) -> tuple[str, ...]:
    """Os tipos que a frase escreve, na ordem ("casa em condomínio" é casa)."""
    t = normal(texto or "")
    return tuple(dict.fromkeys(_familia(v) for p, v in TIPOS if re.search(p, t)))

estado/memoria.py:somar_perfis.codigo:
def somar_perfis(antes: Conversa, depois: Conversa, texto: str = "") -> Conversa:
    """Pedido para vários clientes: o tipo SOMA ao de antes só quando a frase ACRESCENTA ("Casa" e, depois, "E por
    último apartamento de 3 quartos": servem os dois, e os quartos de um não estreitam a busca dos outros).

    Sem a palavra de acréscimo, o tipo e os quartos que ele disse são os da busca (Pedro, 13/10, turno 1934: "meus
    clientes procuram casa de 3 quartos" saiu como casa ou apartamento de qualquer tamanho, e foram apartamentos)."""
    a, d = antes.filtro_tipo, depois.filtro_tipo
    mud: dict = {}
    if acrescenta(texto) and a is not None and d not in (None, "tanto_faz") and _familia(a) != _familia(d):
        mud["filtro_tipo"] = "tanto_faz"
        if depois.filtro_quartos is not None:
            mud["filtro_quartos"] = None
    if depois.filtro_mobilia in (None, "tanto_faz"):
        mud["filtro_mobilia"] = "sem_preferencia"   # cada cliente tem a sua: a busca sai com os dois, sem perguntar
    return depois.com(**mud) if mud else depois

estado/memoria.py:tipo_da_frase.codigo:
def tipo_da_frase(c: Conversa, texto: str) -> Conversa:
    """A parede: a frase escreve UM tipo de moradia, sem "tanto faz" nem acréscimo, e a ficha ficou em "casa ou
    apartamento". Vale o que ele escreveu: quem pede casa nunca recebe apartamento."""
    t = normal(texto or "")
    ditos = tipos_ditos(texto)
    if (c.filtro_tipo != "tanto_faz" or len(ditos) != 1 or ditos[0] not in MORADIA or acrescenta(texto)
            or DE_UM_IMOVEL.search(t) or TANTO_FAZ.search(t) or AMBOS.search(t) or len(t.split()) > 60):
        return c
    return c.com(filtro_tipo=ditos[0])

estado/memoria.py:perfil_inteiro.codigo:
def perfil_inteiro(c: Conversa, cl: Classificacao | None, texto: str) -> bool:
    """A frase traz um perfil INTEIRO (tipo, valor e bairro) de tipo diferente do da ficha, e não é acréscimo: é
    outro pedido. A mobília, os quartos e os recusados do de antes não passam para este."""
    if cl is None or not (cl.tipo and cl.teto and cl.bairros) or acrescenta(texto) or c.filtro_tipo is None:
        return False
    return bool(tipos_ditos(texto)) and _familia(cl.tipo) != _familia(c.filtro_tipo)

estado/memoria.py:para_a_busca.codigo:
def para_a_busca(ja_dito: dict, texto: str) -> tuple[bool, tuple[str, ...]]:
    """O que a busca precisa saber do pedido: são vários clientes? quais tipos ele pediu?"""
    return varios_clientes(ja_dito, texto), tuple(dict.fromkeys((*(ja_dito.get("tipos") or ()), *tipos_ditos(texto))))

estado/memoria.py:ouvido.codigo:
def ouvido(cl: Classificacao | None, bairros: tuple[str, ...]) -> dict:
    """Camada 1: os filtros que o classificador leu nesta mensagem."""
    if cl is None:
        return {}
    return {"finalidade": cl.finalidade if cl.finalidade in ("locacao", "venda") else None, "tipo": cl.tipo,
            "regiao": tuple(bairros), "quartos": cl.quartos,
            "mobilia": cl.mobilia if cl.mobilia not in (None, "tanto_faz") else None}

estado/memoria.py:_do_pedido.codigo:
def _do_pedido(historico: tuple, desde: datetime | None) -> list[str]:
    """As mensagens DELE neste pedido (depois de `desde`), da mais antiga para a mais nova."""
    textos = []
    for m in historico or ():
        quando = m.get("quando")
        if m.get("de") != "corretor" or not (m.get("texto") or "").strip():
            continue
        comparavel = desde is not None and quando is not None and (quando.tzinfo is None) == (desde.tzinfo is None)
        if comparavel and quando < desde:
            continue
        textos.append(m["texto"])
    return textos

estado/memoria.py:ja_dito.codigo:
def ja_dito(historico: tuple, desde: datetime | None = None) -> dict:
    """Camada 2: o que ele já escreveu neste pedido, lido sem modelo. A mais nova vale sobre a mais antiga."""
    d: dict = {}
    for texto in _do_pedido(historico, desde):
        t = normal(texto)
        if VARIOS.search(t):
            d["varios"] = True
        if DE_UM_IMOVEL.search(t) or len(t.split()) > 60:
            continue
        fin = frases.finalidade_dita(texto)
        if fin in ("locacao", "venda"):
            d["finalidade"] = fin
        tipo = _primeiro(TIPOS, t)
        if tipo:
            d["tipo"] = tipo
            d["tipos"] = tuple(dict.fromkeys((*d.get("tipos", ()), *tipos_ditos(texto))))
        m = QUARTOS.search(t)
        if m:
            d["quartos"] = NUMERO.get(m.group(1)) or int(m.group(1))
        mob = mobilia_dita(t)
        if mob:
            d["mobilia"] = mob
    return d

estado/memoria.py:completar.codigo:
def completar(c: Conversa, d: dict) -> Conversa:
    """Só os filtros VAZIOS. Devolve a mesma conversa quando não há o que acrescentar."""
    if not d:
        return c
    mud: dict = {}
    if c.filtro_finalidade is None and d.get("finalidade"):
        mud["filtro_finalidade"] = d["finalidade"]
    if c.filtro_tipo is None and d.get("tipo"):
        mud["filtro_tipo"] = d["tipo"]
    if not c.filtro_regiao and not c.filtro_regiao_tanto_faz and d.get("regiao"):
        mud["filtro_regiao"] = tuple(d["regiao"])
    if c.filtro_quartos is None and d.get("quartos"):
        mud["filtro_quartos"] = int(d["quartos"])
    if c.filtro_mobilia is None and d.get("mobilia"):
        mud["filtro_mobilia"] = d["mobilia"]
    return c.com(**mud) if mud else c

estado/multiplos.py:com_o_envio.codigo:
def com_o_envio(antes: Conversa, ev: Evento, decidido: tuple[Conversa, Acao]) -> tuple[Conversa, Acao]:
    """O pedido novo veio JUNTO do "me envia" do imóvel que ela ofereceu: a ação do pedido leva o envio na frente."""
    nova, acao = decidido
    cod = antes.foco_codigo
    quer = pediu_envio(ev.texto) or frases.aceitou(ev.texto)     # "Me envia." ou "Por favor. A casa no Japiim também"
    if not (cod and antes.ultima_acao in OFERECEU and prazos.gatilho_vale(antes, ev.agora) and quer):
        return decidido
    if acao.tipo not in ("perguntar_filtro", "buscar", "template") or acao.codigo == cod:
        return decidido
    return (nova.com(mostrados=tuple(dict.fromkeys((*nova.mostrados, cod)))),
            replace(acao, dados={**acao.dados, "antes_envia": cod}))

estado/multiplos.py:dois_clientes.codigo:
def dois_clientes(c: Conversa, ev: Evento, perguntar) -> tuple[Conversa, Acao] | None:
    """Ela está no meio das perguntas de um pedido e ele EXPLICA que são clientes diferentes ("o Firenze é para uma
    cliente e a do Japiim é para outro; o Firenze locação e Japiim compra", 3107). Não é pedido de envio nem
    pergunta sobre o imóvel: o pedido em aberto continua. Com as duas finalidades na frase, a do pedido novo é a
    que ele diz por último (o que já estava resolvido vem primeiro); e a pergunta que falta sai de novo."""
    if not (c.estado.startswith("FILTRO_") and frases.segundo_pedido(ev.texto) and "?" not in ev.texto):
        return None
    cl = ev.classificacao
    # o modelo às vezes lê a explicação como "pedir imóvel": sem perfil novo (tipo, valor, quartos) é explicação
    sem_perfil = cl is not None and cl.intencao == "pedir_imovel" and not (cl.tipo or cl.teto or cl.quartos)
    explica = (cl is not None and cl.intencao in EXPLICA) or sem_perfil
    if not explica or pediu_envio(ev.texto) or frases.pediu_fotos(ev.texto):
        return None
    ditas = ULTIMA_FINALIDADE.findall(normal(ev.texto))
    if frases.finalidade_dita(ev.texto) == "ambos" and ditas:
        fin = "locacao" if ditas[-1].startswith(("alug", "loca")) else "venda"
        if fin != c.filtro_finalidade:
            c = corrigir_finalidade(c, fin)
    return perguntar(c)

estado/multiplos.py:tipo_fora.codigo:
def tipo_fora(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele pediu um tipo que o cadastro não tem para oferecer: ela diz, e oferece o que tem. O pedido não começa."""
    palavra = ev.dados_pre.get("tipo") or ""
    return c, Acao("template", template="tipo_que_nao_tenho", dados={"tipo": NOME_DO_TIPO.get(palavra, "Esse tipo")})

estado/multiplos.py:parceria.codigo:
def parceria(c: Conversa, ev: Evento, pedir) -> tuple[Conversa, Acao]:
    """"Aceita parceria?" tem a frase do Tel. Mas quem JÁ diz o que quer na mesma mensagem recebe o que pediu, e a
    frase não sai duas vezes seguidas."""
    codigos = tuple(ev.condominio_codigos)
    cl = ev.classificacao
    quer = pediu_envio(ev.texto) or frases.pediu_fotos(ev.texto) or bool(cl and cl.pede_fotos)
    maximo = int(cfg("limites").get("max_imoveis_de_uma_vez", 5))
    if codigos and quer:
        if len(codigos) == 1:
            return apresentar(c, ev, codigos[0], True, False, origem="condominio")
        if len(codigos) <= maximo:
            return apresentar_varios(c, ev, codigos)
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=codigos[:maximo])
    if quer or frases.quer_resultado_ja(ev.texto):
        # "certo, me manda aí o que tem disponível, vou anunciar agora" (3202): ele pediu os imóveis; segue o pedido
        return pedir(c, ev)
    if c.ultima_acao in ("parceria", "parceria_de_novo") and prazos.gatilho_vale(c, ev.agora):
        return c, Acao("template", template="parceria_de_novo")
    return c, Acao("template", template="parceria")

estado/pedido.py:perguntar_proximo_filtr.codigo:
def perguntar_proximo_filtro(c: Conversa) -> tuple[Conversa, Acao]:
    falta = filtros.primeiro_vazio(c)
    while falta is not None and _ja_perguntou(c, falta):
        # A MESMA PERGUNTA NÃO SAI DUAS VEZES (Tel, 20/10, 559291792460: "Até que valor o seu cliente quer?" quatro
        # vezes, e a corretora tinha dito "aí tu vai dizer o valor"). Perguntou e a resposta não trouxe: o filtro
        # vira tanto faz e ela segue para o próximo, ou para a lista.
        c = filtros.sem_resposta(c, falta)
        falta = filtros.primeiro_vazio(c)
    if falta is None:
        return c.com(estado="BUSCA"), Acao("buscar")
    if falta == "mobilia" and c.filtro_mobilia == "tanto_faz":
        # "os dois / sem preferência" na mobília: são clientes diferentes, ela pergunta a preferência UMA vez
        return c.com(estado="FILTRO_MOBILIA"), Acao("perguntar_filtro", filtro="mobilia_preferencia")
    return c.com(estado="FILTRO_" + falta.upper()), Acao("perguntar_filtro", filtro=falta)

estado/pedido.py:pediu.codigo:
def pediu(ev: Evento) -> bool:
    """Pediu foto ou pediu para mandar: é o que leva as fotos junto do card (`_com_fotos`)."""
    return pediu_fotos(ev) or pediu_envio(ev.texto)

estado/pedido.py:_do_mesmo_pedido.codigo:
def _do_mesmo_pedido(c: Conversa, ev: Evento) -> Conversa:
    """A ficha em que a mensagem entra: a mesma com a finalidade corrigida ("é venda, não locação"), uma nova
    (outro pedido: os filtros de antes saem) ou a que já estava."""
    corrigida = frases.corrigiu_finalidade(ev.texto)
    if corrigida and c.filtro_finalidade in ("locacao", "venda") and corrigida != c.filtro_finalidade:
        return filtros.corrigir_finalidade(c, corrigida)
    cl = ev.classificacao
    if cl is not None and memoria.varios_clientes(ev.ja_dito, ev.texto):
        cl = cl.model_copy(update={"tipo": None})      # vários clientes: outro TIPO é mais um perfil, não outro pedido
    if filtros.pedido_novo(c, cl, ev.texto) or memoria.perfil_inteiro(c, ev.classificacao, ev.texto):
        # a finalidade que ESTA frase diz já entra no pedido novo ("Japiim venda")
        return memoria.da_frase(filtros.completar(filtros.zerar(c, ev.agora), ev.do_card), ev.texto)
    return c

estado/pedido.py:_com_o_condominio.codigo:
def _com_o_condominio(nova: Conversa, ev: Evento) -> Conversa:
    """20/10: o condomínio que ele citou vira a referência; os próximos dele vêm primeiro (cerebro/proximos.py)."""
    return nova.com(filtro_condominio=ev.condominio_ref) if ev.condominio_ref else nova

estado/pedido.py:_do_condominio.codigo:
def _do_condominio(nova: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """O condomínio que ele citou tem oferta. Um imóvel só: apresenta. Dois ou mais condomínios com UM imóvel em
    oferta em cada ("me manda o Jardim das Cerejeiras e o Ariranhas", instrução do Tel de 01/10): vão todos, pela
    regra dos vários (até 2 com fotos, mais que isso só os cards). Senão, "qual deles?"."""
    codigos = ev.condominio_codigos
    if len(codigos) == 1:
        return apresentar(nova, ev, codigos[0], pediu(ev), False, origem="condominio")
    um_de_cada = tuple(dict.fromkeys(g[0] for g in ev.condominio_grupos if len(g) == 1))
    if len(um_de_cada) > 1 and len(um_de_cada) == len(ev.condominio_grupos):
        return apresentar_varios(nova, ev, um_de_cada)
    # quem tira da pergunta o que não cabe no valor dele é a ação, que tem o catálogo (acoes/preparo.py)
    return nova.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=codigos,
                                                  dados={"do_condominio": True, "pediu": pediu(ev)})

estado/pedido.py:ja_disse.codigo:
def ja_disse(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Deixei descrito": está tudo na mensagem de antes, que já foi para a ficha. Segue de onde parou."""
    return perguntar_proximo_filtro(c)

estado/pedido.py:tentar_outro.codigo:
def tentar_outro(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
