    ele respondeu que sim: aí, e só aí, sai a lista do que é mais barato (os outros filtros e o limite de cima
    continuam valendo)."""
    return c.com(estado="BUSCA"), Acao("buscar", dados={"sem_piso": True})

estado/pedido.py:outro_cliente.codigo:
def outro_cliente(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ela perguntou "Está perguntando para outro cliente, certo?" e ele disse que sim (Pedro, 10/10): o pedido é
    outro. Os filtros que ele acabou de dizer ficam; o que foi enviado ou recusado para o cliente de antes deixa
    de contar, e a lista sai de novo, agora com tudo o que cabe."""
    return (c.com(estado="BUSCA", rejeitados=(), ultima_lista=(), pedido_desde=ev.agora),
            Acao("buscar", dados={"repete_lista": True, "outro_cliente": True}))

estado/pedido.py:mesmo_cliente.codigo:
def mesmo_cliente(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """...e ele disse que não: é o mesmo cliente. O que ele já recebeu hoje continua fora da lista."""
    return c, Acao("template", template="mesmo_cliente")

estado/pedido.py:retomar.codigo:
def retomar(c: Conversa, ev: Evento) -> tuple[Conversa, Acao] | None:
    """Não deu para entender a mensagem e há um pedido aberto: ela repete a pergunta que estava fazendo (ou diz o
    que dá para ajustar na busca), UMA vez. None = não há pedido aberto, ou ela já repetiu (aí sobe ao Tel)."""
    if c.estado.startswith("FILTRO_") and c.ultima_acao != "repetiu_pergunta":
        nova, acao = perguntar_proximo_filtro(c)
        return nova, replace(acao, motivo="de_novo") if acao.tipo == "perguntar_filtro" else acao
    if c.estado == "BUSCA" and c.ultima_acao != "retomar_pedido":
        return c, Acao("template", template="retomar_pedido")
    return None

estado/pedido.py:despedida.codigo:
def despedida(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
