def tem_as_fotos(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Tenho 11 fotos no tirei no grupo, se tiver mais" (13567, rodada 9): ele já tem as fotos. Ela não manda de
    novo: diz que as do grupo são todas as que tem."""
    return (c.com(foco_codigo=ev.contexto.codigo, foco_origem=origem_de(c, ev, ev.contexto.codigo)),
