estado/pedido.py:_tambem_recusou.codigo:
def _tambem_recusou(c: Conversa, ev: Evento) -> Conversa:
    """`codigo_rejeitado` vale mesmo fora de rejeitar_imovel (test_recusa_fora_do_rejeitar.py)."""
    cod = ev.classificacao.codigo_rejeitado if ev.classificacao else None
    if not cod or cod in c.rejeitados:
        return c
    return c.com(rejeitados=(*c.rejeitados, cod), foco_codigo=None if c.foco_codigo == cod else c.foco_codigo)

estado/pedido.py:_recusados_pelo_nome.codigo:
def _recusados_pelo_nome(c: Conversa, ev: Evento) -> tuple[Conversa, Evento]:
    """"Esse Parque Golf fica distante pra ela, tem que ser Parque Dez" (13582, rodada 9): o imóvel que ele recusou
    DIZENDO o nome entra nos rejeitados, não é apresentado e não empresta o bairro; o resto da frase (bairro,
    tipo) segue no pedido."""
    ditos = _recusados(ev)
    if not ditos:
        return c, ev
    return (c.com(rejeitados=tuple(dict.fromkeys((*c.rejeitados, *ditos))),
                  foco_codigo=None if c.foco_codigo in ditos else c.foco_codigo),
            replace(ev, condominio_codigos=(), condominio_bairros=(), condominio_sem_oferta=None))

estado/pedido.py:_recusados.codigo:
def _recusados(ev: Evento) -> tuple[int, ...]:
    """Os imóveis dos condomínios que a frase recusa pelo nome (todos os nomes citados têm de ser recusa)."""
    nomes = list(ev.classificacao.condominios) if ev.classificacao else []
    if not nomes or not ev.condominio_codigos or not all(frases.rejeitou_o(ev.texto, n) for n in nomes):
        return ()
    return ev.condominio_codigos

estado/pedido.py:_disse_filtro.codigo:
def _disse_filtro(cl) -> bool:
    """A mensagem trouxe filtro novo além do bairro? (`filtros.aplicar` só usa o que não é vazio.)"""
    return any((cl.finalidade, cl.tipo, cl.teto, cl.quartos, cl.mobilia, cl.tanto_faz))

estado/pergunta.py:sem_dizer_qual.codigo:
def sem_dizer_qual(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """A pergunta não diz de qual imóvel é."""
    if ev.condominio_sem_oferta:
        return c.com(estado="IDENTIFICANDO"), Acao("template", template="condominio_sem_oferta",
                                                   dados={"condominio": ev.condominio_sem_oferta,
                                                          "para": ev.condominio_sem_finalidade})
    if ev.condominio_codigos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.condominio_codigos)
    if c.ultima_acao == "condominio_sem_oferta" and prazos.gatilho_vale(c, ev.agora):
        # ela acabou de dizer que no condomínio não tem nada e ele pergunta "Mobiliado ?": é do mesmo condomínio
        return c, Acao("template", template="condominio_sem_oferta_ainda")
    if 2 <= len(ev.lista_na_frente) <= LISTA_CURTA:
        # a pergunta é sobre um dos que ela acabou de mostrar: qual deles? (nunca "De qual imóvel você fala?")
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ev.lista_na_frente)
    if c.ultima_acao == "pergunta_qual_imovel":    # perguntou e ele de novo não disse qual: sobe ao Tel
        return escalar(c, ev, "perguntou de imóvel sem dizer qual, duas vezes")
    return c.com(estado="IDENTIFICANDO"), Acao("template", template="pergunta_qual_imovel")

estado/pergunta.py:pergunta_sobre_imovel.codigo:
def pergunta_sobre_imovel(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    ctx = ev.contexto
    if ctx.candidatos:
        return c.com(estado="IDENTIFICANDO"), Acao("perguntar_qual", candidatos=ctx.candidatos)
    codigo = ctx.codigo or (ev.condominio_codigos[0] if len(ev.condominio_codigos) == 1 else None)
    if ctx.origem == "foco" and (ev.condominio_codigos or ev.condominio_sem_oferta):
        # ele escreveu o nome de um condomínio AGORA: é dele que fala, não do imóvel de antes
        nomeados = ev.condominio_codigos
        codigo = ctx.codigo if ctx.codigo in nomeados else nomeados[0] if len(nomeados) == 1 else None
    if codigo is None:
        return sem_dizer_qual(c, ev)
    if pediu_fotos(ev) and not ev.classificacao.pede_lista_de_valores:
        if ctx.origem == "foco" and codigo == ctx.codigo and not prazos.gatilho_vale(c, ev.agora):
            # o foco vale 24 h para pergunta e visita; o ENVIO pelo imóvel de antes continua valendo só 2 h
            return sem_dizer_qual(c, ev)
        c, a = so_fotos(c, ev, codigo)
        # "Qual andar? / Manda as fotos por favor" numa rajada só (Adriana, 12/10): as fotos iam e a pergunta era
        # jogada fora. A pergunta que sobra fora do pedido de fotos vai junto, respondida pela ficha.
        resto = pergunta_alem_das_fotos(ev.texto)
        return c, (replace(a, pergunta=resto) if resto else a)
    if frases.pergunta_se_vale(ev.texto):           # "tá valendo?": sim, por quanto, e o card (13653)
        return esta_valendo(c, ev, codigo)
    if so_perguntou_se_esta_disponivel(ev.texto):      # responde e oferece as informações e as fotos
        return apresentar(c, ev, codigo, False, True, so_status=True)
    return (c.com(estado="APRESENTADO", foco_codigo=codigo, foco_origem=ctx.origem or c.foco_origem),
            Acao("responder_ficha", codigo=codigo, pergunta=ev.texto))

estado/pergunta.py:do_escrito.codigo:
def do_escrito(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele escreveu o código de um imóvel nosso ou colou o nosso card, e o modelo leu oferta de imóvel, assunto
    geral ou nada. Com pergunta em volta ("...Código: 9001 ⏎ Mobiliado?"), a ficha responde; o card colado sozinho
    recebe as fotos; o código digitado é o pedido do imóvel."""
    ctx = ev.contexto
    resto = sem_card(ev.texto).strip() if ctx.card_colado else ev.texto
    if "?" in resto:
        if frases.pergunta_se_vale(resto):
            return esta_valendo(c, ev, ctx.codigo)
        if so_perguntou_se_esta_disponivel(resto):
            return apresentar(c, ev, ctx.codigo, False, True, so_status=True)
        return (c.com(estado="APRESENTADO", foco_codigo=ctx.codigo, foco_origem=ctx.origem),
                Acao("responder_ficha", codigo=ctx.codigo, pergunta=resto))
    if ctx.card_colado:
        return do_card_colado(c, ev, ctx.codigo)
    return apresentar(c, ev, ctx.codigo, pediu(ev), False)

estado/pergunta.py:dos_varios.codigo:
def dos_varios(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """"Pela descrição os dois são mobiliados né" depois de ela mandar dois (13768): a ficha de cada um responde
    (acoes/varios.py). O foco continua vazio: ele fala de todos."""
    return c, Acao("responder_varios", candidatos=tuple(ev.dados_pre.get("codigos") or ()), pergunta=ev.texto)

estado/prazos.py:inicio_do_dia.codigo:
def inicio_do_dia(agora: datetime) -> datetime:
    """A meia-noite de Manaus do dia de `agora` (relógio sem fuso, como o dos testes antigos, fica como está)."""
    if agora.tzinfo is None:
        return agora.replace(hour=0, minute=0, second=0, microsecond=0)
    return agora.astimezone(MANAUS).replace(hour=0, minute=0, second=0, microsecond=0)

estado/prazos.py:conta_desde.codigo:
def conta_desde(c: Conversa, agora: datetime | None) -> datetime | None:
    """Desde quando o "já te enviei" vale. Pedro, 10/10/2026: "esse filtro de imóveis já enviado é imóveis
    enviados por solicitação ... põe um filtro de não enviar o mesmo no dia a não ser que ele cite que é para
    outro cliente e mude a solicitação". O envio só conta se foi HOJE e DENTRO DO PEDIDO ATUAL: o que saiu em
    outro dia, ou para outro cliente, pode ser oferecido e enviado de novo."""
    if agora is None:
        return c.pedido_desde
    dia = inicio_do_dia(agora)
    if c.pedido_desde is None or (c.pedido_desde.tzinfo is None) != (dia.tzinfo is None):
        return dia
    return max(dia, c.pedido_desde)

estado/prazos.py:recente.codigo:
def recente(quando: datetime | None, agora: datetime | None, horas: float) -> bool:
    if quando is None or agora is None:
        return True
    return agora - quando <= timedelta(hours=horas)

estado/prazos.py:gatilho_vale.codigo:
def gatilho_vale(c: Conversa, agora: datetime | None) -> bool:
    """O que ela fez por último (card, fotos, pergunta) ainda está valendo para um "manda aí" ou um "sim"?"""
    return recente(c.ultima_acao_em, agora, float(cfg("limites").get("gatilho_vale_h", 2)))

estado/prazos.py:_pedido_do_dia.codigo:
def _pedido_do_dia(c: Conversa, agora: datetime) -> Conversa:
    """O que ele recusou ONTEM não esconde imóvel HOJE (10/10: o corretor recusou o Maison Rochelle na quarta,
    para um cliente de compra, e na quinta ela não o ofereceu a um cliente de locação). Na primeira mensagem de
    um dia novo os recusados saem; os filtros continuam, com o prazo deles. Conversa sem o carimbo (a primeira
    mensagem de quem nunca falou, e os testes) só ganha o carimbo do dia."""
    dia = inicio_do_dia(agora)
    if c.pedido_desde is None:
        return c.com(pedido_desde=dia)
    if (c.pedido_desde.tzinfo is None) == (dia.tzinfo is None) and c.pedido_desde < dia:
        return c.com(rejeitados=(), pedido_desde=dia)
    return c

estado/prazos.py:entrada.codigo:
@no("estado.prazos_de_entrada")
def entrada(c: Conversa, agora: datetime) -> Conversa:
    """Antes do turno: o foco vencido sai; a conversa parada há dias recomeça os filtros; e o pedido é do dia."""
    if not recente(c.ultima_acao_em, agora, 24 * float(cfg("limites").get("filtros_valem_dias", 3))):
        c = filtros.zerar(c, agora)
    c = _pedido_do_dia(c, agora)
    if c.foco_codigo and not foco_vale(c, agora):
        return c.com(foco_codigo=None, foco_origem=None, foco_desde=None)
    return c

estado/prazos.py:saida.codigo:
@no("estado.prazos_de_saida")
def saida(antes: Conversa, nova: Conversa, a: Acao, agora: datetime) -> Conversa:
    """Depois do turno: carimba o foco (quando mudou ou a ação falou dele) e a hora do que ela fez."""
    if nova.foco_codigo is None:
        foco_desde = None
    elif nova.foco_codigo != antes.foco_codigo or (a.tipo not in CALADAS and a.codigo == nova.foco_codigo):
        foco_desde = agora
    else:
        foco_desde = nova.foco_desde
    falou = a.tipo not in CALADAS
    return nova.com(foco_desde=foco_desde, ultima_acao_em=agora if falou else nova.ultima_acao_em)

