estado/visita.py:hora_dita.codigo:
def hora_dita(texto: str) -> str | None:
    """"19:00", "19h", "19h30", "10 horas", "às 14", "meio dia" -> "HH:MM"."""
    t = _plano(texto)
    m = HORA_E_MINUTO.search(t)
    if m:
        return f"{int(m.group(1)):02d}:{m.group(2)}"
    m = HORA_CHEIA.search(t)
    if m:
        return f"{int(m.group(1)):02d}:00"
    m = AS_TANTAS.search(t)
    if m:
        return f"{int(m.group(1)):02d}:{'30' if m.group(2) else '00'}"
    return "12:00" if re.search(r"\bmeio[- ]dia\b", t) else None

estado/visita.py:_do_calendario.codigo:
def _do_calendario(dia: int, mes: int | None, hoje: date) -> date | None:
    """"08/10" ou "dia 8": a próxima data com esse dia (este mês, ou o seguinte se já passou). Data que não
    existe ("31/02", "dia 40") não é data."""
    try:
        if mes:
            d = date(hoje.year, mes, dia)
            return d if d >= hoje else d.replace(year=hoje.year + 1)
        d = hoje.replace(day=dia)
        return d if d >= hoje else (d.replace(day=1) + timedelta(days=32)).replace(day=dia)
    except ValueError:
        return None

estado/visita.py:dia_dito.codigo:
def dia_dito(texto: str, hoje: date) -> date | None:
    """"hoje", "amanhã", "sábado", "08/10", "dia 8" -> a data. O dia da semana é o próximo (hoje conta)."""
    t = _plano(texto)
    if "depois de amanha" in t:
        return hoje + timedelta(days=2)
    if re.search(r"\bamanha\b", t):
        return hoje + timedelta(days=1)
    if re.search(r"\b(hoje|hj|agora)\b", t):
        return hoje
    m = DATA.search(t) or DIA_DO_MES.search(t)
    if m:
        do_mes = _do_calendario(int(m.group(1)), int(m.group(2)) if m.re is DATA else None, hoje)
        if do_mes:
            return do_mes
    for n, nome in enumerate(DIAS):
        if re.search(rf"\b{nome}(?:[- ]feira)?\b", t):
            # "no outro sábado", "sábado da semana que vem" (...0305, 23/10): não é o sábado mais próximo
            outro = rf"\boutr[oa]\s+{nome}\b|\b{nome}(?:[- ]feira)?\s+(?:da\s+)?(?:semana\s+que\s+vem|outra\s+semana)"
            return hoje + timedelta(days=(n - hoje.weekday()) % 7 + (7 if re.search(outro, t) else 0))
    return None

estado/visita.py:pediu.codigo:
def pediu(texto: str) -> bool:
    """Pediu a visita dizendo quando ("vou agendar a visita para amanhã", "quer visitar esse no começo da noite")."""
    t = _plano(texto)
    return bool(PEDE.search(t)) and not JA_FOI.search(t) and disse_quando(texto)

estado/visita.py:aberto.codigo:
def aberto(c: Conversa, agora: datetime | None) -> dict | None:
    """O pedido de visita que ainda está em andamento (falta dado ou falta confirmar), se houver."""
    p = c.visita_pedida or {}
    if p.get("etapa") not in ("falta", "confirmar"):
        return None
    try:
        feito = datetime.fromisoformat(p.get("quando") or "")
    except ValueError:
        return None
    return p if agora is None or agora - feito <= timedelta(hours=VALE_H) else None

estado/visita.py:data_texto.codigo:
def data_texto(d: date) -> str:
    """06/10 (terça)."""
    return f"{d.strftime('%d/%m')} ({NOME_DO_DIA[d.weekday()]})"

estado/visita.py:_quando.codigo:
def _quando(d: date, hoje: date) -> tuple[str, str]:
    """(como entra depois de "cliente", como entra depois de "horário"): ("no sábado", "de sábado")."""
    dias = (d - hoje).days
    if dias in (0, 1):
        nome = "hoje" if dias == 0 else "amanhã"
        return nome, f"de {nome}"
    if 0 < dias < 7:
        return f"n{'o' if d.weekday() >= 5 else 'a'} {NOME_DO_DIA[d.weekday()]}", f"de {NOME_DO_DIA[d.weekday()]}"
    return f"no dia {d.strftime('%d/%m')}", f"do dia {d.strftime('%d/%m')}"

estado/visita.py:_codigos.codigo:
def _codigos(c: Conversa, ev: Evento, antes: dict) -> list[int]:
    """Os imóveis da visita. Mais de um quando ele colou dois cards ou escreveu dois códigos (13789: "Estão
    disponíveis? Querem visitar dia 07/10 às 14:30"), ou citou dois condomínios com um imóvel em oferta cada."""
    ctx = ev.contexto
    if len(ctx.literais) > 1:
        return list(ctx.literais)
    if len(ctx.varios) > 1:      # nomeou dois da lista ("Residencial Tapajós e Reserva das Flores", 21/10)
        return list(ctx.varios)
    if ctx.codigo and ctx.origem in ("literal", "citacao", "card", "lista"):
        return [ctx.codigo]
    um_de_cada = [g[0] for g in ev.condominio_grupos if len(g) == 1]
    if um_de_cada and len(um_de_cada) == len(ev.condominio_grupos):
        return list(dict.fromkeys(um_de_cada))
    if len(ev.condominio_codigos) == 1:
        return [ev.condominio_codigos[0]]
    de_antes = list(antes.get("codigos") or ([antes["codigo"]] if antes.get("codigo") else []))
    return de_antes or [x for x in (ctx.codigo or c.foco_codigo,) if x]

estado/visita.py:_dados.codigo:
def _dados(p: dict) -> dict:
    """O que a confirmação e o "anotei" mostram: a data, a hora e TODOS os códigos (a ponte da visita lê
    `codigos`, a lista de inteiros)."""
    codigos = list(p.get("codigos") or ([p["codigo"]] if p.get("codigo") else []))
    return {"data": data_texto(date.fromisoformat(p["dia"])), "horario": p["hora"].replace(":", "h"),
            "codigos": codigos, "codigos_texto": codigos_texto(codigos), "codigos_tel": codigos_texto(codigos, "")}

estado/visita.py:_lido.codigo:
def _lido(c: Conversa, ev: Evento, antes: dict) -> dict:
    """O pedido com o que esta mensagem trouxe por cima do que já estava anotado."""
    agora = ev.agora.astimezone(MANAUS)
    do_modelo = (ev.classificacao.horario_visita if ev.classificacao else None) or ""
    hora = hora_dita(ev.texto) or hora_dita(do_modelo) or antes.get("hora")
    dia = dia_dito(ev.texto, agora.date()) or dia_dito(do_modelo, agora.date())
    dia = dia or (date.fromisoformat(antes["dia"]) if antes.get("dia") else None)
    parte = None if hora else (parte_dita(ev.texto) or antes.get("parte"))
    if dia is None and (parte or (hora and hora > agora.strftime("%H:%M"))):
        dia = agora.date()          # "às 19:00", "no começo da noite": é hoje (como a Nay velha entendia)
    codigos = _codigos(c, ev, antes)
    return {"codigo": codigos[0] if codigos else None, "codigos": codigos, "dia": dia.isoformat() if dia else None,
            "hora": hora, "parte": parte, "quando": ev.agora.isoformat()}

estado/visita.py:_falta.codigo:
def _falta(p: dict, hoje: date, texto: str = "") -> Acao:
    """A pergunta do que falta: o horário daquele dia, o dia daquela hora, ou os dois. Se ele disse que ainda
    espera o horário do cliente, ela não pergunta: diz que fica no aguardo (a hora que vier depois completa)."""
    dia = date.fromisoformat(p["dia"]) if p["dia"] else None
    if not dia and not p["hora"]:
        return Acao("visita_pedida", template="visita_entregue", codigo=p["codigo"])
    quando, de_dia = _quando(dia, hoje) if dia else (None, None)
    aguarda = bool(dia) and not p["hora"] and bool(AGUARDA_A_HORA.search(_plano(texto)))
    dados = {"aguarda": aguarda, "com_parte": bool(p["parte"]) and not aguarda, "parte": p["parte"], "quando": quando,
             "so_dia": bool(dia) and not p["parte"] and not aguarda, "de_dia": de_dia,
             "so_hora": not dia, "hora": (p["hora"] or "").replace(":", "h")}
    return Acao("visita_pedida", template="visita_qual_horario", codigo=p["codigo"], dados=dados)

estado/visita.py:pedir.codigo:
def pedir(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele quer visitar: junta o que já se sabe e pergunta o que falta, ou manda a confirmação."""
    p = _lido(c, ev, aberto(c, ev.agora) or {})
    if p["codigo"] is None:      # não se sabe de qual imóvel: o dia e a hora ficam anotados para a resposta dele
        return (c.com(visita_pedida={**p, "etapa": "falta"}),
                Acao("template", template="pergunta_qual_imovel"))
    foco = {"foco_codigo": p["codigo"], "foco_origem": c.foco_origem if c.foco_codigo == p["codigo"] else "visita"}
    if not (p["dia"] and p["hora"]):
        return (c.com(estado="VISITA_PEDIDA", visita_pedida={**p, "etapa": "falta"}, **foco),
                _falta(p, ev.agora.astimezone(MANAUS).date(), ev.texto))
    return (c.com(estado="VISITA_PEDIDA", visita_pedida={**p, "etapa": "confirmar"}, **foco),
            Acao("visita_pedida", template="visita_confirmar", codigo=p["codigo"], dados=_dados(p)))

estado/visita.py:confirmar.codigo:
def confirmar(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele confirmou os dados: ela anota e avisa o Tel. A conversa segue (não escala, não para)."""
    p = c.visita_pedida or {}
    return (c.com(estado="APRESENTADO", visita_pedida={**p, "etapa": "anotada", "quando": ev.agora.isoformat()}),
            Acao("visita_pedida", template="visita_anotada", codigo=p.get("codigo"), dados=_dados(p)))

estado/visita.py:corrigir.codigo:
def corrigir(c: Conversa, ev: Evento) -> tuple[Conversa, Acao]:
    """Ele disse que os dados não estão certos, sem dizer os certos: ela pergunta o dia e a hora de novo."""
    p = {**(c.visita_pedida or {}), "dia": None, "hora": None, "parte": None, "etapa": "falta",
         "quando": ev.agora.isoformat()}
    return c.com(visita_pedida=p), Acao("visita_pedida", template="visita_entregue", codigo=p.get("codigo"))

identidade/contato.py:chave.codigo:
def chave(telefone: str | None) -> str | None:
    if not telefone:
        return None
    t = telefone.strip().lower()
    if "@lid" in t or t.startswith("lid:"):
        d = re.sub(r"\D", "", t.split("@")[0])
        return f"lid:{d}" if d else None
    d = re.sub(r"\D", "", t)
    if len(d) < 10:
        return None
    if d.startswith("55") and len(d) in (12, 13):
        return "55" + d[2:4] + d[-8:]
    if len(d) in (10, 11):                      # sem DDI
        return "55" + d[:2] + d[-8:]
    return d

identidade/contato.py:mascarar.codigo:
def mascarar(ch: str | None) -> str:
    """Só os 4 últimos dígitos, para log e relatório."""
    if not ch:
        return "?"
    return "…" + re.sub(r"\D", "", ch)[-4:]

identidade/contato.py:papel.codigo:
@no("identidade.papel")
def papel(ch: str, fonte: FontePapel, tel_telefones: tuple[str, ...]) -> str:
    irmas = fonte.chaves_irmas(ch) | {ch}
    tels = {chave(t) for t in tel_telefones}
    if irmas & tels:
        return "tel"
    for c in irmas:
        p = fonte.papel_equipe(c)
        if p:
            return "acompanhante" if p == "acompanhante" else "equipe"
    if any(fonte.e_proprietario(c) for c in irmas):   # dono de imóvel: a Nay não atende (Tel, 22/10/2026)
        return "proprietario"
    return "corretor"

