nos.py:_resumo.codigo:
def _resumo(v: Any) -> Any:
    """Um resumo curto do valor: o que cabe em JSON, cortado; o resto vira o nome do tipo."""
    if v is None or isinstance(v, bool | int | float):
        return v
    if isinstance(v, str):
        return v if len(v) <= LIMITE_DO_RESUMO else v[:LIMITE_DO_RESUMO] + "…"
    de_valor = type(v).__module__ in VALORES and (hasattr(v, "__dataclass_fields__") or hasattr(v, "model_dump"))
    if not (de_valor or isinstance(v, dict | list | tuple | set | frozenset)):
        return f"<{type(v).__name__}>"
    if isinstance(v, dict | list | tuple | set | frozenset) and len(v) > 40:
        return f"<{type(v).__name__} com {len(v)} itens>"
    try:
        limpo = _json([_resumo(x) for x in v] if isinstance(v, list | tuple | set | frozenset)
                      else {str(k): _resumo(x) for k, x in v.items()} if isinstance(v, dict) else v)
        txt = json.dumps(limpo, ensure_ascii=False, default=str)
    except (TypeError, ValueError, RecursionError):
        return f"<{type(v).__name__}>"
    return limpo if len(txt) <= LIMITE_DO_RESUMO else txt[:LIMITE_DO_RESUMO] + "…"

nos.py:_entrada.codigo:
def _entrada(args: tuple, kwargs: dict) -> Any:
    partes = [_resumo(a) for a in args] + [{k: _resumo(v)} for k, v in kwargs.items()]
    return partes[0] if len(partes) == 1 else partes

nos.py:no.codigo:
def no(id_do_no: str) -> Callable[[Callable], Callable]:
    """Marca a função como o nó `id_do_no`. Fora de um turno (sem trace ligado) ela roda como sempre rodou."""
    meta = descritos().get(id_do_no)
    if meta is None:
        raise ValueError(f"nó {id_do_no} não está em painel/nos.yaml")
    if meta.etapa not in ETAPAS:
        raise ValueError(f"nó {id_do_no}: etapa desconhecida {meta.etapa}")

    def decorar(f: Callable) -> Callable:
        if id_do_no in REGISTRO and REGISTRO[id_do_no][1].__qualname__ != f.__qualname__:
            raise ValueError(f"nó repetido: {id_do_no}")

        @wraps(f)
        def rodar(*args: Any, **kwargs: Any) -> Any:
            tr = _trace.get()
            if tr is None:
                return f(*args, **kwargs)
            e = tr.registrar(meta.etapa, meta.id, _entrada(args, kwargs), no_id=meta.id)
            ini = perf_counter()
            try:
                saida = f(*args, **kwargs)
            except Exception as x:
                e.erro = f"{type(x).__name__}: {x}"[:500]
                raise
            finally:
                e.ms = int((perf_counter() - ini) * 1000)
            e.saida = _resumo(saida)
            return saida

        rodar.no = meta                      # type: ignore[attr-defined]
        REGISTRO[id_do_no] = (meta, f)
        return rodar

    return decorar

