texto.py:teto_na_escala.codigo:
def teto_na_escala(v: float | None, finalidade: str | None) -> float | None:
    """Número pequeno na resposta do teto é mil (ou milhão, na venda): "3" no aluguel é R$ 3 mil, "450" na venda é
    R$ 450 mil, "1,5" na venda é R$ 1,5 milhão. Valor que já parece reais fica como está."""
    if not v:
        return v
    if finalidade == "venda":
        return v * 1e6 if v < 10 else v * 1e3 if v < 1000 else v
    if finalidade == "locacao":
        return v * 1e3 if v < 100 else v
    # alugar OU comprar ("os dois"), ou ainda sem saber: abaixo de mil não é preço de nada, é milhar. Em 03/10 um
    # corretor com "os dois" respondeu "450" e a busca procurou até R$ 450: nada, duas vezes.
    return v * 1e3 if v < 1000 else v

