@no("validacao.regras")
def validar(itens: list[Peca], p: Permitido, isentos: frozenset[str] = frozenset()) -> Veredito:
    """`isentos`: regras que não valem para um template específico (ex.: a frase fixa
    de parceria do Tel usa a palavra 'parceria' no sentido certo)."""
    v = Veredito()
    ativas = [r for r in regras.regras() if r.get("onde") == "validador" and r.get("checa") in CHECAS]
    for item in itens:
        if item.papel_destino in ("tel", "grupo"):   # o aviso ao Tel (e ao grupo) cita o telefone, de propósito
            continue
        if item.tipo == "imagem":
            if not _foto_ok(item, p):
                v.vetos.append(("foto_so_do_imovel", f"foto {item.codigo} fora do turno", "silencio"))
            continue
        for r in ativas:
            if r["id"] in isentos:
                continue
            achou = CHECAS[r["checa"]](item.texto or "", p)
            if achou:
                v.vetos.append((r["id"], f"{r['descricao']}: {achou if isinstance(achou, set) else 'sim'}",
                                r.get("acao_ao_vetar", "regenera")))
    v.passou = not v.vetos
    return v

